// --- Hoisted from inside AppFlow (were nested closures with no React state access) ---
// Moved verbatim, no behavior change, so the headless self-play orchestrator (later milestone) can
// call the same phase-advance primitives the live UI uses. Not every originally-planned function in
// this group could be hoisted this way — see the ones still nested just above AppFlow's closing
// brace (clearAllManaPools, declareAttack, runPhaseActions, advanceSagaLoreCounters) for why.

// Arcane Denial's "at the beginning of the next turn's upkeep" delayed draws (see
// GameSession.pendingUpkeepDraws and parseDelayedUpkeepDraws) — "the next turn's upkeep" means
// the very next upkeep step that begins, whoever's turn it is, not each scheduled seat's own next
// upkeep. So this drains the WHOLE queue the first time any upkeep step is reached, rather than
// filtering by the seat whose upkeep this is.
export function resolvePendingUpkeepDraws(session: GameSession): GameSession {
  const pending = session.pendingUpkeepDraws;
  if (!pending || pending.length === 0) return session;
  let next: GameSession = { ...session, pendingUpkeepDraws: [] };
  for (const entry of pending) {
    const seat = next.seats.find((item) => item.id === entry.seatId);
    if (!seat) continue;
    next = drawMultipleForSeat(next, entry.seatId, entry.amount, `${entry.sourceName} resolves. ${seat.name} draws ${entry.amount === 1 ? "a card" : `${entry.amount} cards`}.`);
  }
  return next;
}

export function untapForSeat(session: GameSession, seatId: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  // Rule 701.44b: a permanent with a stun counter removes one stun counter instead of untapping
  // this step — it stays tapped, but the counter comes off, so it untaps normally again once none
  // are left. summoningSick/attacking/blocking still clear either way (those track "since your
  // last turn began"/"this combat", not tap state).
  // Rule 702.26h: a phased-out permanent phases IN at the start of this same step, before any
  // untapping happens — simplified here to just untapping it along with everything else rather
  // than separately restoring its exact pre-phase-out tapped status, which this engine doesn't
  // track (see phasedOut's doc comment on VisibleCard).
  // "Stun counters can't be removed from permanents your opponents control." (Fear of Sleep
  // Paralysis) overrides rule 701.44b above for whichever seat it's aimed at: normally a stun
  // counter just costs one untap step before wearing off, but this locks it in place — the
  // permanent stays tapped and stunned indefinitely until Fear of Sleep Paralysis itself leaves
  // the battlefield (this check re-runs fresh every untap step, so it stops applying the moment
  // that happens). Reported live as stun counters this seat received always still wearing off
  // after one turn regardless.
  const opponentStunLockActive = session.seats.some(
    (other) => other.id !== seatId && other.board.battlefield.some((card) => /stun counters can'?t be removed from permanents your opponents control/i.test(card.oracleText))
  );
  const everyPermanent = session.seats.flatMap((other) => other.board.battlefield);
  // Goad lasts until the goading player's next turn.
  session = { ...session, seats: session.seats.map((other) => ({ ...other, board: { ...other.board, battlefield: other.board.battlefield.map((card) => (card.goaded?.bySeatId === seatId ? { ...card, goaded: undefined } : card)) } })) };
  const untapOrRemoveStun = (card: VisibleCard): VisibleCard => {
    // Phasing: a phased-in permanent with it phases out as its controller's untap step begins (phased-out ones phase in, just below).
    if (!card.phasedOut && !card.abilitiesStripped && /^phasing\b/im.test(card.oracleText)) return { ...card, phasedOut: true, attacking: false, blocking: false, tapped: card.tapped };
    // "This creature doesn't untap during your untap step." / "Enchanted creature doesn't untap during its controller's untap step."
    if (card.tapped && cantUntap(card, everyPermanent)) return { ...card, summoningSick: false, attacking: false, blocking: false };
    if (card.phasedOut) return { ...card, phasedOut: false, tapped: false, summoningSick: false, attacking: false, blocking: false };
    if (counterCount(card, "stun") > 0) {
      return opponentStunLockActive
        ? { ...card, summoningSick: false, attacking: false, blocking: false }
        : { ...applyCounterDelta(card, "stun", -1), summoningSick: false, attacking: false, blocking: false };
    }
    return { ...card, tapped: false, summoningSick: false, attacking: false, blocking: false };
  };
  const untappedSession = {
    ...session,
    seats: session.seats.map((item) =>
      item.id === seatId
        ? {
            ...item,
            board: {
              ...item.board,
              commander: item.board.commander ? untapOrRemoveStun(item.board.commander) : undefined,
              battlefield: item.board.battlefield.map(untapOrRemoveStun)
            }
          }
        : item
    ),
    events: [
      phaseEvent(
        seatId,
        seat ? seatVerb(seat, `${seat.name} untaps their permanents.`, "You untap your permanents.") : "Player untaps their permanents."
      ),
      ...session.events
    ]
  };
  // "Untap all artifacts/permanents you control during each other player's untap step." (Unwinding
  // Clock, Seedborn Muse) — every OTHER seat's own untap step also untaps this seat's stuff, not
  // just this seat's own.
  return applyExtraUntapEffects(untappedSession, seatId);
}

// Exalted (rule 702.83): a creature attacking ALONE gets +1/+1 for each instance among its controller's permanents. Applied once, when
// damage is about to be dealt, because attackers are declared one at a time here and "alone" is only knowable afterwards.
// "Clues you control have exalted." (Merchant of Truth) adds one instance per Clue.
export function applyExalted(session: GameSession, attackerSeatId: string): GameSession {
  const seat = session.seats.find((item) => item.id === attackerSeatId);
  const attackers = seat?.board.battlefield.filter((card) => card.attacking) ?? [];
  if (!seat || attackers.length !== 1) return session;
  const [lone] = attackers;
  if (lone.temporaryGrantedKeywords?.includes("exalted-applied")) return session;
  const clueExalted = seat.board.battlefield.some((card) => !card.abilitiesStripped && /\bclues you control have exalted\b/i.test(card.oracleText));
  const instances = seat.board.battlefield.reduce((total, card) => {
    if (card.abilitiesStripped) return total;
    let count = hasKeywordText(card.oracleText, "exalted") ? 1 : 0;
    if (clueExalted && card.typeLine.includes("Clue")) count += 1;
    return total + count;
  }, 0);
  if (instances === 0) return session;
  return rulesEvent(
    {
      ...session,
      seats: session.seats.map((item) =>
        item.id !== attackerSeatId
          ? item
          : {
              ...item,
              board: {
                ...item.board,
                battlefield: item.board.battlefield.map((card) =>
                  card.id === lone.id
                    ? { ...card, temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) + instances, temporaryToughnessBonus: (card.temporaryToughnessBonus ?? 0) + instances, temporaryGrantedKeywords: [...(card.temporaryGrantedKeywords ?? []), "exalted-applied"] }
                    : card
                )
              }
            }
      )
    },
    attackerSeatId,
    `${lone.name} attacks alone and gets +${instances}/+${instances} (exalted).`
  );
}

export function resolveCombatDamage(inputSession: GameSession, attackerId: string): GameSession {
  const session = applyExalted(inputSession, attackerId);
  const attacker = session.seats.find((seat) => seat.id === attackerId);
  if (!attacker) return session;
  // Rule 702.8-adjacent Fog effect (Spore Frog's "Prevent all combat damage that would be dealt
  // this turn.", see applySacrificeEffect's "prevent_combat_damage" case) — self-resets once the
  // turn actually changes (see combatDamagePrevented's own doc comment on GameSession), so this
  // check alone is enough without a separate end-of-turn cleanup step. No exceptType: identical
  // to the original all-or-nothing behavior, skip this attacking seat's whole damage assignment.
  const preventedThisTurn = session.combatDamagePrevented?.turn === session.turn;
  const exceptType = session.combatDamagePrevented?.exceptType;
  if (preventedThisTurn && !exceptType) {
    return {
      ...session,
      events: [phaseEvent(attackerId, "All combat damage is prevented this turn."), ...session.events]
    };
  }
  // "Prevent all combat damage that would be dealt this turn by non-Spider creatures." — an
  // exceptType exempts matching attackers from the block above instead of skipping every
  // attacker outright, so Arachnogenesis's own freshly-created Spiders can still deal damage.
  const attackingCardIds = attacker.board.battlefield
    .filter((card) => card.attacking)
    .filter((card) => !preventedThisTurn || (exceptType !== undefined && card.typeLine.includes(exceptType)))
    .map((card) => card.id);
  if (attackingCardIds.length === 0) {
    return {
      ...session,
      events: [phaseEvent(attackerId, "No attacking creatures assign combat damage."), ...session.events]
    };
  }

  let result = session;
  for (const cardId of attackingCardIds) {
    const currentAttacker = result.seats.find((seat) => seat.id === attackerId);
    const attackingCard = currentAttacker?.board.battlefield.find((card) => card.id === cardId);
    if (!attackingCard) continue;
    const target = resolveAttackTarget(result, attackingCard.attackTargetId);
    if (!target) continue;
    const allBlockers = target.seat.board.battlefield.filter((card) => card.blocking && (card.blockingTargetId === attackingCard.id || card.extraBlockingTargetId === attackingCard.id));
    const orderedBlockers = attackingCard.damageAssignmentOrder
      ? attackingCard.damageAssignmentOrder.map((blockerId) => allBlockers.find((card) => card.id === blockerId)).filter((card): card is VisibleCard => Boolean(card))
      : allBlockers;
    result =
      orderedBlockers.length > 0
        ? resolveBlockedCombatDamage(result, attackerId, attackingCard, target, orderedBlockers)
        : // Unblocked: a double striker deals its damage twice (first-strike step, then the regular one) - this used to deal it once.
          Array.from({ length: hasDoubleStrike(attackingCard) ? 2 : 1 }).reduce<GameSession>(
            (acc) => applyCombatDamageToTarget(acc, attackingCard.name, target, Math.max(0, effectivePower(attackingCard)), attackingCard, attackerId),
            result
          );
  }
  return result;
}

export function cleanupCombat(session: GameSession, seatId: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  return {
    ...clearCombatState(session),
    events: [
      phaseEvent(seatId, seat ? seatVerb(seat, `${seat.name} clears combat at end of combat.`, "You clear combat at end of combat.") : "Player clears combat at end of combat."),
      ...session.events
    ]
  };
}

// Hoisted for the same reason as untapForSeat/resolveCombatDamage/cleanupCombat above — was a
// nested closure but never actually touched React state, only session/markAttackDecided/canBlock/
// phaseEvent/seatVerb, all already module-level.
export function assignBlockers(session: GameSession, choice: BlockChoiceState, blockerCardIds: string[]): GameSession {
  const attacker = session.seats.find((seat) => seat.id === choice.attackerSeatId);
  const defender = session.seats.find((seat) => seat.id === choice.defenderSeatId);
  const attackingCard = attacker?.board.battlefield.find((card) => card.id === choice.attackerCardId && card.attacking);
  if (!attacker || !defender || !attackingCard) return session;
  // Lure ("All creatures able to block this creature do so."): every creature that can block it must.
  const lureForced = !attackingCard.abilitiesStripped && /^all creatures able to block (?:this creature|[a-z',\- ]+) do so\.?$/im.test(attackingCard.oracleText)
    ? defender.board.battlefield.filter((card) => canBlock(card, attackingCard, defender.board.battlefield)).map((card) => card.id)
    : undefined;
  const blockers = (lureForced ?? blockerCardIds)
    .map((id) => defender.board.battlefield.find((card) => card.id === id && canBlock(card, attackingCard, defender.board.battlefield)))
    .filter((card): card is VisibleCard => Boolean(card))
    // Challenger Troll: its controller's power-4-or-greater creatures can't be blocked by more than one creature.
    .slice(0, attackerLimitedToOneBlocker(attacker, attackingCard) ? 1 : undefined);
  // Menace: a lone blocker is not a legal block, so the attacker goes unblocked.
  const menaceRejected = hasMenace(attackingCard) && blockers.length === 1;
  if (menaceRejected) blockers.length = 0;
  // Archangel of Tithes: while it attacks, each creature that blocks costs its controller {1}. Only as many blockers as can be paid for block.
  let blockTaxSession = session;
  const blockTax = blockTaxPerBlocker(attackingCard);
  if (blockTax > 0 && blockers.length > 0) {
    for (let count = blockers.length; count >= 0; count -= 1) {
      const total = count * blockTax;
      const payment = total === 0 ? undefined : chooseManaSourcesForCost(defender, genericCostShim(total), total, undefined, session.seats);
      if (total === 0 || payment?.ok) {
        if (payment?.ok) blockTaxSession = { ...session, seats: session.seats.map((seat) => (seat.id === defender.id ? spendManaSources(seat, payment.sourceIds) : seat)) };
        blockers.length = count;
        break;
      }
    }
  }
  const decidedSession = markAttackDecided(blockTaxSession, attacker.id, attackingCard.id);
  if (blockers.length === 0) {
    return {
      ...decidedSession,
      events: [
        phaseEvent(
          defender.id,
          menaceRejected
            ? `${attackingCard.name} has menace; a single blocker isn't a legal block, so it is unblocked.`
            : seatVerb(defender, `${defender.name} declares no blockers for ${attackingCard.name}.`, `You declare no blockers for ${attackingCard.name}.`)
        ),
        ...decidedSession.events
      ]
    };
  }

  const blockerIds = new Set(blockers.map((card) => card.id));
  return {
    ...decidedSession,
    pendingBlockDeclarations: [...(decidedSession.pendingBlockDeclarations ?? []), ...blockers.map((blocker) => ({ seatId: defender.id, card: { ...blocker, blocking: true }, attackerSeatId: attacker.id }))],
    seats: decidedSession.seats.map((seat) => {
      if (seat.id === defender.id) {
        return {
          ...seat,
          // Afflict N: whenever this creature becomes blocked, the defending player loses N life.
          life: seat.life - (attackingCard.abilitiesStripped ? 0 : Number.parseInt(attackingCard.oracleText.match(/^afflict (\d+)/im)?.[1] ?? "0", 10)),
          board: {
            ...seat.board,
            battlefield: seat.board.battlefield.map((card) =>
              blockerIds.has(card.id)
                ? {
                    ...card,
                    blocking: true,
                    ...(card.blocking ? { extraBlockingTargetId: attackingCard.id } : { blockingTargetId: attackingCard.id }),
                    // Flanking: a blocker without flanking gets -1/-1 until end of turn.
                    ...(hasKeywordText(attackingCard.oracleText, "flanking") && !hasKeywordText(card.oracleText, "flanking") ? { temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) - 1, temporaryToughnessBonus: (card.temporaryToughnessBonus ?? 0) - 1 } : {}),
                    // Bushido N: +N/+N until end of turn whenever it blocks.
                    ...(bushidoAmount(card) > 0 ? { temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) + bushidoAmount(card), temporaryToughnessBonus: (card.temporaryToughnessBonus ?? 0) + bushidoAmount(card) } : {})
                  }
                : card
            )
          }
        };
      }
      if (seat.id === attacker.id && (blockers.length > 1 || bushidoAmount(attackingCard) > 0)) {
        return {
          ...seat,
          board: {
            ...seat.board,
            battlefield: seat.board.battlefield.map((card) =>
              card.id === attackingCard.id
                ? {
                    ...card,
                    ...(blockers.length > 1 ? { damageAssignmentOrder: blockers.map((blocker) => blocker.id) } : {}),
                    // Bushido N: +N/+N until end of turn whenever it becomes blocked.
                    ...(bushidoAmount(card) > 0 ? { temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) + bushidoAmount(card), temporaryToughnessBonus: (card.temporaryToughnessBonus ?? 0) + bushidoAmount(card) } : {})
                  }
                : card
            )
          }
        };
      }
      return seat;
    }),
    events: [
      phaseEvent(
        defender.id,
        seatVerb(
          defender,
          `${defender.name} blocks ${attackingCard.name} with ${blockers.map((blocker) => blocker.name).join(" and ")}${blockers.length > 1 ? ` (damage order: ${blockers.map((blocker) => blocker.name).join(" then ")})` : ""}.`,
          `You block ${attackingCard.name} with ${blockers.map((blocker) => blocker.name).join(" and ")}${blockers.length > 1 ? ` (damage order: ${blockers.map((blocker) => blocker.name).join(" then ")})` : ""}.`
        )
      ),
      ...decidedSession.events
    ]
  };
}

type SavedDeck = { id: string; label: string; commander: string; deckList: string };

function DeckSetupPanel({
  config,
  library,
  onBuild,
  onUpdate
}: {
  config: SeatConfig;
  library: SavedDeck[];
  onBuild: (config: SeatConfig) => void | Promise<void>;
  onUpdate: (seatId: string, patch: Partial<SeatConfig>) => void;
}) {
  return (
    <article className={`setup-card ${config.status}`}>
      <header>
        <div>
          <p className="eyebrow">{config.kind === "human" ? "Player" : "Agent seat"}</p>
          <h3>{config.name}</h3>
        </div>
        <strong>{config.status === "building" ? "Building" : config.deck?.validation.legal ? "Ready" : "Draft"}</strong>
      </header>
      <div className="mode-switch" role="group" aria-label={`${config.name} deck input mode`}>
        <button className={config.mode === "commander" ? "selected" : ""} type="button" onClick={() => onUpdate(config.seatId, { mode: "commander" })}>
          Commander
        </button>
        <button className={config.mode === "decklist" ? "selected" : ""} type="button" onClick={() => onUpdate(config.seatId, { mode: "decklist" })}>
          Deck list
        </button>
      </div>
      <label>
        Load saved deck
        <select
          value=""
          onChange={(event) => {
            const saved = library.find((deck) => deck.id === event.target.value);
            if (!saved) return;
            const patch = { commander: saved.commander, deckList: saved.deckList, deck: undefined, mode: "decklist" as const, status: "empty" as const };
            onUpdate(config.seatId, patch);
            void onBuild({ ...config, ...patch });
          }}
        >
          <option value="">{library.length === 0 ? "No saved decks found" : "Choose a deck..."}</option>
          {library.map((deck) => (
            <option key={deck.id} value={deck.id}>
              {deck.label} — {deck.commander}
            </option>
          ))}
        </select>
      </label>
      <label>
        Commander
        <input
          value={config.commander}
          onChange={(event) => onUpdate(config.seatId, { commander: event.target.value, deck: undefined, status: "empty" })}
          placeholder="Meren of Clan Nel Toth"
        />
      </label>
      <label>
        Deck list
        <textarea
          className="decklist-input"
          value={config.deckList}
          onChange={(event) => onUpdate(config.seatId, { deck: undefined, deckList: event.target.value, mode: "decklist", status: "empty" })}
          placeholder={"Commander: Atraxa, Praetors' Voice\n1 Sol Ring\n1 Arcane Signet\n1 Command Tower\n1 Swords to Plowshares\n1 Beast Within\n...continue to 100 cards"}
        />
      </label>
      <button type="button" disabled={config.status === "building"} onClick={() => onBuild(config)}>
        {config.status === "building" ? "Building..." : config.kind === "agent" ? "Build AI Deck" : "Validate Deck"}
      </button>
      <div className="setup-result">
        <span>{config.message}</span>
        {config.deck ? (
          <>
            <dl>
              <div>
                <dt>Cards</dt>
                <dd>{config.deck.validation.cardCount}</dd>
              </div>
              <div>
                <dt>Score</dt>
                <dd>{config.deck.score.total}</dd>
              </div>
              <div>
                <dt>Game Changers</dt>
                <dd>{config.deck.validation.gameChangerCount}</dd>
              </div>
            </dl>
            {config.deck.validation.errors.length > 0 ? (
              <ul className="setup-errors" aria-label={`${config.name} deck validation errors`}>
                {config.deck.validation.errors.map((error) => (
                  <li key={error}>{error}</li>
                ))}
              </ul>
            ) : null}
            {config.activity.length > 0 ? (
              <ul className="agent-activity" aria-label={`${config.name} agent activity`}>
                {config.activity.map((item) => (
                  <li key={item}>{item}</li>
                ))}
              </ul>
            ) : null}
          </>
        ) : null}
      </div>
    </article>
  );
}

function Topbar({ setupSummary, onBack }: { setupSummary: string; onBack?: () => void }) {
  return (
    <section className="topbar">
      <div>
        <p className="eyebrow">Commander session</p>
        <h1>MTG-AI Commander Lab</h1>
        <p className="topbar-subtitle">{setupSummary}</p>
      </div>
      {onBack ? (
        <button type="button" onClick={onBack}>
          Back To Setup
        </button>
      ) : null}
    </section>
  );
}

function Status(props: { label: string; value: string; detail: string }) {
  return (
    <article className="status">
      <span>{props.label}</span>
      <strong>{props.value}</strong>
      <p>{props.detail}</p>
    </article>
  );
}

// Default decks come from decks/foundations/*.txt via the deck library API (the seats start empty and
// are filled by applyDefaultDecks once the library has loaded): the human seat gets Reign Of Dragons and
// each agent seat (in seat order) one of the other three, all in decklist mode.
const DEFAULT_HUMAN_DECK_LABEL = "Reign Of Dragons";
const DEFAULT_AGENT_DECK_LABELS = ["Wretched Ranks", "Tramplesaurus Rex", "Calling All Angels"];

function createInitialConfigs(seats: PlayerSeat[]): SeatConfig[] {
  return seats.map((seat) => ({
    seatId: seat.id,
    name: seat.name,
    kind: seat.kind,
    mode: seat.kind === "human" ? "decklist" : "commander",
    commander: seat.deck?.commander ?? "",
    deckList: "",
    deck: undefined,
    status: "empty",
    message: "Choose a commander or paste a deck list.",
    activity: []
  }));
}

// Fills seats that still have no deck (nothing typed, loaded or built) with the default Foundations decks.
function applyDefaultDecks(configs: SeatConfig[], library: SavedDeck[]): SeatConfig[] {
  const find = (label: string) => library.find((deck) => deck.id.toLowerCase().startsWith("decks/foundations/") && deck.label.toLowerCase() === label.toLowerCase());
  let agentIndex = 0;
  return configs.map((config) => {
    const label = config.kind === "human" ? DEFAULT_HUMAN_DECK_LABEL : DEFAULT_AGENT_DECK_LABELS[agentIndex++];
    const saved = label ? find(label) : undefined;
    if (!saved || config.deckList.trim() || config.deck) return config;
    return { ...config, mode: "decklist", commander: saved.commander, deckList: saved.deckList, message: "Foundations precon will validate automatically." };
  });
}

function formatDeckList(deck: CommanderDeck) {
  const commander = deck.cards.find((card) => card.role === "commander")?.name ?? deck.commander;
  const cards = deck.cards.filter((card) => card.role !== "commander");
  return [`Commander: ${commander}`, ...cards.map((card) => `${card.count} ${card.name}`)].join("\n");
}

export function validateConfigsForPlay(configs: SeatConfig[]) {
  let ready = true;
  const nextConfigs = configs.map((config) => {
    // Never rebuild a decklist-mode seat's deck here as a fallback: createDeckFromList without a
    // `catalog` (loadCardCatalog() reads the local card data file — a server-only concern this
    // client-side function has no access to) silently enriches nothing, so every non-basic-land
    // card in the deck falls back to createVisibleFromDeckCard's "Mock <role> card. Full rules
    // text will come from card data lookup." placeholder — with fake stats guessed from the deck's
    // color identity and no real oracle text at all. Worse, that placeholder deck still came back
    // fully "legal": unknownErrors (the only check that would have caught missing card data) is
    // itself gated behind `input.catalog` in createDeckFromList, so a mock deck sailed through
    // validation silently and the game started anyway. A seat only ever gets a legitimately
    // enriched config.deck via buildDeck's own /api/decks/build round trip (the one place that
    // actually has the catalog); if that never ran, treat it the same as "no deck built yet"
    // instead of silently substituting a broken one. Reported live as Kodama's Reach, Cultivate,
    // and Three Visits each doing nothing when cast — every one of them, and everything else in
    // the affected deck, had been mock cards with no real rules text the whole game.
    const deck = config.deck;
    const errors = deck?.validation.errors ?? ["Build or validate this deck before pressing Play."];

    if (!deck || errors.length > 0 || !deck.validation.legal) {
      ready = false;
      return {
        ...config,
        status: "error" as DeckBuildStatus,
        message: errors[0] ?? "Deck is not legal for Commander."
      };
    }

    return {
      ...config,
      status: "ready" as DeckBuildStatus,
      message: "Deck passed Commander validation."
    };
  });

  return { ready, configs: nextConfigs };
}

export function applyDeckToSeat(seat: PlayerSeat, deck: CommanderDeck): PlayerSeat {
  const commander = createCommanderCard(deck, seat.board.commander);
  return {
    ...seat,
    deck,
    life: 40,
    commanderDamage: {},
    library: [],
    board: {
      ...seat.board,
      commander,
      hand: [],
      battlefield: [],
      graveyard: [],
      exile: []
    },
    zones: {
      ...seat.zones,
      battlefield: 0,
      graveyard: 0,
      hand: 0,
      exile: 0,
      command: 1
    },
    // This is the only call site that ever builds a fresh game (an in-game command-zone recast
    // just moves the existing commander object between zones, it never goes through
    // createCommanderCard) — going "Back to setup" and pressing PLAY again reuses this same seat
    // object rather than creating a new one, so anything not reset here carries a previous game's
    // state straight into the new one. Reported live as a brand-new game starting with Meren of
    // Clan Nel Toth already bearing counters and its controller already holding 2 experience
    // counters, both left over from the game played before it.
    poison: undefined,
    experienceCounters: undefined,
    hasLost: undefined,
    lossReason: undefined,
    nextSpellHasArtifactAffinity: undefined,
    emblems: undefined
  };
}

function createCommanderCard(deck: CommanderDeck, existing?: VisibleCard): VisibleCard {
  const card = deck.commanderCard;
  return {
    id: existing?.id ?? crypto.randomUUID(),
    name: card?.name ?? deck.commander,
    typeLine: card?.typeLine ?? existing?.typeLine ?? "Legendary Creature - Commander",
    oracleText: card?.oracleText ?? existing?.oracleText ?? "AI-selected commander. Full card text will come from card data lookup in the next integration pass.",
    manaCost: card?.manaCost ?? existing?.manaCost,
    manaValue: card?.manaValue ?? existing?.manaValue ?? 4,
    colors: card?.colors ?? deck.colors,
    colorIdentity: card?.colorIdentity ?? deck.colors,
    producedMana: card?.producedMana ?? existing?.producedMana,
    imageUris: card?.imageUris,
    faces: card?.faces,
    role: "commander",
    zone: "command",
    commander: true,
    // Always a fresh 0/none/false here, never carried over from `existing` — this function only
    // ever runs at the start of a brand-new game (see applyDeckToSeat's own comment), so `existing`
    // is the PREVIOUS game's commander object whenever the same seat played one already. Real
    // in-game commander tax growth (recast from the command zone) never goes through this
    // constructor at all, so there's no legitimate same-game case that needs these to persist here.
    commanderTax: 0,
    power: card?.power ?? existing?.power ?? "3",
    toughness: card?.toughness ?? existing?.toughness ?? "4",
    loyalty: card?.loyalty ?? existing?.loyalty,
    tapped: undefined,
    summoningSick: undefined,
    counters: undefined
  };
}

// hasCardType, not a bare typeLine check: a permanent that's a creature only via a granted type
// (Starfield of Nyx's enchantments, the enchantment-animation feature, man-land animation, ...)
// has that on grantedTypes, not its own printed typeLine, which never changes. A bare typeLine
// check meant none of those could ever attack or block despite genuinely being creatures —
// reported live via this session's man-land audit (Celestial Colonnade correctly became a 4/4 but
// still couldn't attack with it).
// "~ can't attack or block unless you control another creature with power 4 or greater." (Rhonas the Indomitable).
// controllerBattlefield is the permanent's controller's board; without it the restriction is assumed satisfied
// (a caller with no board to check shouldn't wrongly forbid the attack — declareAttack and the legal-action lists
// pass the real board).
function attackBlockRestrictionMet(card: VisibleCard, controllerBattlefield?: VisibleCard[]): boolean {
  if (card.abilitiesStripped || !controllerBattlefield) return true;
  for (const line of card.oracleText.split("\n")) {
    const match = line.replace(/\([^)]*\)/g, "").match(/can'?t attack or block unless you control (?:another|an?) creature with power (\d+) or greater/i);
    if (!match) continue;
    const needed = Number.parseInt(match[1], 10);
    return controllerBattlefield.some((other) => other.id !== card.id && other.typeLine.includes("Creature") && effectivePower(other) >= needed);
  }
  return true;
}

// A creature that arrived after the first attacker was declared this combat can't be declared as an attacker (Utvara Hellkite + Dragon Tempest).
export function attackLockedOut(session: GameSession, card: VisibleCard) {
  return Boolean(session.attackPool && session.attackPool.turn === session.turn && !session.attackPool.ids.includes(card.id));
}

function canAttack(card: VisibleCard, controllerBattlefield?: VisibleCard[]) {
  if (!attackBlockRestrictionMet(card, controllerBattlefield)) return false;
  return hasCardType(card, "Creature") && !card.tapped && !card.phasedOut && (!card.summoningSick || hasHaste(card)) && !card.attacking && !hasDefender(card);
}

// "This creature can't block." (Gravecrawler, Carrion Feeder) / "Razorlash Transmogrant can't block." — the
// creature's OWN restriction, named by "this creature", its full name or its short name. A group
// restriction ("Creatures you control can't block ...") is a different shape and isn't matched here.
// What Zur, Eternal Schemer may point at: a non-Aura enchantment its controller has.
export function animateEnchantmentSpec(seat: PlayerSeat, sourceName: string): TargetSpec {
  return {
    id: "target",
    zone: "battlefield",
    permanentType: "enchantment",
    controller: "you",
    min: 1,
    max: 1,
    excludedCardIds: seat.board.battlefield.filter((card) => isAura(card)).map((card) => card.id),
    prompt: `${sourceName}: choose a non-Aura enchantment you control to become a creature.`
  };
}

export function creatureCantBlock(card: VisibleCard): boolean {
  // "Target creature can't block this turn." is recorded as a temporary pseudo-keyword, like "can't be blocked".
  if (card.temporaryGrantedKeywords?.includes("can't block")) return true;
  if (card.abilitiesStripped) return false;
  const shortName = card.name.toLowerCase().split(" // ")[0].split(",")[0].trim();
  return card.oracleText.split("\n").some((line) => {
    const clause = line.replace(/\([^)]*\)/g, "").trim().toLowerCase().replace(/\.$/, "");
    return clause === "this creature can't block" || clause === `${card.name.toLowerCase()} can't block` || clause === `${shortName} can't block`;
  });
}

// "This creature can't be blocked by creatures with power 2 or less." (Steel Leaf Champion)
function attackerEvadesBlocker(attacker: VisibleCard, blocker: VisibleCard): boolean {
  if (attacker.abilitiesStripped) return false;
  // "Target creature can't be blocked this turn." (Rogue's Passage) is recorded as a temporary pseudo-keyword.
  if (attacker.temporaryGrantedKeywords?.includes("can't be blocked")) return true;
  if (attacker.oracleText.split("\n").some((line) => /^(?:this creature )?can'?t be blocked\.?$/i.test(line.replace(/\([^)]*\)/g, "").trim()))) return true;
  for (const line of attacker.oracleText.split("\n")) {
    const match = line.replace(/\([^)]*\)/g, "").match(/can'?t be blocked by creatures with power (\d+) or less/i);
    if (match && effectivePower(blocker) <= Number.parseInt(match[1], 10)) return true;
  }
  // Champion of Lambholt's static (see the keyword-grant scan in runStateBasedActionsPass).
  for (const keyword of attacker.grantedKeywords ?? []) {
    const below = keyword.match(/^can't be blocked by power below (-?\d+)$/);
    if (below && effectivePower(blocker) < Number.parseInt(below[1], 10)) return true;
  }
  return false;
}

function canBlock(card: VisibleCard, attacker?: VisibleCard, controllerBattlefield?: VisibleCard[]) {
  if (!hasCardType(card, "Creature") || card.tapped || card.phasedOut) return false;
  // A creature that already blocks can block one more attacker when its text allows ("can block an additional creature each combat").
  if (card.blocking && !(canBlockAdditionalCreature(card) && !card.extraBlockingTargetId && attacker && attacker.id !== card.blockingTargetId)) return false;
  if (creatureCantBlock(card)) return false;
  if (!attackBlockRestrictionMet(card, controllerBattlefield)) return false;
  if (attacker && attackerEvadesBlocker(attacker, card)) return false;
  // "Target creature can't block this creature this turn." (Kozilek's Pathfinder)
  if (attacker && card.temporaryGrantedKeywords?.includes("can't block:" + attacker.id)) return false;
  if (attacker && hasFlying(attacker) && !hasFlying(card) && !hasReach(card)) return false;
  // Landwalk: unblockable while the defending player controls a land of that type; "can block only creatures with flying".
  if (attacker && landwalkEvades(attacker, controllerBattlefield)) return false;
  if (attacker && canBlockOnlyFliers(card) && !hasFlying(attacker)) return false;
  if (attacker && isProtectedFrom(attacker, card)) return false;
  // Rule 702.111b: menace requires two or more blockers — enforced where the blockers are assigned together (assignBlockers),
  // since a single creature is only illegal as the WHOLE block, not as one member of a gang block.
  return true;
}

function hasReach(card: VisibleCard) {
  return hasKeyword(card, "reach");
}

function hasMenace(card: VisibleCard) {
  return hasKeyword(card, "menace");
}

function hasTrample(card: VisibleCard) {
  return hasKeyword(card, "trample");
}

function hasFirstStrike(card: VisibleCard) {
  return hasKeyword(card, "first strike");
}

function hasDoubleStrike(card: VisibleCard) {
  return hasKeyword(card, "double strike");
}

// "You can't cast Serra Avenger during your first, second, or third turns of the game." Own-turn number assumes plain
// round-robin turns from the first seat (extra turns shift it by at most one).
function castRestrictedByTurnCount(session: GameSession, card: VisibleCard): boolean {
  if (!/\byou can'?t cast [^.]*? during your first, second, or third turns of the game\b/i.test(card.oracleText)) return false;
  return Math.floor((session.turn - 1) / Math.max(1, session.seats.length)) + 1 <= 3;
}

// "As long as this creature is attacking, creatures can't block unless their controller pays {1} for each of those creatures."
function blockTaxPerBlocker(attacker: VisibleCard): number {
  if (attacker.abilitiesStripped) return 0;
  const match = attacker.oracleText.match(/as long as this creature is attacking, creatures can'?t block unless their controller pays \{(\d+)\} for each of those creatures/i);
  return match ? Number.parseInt(match[1], 10) : 0;
}

function attackerLimitedToOneBlocker(attackerSeat: PlayerSeat, attacker: VisibleCard): boolean {
  return (
    effectivePower(attacker) >= 4 &&
    attackerSeat.board.battlefield.some((card) => !card.abilitiesStripped && /\bcreature you control with power 4 or greater can'?t be blocked by more than one creature\b/i.test(card.oracleText))
  );
}

// "Prevent all combat damage that would be dealt to this creature." (Seraph of the Sword) — combat damage only; other
// damage and "destroy" effects still affect it.
function preventsCombatDamageToSelf(card: VisibleCard): boolean {
  return !card.abilitiesStripped && /\bprevent all (?:combat )?damage that would be dealt to this creature\b/i.test(card.oracleText);
}

export function hasVigilance(card: VisibleCard) {
  return hasKeyword(card, "vigilance");
}

function hasDefender(card: VisibleCard) {
  return hasKeyword(card, "defender");
}

function hasWard(card: VisibleCard) {
  return hasKeyword(card, "ward");
}

function describeKeywords(card: VisibleCard): string[] {
  const keywords: string[] = [];
  if (hasFlying(card)) keywords.push("flying");
  if (hasReach(card)) keywords.push("reach");
  if (hasMenace(card)) keywords.push("menace");
  if (hasDeathtouch(card)) keywords.push("deathtouch");
  if (hasTrample(card)) keywords.push("trample");
  if (hasDoubleStrike(card)) keywords.push("double strike");
  else if (hasFirstStrike(card)) keywords.push("first strike");
  if (hasIndestructible(card)) keywords.push("indestructible");
  if (hasVigilance(card)) keywords.push("vigilance");
  if (hasDefender(card)) keywords.push("defender");
  if (hasHaste(card)) keywords.push("haste");
  if (hasLifelink(card)) keywords.push("lifelink");
  if (hasWither(card)) keywords.push("wither");
  if (hasInfect(card)) keywords.push("infect");
  if (hasHexproof(card)) keywords.push("hexproof");
  if (hasShroud(card)) keywords.push("shroud");
  const ward = cardWardAmount(card.oracleText);
  if (ward !== undefined) keywords.push(`ward {${ward}}`);
  else if (hasWard(card)) keywords.push("ward");
  const protection = allProtectionColors(card);
  if (protection.length > 0) keywords.push(`protection from ${protection.join(" and ")}`);
  return keywords;
}

export function resolveAttackTarget(session: GameSession, targetId: string | undefined): { seat: PlayerSeat; planeswalker?: VisibleCard } | undefined {
  if (!targetId) return undefined;
  const seat = session.seats.find((item) => item.id === targetId);
  if (seat) return { seat };
  for (const candidate of session.seats) {
    const planeswalker = candidate.board.battlefield.find((card) => card.id === targetId && isPlaneswalkerCard(card));
    if (planeswalker) return { seat: candidate, planeswalker };
  }
  return undefined;
}

// "...where X is the number of creatures attacking you." (Arachnogenesis) — counts only attackers
// whose target IS the named seat itself (the player), not a planeswalker that seat controls (real
// wording says "attacking you," not "attacking you or a planeswalker you control").
export function countCreaturesAttackingSeat(session: GameSession, seatId: string): number {
  let count = 0;
  for (const seat of session.seats) {
    for (const card of seat.board.battlefield) {
      if (!card.attacking) continue;
      const target = resolveAttackTarget(session, card.attackTargetId);
      if (target && target.seat.id === seatId && !target.planeswalker) count += 1;
    }
  }
  return count;
}

function markAttackDecided(session: GameSession, seatId: string, cardId: string): GameSession {
  return {
    ...session,
    seats: session.seats.map((seat) =>
      seat.id === seatId
        ? {
            ...seat,
            board: {
              ...seat.board,
              battlefield: seat.board.battlefield.map((card) => (card.id === cardId ? { ...card, blockDecided: true } : card))
            }
          }
        : seat
    )
  };
}

// Reuses the same "+1/+1" counter kind the manual inspector +/- controls already write, so
// counters gained either way stay consistent.
function plusOneCounterCount(card: VisibleCard) {
  return card.counters?.find((counter) => counter.kind === "+1/+1")?.count ?? 0;
}

type AuraAttachResult =
  | { kind: "attach"; seatId: string; cardId: string }
  | { kind: "attach_player"; seatId: string }
  | { kind: "no_target" }
  | { kind: "unsupported" };

// No interactive targeting exists for Auras, so this picks a legal target deterministically:
// "Enchant creature you control" (or a positive/buff aura with an unrestricted "Enchant
// creature") targets the caster's own best creature; a removal-style aura (Pacifism, "can't
// attack or block") targets the best opposing creature instead.
function chooseAuraAttachTarget(session: GameSession, casterSeatId: string, oracleText: string): AuraAttachResult {
  const restriction = enchantRestriction(oracleText);
  if (restriction === "player") {
    // Shadow of the Second Sun is the one printed "Enchant player" exception to the "always a
    // hoser, never self-targeted" assumption below — its extra untap/upkeep/draw is a benefit to
    // whoever it's on, so casting it on anyone but yourself would be pointless. Reported live: cast
    // on an opponent by the general "pick a target" logic below, the caster's own postcombat main
    // phase never matched hasExtraBeginningPhaseAura(session, activeSeat.id) (attachedToSeatId
    // pointed at the wrong seat), so the extra phase never fired for the player who actually wanted it.
    if (attachmentGrantsExtraBeginningPhase(oracleText)) return { kind: "attach_player", seatId: casterSeatId };
    // "Enchant player" (Overwhelming Splendor, the Curse cycle, ...) is overwhelmingly a hoser
    // aimed at an opponent rather than the caster's own player — so pick the opponent who looks
    // like the biggest threat (highest life total), mirroring chooseRemovalTarget's "biggest
    // threat" tie-break below.
    const opponents = session.seats.filter((seat) => seat.id !== casterSeatId && !seat.hasLost);
    if (opponents.length === 0) return { kind: "no_target" };
    const best = opponents.reduce((a, b) => (b.life > a.life ? b : a));
    return { kind: "attach_player", seatId: best.id };
  }
  if (restriction === undefined || restriction === "other" || restriction === "permanent") return { kind: "unsupported" };

  const targetOwn = restriction === "creature_you_control" || !isRemovalStyleAura(oracleText);
  const candidates: Array<{ seatId: string; card: VisibleCard }> = [];
  for (const seat of session.seats) {
    if (targetOwn ? seat.id !== casterSeatId : seat.id === casterSeatId) continue;
    for (const card of seat.board.battlefield) {
      if (card.typeLine.includes("Creature")) candidates.push({ seatId: seat.id, card });
    }
  }
  if (candidates.length === 0) return { kind: "no_target" };

  const best = candidates.reduce((a, b) =>
    effectivePower(b.card) + effectiveToughness(b.card) > effectivePower(a.card) + effectiveToughness(a.card) ? b : a
  );
  return { kind: "attach", seatId: best.seatId, cardId: best.card.id };
}

// Continuous effects (Aura attachments, Equip) are stamped with a monotonic counter, not
// wall-clock time, so layer 7b can deterministically pick "the newest one" when more than one
// "set base power/toughness" effect ends up on the same creature.
function nextTimestamp(session: GameSession): { timestamp: number; session: GameSession } {
  const timestamp = session.effectTimestampCounter ?? 0;
  return { timestamp, session: { ...session, effectTimestampCounter: timestamp + 1 } };
}

function applyAuraAttachment(session: GameSession, casterSeatId: string, auraCardId: string, targetSeatId: string, targetCardId: string): GameSession {
  const { timestamp, session: stampedSession } = nextTimestamp(session);
  return {
    ...stampedSession,
    seats: stampedSession.seats.map((seat) =>
      seat.id === casterSeatId
        ? {
            ...seat,
            board: {
              ...seat.board,
              battlefield: seat.board.battlefield.map((card) => (card.id === auraCardId ? { ...card, attachedToId: targetCardId, attachTimestamp: timestamp } : card))
            }
          }
        : seat
    ),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId: casterSeatId,
        message: `${session.seats.find((seat) => seat.id === casterSeatId)?.board.battlefield.find((card) => card.id === auraCardId)?.name ?? "Aura"} attaches to ${
          session.seats.find((seat) => seat.id === targetSeatId)?.board.battlefield.find((card) => card.id === targetCardId)?.name ?? "a creature"
        }.`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

function applyAuraAttachToPlayer(session: GameSession, casterSeatId: string, auraCardId: string, targetSeatId: string): GameSession {
  const { timestamp, session: stampedSession } = nextTimestamp(session);
  return {
    ...stampedSession,
    seats: stampedSession.seats.map((seat) =>
      seat.id === casterSeatId
        ? {
            ...seat,
            board: {
              ...seat.board,
              battlefield: seat.board.battlefield.map((card) =>
                card.id === auraCardId ? { ...card, attachedToSeatId: targetSeatId, attachTimestamp: timestamp } : card
              )
            }
          }
        : seat
    ),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId: casterSeatId,
        message: `${session.seats.find((seat) => seat.id === casterSeatId)?.board.battlefield.find((card) => card.id === auraCardId)?.name ?? "Aura"} attaches to ${
          session.seats.find((seat) => seat.id === targetSeatId)?.name ?? "a player"
        }.`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

// Rule 500.7: "Take an extra turn after this one." (Temporal Mastery, Time Warp, Nexus of Fate,
// ...) — matched narrowly to this exact, extremely consistent real-card phrasing, same "only the
// well-templated shape, no guessing" boundary as the rest of this file's deterministic parsers.
// "Untap all lands you control. You get an emblem..."-style variants with additional clauses on the
// same card (Karn's Temporal Sundering, Time Walk's "you may play an additional land"-adjacent
// text) still match here for the extra-turn half — this only ever grants the turn, not any other
// clause bundled onto the same spell, since those are handled by their own respective parsers.
export function grantsExtraTurn(oracleText: string): boolean {
  return /\btake an extra turn after this one\b/i.test(oracleText);
}

function entersWithXCounters(oracleText: string): boolean {
  return /\benters?(?: the battlefield)? with x \+1\/\+1 counters? on (?:it|this (?:creature|artifact|permanent))\b/i.test(oracleText);
}

// "This artifact enters with a charge counter on it for each time it was kicked." (Everflowing
// Chalice, and the rest of the multikicker-charge-counter cycle) — without this, a multikicker
// artifact that only ever tracks +1/+1 counters (entersWithXCounters, creature-only) never got its
// charge counters at all, so its own "add {C} for each charge counter" ability always produced
// nothing, kicked or not — the actual bug reported: an agent paid {0} (never kicked, since nothing
// ever offered a reason to) and the game never even understood a kicked cast would have done
// anything different.
function entersWithChargeCounterPerKick(oracleText: string): boolean {
  return /\benters? (?:the battlefield )?with a charge counter on it for each time it was kicked\b/i.test(oracleText);
}

// The controller's full owned card pool for pickChosenCreatureType/pickChosenColor — prefers the
// deck list (so a tribal/mono-color-heavy deck picks its actual theme even before any copies have
// been drawn) and falls back to whatever visible zones exist when there's no deck record
// (synthetic/test sessions).
function controllerCardPool(seat: PlayerSeat): Array<{ typeLine: string; manaCost?: string }> {
  const deckCards = seat.deck?.cards.flatMap((entry) => (entry.card ? [entry.card] : [])) ?? [];
  if (deckCards.length > 0) return deckCards;
  return [...seat.board.hand, ...seat.board.battlefield, ...(seat.board.graveyard ?? []), ...(seat.library ?? [])];
}

function applyChosenCreatureType(session: GameSession, seatId: string, cardId: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  const permanent = seat?.board.battlefield.find((card) => card.id === cardId);
  if (!seat || !permanent || permanent.chosenCreatureType) return session;
  const chosenType = pickChosenCreatureType(controllerCardPool(seat));
  if (!chosenType) return session;
  return {
    ...session,
    seats: session.seats.map((item) =>
      item.id === seatId
        ? { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((card) => (card.id === cardId ? { ...card, chosenCreatureType: chosenType } : card)) } }
        : item
    )
  };
}

function applyChosenColor(session: GameSession, seatId: string, cardId: string, excludedColor: ManaColorLetter | undefined): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  const permanent = seat?.board.battlefield.find((card) => card.id === cardId);
  if (!seat || !permanent || permanent.chosenColor) return session;
  const chosenColor = pickChosenColor(controllerCardPool(seat), excludedColor);
  if (!chosenColor) return session;
  return {
    ...session,
    seats: session.seats.map((item) =>
      item.id === seatId
        ? { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((card) => (card.id === cardId ? { ...card, chosenColor } : card)) } }
        : item
    )
  };
}

// Only matches the self-referential "When this creature enters, it explores" phrasing (Jadelight
// Spelunker-style) — explore triggered by other conditions (combat, gaining life, ...) isn't
// covered, since this engine has no generic "whenever X, do Y" trigger-condition system yet.
function exploreCount(oracleText: string): number | undefined {
  const match = oracleText.toLowerCase().match(/when(?:ever)? this creature enters,?\s+(?:it\s+)?explores?(?:\s+(x|\d+|one|two|three)\s+times?)?/);
  if (!match) return undefined;
  return numberWordToInt(match[1]) ?? 1;
}

// "Reveal the top card of your library. Put that card into your hand if it's a land. Otherwise,
// put a +1/+1 counter on this creature, then put the card back or put it into your graveyard."
// With no choice UI, defaults to keeping a non-land card on top rather than milling it.
function resolveExplore(session: GameSession, seatId: string, cardId: string, times: number): GameSession {
  let next = session;
  for (let iteration = 0; iteration < times; iteration += 1) {
    const seat = next.seats.find((item) => item.id === seatId);
    const topCard = seat?.library?.[0];
    if (!seat || !topCard) break;
    const isLand = topCard.typeLine.includes("Land");
    next = {
      ...next,
      seats: next.seats.map((item) => {
        if (item.id !== seatId) return item;
        if (isLand) {
          return {
            ...item,
            library: (item.library ?? []).slice(1),
            board: { ...item.board, hand: [...item.board.hand, { ...topCard, zone: "hand" as const }] },
            zones: { ...item.zones, hand: item.zones.hand + 1, library: Math.max(0, item.zones.library - 1) }
          };
        }
        return {
          ...item,
          board: {
            ...item.board,
            battlefield: item.board.battlefield.map((card) => (card.id === cardId ? applyCounterDelta(card, "+1/+1", 1) : card))
          }
        };
      }),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: isLand
            ? `${seat.name} explores: reveals ${topCard.name}, a land, and puts it into hand.`
            : `${seat.name} explores: reveals ${topCard.name}, not a land, puts a +1/+1 counter on it, and keeps ${topCard.name} on top.`,
          detail: "Rules action"
        },
        ...next.events
      ]
    };
  }
  return next;
}

function isMainPhase(phase: string) {
  return phase === "precombat main phase" || phase === "postcombat main phase";
}

const DEFAULT_MAX_HAND_SIZE = 7;

// Rule 402.2: only the very common, consistently-worded "you have no maximum hand size" grant is
// recognized here (Spellbook, Thought Reflection, Reliquary Tower, ...) — matching this codebase's
// existing pattern of handling the standard real-card phrasing deterministically and declining
// rarer/looser shapes (a numeric override like "your maximum hand size is X" isn't modeled) rather
// than guessing at them.
function hasNoMaximumHandSize(seat: PlayerSeat): boolean {
  if (seat.noMaximumHandSize) return true;
  const permanents = [seat.board.commander, ...seat.board.battlefield].filter((card): card is VisibleCard => Boolean(card));
  return permanents.some((card) => /\bno maximum hand size\b/i.test(card.oracleText));
}

function effectiveMaxHandSize(seat: PlayerSeat): number {
  return hasNoMaximumHandSize(seat) ? Number.POSITIVE_INFINITY : DEFAULT_MAX_HAND_SIZE;
}

function loyaltyTurnKey(seatId: string, cardId: string, turn: number) {
  return `${turn}:${seatId}:${cardId}`;
}

function formatLoyaltyCost(cost: number) {
  return cost > 0 ? `+${cost}` : `${cost}`;
}

function isCumulativeUpkeepCard(card: VisibleCard) {
  return /\bcumulative upkeep\b/i.test(card.oracleText);
}

function cumulativeUpkeepCost(card: VisibleCard) {
  const ageCounters = card.counters?.find((counter) => counter.kind === "age")?.count ?? 0;
  const text = card.oracleText.toLowerCase();
  const genericMatch = text.match(/cumulative upkeep\s*\{(\d+)\}/);
  const base = genericMatch ? Number.parseInt(genericMatch[1], 10) : 1;
  return Math.max(1, base) * (ageCounters + 1);
}

export function legalMainPhaseActions(
  seat: PlayerSeat,
  hasPlayedLand: boolean,
  activeSeatId: string | undefined,
  turn: number,
  activatedLoyaltyKeys: Set<string>,
  session: GameSession
): LegalAgentAction[] {
  const actions: LegalAgentAction[] = [];
  if (!hasPlayedLand) {
    for (const card of seat.board.hand) {
      const split = modalDoubleFacedLandSplit(card);
      if (split) {
        actions.push({
          id: `play-land:${card.id}:face${split.landIndex}`,
          actionType: "play_land",
          cardId: card.id,
          faceIndex: split.landIndex,
          targetIds: [],
          label: `play ${split.landFace.name} (land side of ${card.name})`,
          detail: `${split.landFace.oracleText} (land drop available this turn)`.trim(),
          role: card.role
        });
        continue;
      }
      if (isLandCard(card)) {
        actions.push({
          id: `play-land:${card.id}`,
          actionType: "play_land",
          cardId: card.id,
          targetIds: [],
          label: `play land ${card.name}`,
          detail: `${card.oracleText} (land drop available this turn)`.trim(),
          role: card.role
        });
      }
    }
    // A land this seat was given permission to play from exile (a hideaway land's free play) uses the land drop like any other.
    for (const card of seat.board.exile ?? []) {
      if (card.exiledPlayableBySeatId !== seat.id || !isLandCard(card)) continue;
      if (card.exiledPlayableUntilTurn !== undefined && turn > card.exiledPlayableUntilTurn) continue;
      actions.push({
        id: `play-land-exile:${card.id}`,
        actionType: "play_land",
        cardId: card.id,
        sourceZone: "exile",
        targetIds: [],
        label: `play land ${card.name} from exile`,
        detail: `${card.oracleText} (land drop available this turn)`.trim(),
        role: card.role
      });
    }
  }
  for (const card of seat.board.hand) {
    const split = modalDoubleFacedLandSplit(card);
    if (split) {
      const totalCost = adjustedCastingCost(seat, card, card.manaValue, "hand", activeSeatId, session.seats);
      const payment = chooseManaSourcesForCost(seat, card, totalCost, undefined, session.seats);
      // hasResolvableTarget reads oracleText/typeLine off whatever card it's given — the top-level
      // VisibleCard fields describe the *primary* face, not necessarily this spell face (Malakir
      // Rebirth // Malakir Mire and the rest of the Zendikar Rising MDFC cycle put the spell face
      // first, so this happens to already line up for that cycle, but relying on that would silently
      // stop working for any MDFC printed the other way round). Building a shim from split.spellFace
      // keeps this correct regardless of face order, so a target-requiring spell face (e.g. "return
      // target creature card from your graveyard") with no legal target is never offered as castable.
      if (payment.ok && hasResolvableTarget(session, seat.id, { ...card, name: split.spellFace.name, typeLine: split.spellFace.typeLine, oracleText: split.spellFace.oracleText })) {
        actions.push({
          id: `cast:${card.id}:face${split.spellIndex}`,
          actionType: "cast_spell",
          cardId: card.id,
          faceIndex: split.spellIndex,
          targetIds: [],
          label: `cast ${split.spellFace.name}`,
          detail: `${split.spellFace.manaCost ?? ""} ${split.spellFace.typeLine}. ${split.spellFace.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
          role: card.role
        });
      }
      continue;
    }

    const doors = roomDoorFaces(card);
    if (doors) {
      doors.forEach((door, index) => {
        const shim = cardWithFaceManaCost(card, door.manaCost);
        const totalCost = adjustedCastingCost(seat, shim, manaValueFromManaCost(door.manaCost), "hand", activeSeatId, session.seats);
        const payment = chooseManaSourcesForCost(seat, shim, totalCost, undefined, session.seats);
        if (!payment.ok) return;
        actions.push({
          id: `cast:${card.id}:face${index}`,
          actionType: "cast_spell",
          cardId: card.id,
          faceIndex: index,
          targetIds: [],
          label: `cast ${door.name} (unlock this door)`,
          detail: `${door.manaCost ?? ""} ${door.typeLine}. ${door.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
          role: card.role
        });
      });
      continue;
    }

    const spellFaces = independentlyCastableSpellFaces(card);
    if (spellFaces) {
      spellFaces.forEach((face, index) => {
        // An aftermath half is only castable from the graveyard; every half is priced from its OWN cost, type and text (never the combined card's).
        if (!spellFaceCastableFromHand(face)) return;
        const shim = spellFaceCostCard(card, face);
        const baseCost = shim.manaValue;
        const fixedCost = adjustedCastingCost(seat, shim, baseCost, "hand", activeSeatId, session.seats);
        const chosenX = maxAffordableX(seat, shim, fixedCost);
        const totalCost = totalCastingCost(seat, shim, baseCost, chosenX, session.seats);
        const payment = chooseManaSourcesForCost(seat, shim, totalCost, undefined, session.seats);
        if (!payment.ok) return;
        if (!hasResolvableTarget(session, seat.id, { ...card, name: face.name, typeLine: face.typeLine, oracleText: face.oracleText })) return;
        const xNote = chosenX > 0 ? ` Casting for X=${chosenX}.` : "";
        actions.push({
          id: `cast:${card.id}:face${index}`,
          actionType: "cast_spell",
          cardId: card.id,
          faceIndex: index,
          targetIds: [],
          label: chosenX > 0 ? `cast ${face.name} (X=${chosenX})` : `cast ${face.name}`,
          detail: `${face.manaCost ?? ""} ${face.typeLine}. ${face.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.${xNote}`.trim(),
          role: card.role
        });
      });
      continue;
    }

    if (isLandCard(card)) continue;
    if (castRestrictedByTurnCount(session, card)) continue;
    if (spellCastLockedOut(session, seat.id, activeSeatId)) continue;

    const fixedCost = adjustedCastingCost(seat, card, card.manaValue, "hand", activeSeatId, session.seats);
    const chosenX = maxAffordableX(seat, card, fixedCost);
    const totalCost = totalCastingCost(seat, card, card.manaValue, chosenX, session.seats);
    let payment = chooseManaSourcesForCost(seat, card, totalCost, undefined, session.seats);
    // An alternative cost (Sephara) that lets an otherwise unaffordable spell be cast.
    const legalTapAlt = tapCreaturesAltCostFor(seat, card);
    if (legalTapAlt) {
      const altPayment = chooseManaSourcesForCost(seat, cardWithFaceManaCost(card, legalTapAlt.costManaText), manaValueFromManaCost(legalTapAlt.costManaText), undefined, session.seats);
      if (altPayment.ok) payment = altPayment;
    }
    if (!payment.ok) continue;
    if (!hasResolvableTarget(session, seat.id, card)) continue;
    const xNote = chosenX > 0 ? ` Casting for X=${chosenX}.` : "";
    actions.push({
      id: `cast:${card.id}`,
      actionType: "cast_spell",
      cardId: card.id,
      targetIds: [],
      label: chosenX > 0 ? `cast ${card.name} (X=${chosenX})` : `cast ${card.name}`,
      detail: `${card.manaCost ?? ""} ${card.typeLine}. ${card.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.${xNote}`.trim(),
      role: card.role
    });
  }
  // Cards exiled by an impulse-draw/steal-and-play effect (see zoneEffects.ts), or by casting an
  // Adventure card's spell half (see spellResolutionDestination's "exile" branch), that this seat
  // is currently permitted to cast — land-plays from exile aren't offered (a deliberate scope
  // limit, see playCard's playingAsLand branch, which only ever removes from hand). Scanned across
  // every seat's exile, not just this one's own: a card exiled by an effect like Mind's Dilation's
  // physically sits in its OWNER's exile, which can be a different seat than the one permitted to
  // cast it (see playCardFromZone's own cross-seat handling).
  for (const card of session.seats.flatMap((s) => s.board.exile ?? [])) {
    if (card.exiledPlayableBySeatId !== seat.id || isLandCard(card)) continue;
    if (card.exiledPlayableUntilTurn !== undefined && turn > card.exiledPlayableUntilTurn) continue;
    // An Adventure/Omen-shaped card in exile can only be cast as its OTHER (permanent) face from
    // here on — the spell half is what got it exiled in the first place, and real rules don't let
    // it be cast again. Simplification: this also applies to the much rarer case of an Adventure
    // card exiled by an unrelated impulse-draw/steal effect before either face was ever cast, where
    // real rules would actually allow choosing either face — declined in favor of always offering
    // the permanent face, since nothing here tracks whether this specific exiled copy has already
    // used its spell half.
    const spellFaces = independentlyCastableSpellFaces(card);
    const permanentFace = spellFaces?.find((face) => !face.typeLine.includes("Adventure") && !face.typeLine.includes("Omen"));
    const permanentFaceIndex = permanentFace ? spellFaces!.indexOf(permanentFace) : undefined;
    const castCard = permanentFace ? cardWithFaceManaCost(card, permanentFace.manaCost) : card;
    const baseCost = permanentFace ? manaValueFromManaCost(permanentFace.manaCost) : card.manaValue;
    const fixedCost = adjustedCastingCost(seat, castCard, baseCost, "exile", activeSeatId, session.seats);
    // "Without paying its mana cost" (a hideaway land's free play, Mind's Dilation, ...): playCard charges nothing for such a cast
    // (its costWaived rule), so the listing must not price the spell at its printed cost either. Pricing it in full hid the card from
    // an agent that could not afford the real cost, e.g. Mosswort Bridge's hidden card was never offered after the ability was paid.
    const costWaivedHere = baseCost > 0 && fixedCost === 0;
    const chosenX = costWaivedHere ? 0 : maxAffordableX(seat, castCard, fixedCost);
    const totalCost = costWaivedHere ? fixedCost : totalCastingCost(seat, castCard, baseCost, chosenX, session.seats);
    const payment = chooseManaSourcesForCost(seat, castCard, totalCost, undefined, session.seats);
    if (!payment.ok) continue;
    const targetCheckCard = permanentFace ? { ...card, name: permanentFace.name, typeLine: permanentFace.typeLine, oracleText: permanentFace.oracleText } : card;
    if (!hasResolvableTarget(session, seat.id, targetCheckCard)) continue;
    actions.push({
      id: `cast-exile:${card.id}`,
      actionType: "cast_spell",
      cardId: card.id,
      sourceZone: "exile",
      faceIndex: permanentFaceIndex,
      targetIds: [],
      label: `cast ${permanentFace?.name ?? card.name} from exile`,
      detail: permanentFace
        ? `${permanentFace.manaCost ?? ""} ${permanentFace.typeLine}. ${permanentFace.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim()
        : `${card.manaCost ?? ""} ${card.typeLine}. ${card.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
      role: card.role
    });
  }
  // Cards in this seat's own graveyard it may cast from there: flashback (Army of the Damned, Moan of the
  // Unhallowed), a standing "you may cast this card from your graveyard" (Gravecrawler), or a one-turn grant
  // (Zul Ashur). See graveyardCasting.ts.
  for (const card of seat.board.graveyard ?? []) {
    const permission = graveyardCastPermission(card, { seatId: seat.id, turn, controllerBattlefield: seat.board.battlefield });
    if (!permission) continue;
    const castCard = permission.costText ? cardWithFaceManaCost(card, permission.costText) : card;
    const baseCost = permission.costText ? manaValueFromManaCost(permission.costText) : card.manaValue;
    const fixedCost = adjustedCastingCost(seat, castCard, baseCost, "graveyard", activeSeatId, session.seats);
    const chosenX = maxAffordableX(seat, castCard, fixedCost);
    const totalCost = totalCastingCost(seat, castCard, baseCost, chosenX, session.seats);
    const payment = chooseManaSourcesForCost(seat, castCard, totalCost, undefined, session.seats);
    if (!payment.ok) continue;
    if (!hasResolvableTarget(session, seat.id, card)) continue;
    actions.push({
      id: `cast-graveyard:${card.id}`,
      actionType: "cast_spell",
      cardId: card.id,
      sourceZone: "graveyard",
      targetIds: [],
      label: `cast ${card.name} from the graveyard${permission.kind === "flashback" ? " (flashback)" : ""}`,
      detail: `${permission.costText ?? card.manaCost ?? ""} ${card.typeLine}. ${card.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
      role: card.role
    });
  }
  // The top card of the library, when a permanent lets it be cast from there (Thundermane Dragon).
  const topCard = (seat.library ?? [])[0];
  // (A land on top, playable with One with the Multiverse, is a human's land play; agents are not offered it as a cast.)
  if (topCard && !isLandCard(topCard) && libraryTopCastPermission(topCard, seat.board.battlefield)) {
    const fixedCost = adjustedCastingCost(seat, topCard, topCard.manaValue, "library", activeSeatId, session.seats);
    const chosenX = maxAffordableX(seat, topCard, fixedCost);
    const totalCost = totalCastingCost(seat, topCard, topCard.manaValue, chosenX, session.seats);
    const payment = chooseManaSourcesForCost(seat, topCard, totalCost, undefined, session.seats);
    if (payment.ok && hasResolvableTarget(session, seat.id, topCard)) {
      actions.push({
        id: `cast-library:${topCard.id}`,
        actionType: "cast_spell",
        cardId: topCard.id,
        sourceZone: "library",
        targetIds: [],
        label: `cast ${topCard.name} from the top of the library`,
        detail: `${topCard.manaCost ?? ""} ${topCard.typeLine}. ${topCard.oracleText} It gains haste. Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
        role: topCard.role
      });
    }
  }
  actions.push(...legalRoomUnlockActions(seat, session.seats));
  const commander = seat.board.commander;
  if (commander) {
    const totalCost = adjustedCastingCost(seat, commander, commander.manaValue, "command", activeSeatId, session.seats) + (commander.commanderTax ?? 0);
    const payment = chooseManaSourcesForCost(seat, commander, totalCost, undefined, session.seats);
    if (payment.ok && hasResolvableTarget(session, seat.id, commander)) {
      actions.push({
        id: `cast-commander:${commander.id}`,
        actionType: "cast_commander",
        cardId: commander.id,
        targetIds: [],
        label: `cast commander ${commander.name}`,
        detail: `${commander.manaCost ?? ""} commander tax ${commander.commanderTax ?? 0}. ${commander.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
        role: commander.role
      });
    }
  }
  // Cycling (Barren Moor, Forgotten Cave, Tranquil Thicket): trade a surplus land for a fresh card. Offered only when the seat is already
  // flooded — six or more lands in play, or four-plus with this turn's land drop used.
  const landsInPlay = seat.board.battlefield.filter((permanent) => isLandCard(permanent)).length;
  const handHasLand = seat.board.hand.some((card) => isLandCard(card));
  for (const card of seat.board.hand) {
    const cycling = parseCycling(card.oracleText);
    // Landcycling (Angel of the Ruins' Plainscycling): the seven-drop is dead weight early, and the fetched land is what it needs.
    if (cycling?.searchType && !handHasLand && landsInPlay <= 4 && card.manaValue > landsInPlay + 1 && chooseManaSourcesForCost(seat, genericManaAbilityCostShim({ costManaText: cycling.costManaText }), manaValueFromManaCost(cycling.costManaText), undefined, session.seats).ok) {
      actions.push({
        id: `cycle:${card.id}`,
        actionType: "activate_ability",
        abilityKind: "cycling",
        cardId: card.id,
        targetIds: [],
        label: `${cycling.searchType.toLowerCase()}cycle ${card.name}`,
        detail: `${cycling.searchType}cycling ${cycling.costManaText}: discard this card to search for a ${cycling.searchType} card (you have ${landsInPlay} lands and none in hand).`,
        role: card.role
      });
    }
  }
  if (landsInPlay >= 6 || (hasPlayedLand && landsInPlay >= 4)) {
    for (const card of seat.board.hand) {
      const cycling = parseCycling(card.oracleText);
      if (cycling?.searchType) continue;
      if (!cycling || !chooseManaSourcesForCost(seat, genericManaAbilityCostShim({ costManaText: cycling.costManaText }), manaValueFromManaCost(cycling.costManaText), undefined, session.seats).ok) continue;
      actions.push({
        id: `cycle:${card.id}`,
        actionType: "activate_ability",
        abilityKind: "cycling",
        cardId: card.id,
        targetIds: [],
        label: `cycle ${card.name}`,
        detail: `Cycling ${cycling.costManaText}: discard this card to draw a card (you have ${landsInPlay} lands in play).`,
        role: card.role
      });
    }
  }
  actions.push(...legalActivatedAbilityActions(seat, true, turn, activatedLoyaltyKeys, session, !hasPlayedLand));
  actions.push({ id: "pass-phase", actionType: "pass_priority", targetIds: [], label: "pass this phase" });
  actions.push({ id: "end-turn", actionType: "end_turn", targetIds: [], label: "end turn and skip remaining phases" });
  // This list is the stack-empty main-phase list: a "counter target spell" card has nothing to target here (rule 601.2c), so it is never offered.
  // (Reported live: Sable cast Swan Song on turn 1 with nothing on the stack.) Responses are a separate list that does check the stack.
  return actions.filter((action) => {
    if (action.actionType !== "cast_spell" || !action.cardId) return true;
    const handCard = seat.board.hand.find((card) => card.id === action.cardId);
    return !handCard || !isTargetedCounterspell(handCard);
  });
}

// A card whose spell is "Counter target ... spell" (Swan Song, Counterspell, Negate, ...) and is not a modal card that may have a non-counter mode.
function isTargetedCounterspell(card: { oracleText: string }): boolean {
  return Boolean(parseCounterSpellAbility(card.oracleText)) && !parseModalHeader(card.oracleText);
}

function hasAgentMainPhaseAction(seat: PlayerSeat, hasPlayedLand: boolean, activeSeatId: string | undefined, turn: number, activatedLoyaltyKeys: Set<string>, session: GameSession) {
  return legalMainPhaseActions(seat, hasPlayedLand, activeSeatId, turn, activatedLoyaltyKeys, session).some((action) =>
    action.actionType === "play_land" || action.actionType === "cast_spell" || action.actionType === "cast_commander" || action.actionType === "activate_ability"
  );
}

function clearCombatState(session: GameSession): GameSession {
  return {
    ...session,
    attackPool: undefined,
    seats: session.seats.map((seat) => ({
      ...seat,
      zones: seat.board.battlefield.some((card) => card.exileAtEndOfCombat) ? { ...seat.zones, battlefield: seat.zones.battlefield - seat.board.battlefield.filter((card) => card.exileAtEndOfCombat).length } : seat.zones,
      board: {
        ...seat.board,
        // Myriad tokens are exiled at end of combat.
        battlefield: seat.board.battlefield.filter((card) => !card.exileAtEndOfCombat).map((card) => ({
          ...card,
          attacking: false,
          attackTargetId: undefined,
          blockDecided: false,
          blocking: false,
          blockingTargetId: undefined,
          extraBlockingTargetId: undefined
        }))
      }
    }))
  };
}

// "Until end of turn" effects (prowess, combat pumps, ...) expire when the turn ends.
export function clearTemporaryBuffs(session: GameSession): GameSession {
  const withBuffsCleared: GameSession = {
    ...session,
    seats: session.seats.map((seat) => ({
      ...seat,
      // Safety net for "the next spell you cast this turn" if no spell was ever cast — the normal
      // consumption path is checkCastTriggeredKeywords, which only runs when a spell is cast.
      nextSpellHasArtifactAffinity: undefined,
      createdTokenThisTurn: undefined,
      // Snapshot at each turn change: "if you gained life this turn" (Witch of the Moors, Moseo, Eccentric Pestfinder) reads as life now above this.
      lifeAtTurnStart: seat.life,
      board: {
        ...seat.board,
        // Every until-end-of-turn field is cleared together: a creature can carry several at once (a pump that also grants trample,
        // Nogi's temporary Dragon P/T plus a keyword), and clearing only the first kind found left the rest on all game.
        battlefield: seat.board.battlefield.map((card) =>
          card.temporaryPowerBonus ||
          card.temporaryToughnessBonus ||
          card.temporaryBasePower !== undefined ||
          card.temporaryBaseToughness !== undefined ||
          card.temporaryAbilitiesStripped ||
          card.temporaryAnimatedAsCreature ||
          card.temporaryGrantedKeywords ||
          card.temporaryOriginalTypeLine !== undefined ||
          card.temporaryCopyOriginal ||
          card.damagedPlayersThisTurn ||
          card.damage
            ? {
                ...card,
                damage: undefined,
                damagedPlayersThisTurn: undefined,
                ...(card.temporaryCopyOriginal ? { ...card.temporaryCopyOriginal, temporaryCopyOriginal: undefined } : {}),
                temporaryPowerBonus: undefined,
                temporaryToughnessBonus: undefined,
                temporaryBasePower: undefined,
                temporaryBaseToughness: undefined,
                temporaryAbilitiesStripped: undefined,
                temporaryAnimatedAsCreature: undefined,
                temporaryGrantedKeywords: undefined,
                // The layer pass recomputes grantedKeywords on the next state check; dropping the temporary ones now keeps it right in between.
                ...(card.temporaryGrantedKeywords?.length ? { grantedKeywords: card.grantedKeywords?.filter((keyword) => !card.temporaryGrantedKeywords!.includes(keyword)) } : {}),
                ...(card.temporaryOriginalTypeLine !== undefined ? { typeLine: card.temporaryOriginalTypeLine, temporaryOriginalTypeLine: undefined } : {})
              }
            : card
        )
      }
    }))
  };

  // Revert any "gain control...until end of turn" changes (Threaten-style) back to the true
  // owner's battlefield — same timing as the power/toughness buffs above.
  const reverting = withBuffsCleared.seats.flatMap((seat) =>
    seat.board.battlefield.filter((card) => card.temporaryControlChange).map((card) => ({ fromSeatId: seat.id, cardId: card.id, toSeatId: card.ownerSeatId ?? seat.id }))
  );
  const controlReverted = reverting.reduce(
    (next, entry) => (entry.fromSeatId === entry.toSeatId ? next : changeControlWithinBattlefield(next, entry.cardId, entry.fromSeatId, entry.toSeatId)),
    withBuffsCleared
  );

  // Time-limited exile-play permission (impulse draw's "until end of turn"/"until the end of your
  // next turn") that's expired — the card just stays exiled, it isn't destroyed or moved.
  // controlReverted.turn is already the NEW turn number by the time this runs (both call sites
  // update it before calling clearTemporaryBuffs).
  return {
    ...controlReverted,
    seats: controlReverted.seats.map((seat) => ({
      ...seat,
      board: {
        ...seat.board,
        exile: (seat.board.exile ?? []).map((card) =>
          card.exiledPlayableUntilTurn !== undefined && controlReverted.turn > card.exiledPlayableUntilTurn
            ? { ...card, exiledPlayableBySeatId: undefined, exiledPlayableUntilTurn: undefined }
            : card
        )
      }
    }))
  };
}

function describeAttackOption(card: VisibleCard, legalBlockers: VisibleCard[], tax: number): string {
  const keywords = describeKeywords(card);
  const keywordText = keywords.length > 0 ? ` (${keywords.join(", ")})` : "";
  const taxText = tax > 0 ? ` Attacking here costs an additional {${tax}} generic mana due to a static effect.` : "";
  return `${effectivePower(card)}/${effectiveToughness(card)}${keywordText} ${card.oracleText} (${legalBlockers.length} untapped creature${legalBlockers.length === 1 ? "" : "s"} there could legally block).${taxText}`.trim();
}

export function legalAttackActions(seat: PlayerSeat, opponents: PlayerSeat[] = []): LegalAgentAction[] {
  const attackers = seat.board.battlefield.filter((card) => canAttack(card, seat.board.battlefield));
  const actions: LegalAgentAction[] = [];
  for (const card of attackers) {
    for (const opponent of opponents) {
      const legalBlockers = opponent.board.battlefield.filter((blocker) => canBlock(blocker, card, opponent.board.battlefield));
      const tax = totalAttackTax(opponent, false);
      if (tax === 0 || chooseManaSourcesForCost(seat, genericCostShim(tax), tax, undefined, opponents).ok) {
        actions.push({
          id: `attack:${card.id}:${opponent.id}`,
          actionType: "attack",
          cardId: card.id,
          targetIds: [opponent.id],
          label: `attack ${opponent.name} with ${card.name}`,
          detail: describeAttackOption(card, legalBlockers, tax),
          role: card.role
        });
      }
      for (const planeswalker of opponent.board.battlefield.filter(isPlaneswalkerCard)) {
        const planeswalkerTax = totalAttackTax(opponent, true);
        if (planeswalkerTax > 0 && !chooseManaSourcesForCost(seat, genericCostShim(planeswalkerTax), planeswalkerTax, undefined, opponents).ok) continue;
        actions.push({
          id: `attack:${card.id}:${planeswalker.id}`,
          actionType: "attack",
          cardId: card.id,
          targetIds: [planeswalker.id],
          label: `attack ${planeswalker.name} (${opponent.name}'s planeswalker, ${loyaltyCounterCount(planeswalker)} loyalty) with ${card.name}`,
          detail: describeAttackOption(card, legalBlockers, planeswalkerTax),
          role: card.role
        });
      }
    }
  }
  actions.push({ id: "no-attacks", actionType: "pass_priority", targetIds: [], label: "declare no attackers" });
  return actions;
}

// "This spell can't be countered." (printed on the target itself) or "[Creature s]pells you
// [control/cast] can't be countered." (a static grant from a permanent the target's controller
// has) — checked wherever a counterspell's legality or resolution depends on being able to target
// the spell at all.
function spellIsImmuneToCounters(session: GameSession, targetCard: VisibleCard, targetControllerSeatId: string): boolean {
  if (hasCantBeCountered(targetCard.oracleText)) return true;
  const controller = session.seats.find((seat) => seat.id === targetControllerSeatId);
  if (!controller) return false;
  return controller.board.battlefield.some((source) => {
    const scope = parseCounterImmunityGrant(source.oracleText);
    return scope !== undefined && counterImmunityScopeMatches(scope, targetCard.typeLine);
  });
}

// Phase 5a's other auto-pass gate — canReceivePriorityForPendingAction already guarantees this seat
// has SOME legal instant-speed response before decideAgentPriorityAction is ever called, so "has an
// option" is never in question here; this is the narrower "is it worth spending an LLM call to
// weigh that option" check. Deliberately conservative: only returns true when there's a clear reason
// nothing about the pending action could concern this seat, never when unsure — an agent silently
// missing a real response is a worse failure than one extra Ollama call. Doesn't attempt "would this
// kill my creature" (no structured per-target data reaches this dispatch layer, only oracle text and
// a message string) — "mentions target at all" already covers that case conservatively, since a
// removal/damage spell that could kill a creature always says "target" somewhere in its text.
function isPendingActionLikelyIrrelevantToSeat(seat: PlayerSeat, pendingAction: PendingAction, session: GameSession): boolean {
  // The actor's own spell/trigger gets its own required-pass handling elsewhere (rule 117.3b —
  // caster responds to their own action first); never second-guess that path here.
  if (pendingAction.actorSeatId === seat.id) return false;
  if (pendingAction.type === "trigger" && pendingAction.controllerSeatId === seat.id) return false;

  const oracleText = pendingActionSourceCard(session, pendingAction)?.oracleText ?? "";
  if (!oracleText) return false;
  if (isBoardWipeText(oracleText)) return false;
  // Graveyard hate concerns a seat whose graveyard has cards (it may answer with a graveyard shuffle such as Enhanced Surveillance's).
  if ((seat.board.graveyard?.length ?? 0) > 0 && graveyardHateOnStack(session, seat, [pendingAction])) return false;
  const text = oracleText.toLowerCase();
  // A mass effect with no literal "target" (Blasphemous Act-style "all creatures", Wrath-adjacent
  // "each player" clauses not already caught by isBoardWipeText) still touches this seat's board.
  if (/\beach (player|opponent|creature)\b/.test(text) || /\ball (creatures|players|permanents)\b/.test(text)) return false;
  // Anything with an explicit target could plausibly hit this seat, their permanents, or something
  // they care about — don't try to resolve who it actually targets here, just don't skip.
  if (/\btarget\b/.test(text)) return false;

  return true;
}

export function legalPriorityActions(seat: PlayerSeat, pendingAction: PendingAction, activeSeatId: string | undefined, session: GameSession): LegalAgentAction[] {
  if (pendingAction.type === "trigger" && pendingAction.controllerSeatId === seat.id) {
    return [{ id: "resolve-trigger", actionType: "pass_priority", targetIds: [], label: `resolve ${pendingAction.sourceCardName} trigger` }];
  }
  const pendingSpellTarget = pendingAction.type === "spell" ? findSpellSourceCard(session, pendingAction) : undefined;
  // Instant-speed responses can come from hand OR from an exile pile the seat currently has play
  // permission for (impulse-draw/steal-and-play — see zoneEffects.ts) — gated by the exact same
  // canCastAtInstantSpeed check either way, so an exiled sorcery still isn't offered as a response,
  // only an exiled instant/flash card is. Scanned across every seat's exile, not just this one's
  // own: a card exiled by an effect like Mind's Dilation's physically sits in its OWNER's exile,
  // which can be a different seat than the one permitted to cast it (see playCardFromZone's own
  // cross-seat handling).
  const respondableCards: Array<{ card: VisibleCard; sourceZone: "exile" | undefined }> = [
    ...seat.board.hand.map((card) => ({ card, sourceZone: undefined })),
    ...session.seats
      .flatMap((s) => s.board.exile ?? [])
      .filter((card) => card.exiledPlayableBySeatId === seat.id && (card.exiledPlayableUntilTurn === undefined || session.turn <= card.exiledPlayableUntilTurn))
      .map((card) => ({ card, sourceZone: "exile" as const }))
  ];
  const flashGranted = seatHasFlashGrant(seat);
  const actions: LegalAgentAction[] = respondableCards
    .filter(() => !spellCastLockedOut(session, seat.id, activeSeatId))
    .filter(({ card, sourceZone }) => canCastAtInstantSpeed(card, flashGranted || seatHasFlashGrant(seat, card)) || (sourceZone === "exile" && Boolean(card.exiledPlayableAnyTime)))
    .filter(({ card }) => {
      const counterAbility = parseCounterSpellAbility(card.oracleText);
      if (!counterAbility || parseModalHeader(card.oracleText)) return true;
      if (!pendingSpellTarget || pendingAction.type !== "spell") return false;
      if (spellIsImmuneToCounters(session, pendingSpellTarget, pendingAction.actorSeatId)) return false;
      return counterSpellCanTarget(counterAbility, pendingSpellTarget.typeLine, pendingAction.sourceZone === "command");
    })
    .filter(({ card }) => {
      const fixedCost = adjustedCastingCost(seat, card, card.manaValue, "hand", activeSeatId, session.seats);
      const chosenX = maxAffordableX(seat, card, fixedCost);
      return chooseManaSourcesForCost(seat, card, totalCastingCost(seat, card, card.manaValue, chosenX, session.seats), undefined, session.seats).ok;
    })
    .filter(({ card }) => hasResolvableTarget(session, seat.id, card))
    .map(({ card, sourceZone }) => ({
      id: sourceZone === "exile" ? `respond-exile:${card.id}` : `respond:${card.id}`,
      actionType: "cast_spell" as const,
      cardId: card.id,
      sourceZone,
      targetIds: [pendingAction.id],
      label: `respond with ${card.name}${sourceZone === "exile" ? " from exile" : ""}`,
      detail: `${card.manaCost ?? ""} ${card.typeLine}. ${card.oracleText}`.trim(),
      role: card.role
    }));
  // Loyalty/equip activation isn't legal at instant speed, so turn/activatedLoyaltyKeys are unused
  // here — sorcerySpeedAllowed=false skips that branch entirely.
  actions.push(...legalActivatedAbilityActions(seat, false, session.turn, EMPTY_LOYALTY_KEYS, session, true, [pendingAction]));
  actions.push({ id: "pass-priority", actionType: "pass_priority", targetIds: [pendingAction.id], label: "pass priority" });
  return actions;
}

const EMPTY_LOYALTY_KEYS = new Set<string>();

function legalActivatedAbilityActions(seat: PlayerSeat, sorcerySpeedAllowed: boolean, turn: number, activatedLoyaltyKeys: Set<string>, session: GameSession, landDropAvailable = true, stack: PendingAction[] = []): LegalAgentAction[] {
  const actions: LegalAgentAction[] = seat.board.battlefield
    .filter((card) => {
      if (card.abilitiesStripped) return false;
      if (!isBasicLandFetchAbility(card)) return false;
      const requiresTap = basicLandFetchCostRequiresTap(card);
      // Rule 302.6: only applies when the cost actually includes {T} (Evolving Wilds) — Sakura-
      // Tribe Elder's plain sacrifice cost isn't restricted by being tapped or summoning sick.
      if (requiresTap && card.tapped) return false;
      if (requiresTap && card.typeLine.includes("Creature") && card.summoningSick && !hasHaste(card)) return false;
      // Wayfarer's Bauble-style "{2}, {T}, Sacrifice ...: Search..." has a real generic-mana
      // component on top of tap+sacrifice — Evolving Wilds' plain "{T}, Sacrifice ..." costs 0 here,
      // so this is a no-op affordability check for that whole original card family.
      const manaCost = basicLandFetchManaCost(card);
      if (manaCost > 0 && !chooseManaSourcesForCost(seat, genericCostShim(manaCost), manaCost, card.id, session.seats).ok) return false;
      return getBasicLandFetchOptions(seat.library ?? []).length > 0;
    })
    .map((card) => ({
      id: `activate-basic-fetch:${card.id}`,
      actionType: "activate_ability" as const,
      abilityKind: "basic_land_fetch" as const,
      cardId: card.id,
      targetIds: [],
      label: `activate ${card.name}`,
      detail: `Sacrifice ${card.name}: search your library for a basic land, put it onto the battlefield tapped, then shuffle.`
    }));

  for (const card of seat.board.battlefield) {
    if (card.abilitiesStripped) continue;
    parseGenericSacrificeAbilities(abilityOracleText(card)).forEach((ability, abilityIndex) => {
      if (!activateOnlyIfConditionMet(ability.clause, seat)) return;
      // "Activate only as a sorcery." (Fiend Artisan, Birthing Pod): never offered at instant speed.
      if (hasSorcerySpeedOnlyLimiter(ability.clause) && !sorcerySpeedAllowed) return;
      // An {X} cost: the engine picks X (see chooseAbilityX); with no fetchable creature the ability is not offered.
      const abilityX = ability.costX ? chooseAbilityX(session, seat, card, ability) : 0;
      if (abilityX === undefined) return;
      const payAbility = ability.costX ? abilityCostWithX(ability, abilityX) : ability;
      // Evolving Wilds/Terramorphic Expanse-style "search a basic land" abilities now also match
      // the general search_library shape below, but isBasicLandFetchAbility already owns them via
      // its own simpler auto-resolving system (basic_land_fetch) — without this, the same physical
      // ability would show up twice in the legal-actions list, once auto-picking a land and once
      // opening the interactive search UI for the exact same choice.
      if (ability.effect.kind === "search_library" && isBasicLandFetchAbility(card)) return;
      // Graveyard hate only when it hurts opponents more than you (Scavenger Grounds).
      if (
        ability.effect.kind === "exile_all_graveyards" &&
        session.seats.filter((other) => other.id !== seat.id).reduce((total, other) => total + (other.board.graveyard ?? []).length, 0) < (seat.board.graveyard ?? []).length + 4
      ) {
        return;
      }
      // Wasted-activation guards. The zone effects below need something to act on (a creature card to return, a graveyard to exile), exactly
      // as the tap-ability loop checks; without it Memorial to Folly was offered (and its land sacrificed) with an empty graveyard.
      if (ability.effect.kind === "zone_effect" && !zoneEffectHasLegalTarget(session, seat.id, ability.effect.effect)) return;
      if (seat.kind !== "human" && ability.effect.kind === "zone_effect") {
        const zone = ability.effect.effect;
        // Enhanced Surveillance's "Exile this enchantment: Shuffle your graveyard into your library." - see graveyardShuffleIsWorthIt.
        if (zone.kind === "graveyard_to_library" && zone.scope === "you" && !graveyardShuffleIsWorthIt(session, seat, stack)) return;
        // Nihil Spellbomb / Soul-Guide Lantern: graveyard hate is only worth the artifact when opponents' graveyards hold something.
        if (zone.kind === "exile_graveyard") {
          const theirs = session.seats.filter((other) => other.id !== seat.id && !other.hasLost).reduce((total, other) => total + (other.board.graveyard?.length ?? 0), 0);
          if (zone.scope === "you" || theirs < 3) return;
        }
      }
      // Selfless Spirit / Spectacular Spider-Man: an agent sacrifices its creature only IN RESPONSE to something on the stack, never at random.
      if (seat.kind !== "human" && ability.effect.kind === "grant_keywords_to_your_creatures" && !(stack && stack.length > 0 && !sorcerySpeedAllowed)) return;
      // Spore Frog's fog does nothing outside a combat with attackers.
      if (seat.kind !== "human" && ability.effect.kind === "prevent_combat_damage" && !(/declare blockers|combat damage/i.test(session.phase) && session.seats.some((other) => other.id !== seat.id && other.board.battlefield.some((attacker) => attacker.attacking)))) return;
      if (ability.costTap && card.tapped) return;
      // Rule 302.6: a creature with summoning sickness can't be tapped to pay an activated
      // ability's {T} cost (Viscera Seer, Carrion Feeder-style "{T}, Sacrifice a creature: ..."
      // are themselves creatures) unless it has haste. Non-creature permanents (Food/Clue tokens,
      // artifacts) have no such restriction.
      if (ability.costTap && card.typeLine.includes("Creature") && card.summoningSick && !hasHaste(card)) return;
      if (ability.costDiscard && seat.board.hand.length === 0) return;
      // Rule 119.4: a life payment (Arid Mesa and the rest of the fetch-land cycle's "Pay 1 life"
      // cost, ...) can only be made if the player's life total is at least that much.
      if (ability.costLife > 0 && seat.life < ability.costLife) return;
      if (ability.sacrificeTarget !== "self" && !chooseSacrificeTargets(seat, ability.sacrificeTargetTypeFilter, ability.sacrificeCount, ability.sacrificeExcludesSelf || ability.sacrificeTarget === "permanent" ? card.id : undefined, ability.sacrificeTarget === "permanent")) return;
      if (ability.effect.kind === "search_library" && (seat.library?.length ?? 0) === 0) return;
      // Sacrificing for floating mana is a human's play; an agent has no way to spend the pool, so it is never offered to one.
      if (ability.effect.kind === "add_mana" && seat.kind !== "human") return;
      // Rule 601.2c-equivalent for an activated ability: don't offer "activate Cankerbloom" with
      // nothing to destroy any more than legalMainPhaseActions offers casting a removal spell with
      // no legal target (see hasResolvableRemovalTarget) — same underlying check, reused here.
      if (ability.effect.kind === "removal" && !removalEffectHasLegalTarget(session, seat.id, card, ability.effect.effect)) return;
      // excludeCardId: card.id — this ability's own {T} (Mind Stone's "{1}, {T}, Sacrifice...")
      // already requires the source untapped; it can't also tap itself via its own separate mana
      // ability to help pay the generic portion of this same activation (a permanent can only
      // supply one tap). Without this exclusion a mana-producing sacrifice permanent could pay part
      // of its own cost with itself — reported live as Mind Stone tapping for {C} and then still
      // being sacrificed for its draw ability the same turn.
      const sacrificeCostTotal = manaValueFromManaCost(payAbility.costManaText);
      const affordable = sacrificeCostTotal === 0 || chooseManaSourcesForCost(seat, genericManaAbilityCostShim(payAbility), sacrificeCostTotal, card.id, session.seats).ok;
      if (!affordable) return;
      const sacrificeCards =
        ability.sacrificeTarget === "self"
          ? [card]
          : (chooseSacrificeTargets(seat, ability.sacrificeTargetTypeFilter, ability.sacrificeCount, ability.sacrificeExcludesSelf || ability.sacrificeTarget === "permanent" ? card.id : undefined, ability.sacrificeTarget === "permanent") ?? []);
      const targetNames = sacrificeCards.map((target) => target.name);
      actions.push({
        id: `activate-sacrifice:${card.id}:${abilityIndex}`,
        actionType: "activate_ability",
        abilityKind: "generic_sacrifice",
        abilityIndex,
        sacrificeCardIds: sacrificeCards.map((target) => target.id),
        cardId: card.id,
        targetIds: [],
        label: `activate ${card.name} (sacrifice ${targetNames.join(", ") || "a creature"}${ability.costX ? `, X=${abilityX}` : ""})`,
        detail: ability.clause
      });
    });
  }

  for (const card of seat.board.battlefield) {
    if (card.abilitiesStripped) continue;
    parseGenericTapAbilities(abilityOracleText(card)).forEach((ability, abilityIndex) => {
      if (!activateOnlyIfConditionMet(ability.clause, seat)) return;
      if (hasSorcerySpeedOnlyLimiter(ability.clause) && !sorcerySpeedAllowed) return;
      if (ability.costRemoveCounter && counterCount(card, ability.costRemoveCounter) < 1) return;
      if (ability.costExileGraveyard && (seat.board.graveyard?.length ?? 0) < ability.costExileGraveyard) return;
      // Sunken Palace's marked mana only helps a human, who spends it from the pool; agents are not offered it.
      if (ability.effect.kind === "add_copy_mana" && seat.kind !== "human") return;
      if (ability.costLifeCommanderColors && seat.life <= commanderColorCount(seat)) return;
      // Hideaway lands (Spinerock Knoll, Mosswort Bridge): worth activating only with a hidden card and the condition already true.
      if (ability.effect.kind === "hideaway_play") {
        // A hidden LAND can only be played with a land drop left (the play-land-from-exile action below), so paying for it with none would be wasted.
        const hiddenCard = seat.board.exile?.find((hidden) => hidden.hideawaySourceId === card.id);
        if (!hiddenCard || (isLandCard(hiddenCard) && !landDropAvailable)) return;
        const damageMet = hideawayDamageConditionMet(session, seat.id, ability.effect.conditionText);
        if (!(damageMet !== undefined ? damageMet : isBoardConditionMet(ability.effect.conditionText, seat, session.seats))) return;
      }
      if (ability.costDiscard && discardableHandCards(seat, ability.costDiscardType).length === 0) return;
      if (ability.costTapCreatures) {
        if (!chooseCreaturesToTapForCost(seat, ability.costTapCreatures.count, ability.costTapCreatures.subtype)) return;
      } else {
        if (card.tapped) return;
        // Rule 302.6: same summoning-sickness gate as the sacrifice-ability loop above — a creature
        // can't be tapped to pay a {T} cost the turn it entered without haste.
        if (card.typeLine.includes("Creature") && card.summoningSick && !hasHaste(card)) return;
      }
      if (ability.costDiscard && seat.board.hand.length === 0) return;
      // excludeCardId: card.id — same self-tap exclusion as the sacrifice-ability loop above.
      const tapCostTotal = manaValueFromManaCost(ability.costManaText);
      const affordable = tapCostTotal === 0 || chooseManaSourcesForCost(seat, genericManaAbilityCostShim(ability), tapCostTotal, card.id, session.seats).ok;
      if (!affordable) return;
      if (
        (ability.effect.kind === "counter_and_transform" || ability.effect.kind === "bounce_own") &&
        !chooseGenericTapTarget(seat, ability.effect.targetTypeFilter)
      ) {
        return;
      }
      if (ability.effect.kind === "search_library" && (seat.library?.length ?? 0) === 0) return;
      // Nothing to act on: no creature card in any graveyard to exile, or no legal graveyard target.
      if (ability.effect.kind === "exile_graveyard_creature_then_tokens" && !session.seats.some((s) => (s.board.graveyard ?? []).some((c) => c.typeLine.includes("Creature")))) return;
      if (ability.effect.kind === "zone_effect" && !zoneEffectHasLegalTarget(session, seat.id, ability.effect.effect)) return;
      // A self-mill tap ability (Skull Prophet) is only worth an agent's activation while the library is deep: never mill toward an empty library.
      if (ability.effect.kind === "zone_effect" && ability.effect.effect.kind === "mill" && (seat.library?.length ?? 0) < ability.effect.effect.amount + 20) return;
      if (ability.effect.kind === "grant_graveyard_cast" && !(seat.board.graveyard ?? []).some((c) => permanentMatchesQualifier(c, ability.effect.kind === "grant_graveyard_cast" ? ability.effect.cardMatcher : ""))) return;
      actions.push({
        id: `activate-generic-tap:${card.id}:${abilityIndex}`,
        actionType: "activate_ability",
        abilityKind: "generic_tap",
        abilityIndex,
        cardId: card.id,
        targetIds: [],
        label: `activate ${card.name}`,
        detail: ability.clause
      });
    });
  }

  // "{cost}: Untap ~." (Retrofitter Foundry's "{3}: Untap this artifact.") only ever does anything
  // useful while the permanent is actually tapped — no {T} in its own cost, so summoning sickness
  // (rule 302.6) doesn't apply here regardless of whether the source is a creature.
  for (const card of seat.board.battlefield.filter((item) => item.tapped && !item.abilitiesStripped)) {
    parseSelfUntapAbilities(card.oracleText).forEach((ability, abilityIndex) => {
      if (!activateOnlyIfConditionMet(ability.clause, seat)) return;
      const affordable = ability.costMana === 0 || chooseManaSourcesForCost(seat, genericCostShim(ability.costMana), ability.costMana, undefined, session.seats).ok;
      if (!affordable) return;
      actions.push({
        id: `activate-self-untap:${card.id}:${abilityIndex}`,
        actionType: "activate_ability",
        abilityKind: "self_untap",
        abilityIndex,
        cardId: card.id,
        targetIds: [],
        label: `activate ${card.name} (untap)`,
        detail: ability.clause
      });
    });
  }

  for (const card of seat.board.battlefield) {
    if (card.abilitiesStripped) continue;
    parseGenericManaAbilities(card.oracleText).forEach((ability, abilityIndex) => {
      if (!activateOnlyIfConditionMet(ability.clause, seat)) return;
      if (hasSorcerySpeedOnlyLimiter(ability.clause) && !sorcerySpeedAllowed) return;
      if (ability.costDiscard && seat.board.hand.length === 0) return;
      if (hasOnceEachTurnLimiter(ability.clause) && session.onceEachTurnEffectsUsed?.includes(`${session.turn}:${card.id}:generic_mana:${abilityIndex}`)) return;
      if (ability.costHasX) {
        const best = steelHellkiteXOptions(session, seat, card).find((option) => option.best);
        if (!best) return;
        actions.push({ id: `activate-generic-mana:${card.id}:${abilityIndex}`, actionType: "activate_ability", abilityKind: "generic_mana", abilityIndex, cardId: card.id, targetIds: [], label: `activate ${card.name} (X=${best.x})`, detail: ability.clause });
        return;
      }
      if (!genericManaAbilityAffordable(seat, ability, session.seats)) return;
      const effect = parseGenericAbilityEffect(ability.effectText);
      if (!effect) return;
      if (!genericAbilityEffectHasLegalTarget(session, seat.id, card, effect)) return;
      // Beledros Witherbloom: an agent pays life to untap lands only when it unlocks a spell it could not otherwise cast (a human decides for themselves).
      if (effect.kind === "untap_all_lands" && seat.kind !== "human" && !untapAllLandsIsWorthIt(seat, ability.costLife, session.seats)) return;
      actions.push({
        id: `activate-generic-mana:${card.id}:${abilityIndex}`,
        actionType: "activate_ability",
        abilityKind: "generic_mana",
        abilityIndex,
        cardId: card.id,
        targetIds: [],
        label: `activate ${card.name}`,
        detail: ability.clause
      });
    });
  }

  for (const card of seat.board.battlefield.filter((item) => item.name === "Myriad Landscape" && !item.tapped)) {
    if (!chooseManaSourcesForCost(seat, genericCostShim(2), 2, card.id, session.seats).ok) continue;
    if (chooseBestBasicLandPairForMyriad(seat).length !== 2) continue;
    actions.push({
      id: `activate-myriad:${card.id}`,
      actionType: "activate_ability",
      abilityKind: "myriad_landscape",
      cardId: card.id,
      targetIds: [],
      label: `activate ${card.name}`,
      detail: `{2}, {T}, Sacrifice ${card.name}: search your library for up to two basic land cards that share a land type, put them onto the battlefield tapped, then shuffle.`
    });
  }

  // Man-land animation has no {T} in its own cost (Celestial Colonnade, Mishra's Factory, ...),
  // so unlike every other ability in this function it's legal at instant speed, not gated by
  // sorcerySpeedAllowed. Excludes an already-animated-this-turn land: reactivating would just
  // re-apply the exact same until-end-of-turn state for no benefit.
  for (const card of seat.board.battlefield.filter((item) => !item.temporaryAnimatedAsCreature)) {
    const animation = parseManlandAnimation(card.oracleText);
    if (!animation) continue;
    if (animation.cost > 0 && !chooseManaSourcesForCost(seat, genericCostShim(animation.cost), animation.cost, card.id, session.seats).ok) continue;
    actions.push({
      id: `activate-manland:${card.id}`,
      actionType: "activate_ability",
      abilityKind: "animate_manland",
      cardId: card.id,
      targetIds: [],
      label: `activate ${card.name} (become a creature)`,
      detail: `Until end of turn, ${card.name} becomes a ${animation.power}/${animation.toughness} creature${animation.keywords ? ` with ${animation.keywords.join(", ")}` : ""}. It's still a land.`
    });
  }

  // Equip and loyalty abilities are both sorcery-speed only (rules 702.6e, 606.3): not offered
  // while responding during a priority window, only from the controller's own main phase.
  if (sorcerySpeedAllowed) {
    for (const card of seat.board.battlefield.filter((item) => isEquipment(item))) {
      const cost = equipCost(card.oracleText);
      if (cost === undefined) continue;
      if (cost > 0 && !chooseManaSourcesForCost(seat, genericCostShim(cost), cost, undefined, session.seats).ok) continue;
      const target = chooseEquipTarget(seat, card);
      if (!target) continue;
      actions.push({
        id: `activate-equip:${card.id}`,
        actionType: "activate_ability",
        abilityKind: "equip",
        cardId: card.id,
        targetIds: [],
        label: `activate ${card.name} (equip ${target.name})`,
        detail: `Equip {${cost}}: Attach ${card.name} to ${target.name}. ${card.oracleText}`.trim()
      });
    }

    for (const card of seat.board.battlefield.filter((item) => isPlaneswalkerCard(item))) {
      if (activatedLoyaltyKeys.has(loyaltyTurnKey(seat.id, card.id, turn))) continue;
      parseLoyaltyAbilities(card.oracleText).forEach((ability, abilityIndex) => {
        if (ability.cost < 0 && loyaltyCounterCount(card) < Math.abs(ability.cost)) return;
        // "The next spell you cast this turn has affinity for artifacts." (Saheeli, the Gifted's
        // second +1) does nothing at all with no spell left in hand to cast this turn — same "don't
        // offer a strictly pointless action" reasoning chooseEquipTarget already applies to a
        // non-improving equip move, just for a loyalty ability instead. Without this, the ability
        // still showed up as a legal action with nothing distinguishing it from a genuinely useful
        // pick, and an agent activated it with an empty hand instead of its sibling +1 (which always
        // makes a Servo token) — reported live, burning the planeswalker's one activation this turn
        // for an effect that could never matter.
        if (
          /costs? \{1\} less to cast for each artifact you control|has affinity for artifacts/i.test(ability.text) &&
          !seat.board.hand.some((handCard) => !handCard.typeLine.includes("Land"))
        ) {
          return;
        }
        actions.push({
          id: `activate-loyalty:${card.id}:${abilityIndex}`,
          actionType: "activate_ability",
          abilityKind: "loyalty_ability",
          cardId: card.id,
          loyaltyCost: ability.cost,
          targetIds: [],
          label: `activate ${card.name} ${formatLoyaltyCost(ability.cost)}`,
          detail: ability.text
        });
      });
    }
  }

  // "Enchanted player can't activate abilities that aren't mana abilities or loyalty abilities."
  // (Overwhelming Splendor). This engine doesn't expose land-tap-for-mana as a discrete
  // activate_ability action (mana costs are paid automatically through chooseManaSourcesForCost),
  // so no abilityKind produced above is a genuine rule-605.1 mana ability — the restriction
  // therefore reduces, in this engine's model, to "only loyalty_ability actions remain legal."
  const playerLocked = session.seats.some((lockSeat) =>
    lockSeat.board.battlefield.some(
      (card) => isAura(card) && card.attachedToSeatId === seat.id && restrictsNonManaNonLoyaltyAbilities(card.oracleText)
    )
  );
  if (playerLocked) return actions.filter((action) => action.abilityKind === "loyalty_ability");

  return actions;
}

function parseLoyaltyAbilities(oracleText: string): Array<{ cost: number; text: string }> {
  return oracleText
    .split("\n")
    .map((line) => line.trim())
    .map((line) => {
      const match = line.match(/^([+−-]?\d+):\s*(.+)$/);
      if (!match) return undefined;
      return { cost: Number.parseInt(match[1].replace("−", "-"), 10), text: match[2] };
    })
    .filter((ability): ability is { cost: number; text: string } => Boolean(ability && Number.isFinite(ability.cost) && ability.text));
}

// No interactive targeting for equip either; prefers the creature the equipment would most
// improve (highest resulting combined power+toughness).
//
// Deliberately does NOT exclude the current holder from the ranking (an earlier version did, to
// avoid "re-equipping the same creature" as a no-op action) — that exclusion is what caused a real,
// reproduced infinite loop: with the holder excluded, ranking the REMAINING creatures always finds
// some *other* "best" one to move to, and once moved, the creature that just lost the equipment is
// no longer excluded and becomes the new best target again, forever alternating between the top two
// creatures on the board with neither side ever a real improvement (reported live as an agent stuck
// re-equipping Lightning Greaves back and forth between Meren of Clan Nel Toth and Acidic Slime
// hundreds of times without the turn ever advancing). Ranking ALL creatures (holder included) and
// only recommending a move when some other creature is a genuine, strict improvement over the
// current holder fixes this at the source: once equipment is on the actual best creature, this
// returns undefined and "equip" stops being offered as a legal action at all, rather than an
// artificial exclusion manufacturing a new "best" target every single time.
function chooseEquipTarget(seat: PlayerSeat, equipment: VisibleCard): VisibleCard | undefined {
  const creatures = seat.board.battlefield.filter((card) => card.typeLine.includes("Creature"));
  if (creatures.length === 0) return undefined;
  const best = creatures.reduce((a, b) => (effectivePower(b) + effectiveToughness(b) > effectivePower(a) + effectiveToughness(a) ? b : a));
  return best.id === equipment.attachedToId ? undefined : best;
}

// humanPool: see payGenericSacrificeCost's own doc comment — same pool-first-then-auto-tap
// preference. Returns undefined (rather than the unchanged session) when nothing could be done, so
// the caller can tell "equip failed" apart from "equip succeeded, nothing to sync" the same way
// payGenericSacrificeCost's undefined-vs-object return already does.
export function resolveEquip(
  session: GameSession,
  seatId: string,
  cardId: string,
  humanPool?: ManaPool,
  // A human's already-chosen creature (see choose_equip_target) — when provided, used instead of
  // chooseEquipTarget's auto-pick heuristic. Undefined for the agent path, which keeps the exact
  // heuristic behavior it had before. Unlike chooseEquipTarget, a pre-chosen target has no
  // same-creature exclusion — a real click-to-choose re-equip to the same creature is still legal.
  preChosenTargetId?: string
): { session: GameSession; poolSpent?: ManaPool } | undefined {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card) return undefined;
  const cost = equipCost(card.oracleText);
  if (cost === undefined) return undefined;
  const target = preChosenTargetId
    ? seat.board.battlefield.find((item) => item.id === preChosenTargetId && item.typeLine.includes("Creature"))
    : chooseEquipTarget(seat, card);
  if (!target) return undefined;
  const costCard = genericCostShim(cost);
  const poolPayment = cost > 0 && humanPool ? payCostFromPool(humanPool, costCard, cost) : undefined;
  const payment = cost > 0 ? (poolPayment?.ok ? poolPayment : chooseManaSourcesForCost(seat, costCard, cost, undefined, session.seats)) : undefined;
  if (cost > 0 && !payment?.ok) return undefined;

  let next = session;
  if (payment?.ok && !poolPayment?.ok) {
    next = { ...next, seats: next.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  }
  const { timestamp, session: stampedNext } = nextTimestamp(next);
  next = stampedNext;

  return {
    session: {
    ...next,
    seats: next.seats.map((item) =>
      item.id === seatId
        ? {
            ...item,
            board: {
              ...item.board,
              battlefield: item.board.battlefield.map((permanent) => (permanent.id === cardId ? { ...permanent, attachedToId: target.id, attachTimestamp: timestamp } : permanent))
            }
          }
        : item
    ),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${seat.name} equips ${card.name} to ${target.name}.`,
        detail: "Rules action"
      },
      ...next.events
    ]
    },
    poolSpent: poolPayment?.ok ? poolPayment.pool : undefined
  };
}

// humanPool: same pool-first-then-auto-tap preference as resolveEquip/payGenericSacrificeCost.
function resolveManlandAnimation(session: GameSession, seatId: string, cardId: string, humanPool?: ManaPool): { session: GameSession; poolSpent?: ManaPool } | undefined {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card) return undefined;
  const animation = parseManlandAnimation(card.oracleText);
  if (!animation) return undefined;
  const costCard = genericCostShim(animation.cost);
  const poolPayment = animation.cost > 0 && humanPool ? payCostFromPool(humanPool, costCard, animation.cost) : undefined;
  const payment = animation.cost > 0 ? (poolPayment?.ok ? poolPayment : chooseManaSourcesForCost(seat, costCard, animation.cost, undefined, session.seats)) : undefined;
  if (animation.cost > 0 && !payment?.ok) return undefined;

  let next = session;
  if (payment?.ok && !poolPayment?.ok) {
    next = { ...next, seats: next.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  }

  return {
    session: {
      ...next,
      seats: next.seats.map((item) =>
        item.id === seatId
          ? {
              ...item,
              board: {
                ...item.board,
                battlefield: item.board.battlefield.map((permanent) =>
                  permanent.id === cardId
                    ? {
                        ...permanent,
                        temporaryAnimatedAsCreature: true,
                        temporaryBasePower: animation.power,
                        temporaryBaseToughness: animation.toughness,
                        temporaryGrantedKeywords: animation.keywords
                      }
                    : permanent
                )
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} activates ${card.name}: it becomes a ${animation.power}/${animation.toughness} creature until end of turn.`,
          detail: "Rules action"
        },
        ...next.events
      ]
    },
    poolSpent: poolPayment?.ok ? poolPayment.pool : undefined
  };
}

// No dedicated "choose a permanent" UI exists yet (matching how Myriad Landscape/basic-land-fetch
// already auto-resolve their choices), so this deterministically picks the least costly creature
// to lose: prefer a token over a real card, then the lowest combined power+toughness.
function chooseSacrificeTarget(seat: PlayerSeat, typeFilter?: string): VisibleCard | undefined {
  const creatures = seat.board.battlefield.filter(
    (card) => card.typeLine.includes("Creature") && (!typeFilter || card.typeLine.toLowerCase().includes(typeFilter.toLowerCase()))
  );
  if (creatures.length === 0) return undefined;
  const tokens = creatures.filter((card) => card.token);
  const pool = tokens.length > 0 ? tokens : creatures;
  return pool.reduce((worst, card) =>
    effectivePower(card) + effectiveToughness(card) < effectivePower(worst) + effectiveToughness(worst) ? card : worst
  );
}

// Same "no choice UI, pick deterministically" pattern as chooseSacrificeTarget, for a generic tap
// ability's "target X you control" (a counter/upgrade or a bounce-to-hand) — every such target this
// engine's generic tap parser recognizes is always "you control", so this only ever searches the
// activating seat's own battlefield. Prefers the lowest combined power+toughness match, same
// reasoning as chooseSacrificeTarget: spend the least valuable eligible permanent when there's a
// choice, rather than guessing at which one the controller would actually want.
function chooseGenericTapTarget(seat: PlayerSeat, typeFilter: string | undefined): VisibleCard | undefined {
  const candidates = seat.board.battlefield.filter(
    (card) => card.typeLine.includes("Creature") && (!typeFilter || card.typeLine.toLowerCase().includes(typeFilter.toLowerCase()))
  );
  if (candidates.length === 0) return undefined;
  return candidates.reduce((worst, card) =>
    effectivePower(card) + effectiveToughness(card) < effectivePower(worst) + effectiveToughness(worst) ? card : worst
  );
}

// Annihilator lets the defending player choose which permanents to sacrifice; with no choice UI
// for this yet, deterministically picks the least costly ones to lose (tokens first, then lowest
// mana value), avoiding the commander unless nothing else is left.
function chooseAnnihilatorSacrifices(seat: PlayerSeat, count: number): VisibleCard[] {
  const nonCommanders = seat.board.battlefield.filter((card) => !card.commander);
  const pool = nonCommanders.length > 0 ? nonCommanders : seat.board.battlefield;
  const sorted = [...pool].sort((a, b) => {
    if (Boolean(a.token) !== Boolean(b.token)) return a.token ? -1 : 1;
    return a.manaValue - b.manaValue;
  });
  return sorted.slice(0, count);
}

// Same "prefer a token, then cheapest" bias as choosePlaguecrafterSacrifice above, for a punisher
// effect's "sacrifices a nonland permanent" outcome (Torment of Hailfire, ...) instead of a typed
// filter — "nonland" isn't one of matchesEachPlayerSacrificeFilter's word tokens, so this needs its
// own pool instead of reusing that function with an invented filter string.
function chooseNonlandPermanentToSacrifice(seat: PlayerSeat): VisibleCard | undefined {
  const candidates = seat.board.battlefield.filter((card) => !card.typeLine.includes("Land"));
  if (candidates.length === 0) return undefined;
  const nonCommanders = candidates.filter((card) => !card.commander);
  const pool = nonCommanders.length > 0 ? nonCommanders : candidates;
  return pool.reduce((best, card) => {
    if (Boolean(card.token) !== Boolean(best.token)) return card.token ? card : best;
    return card.manaValue < best.manaValue ? card : best;
  });
}

// Karoo/bounce lands' mandatory "return a land you control" — bouncing the karoo land itself (a
// legal but pointless choice, always available since it's already on the battlefield by the time
// this fires) defeats the entire point of the card, so this prefers any OTHER land, and among those
// a basic land specifically: cheapest to just replay next turn, versus giving up a nonbasic utility
// land's other abilities for a turn. Falls back to the karoo land itself only when it's the
// controller's sole land (an edge case, not the common path).
function chooseLandToReturn(seat: PlayerSeat, excludeId: string): VisibleCard | undefined {
  const lands = seat.board.battlefield.filter((card) => card.typeLine.includes("Land"));
  const others = lands.filter((card) => card.id !== excludeId);
  return others.find((card) => basicLandTypes(card).length > 0) ?? others[0] ?? lands.find((card) => card.id === excludeId);
}

// Prefers a permanent with its own "when/whenever this enters" ability, since that's the whole
// point of blinking something (Aminatou, the Fateshifter's -1, ...) — falls back to any other
// permanent when nothing on the board has one, and only ever falls back to the source itself
// defensively (finishTriggerResolution already only offers this choice when a real other-permanent
// target exists).
function choosePermanentToBlink(seat: PlayerSeat, excludeId: string): VisibleCard | undefined {
  const others = seat.board.battlefield.filter((card) => card.id !== excludeId);
  const withEtb = others.find((card) => etbEffectText(card.oracleText).trim().length > 0);
  return withEtb ?? others[0] ?? seat.board.battlefield.find((card) => card.id === excludeId);
}

// Pays a generic sacrifice ability's cost (mana + discard + sacrifice) without resolving its
// effect — kept separate from applySacrificeEffect so activateGenericSacrificeAbility (the
// component closure both the human's click and the agent dispatch loop funnel through) can pay
// the cost first, sync the floating-pool React state if it was used, and only then either open the
// interactive library-search choice (search_library effects) or resolve everything else via
// applySacrificeEffect — pendingRuleChoice/setSeatManaPool are component state applySacrificeEffect,
// a pure module-level function, has no access to.
// humanPool: the human caller's floating mana pool (undefined for an agent seat, which never has
// one) — preferred over auto-tapping untapped lands when it already covers the cost, so choosing
// which specific lands to tap for this actually works, the same as casting a spell from hand
// The human seat's PlayerSeat.name is literally "You" (see sessionStore.ts's emptySeat) so it
// reads naturally in the UI's own per-seat panels ("Your battlefield," ...), but most event
// messages in this file interpolate seat.name into a THIRD-person template ("Veyra draws for
// turn.") — for the human seat that collides into ungrammatical text ("You untaps their
// permanents.", "You discards a card to activate X."). Module-level (not nested in the component)
// so both component closures and standalone functions like this one's neighbors can use it.
// Applied to the phase/combat banners that fire every turn and the cost-payment messages a human
// actually triggers by clicking an activate-ability button; the long tail of rarer one-off event
// messages elsewhere in this file has the same underlying issue and would need the same treatment
// if it's ever worth a full sweep.
function seatVerb(seat: { name: string }, thirdPerson: string, secondPerson: string): string {
  return seat.name === "You" ? secondPerson : thirdPerson;
}

// already does. Falls back to auto-tap when the pool doesn't cover it (or there isn't one), so a
// human who hasn't pre-tapped still isn't stuck. poolSpent on the return value tells the caller
// (a component closure, which alone can update the live manaPools React state) to sync it.
export function payGenericSacrificeCost(
  session: GameSession,
  seatId: string,
  cardId: string,
  abilityIndex: number,
  humanPool?: ManaPool,
  // A human's already-chosen creature(s) for a "sacrifice a creature" cost (see
  // choose_creature_to_sacrifice) — when provided, used instead of chooseSacrificeTargets' heuristic.
  // Undefined for every other caller (search_library's own cost payment, the agent path, "sacrifice
  // this creature" self-sacrifices), which all keep the exact heuristic behavior they had before.
  preChosenSacrificeTargets?: VisibleCard[]
): { session: GameSession; ability: SacrificeAbility; card: VisibleCard; sacrificed: VisibleCard[]; poolSpent?: ManaPool; xValue?: number } | undefined {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card) return undefined;
  const ability = parseGenericSacrificeAbilities(abilityOracleText(card))[abilityIndex];
  if (!ability || (ability.costTap && card.tapped)) return undefined;
  if (ability.costTap && card.typeLine.includes("Creature") && card.summoningSick && !hasHaste(card)) return undefined;
  if (!activateOnlyIfConditionMet(ability.clause, seat)) return undefined;
  // An {X} in the cost (Fiend Artisan): the engine picks X, and the cost below is paid with it.
  const xValue = ability.costX ? chooseAbilityX(session, seat, card, ability) : 0;
  if (xValue === undefined) return undefined;
  const payAbility = ability.costX ? abilityCostWithX(ability, xValue) : ability;

  const discardCard = ability.costDiscard ? chooseWorstHandCardToDiscard(seat) : undefined;
  if (ability.costDiscard && !discardCard) return undefined;
  // Rule 119.4: a life payment can only be made if the player's life total is at least that much
  // (Arid Mesa and the rest of the fetch-land cycle's "Pay 1 life" cost, ...) — without this gate a
  // seat at 0 life could still activate a life-cost ability.
  if (ability.costLife > 0 && seat.life < ability.costLife) return undefined;

  const totalManaCost = manaValueFromManaCost(payAbility.costManaText);
  const costCard = genericManaAbilityCostShim(payAbility);
  const poolPayment = totalManaCost > 0 && humanPool ? payCostFromPool(humanPool, costCard, totalManaCost) : undefined;
  // excludeCardId: cardId — this ability's own {T} already requires the source untapped; it can't
  // also tap itself via a separate mana ability of its own to help pay this same activation's
  // generic cost (a permanent can only supply one tap). See the sibling exclusion in
  // legalActivatedAbilityActions' own affordability check above.
  const payment =
    totalManaCost > 0
      ? poolPayment?.ok
        ? poolPayment
        : chooseManaSourcesForCost(seat, costCard, totalManaCost, cardId, session.seats)
      : undefined;
  if (totalManaCost > 0 && !payment?.ok) return undefined;

  const sacrificeTargets =
    ability.sacrificeTarget === "self"
      ? [card]
      : (preChosenSacrificeTargets ?? chooseSacrificeTargets(seat, ability.sacrificeTargetTypeFilter, ability.sacrificeCount, ability.sacrificeExcludesSelf || ability.sacrificeTarget === "permanent" ? card.id : undefined, ability.sacrificeTarget === "permanent"));
  if (!sacrificeTargets || sacrificeTargets.length === 0) return undefined;

  let next = session;
  if (payment?.ok && !poolPayment?.ok) {
    next = {
      ...next,
      seats: next.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item))
    };
  }

  if (ability.costLife > 0) {
    next = {
      ...next,
      seats: next.seats.map((item) => (item.id === seatId ? { ...item, life: item.life - ability.costLife } : item))
    };
  }

  if (discardCard) {
    next = {
      ...next,
      seats: next.seats.map((item) =>
        item.id === seatId
          ? {
              ...item,
              board: {
                ...item.board,
                hand: item.board.hand.filter((handCard) => handCard.id !== discardCard.id),
                graveyard: [...(item.board.graveyard ?? []), { ...discardCard, zone: "graveyard" as const, counters: undefined, interpretedEffects: undefined }]
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: seatVerb(seat, `${seat.name} discards ${discardCard.name} to activate ${card.name}.`, `You discard ${discardCard.name} to activate ${card.name}.`),
          detail: "Rules action"
        },
        ...next.events
      ]
    };
  }

  // Paying the {T} in the cost taps the source — same as payGenericTapCost's sibling step. Mapping
  // over battlefield to tap cardId is a harmless no-op when sacrificeTarget === "self" (the source
  // is about to be removed by the destroyCreatures call right below anyway).
  if (ability.costTap) {
    next = {
      ...next,
      seats: next.seats.map((item) =>
        item.id === seatId ? { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((c) => (c.id === cardId ? { ...c, tapped: true } : c)) } } : item
      )
    };
  }

  if (ability.exileSelf) {
    next = rulesEvent(moveCardBetweenVisibleZones(next, seatId, card.id, "exile"), seatId, `${seat.name} exiles ${card.name} to activate it.`);
    return { session: next, ability, card, sacrificed: sacrificeTargets, poolSpent: poolPayment?.ok ? poolPayment.pool : undefined, xValue };
  }
  next = destroyCreatures(
    next,
    sacrificeTargets.map((target) => ({
      seatId,
      cardId: target.id,
      message:
        sacrificeTargets.length === 1
          ? seatVerb(seat, `${seat.name} sacrifices ${target.name} to activate ${card.name}.`, `You sacrifice ${target.name} to activate ${card.name}.`)
          : seatVerb(
              seat,
              `${seat.name} sacrifices ${target.name} (part of ${sacrificeTargets.length} creatures) to activate ${card.name}.`,
              `You sacrifice ${target.name} (part of ${sacrificeTargets.length} creatures) to activate ${card.name}.`
            )
    })),
    "Rules action"
  );

  return { session: next, ability, card, sacrificed: sacrificeTargets, poolSpent: poolPayment?.ok ? poolPayment.pool : undefined, xValue };
}

export function applySacrificeEffect(
  session: GameSession,
  seatId: string,
  sourceCard: VisibleCard,
  effect: SacrificeAbility["effect"],
  clause: string,
  // The creature(s) sacrificed to pay for this activation — Ghoulcaller Gisa's X is "the sacrificed
  // creature's power".
  sacrificed: VisibleCard[] = []
): GameSession {
  const sourceCardId = sourceCard.id;
  const sourceCardName = sourceCard.name;
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return session;

  // search_library never actually reaches this function: activateGenericSacrificeAbility detects
  // it before ever calling applySacrificeEffect and opens the interactive library-search choice
  // instead (pendingRuleChoice is component state applySacrificeEffect can't reach). This branch
  // only exists to keep the switch exhaustive for the type checker.
  if (effect.kind === "search_library") return session;

  // Command Beacon: the commander leaves the command zone for the hand (its tax is untouched).
  if (effect.kind === "commander_to_hand") {
    const commander = seat.board.commander;
    if (!commander) return rulesEvent(session, seatId, `${seat.name} has no commander in the command zone for ${sourceCardName}.`);
    return rulesEvent(
      {
        ...session,
        seats: session.seats.map((item) =>
          item.id !== seatId ? item : { ...item, board: { ...item.board, commander: undefined, hand: [...item.board.hand, { ...commander, zone: "hand" as const }] }, zones: { ...item.zones, command: Math.max(0, item.zones.command - 1), hand: item.zones.hand + 1 } }
        )
      },
      seatId,
      `${seat.name} puts ${commander.name} into their hand from the command zone with ${sourceCardName}.`
    );
  }

  if (effect.kind === "create_tokens") {
    const specs = parseCreateTokenSpecs(clause);
    if (specs.length === 0) return session;
    const created = createTokensForSeat(session, seatId, sourceCardId, specs);
    const createdNames = created.createdTokens.map((token) => token.name);
    return {
      ...created.session,
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} activates ${sourceCardName} and creates ${createdNames.join(", ")}.`,
          detail: "Rules action"
        },
        ...created.session.events
      ]
    };
  }

  if (effect.kind === "zone_effect") return applyZoneEffect(session, seatId, sourceCardName, effect.effect);

  // Ghoulcaller Gisa: X Zombies, X = the sacrificed creature's power.
  if (effect.kind === "create_tokens_by_sacrificed_power") {
    const count = Math.max(0, ...sacrificed.map((creature) => effectivePower(creature)));
    const specs = parseCreateTokenSpecs(clause.replace(/\bcreate x\b/i, "create two"));
    if (specs.length === 0 || count <= 0) {
      return rulesEvent(session, seatId, `${sourceCardName} resolves, but the sacrificed creature had no power to make tokens from.`);
    }
    const created = createTokensForSeat(session, seatId, sourceCardId, specs.map((spec) => ({ ...spec, count })));
    return rulesEvent(created.session, seatId, `${seat.name} activates ${sourceCardName} and creates ${count} ${created.createdTokens[0]?.name ?? "token"}${count === 1 ? "" : "s"}.`);
  }

  if (effect.kind === "pump_self_by_sacrificed_mv") {
    const bonus = sacrificed.reduce((total, permanent) => total + permanent.manaValue, 0);
    return rulesEvent(
      {
        ...session,
        seats: session.seats.map((item) =>
          item.id !== seatId
            ? item
            : { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((card) => (card.id === sourceCardId ? { ...card, temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) + bonus } : card)) } }
        )
      },
      seatId,
      `${sourceCardName} gets +${bonus}/+0 until end of turn.`
    );
  }
  // Dina, Essence Brewer: gain X life and put X +1/+1 counters on a creature you control (an agent picks its strongest; a human is asked).
  if (effect.kind === "gain_life_counters_by_sacrificed_power") {
    const amount = Math.max(0, ...sacrificed.map((creature) => effectivePower(creature)));
    if (amount <= 0) return rulesEvent(session, seatId, `${sourceCardName} resolves, but the sacrificed creature had no power.`);
    const gained = rulesEvent({ ...session, seats: session.seats.map((item) => (item.id === seatId ? { ...item, life: item.life + amount } : item)) }, seatId, `${seat.name} gains ${amount} life from ${sourceCardName}.`);
    const targets = seat.board.battlefield.filter((card) => card.typeLine.includes("Creature") && !sacrificed.some((gone) => gone.id === card.id));
    if (targets.length === 0) return gained;
    if (seat.kind === "human" && targets.length > 1) {
      return queuePlayerChoice(gained, {
        seatId, sourceCardId, sourceCardName,
        prompt: `${sourceCardName}: put ${amount} +1/+1 counter${amount === 1 ? "" : "s"} on which creature you control?`,
        options: targets.map((card) => ({ label: `${card.name} (${effectivePower(card)}/${effectiveToughness(card)})`, value: card.id })),
        resolver: "counters_on_creature", data: { amount }
      });
    }
    const best = [...targets].sort((a, b) => effectivePower(b) - effectivePower(a))[0];
    return resolveDeferredChoice(gained, seatId, sourceCardId, sourceCardName, "counters_on_creature", { amount }, best.id);
  }
  if (effect.kind === "drain_by_sacrificed_power" || effect.kind === "mill_by_sacrificed_power") {
    const amount = Math.max(0, ...sacrificed.map((creature) => effectivePower(creature)));
    if (amount <= 0) return rulesEvent(session, seatId, `${sourceCardName} resolves, but the sacrificed creature had no power.`);
    if (effect.kind === "mill_by_sacrificed_power") {
      // "Target player": the opponent with the most cards left to lose.
      const victim = session.seats.filter((other) => other.id !== seatId && !other.hasLost).sort((a, b) => (b.library?.length ?? 0) - (a.library?.length ?? 0))[0];
      return victim ? applyMill(session, victim.id, sourceCardName, amount) : session;
    }
    const victims = session.seats.filter((other) => other.id !== seatId && !other.hasLost);
    const drained: GameSession = { ...session, seats: session.seats.map((other) => (victims.some((victim) => victim.id === other.id) ? { ...other, life: other.life - amount } : other)) };
    return rulesEvent(drained, seatId, `${sourceCardName}: each opponent loses ${amount} life.`);
  }
  if (effect.kind === "search_creature_by_sacrificed_mv" || effect.kind === "search_creature_by_x") return session;

  if (effect.kind === "draw_cards") {
    const drawnOnly = drawMultipleForSeat(session, seatId, effect.amount, `${seat.name} draws ${effect.amount} from ${sourceCardName}.`);
    // Izoni, Thousand-Eyed: "You gain 1 life and draw a card."
    const drawn = effect.alsoGainLife
      ? rulesEvent({ ...drawnOnly, seats: drawnOnly.seats.map((item) => (item.id === seatId ? { ...item, life: item.life + effect.alsoGainLife! } : item)) }, seatId, `${seat.name} gains ${effect.alsoGainLife} life from ${sourceCardName}.`)
      : drawnOnly;
    if (!effect.alsoLoseLife) return drawn;
    return rulesEvent(
      { ...drawn, seats: drawn.seats.map((item) => (item.id === seatId ? { ...item, life: item.life - effect.alsoLoseLife! } : item)) },
      seatId,
      `${seat.name} loses ${effect.alsoLoseLife} life from ${sourceCardName}.`
    );
  }

  if (effect.kind === "gain_life" || effect.kind === "lose_life") {
    const delta = effect.kind === "gain_life" ? effect.amount : -effect.amount;
    return {
      ...session,
      seats: session.seats.map((item) => (item.id === seatId ? { ...item, life: Math.max(0, item.life + delta) } : item)),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} ${delta > 0 ? "gains" : "loses"} ${Math.abs(delta)} life from ${sourceCardName}.`
        },
        ...session.events
      ]
    };
  }

  if (effect.kind === "add_counter") {
    return {
      ...session,
      seats: session.seats.map((item) =>
        item.id === seatId
          ? {
              ...item,
              board: {
                ...item.board,
                battlefield: item.board.battlefield.map((card) => (card.id === sourceCardId ? applyCounterDelta(card, effect.counterKind, effect.amount) : card))
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} puts a ${effect.counterKind} counter on ${sourceCardName}.`
        },
        ...session.events
      ]
    };
  }

  if (effect.kind === "transform_self") {
    return transformPermanent(session, seatId, sourceCardId, sourceCardName, /\bthen untap it\b/i.test(clause));
  }

  if (effect.kind === "dig_type_to_hand") return applyDigPick(session, seatId, sourceCardName, effect.count, effect.typeWord);

  if (effect.kind === "exile_all_graveyards") {
    const exiled = session.seats.reduce((next, other) => (other.board.graveyard ?? []).reduce((acc, card) => moveCardAcrossSeats(acc, other.id, card.id, other.id, "exile").session, next), session);
    return rulesEvent(exiled, seatId, `${seat.name} sacrifices ${sourceCardName}: all graveyards are exiled.`);
  }

  if (effect.kind === "prevent_combat_damage") {
    return {
      ...session,
      combatDamagePrevented: { turn: session.turn },
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} sacrifices ${sourceCardName}; all combat damage is prevented this turn.`,
          detail: "Rules action"
        },
        ...session.events
      ]
    };
  }

  if (effect.kind === "removal") {
    // sourceCard has already left the battlefield by the time this runs (payGenericSacrificeCost
    // sacrifices it before the effect resolves) — passed through anyway since applyRemovalEffect
    // only reads it for excluded-self/self-name checks, same as a normal spell's own source card
    // is still readable off the stack after it's already been sacrificed as an additional cost.
    return applyPrimitiveAction(session, seatId, sourceCard, { kind: "removal", effect: effect.effect });
  }

  // Scry/surveil auto-resolve deterministically for both agents and humans (no dedicated
  // interactive prompt wired up for this entry point yet, matching the auto-resolved mana/search
  // choices used elsewhere in this engine).
  if (effect.kind === "targeted_effect") return applyTargetedEffect(session, seatId, sourceCard, effect.effect);
  // Selfless Spirit / Spectacular Spider-Man: the controller's creatures gain the keywords until end of turn (read off temporaryGrantedKeywords).
  if (effect.kind === "grant_keywords_to_your_creatures") {
    const granted = session.seats.map((item) =>
      item.id !== seatId
        ? item
        : {
            ...item,
            board: {
              ...item.board,
              battlefield: item.board.battlefield.map((permanent) =>
                hasCardType(permanent, "Creature") ? { ...permanent, temporaryGrantedKeywords: [...(permanent.temporaryGrantedKeywords ?? []), ...effect.keywords] } : permanent
              )
            }
          }
    );
    return rulesEvent({ ...session, seats: granted }, seatId, `${seat.name} activates ${sourceCardName}: their creatures gain ${effect.keywords.join(" and ")} until end of turn.`);
  }
  // Fixed mana from a sacrifice (Ashnod's Altar) goes into the human's pool in finishPaidSacrificeAbility, which has the pool state.
  if (effect.kind === "add_mana") return session;
  const surveilAdjustedAmount = effect.kind === "surveil" ? effect.amount + surveilBonusForSeat(seat) : effect.amount;
  return resolveAgentLibraryLookWorkflow(session, seatId, sourceCardName, effect.kind === "surveil" ? "surveil_cards" : "scry_cards", surveilAdjustedAmount);
}

// Pays a generic tap ability's cost (mana + discard + tap) without resolving its effect — kept
// separate from applyGenericTapEffect for the same reason payGenericSacrificeCost is split from
// applySacrificeEffect: activateGenericTapAbility's search_library branch needs to pay the cost,
// sync the floating pool if used, and then open the interactive library-search choice itself.
// humanPool: see payGenericSacrificeCost's own doc comment — same pool-first-then-auto-tap
// preference, and the same poolSpent-on-the-return-value handoff back to the caller.
export function payGenericTapCost(
  session: GameSession,
  seatId: string,
  cardId: string,
  abilityIndex: number,
  humanPool?: ManaPool,
  // A human's own pick for a "Discard a card" cost (Cryptbreaker, ...) — chooseWorstHandCardToDiscard
  // is only the fallback for agents and callers with no prompt of their own.
  chosenDiscardId?: string,
  // A human's own picks for "Tap N untapped Zombies you control" (Cryptbreaker).
  chosenTapCreatureIds?: string[]
): { session: GameSession; ability: GenericTapAbility; card: VisibleCard; poolSpent?: ManaPool } | undefined {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card) return undefined;
  const ability = parseGenericTapAbilities(abilityOracleText(card))[abilityIndex];
  if (!ability) return undefined;
  // "Tap three untapped Zombies you control" has no {T} of its own, so the source's own tapped/summoning-sick state is irrelevant.
  if (!ability.costTapCreatures) {
    if (card.tapped) return undefined;
    if (card.typeLine.includes("Creature") && card.summoningSick && !hasHaste(card)) return undefined;
  }
  const chosenTaps = ability.costTapCreatures && chosenTapCreatureIds && chosenTapCreatureIds.length === ability.costTapCreatures.count
    ? chosenTapCreatureIds.map((id) => seat.board.battlefield.find((creature) => creature.id === id && !creature.tapped)).filter((creature): creature is VisibleCard => Boolean(creature))
    : undefined;
  const tappedForCost = ability.costTapCreatures
    ? chosenTaps && chosenTaps.length === ability.costTapCreatures.count
      ? chosenTaps
      : chooseCreaturesToTapForCost(seat, ability.costTapCreatures.count, ability.costTapCreatures.subtype)
    : undefined;
  if (ability.costTapCreatures && !tappedForCost) return undefined;
  if (!activateOnlyIfConditionMet(ability.clause, seat)) return undefined;
  if (ability.costRemoveCounter && counterCount(card, ability.costRemoveCounter) < 1) return undefined;
  if (ability.costExileGraveyard && (seat.board.graveyard?.length ?? 0) < ability.costExileGraveyard) return undefined;
  const lifeCost = ability.costLifeCommanderColors ? commanderColorCount(seat) : 0;
  if (lifeCost > 0 && seat.life <= lifeCost) return undefined;
  const tapIds = new Set((tappedForCost ?? []).map((creature) => creature.id));

  const discardCard = ability.costDiscard
    ? (chosenDiscardId ? discardableHandCards(seat, ability.costDiscardType).find((handCard) => handCard.id === chosenDiscardId) : undefined) ?? chooseWorstHandCardToDiscard(seat, ability.costDiscardType)
    : undefined;
  if (ability.costDiscard && !discardCard) return undefined;

  const totalManaCost = manaValueFromManaCost(ability.costManaText);
  const costCard = genericManaAbilityCostShim(ability);
  const poolPayment = totalManaCost > 0 && humanPool ? payCostFromPool(humanPool, costCard, totalManaCost) : undefined;
  // excludeCardId: cardId — same self-tap exclusion as payGenericSacrificeCost above: this
  // ability's own {T} already requires the source untapped, so it can't also tap itself via a
  // separate mana ability of its own to help pay this same activation's generic cost.
  const payment =
    totalManaCost > 0
      ? poolPayment?.ok
        ? poolPayment
        : chooseManaSourcesForCost(seat, costCard, totalManaCost, cardId, session.seats)
      : undefined;
  if (totalManaCost > 0 && !payment?.ok) return undefined;

  let next = session;
  if (payment?.ok && !poolPayment?.ok) {
    next = { ...next, seats: next.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  }
  if (lifeCost > 0) {
    next = rulesEvent({ ...next, seats: next.seats.map((item) => (item.id === seatId ? { ...item, life: item.life - lifeCost } : item)) }, seatId, `${seat.name} pays ${lifeCost} life to activate ${card.name}.`);
  }
  if (discardCard) {
    next = {
      ...next,
      seats: next.seats.map((item) =>
        item.id === seatId
          ? {
              ...item,
              board: {
                ...item.board,
                hand: item.board.hand.filter((handCard) => handCard.id !== discardCard.id),
                graveyard: [...(item.board.graveyard ?? []), { ...discardCard, zone: "graveyard" as const, counters: undefined, interpretedEffects: undefined }]
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: seatVerb(seat, `${seat.name} discards ${discardCard.name} to activate ${card.name}.`, `You discard ${discardCard.name} to activate ${card.name}.`),
          detail: "Rules action"
        },
        ...next.events
      ]
    };
  }
  // "Exile seven cards from your graveyard" (Sunken Palace): the least valuable cards go first (spells and lands before creatures).
  if (ability.costExileGraveyard) {
    const keepValue = (graveCard: VisibleCard) => (graveCard.typeLine.includes("Creature") ? 3 : /Instant|Sorcery/.test(graveCard.typeLine) ? 1 : 2) + graveCard.manaValue * 0.1;
    const toExile = [...(seat.board.graveyard ?? [])].sort((a, b) => keepValue(a) - keepValue(b)).slice(0, ability.costExileGraveyard);
    next = toExile.reduce((current, graveCard) => moveCardBetweenVisibleZones(current, seatId, graveCard.id, "exile"), next);
    next = rulesEvent(next, seatId, `${seat.name} exiles ${toExile.length} cards from their graveyard to activate ${card.name}.`);
  }
  // Paying the {T} in the cost taps the source; an "Untap ~." effect (Retrofitter Foundry's 2nd/3rd
  // abilities) then immediately untaps it again as part of resolving — net result is it stays
  // untapped, and can be activated again the same turn if its cost can be paid again.
  next = {
    ...next,
    seats: next.seats.map((item) =>
      item.id === seatId
        ? {
            ...item,
            board: {
              ...item.board,
              battlefield: item.board.battlefield.map((c) =>
                tapIds.has(c.id)
                  ? { ...c, tapped: true }
                  : c.id !== cardId || ability.costTapCreatures
                  ? c
                  : {
                      ...c,
                      tapped: !ability.untapsSelf,
                      // "Remove a gold counter from this artifact" is part of the cost.
                      ...(ability.costRemoveCounter
                        ? { counters: (c.counters ?? []).map((counter) => (counter.kind === ability.costRemoveCounter ? { ...counter, count: counter.count - 1 } : counter)).filter((counter) => counter.count > 0) }
                        : {})
                    }
              )
            }
          }
        : item
    )
  };

  return { session: next, ability, card, poolSpent: poolPayment?.ok ? poolPayment.pool : undefined };
}

// The effect half of a plain "{cost}: effect." activated ability (parseGenericManaAbilities'
// GenericManaAbility.effectText) — dispatched through the same removal/zone/common-trigger parsers
// already used for modal spells and recurring phase triggers, rather than re-narrowing the effect
// vocabulary a fourth time. Unlike parseGenericModalEffect's per-mode variant, this also tries
// removalEffect first: a single (non-modal) ability isn't already owned by removalSpells.ts's own
// modal system the way a modal bullet can be, so there's no overlap to guard against here.
type GenericAbilityEffect =
  | { kind: "removal"; effect: RemovalEffect }
  | { kind: "zone"; effect: ZoneEffect }
  | { kind: "pump"; effect: PumpEffect }
  | { kind: "search_library"; effect: SearchLibraryEffect }
  | { kind: "animate_enchantment" }
  | { kind: "trigger"; effect: TriggerEffect }
  | { kind: "phase_out" }
  // "{2}{C}: Exile enchanted creature." (Utter Insignificance): exiles whatever this Aura is attached to.
  | { kind: "exile_enchanted" }
  // Scavenging Ooze: "Exile target card from a graveyard. If it was a creature card, put a +1/+1 counter on this creature and you gain 1 life."
  | { kind: "exile_graveyard_card_scavenge" }
  // "Untap all lands you control." (Beledros Witherbloom)
  | { kind: "untap_all_lands" }
  | { kind: "transform_self" };

// "Transform Heliod." (Heliod, the Radiant Dawn's own activated ability, naming itself rather than
// "this creature") — reuses transformPermanent, the same flip-to-other-face logic
// SacrificeEffect's own "transform_self" kind already applies for sacrifice-costed transformers
// (Westvale Abbey). The "not target" exclusion keeps this from misreading an unrelated "Transform
// target X" effect (transforming something else) as this shape.
function parseTransformSelfEffect(effectText: string): boolean {
  return /^transform\s+(?!target\b)/i.test(effectText);
}

// "Enchanted/equipped creature phases out." (Vanishing) — no other card in this engine's real-card
// sample uses this shape, matched narrowly like parseEnchantmentAnimationEffect above rather than a
// general "X phases out" grammar.
function parsePhaseOutEffect(effectText: string): boolean {
  return /\b(?:enchanted|equipped) creature phases out\b/i.test(effectText);
}

// Shared by every "enter as a copy" shape parseEnterAsCopyEffect recognizes: controlledOnly (Estrid's
// Invocation) only ever looks at the caster's own battlefield, while the broader "any ... on the
// battlefield" shape (Mirrormade) searches everyone's — the caster's own permanents first (matching
// the "prefer your own stuff" bias other unmodeled-choice heuristics in this file already use, e.g.
// chooseNonAuraEnchantmentTarget for Zur), then every other seat's in turn order.
// The target spec for a zone effect only when the human really has more than one thing to choose between.
// A reanimation ability's target (Whip of Erebos, Cauldron of Essence): a creature/permanent card in your graveyard, or in any graveyard.
function reanimateAbilitySpec(effect: ZoneEffect): TargetSpec | undefined {
  if (effect.kind !== "reanimate") return undefined;
  return {
    id: "target",
    zone: "graveyard",
    permanentType: effect.targetType === "card" ? undefined : (effect.targetType as TargetSpec["permanentType"]),
    controller: effect.anyGraveyard ? "any" : "you",
    min: 1,
    max: 1,
    prompt: `Return target ${effect.targetType === "card" ? "card" : effect.targetType.replace(/_/g, " ")} card from ${effect.anyGraveyard ? "a" : "your"} graveyard to the battlefield.`
  };
}

function zoneChoiceSpecFor(session: GameSession, seatId: string, effect: ZoneEffect, sourceCard: VisibleCard): TargetSpec | undefined {
  const spec = zoneEffectTargetSpec(effect) ?? reanimateAbilitySpec(effect);
  if (!spec) return undefined;
  return legalTargets(session, seatId, spec, sourceCard).length > 1 ? spec : undefined;
}

// Zur, Eternal Schemer: "Target non-Aura enchantment becomes a creature. It's still an enchantment.
// Its power and toughness are each equal to its mana value." No other card in this engine's real-card
// sample uses this shape, so it's matched loosely (the two load-bearing phrases, not the whole
// sentence verbatim) rather than pinned to one exact wording.
function parseEnchantmentAnimationEffect(effectText: string): boolean {
  const text = effectText.toLowerCase();
  return /\btarget non-aura enchantment becomes an? creature\b/.test(text) && /\bequal to its mana value\b/.test(text);
}

// No chosenX exists for an activated ability (parseGenericManaAbilities already declines {X}-cost
// abilities outright), so unlike the modal/spell path this never substitutes X — a "target creature
// gets -X/-X" activated ability is simply declined, the same "no guessing" behavior it always had.
export function parseGenericAbilityEffect(effectText: string): GenericAbilityEffect | undefined {
  // "Untap all lands you control." (Beledros Witherbloom's "Pay 10 life: ...").
  if (/^untap all lands you control\.?(?:\s*activate only once each turn\.?)?$/i.test(effectText.trim())) return { kind: "untap_all_lands" };
  if (/^exile target card from a graveyard\.\s*if it was a creature card, put a \+1\/\+1 counter on this creature and you gain 1 life\.?$/i.test(effectText.trim())) {
    return { kind: "exile_graveyard_card_scavenge" };
  }
  // One verb on a chosen target ("Target creature gains flying until end of turn.", "Put a +1/+1 counter on target creature. Activate only as a
  // sorcery."): the shared targeted effect, so a human is asked for the target. The timing restriction is enforced by the ability's own limiter.
  const targetedWhole = parseTargetedEffect(effectText.replace(/\s*activate only (?:as a sorcery|during your turn)[^.]*\.?\s*$/i, ""));
  if (targetedWhole) return { kind: "trigger", effect: { kind: "targeted_effect", effect: targetedWhole } };
  const removal = parseRemovalEffect(effectText);
  if (removal) return { kind: "removal", effect: removal };
  const pump = parseTargetedPump(effectText);
  if (pump) return { kind: "pump", effect: pump };
  const searchLibrary = parseSearchLibraryEffectText(effectText);
  if (searchLibrary) return { kind: "search_library", effect: searchLibrary };
  if (parseEnchantmentAnimationEffect(effectText)) return { kind: "animate_enchantment" };
  if (parsePhaseOutEffect(effectText)) return { kind: "phase_out" };
  if (/^exile enchanted (?:creature|permanent)\.?$/i.test(effectText.trim())) return { kind: "exile_enchanted" };
  if (parseTransformSelfEffect(effectText)) return { kind: "transform_self" };
  const zone = parseZoneEffect(effectText);
  if (zone) return { kind: "zone", effect: zone };
  const trigger = commonTriggerEffect(effectText, "clause");
  if (trigger) return { kind: "trigger", effect: trigger };
  return undefined;
}

// No "you control" restriction is printed on Zur's ability, but a deterministic policy still needs
// to pick one side first: the caster's own non-Aura enchantment is almost always the intended target
// (it's what benefits from Zur's "enchantment creatures you control have deathtouch, lifelink, and
// hexproof"), so that's preferred; an opponent's is only considered if the caster controls none.
function chooseNonAuraEnchantmentTarget(session: GameSession, casterSeatId: string): { seatId: string; card: VisibleCard } | undefined {
  const ownCandidates = session.seats.find((seat) => seat.id === casterSeatId)?.board.battlefield.filter(isNonAuraEnchantment) ?? [];
  if (ownCandidates.length > 0) return { seatId: casterSeatId, card: ownCandidates[0] };
  for (const seat of session.seats) {
    if (seat.id === casterSeatId || seat.hasLost) continue;
    const candidate = seat.board.battlefield.find(isNonAuraEnchantment);
    if (candidate) return { seatId: seat.id, card: candidate };
  }
  return undefined;
}

function applyEnchantmentAnimation(session: GameSession, casterSeatId: string, sourceCardName: string, target: { seatId: string; card: VisibleCard }): GameSession {
  return {
    ...session,
    seats: session.seats.map((seat) =>
      seat.id === target.seatId
        ? {
            ...seat,
            board: {
              ...seat.board,
              battlefield: seat.board.battlefield.map((card) =>
                card.id === target.card.id
                  ? { ...card, grantedTypes: [...(card.grantedTypes ?? []).filter((type) => type !== "Creature"), "Creature"], animatedAsCreature: true }
                  : card
              )
            }
          }
        : seat
    ),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId: casterSeatId,
        message: `${target.card.name} becomes a ${target.card.manaValue}/${target.card.manaValue} creature from ${sourceCardName}.`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

// "Enchanted/equipped creature phases out." (Vanishing). Rule 702.26 in full is "treated as though
// it doesn't exist" — untargetable, can't attack/block, doesn't change zones, ignored by SBAs and
// most triggers — which this engine only enforces at the highest-value points (canAttack/canBlock,
// and chooseRemovalTarget so phasing genuinely dodges the removal spells this card is cast to dodge)
// rather than threading a phasedOut check through every board-scanning function; it stays a legal
// (if pointless) target for anthem/devotion-style counting and other targeted effects this codebase
// doesn't route through those two chokepoints. Phases back in, untapped, at its controller's next
// untap step (untapForSeat) — including a Shadow of the Second Sun-style bonus untap step, since
// that's the same real phase.
function applyPhaseOut(session: GameSession, casterSeatId: string, sourceCard: VisibleCard): GameSession {
  const targetId = sourceCard.attachedToId;
  if (!targetId) return session;
  let targetName: string | undefined;
  const next: GameSession = {
    ...session,
    seats: session.seats.map((seat) => ({
      ...seat,
      board: {
        ...seat.board,
        battlefield: seat.board.battlefield.map((card) => {
          if (card.id !== targetId) return card;
          targetName = card.name;
          return { ...card, phasedOut: true };
        })
      }
    }))
  };
  if (!targetName) return session;
  return {
    ...next,
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId: casterSeatId,
        message: `${targetName} phases out from ${sourceCard.name}.`,
        detail: "Rules action"
      },
      ...next.events
    ]
  };
}

function genericAbilityEffectHasLegalTarget(session: GameSession, casterSeatId: string, sourceCard: VisibleCard, effect: GenericAbilityEffect): boolean {
  if (effect.kind === "removal") return removalEffectHasLegalTarget(session, casterSeatId, sourceCard, effect.effect);
  if (effect.kind === "zone") return zoneEffectHasLegalTarget(session, casterSeatId, effect.effect);
  if (effect.kind === "pump") return choosePumpTarget(session, casterSeatId, effect.effect) !== undefined;
  if (effect.kind === "animate_enchantment") return chooseNonAuraEnchantmentTarget(session, casterSeatId) !== undefined;
  if (effect.kind === "exile_graveyard_card_scavenge") return session.seats.some((seat) => (seat.board.graveyard ?? []).length > 0);
  if (effect.kind === "phase_out") {
    const target = sourceCard.attachedToId ? findPermanentById(session, sourceCard.attachedToId) : undefined;
    return target !== undefined && !target.phasedOut;
  }
  if (effect.kind === "exile_enchanted") return sourceCard.attachedToId !== undefined && findPermanentById(session, sourceCard.attachedToId) !== undefined;
  if (effect.kind === "transform_self") return Boolean(sourceCard.faces && sourceCard.faces.length === 2);
  if (effect.kind === "untap_all_lands") return (session.seats.find((item) => item.id === casterSeatId)?.board.battlefield ?? []).some((card) => card.tapped && card.typeLine.includes("Land"));
  if (effect.kind === "search_library") {
    const seat = session.seats.find((item) => item.id === casterSeatId);
    return (seat?.library?.length ?? 0) > 0;
  }
  if (effect.effect.kind === "add_counter" && effect.effect.scope !== "self" && effect.effect.scope !== "context") {
    return chooseCounterTarget(session, casterSeatId, effect.effect.counterKind, effect.effect.scope === "target_creature_you_control") !== undefined;
  }
  return true;
}

export function applyGenericAbilityEffect(session: GameSession, casterSeatId: string, sourceCard: VisibleCard, effect: GenericAbilityEffect, chosenCardId?: string): GameSession {
  if (effect.kind === "removal") return applyPrimitiveAction(session, casterSeatId, sourceCard, { kind: "removal", effect: effect.effect });
  if (effect.kind === "zone") return applyPrimitiveAction(session, casterSeatId, sourceCard, { kind: "zone", effect: effect.effect });
  if (effect.kind === "pump") return applyPrimitiveAction(session, casterSeatId, sourceCard, { kind: "pump_target", effect: effect.effect });
  if (effect.kind === "animate_enchantment") {
    const target = chooseNonAuraEnchantmentTarget(session, casterSeatId);
    return target ? applyEnchantmentAnimation(session, casterSeatId, sourceCard.name, target) : session;
  }
  // search_library never actually reaches this function: activateGenericManaAbility detects it
  // before ever calling applyGenericAbilityEffect and opens the interactive library-search choice
  // instead (pendingRuleChoice is component state this pure function can't reach).
  if (effect.kind === "search_library") return session;
  if (effect.kind === "exile_graveyard_card_scavenge") {
    const caster = session.seats.find((seat) => seat.id === casterSeatId);
    const all = session.seats.flatMap((seat) => (seat.board.graveyard ?? []).map((card) => ({ seatId: seat.id, card })));
    // Prefers an opponent's creature card (growth + graveyard hate), then any other opponent card; never your own creature
    // cards, which may be reanimation targets. Falls back to your own non-creature card only when nothing else exists.
    const rank = (entry: { seatId: string; card: VisibleCard }) => {
      const isCreature = entry.card.typeLine.includes("Creature");
      if (entry.seatId !== casterSeatId) return (isCreature ? 20 : 10) + entry.card.manaValue / 100;
      return isCreature ? -1 : 1;
    };
    const pick = (chosenCardId ? all.find((entry) => entry.card.id === chosenCardId) : undefined) ?? all.reduce<(typeof all)[number] | undefined>((best, entry) => (!best || rank(entry) > rank(best) ? entry : best), undefined);
    if (!caster || !pick) return rulesEvent(session, casterSeatId, `${sourceCard.name} has no card in any graveyard to exile.`);
    const exiled = moveCardAcrossSeats(session, pick.seatId, pick.card.id, pick.seatId, "exile").session;
    if (!pick.card.typeLine.includes("Creature")) return rulesEvent(exiled, casterSeatId, `${caster.name} exiles ${pick.card.name} with ${sourceCard.name}.`);
    const grown: GameSession = {
      ...exiled,
      seats: exiled.seats.map((seat) =>
        seat.id !== casterSeatId
          ? seat
          : {
              ...seat,
              life: seat.life + 1,
              board: {
                ...seat.board,
                battlefield: seat.board.battlefield.map((card) =>
                  card.id === sourceCard.id
                    ? { ...card, counters: [...(card.counters ?? []).filter((counter) => counter.kind !== "+1/+1"), { kind: "+1/+1", count: ((card.counters ?? []).find((counter) => counter.kind === "+1/+1")?.count ?? 0) + 1 }] }
                    : card
                )
              }
            }
      )
    };
    return rulesEvent(grown, casterSeatId, `${caster.name} exiles ${pick.card.name} with ${sourceCard.name}: a +1/+1 counter and 1 life.`);
  }
  if (effect.kind === "untap_all_lands") {
    const owner = session.seats.find((seat) => seat.id === casterSeatId);
    const tappedLands = (owner?.board.battlefield ?? []).filter((card) => card.tapped && card.typeLine.includes("Land"));
    const untapped: GameSession = {
      ...session,
      seats: session.seats.map((seat) =>
        seat.id !== casterSeatId ? seat : { ...seat, board: { ...seat.board, battlefield: seat.board.battlefield.map((card) => (card.tapped && card.typeLine.includes("Land") ? { ...card, tapped: false } : card)) } }
      )
    };
    return rulesEvent(untapped, casterSeatId, `${owner?.name ?? "A player"} untaps ${tappedLands.length} land${tappedLands.length === 1 ? "" : "s"} with ${sourceCard.name}.`);
  }
  if (effect.kind === "phase_out") return applyPhaseOut(session, casterSeatId, sourceCard);
  if (effect.kind === "exile_enchanted") {
    const holder = sourceCard.attachedToId ? session.seats.find((seat) => seat.board.battlefield.some((card) => card.id === sourceCard.attachedToId)) : undefined;
    const target = holder?.board.battlefield.find((card) => card.id === sourceCard.attachedToId);
    if (!holder || !target) return noLegalTargetEvent(session, casterSeatId, sourceCard.name);
    return rulesEvent(moveCardBetweenVisibleZones(session, holder.id, target.id, "exile"), casterSeatId, `${sourceCard.name} exiles ${target.name}.`);
  }
  if (effect.kind === "transform_self") return transformPermanent(session, casterSeatId, sourceCard.id, sourceCard.name, false);
  const syntheticTrigger: Extract<PendingAction, { type: "trigger" }> = {
    id: crypto.randomUUID(),
    type: "trigger",
    actorSeatId: casterSeatId,
    controllerSeatId: casterSeatId,
    sourceCardId: sourceCard.id,
    sourceCardName: sourceCard.name,
    triggerKind: "common",
    effect: effect.effect,
    message: ""
  };
  return resolveTriggerEffect(session, syntheticTrigger);
}

// Pays a generic mana-cost ability's cost (mana + discard + once-each-turn marking) without
// resolving its effect — kept separate from applyGenericAbilityEffect for the same reason
// payGenericSacrificeCost/payGenericTapCost are: a search_library effect needs to open the
// interactive library-search choice, which this pure function can't do.
// humanPool: see payGenericSacrificeCost's own doc comment — same pool-first-then-auto-tap
// preference, and the same poolSpent-on-the-return-value handoff back to the caller.
export function payGenericManaCost(
  session: GameSession,
  seatId: string,
  cardId: string,
  abilityIndex: number,
  humanPool?: ManaPool
): { session: GameSession; ability: GenericManaAbility; card: VisibleCard; effect: GenericAbilityEffect; poolSpent?: ManaPool } | undefined {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card) return undefined;
  const ability = parseGenericManaAbilities(card.oracleText)[abilityIndex];
  if (!ability) return undefined;
  if (!activateOnlyIfConditionMet(ability.clause, seat)) return undefined;

  const onceKey = `${session.turn}:${cardId}:generic_mana:${abilityIndex}`;
  const limitedOnceEachTurn = hasOnceEachTurnLimiter(ability.clause);
  if (limitedOnceEachTurn && session.onceEachTurnEffectsUsed?.includes(onceKey)) return undefined;

  const effect = parseGenericAbilityEffect(ability.effectText);
  if (!effect) return undefined;

  const discardCard = ability.costDiscard ? chooseWorstHandCardToDiscard(seat) : undefined;
  if (ability.costDiscard && !discardCard) return undefined;

  // Rule 118.4: a life-payment cost can't be paid below 0 life — checked as a hard precondition,
  // same as costDiscard's "nothing to discard" check above.
  if (seat.life < ability.costLife) return undefined;
  const totalManaCost = manaValueFromManaCost(ability.costManaText);
  const costCard = genericManaAbilityCostShim(ability);
  const poolPayment = totalManaCost > 0 && humanPool ? payCostFromPool(humanPool, costCard, totalManaCost) : undefined;
  const payment =
    totalManaCost > 0
      ? poolPayment?.ok
        ? poolPayment
        : chooseManaSourcesForCost(seat, costCard, totalManaCost, undefined, session.seats)
      : undefined;
  if (totalManaCost > 0 && !payment?.ok) return undefined;

  let next = session;
  if (limitedOnceEachTurn) {
    next = { ...next, onceEachTurnEffectsUsed: [...(next.onceEachTurnEffectsUsed ?? []), onceKey] };
  }
  if (payment?.ok && !poolPayment?.ok) {
    next = { ...next, seats: next.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  }
  if (ability.costLife > 0) {
    next = {
      ...next,
      seats: next.seats.map((item) => (item.id === seatId ? { ...item, life: item.life - ability.costLife } : item)),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} pays ${ability.costLife} life to activate ${card.name}.`,
          detail: "Rules action"
        },
        ...next.events
      ]
    };
  }
  if (discardCard) {
    next = {
      ...next,
      seats: next.seats.map((item) =>
        item.id === seatId
          ? {
              ...item,
              board: {
                ...item.board,
                hand: item.board.hand.filter((handCard) => handCard.id !== discardCard.id),
                graveyard: [...(item.board.graveyard ?? []), { ...discardCard, zone: "graveyard" as const, counters: undefined, interpretedEffects: undefined }]
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: seatVerb(seat, `${seat.name} discards ${discardCard.name} to activate ${card.name}.`, `You discard ${discardCard.name} to activate ${card.name}.`),
          detail: "Rules action"
        },
        ...next.events
      ]
    };
  }

  return { session: next, ability, card, effect, poolSpent: poolPayment?.ok ? poolPayment.pool : undefined };
}

// humanPool: see payGenericSacrificeCost's own doc comment — same pool-first-then-auto-tap
// preference, and the same poolSpent-on-the-return-value handoff back to the caller.
function resolveSelfUntapAbility(session: GameSession, seatId: string, cardId: string, abilityIndex: number, humanPool?: ManaPool): { session: GameSession; poolSpent?: ManaPool } {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card || !card.tapped) return { session };
  const ability = parseSelfUntapAbilities(card.oracleText)[abilityIndex];
  if (!ability) return { session };
  if (!activateOnlyIfConditionMet(ability.clause, seat)) return { session };

  const costCard = genericCostShim(ability.costMana);
  const poolPayment = ability.costMana > 0 && humanPool ? payCostFromPool(humanPool, costCard, ability.costMana) : undefined;
  const payment =
    ability.costMana > 0 ? (poolPayment?.ok ? poolPayment : chooseManaSourcesForCost(seat, costCard, ability.costMana, undefined, session.seats)) : undefined;
  if (ability.costMana > 0 && !payment?.ok) return { session };

  let next = session;
  if (payment?.ok && !poolPayment?.ok) {
    next = { ...next, seats: next.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  }
  return {
    session: {
      ...next,
      seats: next.seats.map((item) =>
        item.id === seatId
          ? { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((c) => (c.id === cardId ? { ...c, tapped: false } : c)) } }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} activates ${card.name}: untaps it.`,
          detail: "Rules action"
        },
        ...next.events
      ]
    },
    poolSpent: poolPayment?.ok ? poolPayment.pool : undefined
  };
}

// Inserts a creature type into the subtype section (after the em dash) rather than just
// appending it to the end of the type line, so a "becomes a 4/4 Construct ... in addition to its
// other types" upgrade reads as "Artifact Creature — Construct Servo", not "Artifact Creature —
// Servo Construct" tacked on after the whole line.
function addCreatureTypeToTypeLine(typeLine: string, newType: string): string {
  if (typeLine.toLowerCase().includes(newType.toLowerCase())) return typeLine;
  const dashIndex = typeLine.indexOf("—");
  if (dashIndex === -1) return `${typeLine} — ${newType}`;
  const before = typeLine.slice(0, dashIndex).trim();
  const after = typeLine.slice(dashIndex + 1).trim();
  return `${before} — ${newType}${after ? ` ${after}` : ""}`;
}

export function applyGenericTapEffect(
  session: GameSession,
  seatId: string,
  sourceCardId: string,
  sourceCardName: string,
  effect: GenericTapEffect,
  clause: string,
  // The human's pick for "exile/choose target card in a graveyard" effects (Cemetery Reaper, Zul Ashur).
  chosenCardId?: string,
  options?: { skipDiscardSeatId?: string }
): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return session;

  // search_library never actually reaches this function: activateGenericTapAbility detects it
  // before ever calling applyGenericTapEffect and opens the interactive library-search choice
  // instead (pendingRuleChoice is component state applyGenericTapEffect can't reach). This branch
  // only exists to keep the switch exhaustive for the type checker.
  if (effect.kind === "search_library") return session;

  if (effect.kind === "self_counter") {
    return rulesEvent(
      { ...session, seats: session.seats.map((item) => (item.id !== seatId ? item : { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((card) => (card.id === sourceCardId ? applyCounterDelta(card, effect.counterKind, effect.amount) : card)) } })) },
      seatId,
      `${seat.name} activates ${sourceCardName}: it gets ${effect.amount} ${effect.counterKind} counter${effect.amount === 1 ? "" : "s"}.`
    );
  }

  if (effect.kind === "next_spell_improvise") {
    return rulesEvent({ ...session, seats: session.seats.map((item) => (item.id === seatId ? { ...item, nextSpellHasImprovise: true } : item)) }, seatId, `${seat.name} activates ${sourceCardName}: the next spell this turn has improvise.`);
  }

  if (effect.kind === "copy_imprinted_card") {
    // The best imprinted card (highest mana value) — a human is not asked which.
    const imprinted = session.seats.flatMap((item) => item.board.exile ?? []).filter((card) => card.imprintedOnId === sourceCardId).sort((a, b) => b.manaValue - a.manaValue)[0];
    if (!imprinted) return rulesEvent(session, seatId, `${sourceCardName} has no imprinted card to copy.`);
    const copied = createCopyTokenForSeat(session, seatId, imprinted);
    const hasted: GameSession = {
      ...copied.session,
      seats: copied.session.seats.map((item) =>
        item.id !== seatId
          ? item
          : {
              ...item,
              board: {
                ...item.board,
                battlefield: item.board.battlefield.map((card) =>
                  card.id === copied.token.id ? { ...card, summoningSick: false, exileAtEndStep: true, grantedKeywords: [...(card.grantedKeywords ?? []), "haste"], temporaryGrantedKeywords: [...(card.temporaryGrantedKeywords ?? []), "haste"] } : card
                )
              }
            }
      )
    };
    return rulesEvent(hasted, seatId, `${seat.name} activates ${sourceCardName} and creates a token copy of ${imprinted.name} with haste (exiled at the next end step).`);
  }

  if (effect.kind === "create_tokens") {
    const specs = parseCreateTokenSpecs(clause);
    if (specs.length === 0) return session;
    const created = createTokensForSeat(session, seatId, sourceCardId, specs);
    const createdNames = created.createdTokens.map((token) => token.name);
    return {
      ...created.session,
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} activates ${sourceCardName} and creates ${createdNames.join(", ")}.`,
          detail: "Rules action"
        },
        ...created.session.events
      ]
    };
  }

  if (effect.kind === "counter_and_transform") {
    const target = chooseGenericTapTarget(seat, effect.targetTypeFilter);
    if (!target) return session;
    const transforms = effect.power !== undefined && effect.toughness !== undefined;
    return {
      ...session,
      seats: session.seats.map((item) =>
        item.id === seatId
          ? {
              ...item,
              board: {
                ...item.board,
                battlefield: item.board.battlefield.map((permanent) => {
                  if (permanent.id !== target.id) return permanent;
                  const withCounter = applyCounterDelta(permanent, "+1/+1", 1);
                  if (!transforms) return withCounter;
                  return {
                    ...withCounter,
                    power: String(effect.power),
                    toughness: String(effect.toughness),
                    typeLine: effect.addedType ? addCreatureTypeToTypeLine(withCounter.typeLine, effect.addedType) : withCounter.typeLine
                  };
                })
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: transforms
            ? `${seat.name} activates ${sourceCardName}: ${target.name} gets a +1/+1 counter and becomes a ${effect.power}/${effect.toughness}${effect.addedType ? ` ${effect.addedType}` : ""}.`
            : `${seat.name} activates ${sourceCardName}: ${target.name} gets a +1/+1 counter.`,
          detail: "Rules action"
        },
        ...session.events
      ]
    };
  }

  if (effect.kind === "zone_effect") return applyZoneEffect(session, seatId, sourceCardName, effect.effect);

  // Castle Locthwain: "Draw a card, then you lose life equal to the number of cards in your hand."
  if (effect.kind === "draw_then_lose_life_equal_hand") {
    const drawn = drawForSeat(session, seatId, `${seat.name} draws a card from ${sourceCardName}.`);
    const handSize = drawn.seats.find((item) => item.id === seatId)?.board.hand.length ?? 0;
    return rulesEvent(
      { ...drawn, seats: drawn.seats.map((item) => (item.id === seatId ? { ...item, life: item.life - handSize } : item)) },
      seatId,
      `${seat.name} loses ${handSize} life (cards in hand) from ${sourceCardName}.`
    );
  }

  if (effect.kind === "target_unblockable" || effect.kind === "commander_gains_keyword") {
    const keyword = effect.kind === "target_unblockable" ? "can't be blocked" : effect.keyword;
    const mine = session.seats.find((item) => item.id === seatId);
    const pool = (mine?.board.battlefield ?? []).filter((card) => (effect.kind === "commander_gains_keyword" ? card.commander : card.typeLine.includes("Creature") && !card.summoningSick));
    const target = pool.sort((a, b) => effectivePower(b) - effectivePower(a))[0] ?? (effect.kind === "target_unblockable" ? strongestControlledCreature(mine) : undefined);
    if (!mine || !target) return rulesEvent(session, seatId, `${sourceCardName} has no creature to target.`);
    return rulesEvent(
      {
        ...session,
        seats: session.seats.map((item) =>
          item.id !== seatId
            ? item
            : {
                ...item,
                board: {
                  ...item.board,
                  battlefield: item.board.battlefield.map((card) =>
                    card.id === target.id ? { ...card, temporaryGrantedKeywords: [...(card.temporaryGrantedKeywords ?? []), keyword], grantedKeywords: [...new Set([...(card.grantedKeywords ?? []), keyword])] } : card
                  )
                }
              }
        )
      },
      seatId,
      `${seat.name} activates ${sourceCardName}: ${target.name} ${effect.kind === "target_unblockable" ? "can't be blocked this turn" : `gains ${keyword} until end of turn`}.`
    );
  }
  if (effect.kind === "hideaway_play") {
    const mine = session.seats.find((item) => item.id === seatId);
    const hidden = (mine?.board.exile ?? []).find((card) => card.hideawaySourceId === sourceCardId);
    if (!mine || !hidden) return rulesEvent(session, seatId, `${sourceCardName} has no hidden card.`);
    const damageCondition = hideawayDamageConditionMet(session, seatId, effect.conditionText);
    const conditionMet = damageCondition !== undefined ? damageCondition : isBoardConditionMet(effect.conditionText, mine, session.seats);
    if (!conditionMet) return rulesEvent(session, seatId, `${seat.name} activates ${sourceCardName}, but the condition isn't met.`);
    return rulesEvent(
      {
        ...session,
        seats: session.seats.map((item) =>
          item.id !== seatId ? item : { ...item, board: { ...item.board, exile: (item.board.exile ?? []).map((card) => (card.id === hidden.id ? { ...card, exiledPlayableBySeatId: seatId, exiledPlayableFree: true, exiledPlayableAnyTime: !isLandCard(card), hideawaySourceId: undefined } : card)) } }
        )
      },
      seatId,
      `${seat.name} may play ${hidden.name} from exile without paying its mana cost (${sourceCardName}).${seat.kind === "human" ? " Open your exile pile and use Cast from Exile." : ""}`
    );
  }
  if (effect.kind === "dig_creature_to_battlefield") {
    const lands = seat.board.battlefield.filter((card) => isLandCard(card)).length;
    return applyDigToBattlefield(session, seatId, sourceCardName, effect.count, lands);
  }
  if (effect.kind === "draw_and_lose_life") {
    const drawn = drawMultipleForSeat(session, seatId, effect.draw, `${seat.name} draws ${effect.draw} card${effect.draw === 1 ? "" : "s"} from ${sourceCardName}.`);
    return rulesEvent({ ...drawn, seats: drawn.seats.map((item) => (item.id === seatId ? { ...item, life: item.life - effect.lose } : item)) }, seatId, `${seat.name} loses ${effect.lose} life from ${sourceCardName}.`);
  }
  if (effect.kind === "draw_cards") {
    return drawMultipleForSeat(session, seatId, effect.amount, `${seat.name} draws ${effect.amount} card${effect.amount === 1 ? "" : "s"} from ${sourceCardName}.`);
  }

  // Geier Reach Sanitarium: each player draws a card, then discards a card.
  if (effect.kind === "each_player_loots") {
    let next = session;
    for (const player of session.seats) {
      if (player.hasLost) continue;
      next = drawForSeat(next, player.id, `${player.name} draws a card from ${sourceCardName}.`);
      const current = next.seats.find((item) => item.id === player.id);
      const discard = current && player.id !== options?.skipDiscardSeatId ? chooseWorstHandCardToDiscard(current) : undefined;
      if (discard) {
        next = moveCardBetweenVisibleZones(next, player.id, discard.id, "graveyard");
        next = rulesEvent(next, player.id, `${player.name} discards ${discard.name} (${sourceCardName}).`);
      }
    }
    return next;
  }

  // Lord of the Accursed: all Zombies gain menace until end of turn (every player's).
  if (effect.kind === "grant_keyword_to_all_until_eot") {
    const seats = session.seats.map((item) => ({
      ...item,
      board: {
        ...item.board,
        battlefield: item.board.battlefield.map((permanent) =>
          permanentMatchesQualifier(permanent, effect.typeMatcher) ? { ...permanent, temporaryGrantedKeywords: [...(permanent.temporaryGrantedKeywords ?? []), effect.keyword] } : permanent
        )
      }
    }));
    return rulesEvent({ ...session, seats }, seatId, `${seat.name} activates ${sourceCardName}: all ${effect.typeMatcher}s gain ${effect.keyword} until end of turn.`);
  }

  // Cemetery Reaper: exile a creature card from a graveyard, then create the token.
  if (effect.kind === "exile_graveyard_creature_then_tokens") {
    const candidates = session.seats.flatMap((item) => (item.board.graveyard ?? []).filter((c) => c.typeLine.includes("Creature")).map((c) => ({ seatId: item.id, card: c })));
    // Prefers an opponent's best card (graveyard hate), otherwise the weakest card of its own.
    const opposing = candidates.filter((entry) => entry.seatId !== seatId);
    const heuristicPick = opposing.length > 0 ? opposing.reduce((a, b) => (b.card.manaValue > a.card.manaValue ? b : a)) : candidates.reduce((a, b) => (b.card.manaValue < a.card.manaValue ? b : a), candidates[0]);
    const pick = candidates.find((entry) => entry.card.id === chosenCardId) ?? heuristicPick;
    if (!pick) return rulesEvent(session, seatId, `${sourceCardName} has no creature card in any graveyard to exile.`);
    const exiled = moveCardAcrossSeats(session, pick.seatId, pick.card.id, pick.seatId, "exile").session;
    const specs = parseCreateTokenSpecs(clause);
    const created = specs.length > 0 ? createTokensForSeat(exiled, seatId, sourceCardId, specs).session : exiled;
    return rulesEvent(created, seatId, `${seat.name} activates ${sourceCardName}: exiles ${pick.card.name} and creates a token.`);
  }

  // Zul Ashur: pick the best matching creature card in the graveyard and let its controller cast it this turn.
  if (effect.kind === "grant_graveyard_cast") {
    const options = (seat.board.graveyard ?? []).filter((c) => permanentMatchesQualifier(c, effect.cardMatcher));
    const best = options.find((c) => c.id === chosenCardId) ?? (options.length > 0 ? options.reduce((a, b) => (b.manaValue > a.manaValue ? b : a)) : undefined);
    if (!best) return rulesEvent(session, seatId, `${sourceCardName} has no ${effect.cardMatcher} card in your graveyard to cast.`);
    return rulesEvent(
      {
        ...session,
        seats: session.seats.map((item) =>
          item.id === seatId
            ? { ...item, board: { ...item.board, graveyard: (item.board.graveyard ?? []).map((c) => (c.id === best.id ? { ...c, graveyardCastGrant: { seatId, turn: session.turn } } : c)) } }
            : item
        )
      },
      seatId,
      `${seat.name} may cast ${best.name} from the graveyard this turn (${sourceCardName}).`
    );
  }

  if (effect.kind === "targeted_effect") {
    const tapSource = session.seats.flatMap((item) => item.board.battlefield).find((card) => card.id === sourceCardId) ?? ({ id: sourceCardId, name: sourceCardName, typeLine: "", oracleText: "", manaValue: 0, colors: [], role: "effect", zone: "battlefield" } as VisibleCard);
    return applyTargetedEffect(session, seatId, tapSource, effect.effect, chosenCardId ? findPermanentOwnerTarget(session, chosenCardId) : undefined);
  }
  if (effect.kind !== "bounce_own") return session;
  // bounce_own
  const target = chooseGenericTapTarget(seat, effect.targetTypeFilter);
  if (!target) return session;
  const bounced = moveCardBetweenVisibleZones(session, seatId, target.id, "hand");
  return {
    ...bounced,
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${seat.name} activates ${sourceCardName}: returns ${target.name} to hand.`,
        detail: "Rules action"
      },
      ...bounced.events
    ]
  };
}

function legalRoomUnlockActions(seat: PlayerSeat, allSeats?: PlayerSeat[]): LegalAgentAction[] {
  const actions: LegalAgentAction[] = [];
  for (const card of seat.board.battlefield) {
    const doors = roomDoorFaces(card);
    if (!doors) continue;
    const unlocked = card.unlockedFaceIndices ?? [];
    if (unlocked.length !== 1) continue;
    const lockedIndex = unlocked[0] === 0 ? 1 : 0;
    const lockedDoor = doors[lockedIndex];
    const shim = cardWithFaceManaCost(card, lockedDoor.manaCost);
    const totalCost = Math.max(0, manaValueFromManaCost(lockedDoor.manaCost) - unlockCostReduction(seat));
    const payment = chooseManaSourcesForCost(seat, shim, totalCost, undefined, allSeats);
    if (!payment.ok) continue;
    actions.push({
      id: `unlock-door:${card.id}`,
      actionType: "activate_ability",
      abilityKind: "unlock_room_door",
      faceIndex: lockedIndex,
      cardId: card.id,
      targetIds: [],
      label: `unlock ${lockedDoor.name} on ${card.name}`,
      detail: `${lockedDoor.manaCost ?? ""} ${lockedDoor.oracleText} Payable with ${formatManaPoolPayment(payment.spent)}.`.trim(),
      role: card.role
    });
  }
  return actions;
}

function createCombatBlockChoice(session: GameSession, attackerSeatId: string | undefined): BlockChoiceState | undefined {
  if (!attackerSeatId) return undefined;
  const attacker = session.seats.find((seat) => seat.id === attackerSeatId);
  const attackingCard = attacker?.board.battlefield.find((card) => card.attacking && !card.blockDecided);
  const target = attackingCard ? resolveAttackTarget(session, attackingCard.attackTargetId) : undefined;
  if (!attacker || !attackingCard || !target) return undefined;
  return {
    attackerSeatId: attacker.id,
    defenderSeatId: target.seat.id,
    attackerCardId: attackingCard.id,
    targetId: attackingCard.attackTargetId ?? target.seat.id
  };
}

// Triggered "deals N damage to any target" (Dragon Tempest-style, Scourge of Valkas, Warstorm Surge, Outpost Siege's Dragons): the damage the
// human aims, the source for legality checks, and the target pool. Undefined when the trigger isn't a single-target damage trigger.
function triggerDamageAiming(session: GameSession, trigger: Extract<PendingAction, { type: "trigger" }>, controllerSeatId: string): { effect: RemovalEffect; options: LabeledSlot["options"] } | undefined {
  const fallbackSource = { id: trigger.sourceCardId, name: trigger.sourceCardName, typeLine: "", oracleText: "", manaValue: 0, colors: [], role: "effect", zone: "battlefield" } as VisibleCard;
  const source = findPermanentById(session, trigger.sourceCardId) ?? fallbackSource;
  if (trigger.effect.kind === "damage_effect" && trigger.effect.effect.kind === "damage") {
    const dmg = trigger.effect.effect;
    // "target creature or planeswalker an opponent controls" (Skysovereign) / "target creature defending player controls" (Tyrant's Familiar):
    // only the opponents' permanents are legal, not just any creature.
    const opponentOnly = dmg.targetType === "creature" && /\btarget creature(?: or planeswalker)? (?:an opponent controls|defending player controls|you don'?t control)/i.test(source.oracleText ?? "");
    const slot = opponentOnly ? (/target creature or planeswalker\b/i.test(source.oracleText ?? "") ? "opponent_creature_or_planeswalker" : "opponent_creature") : dmg.targetType === "player" ? "player" : dmg.targetType === "creature" ? "any_creature" : "any_damage";
    return { effect: dmg, options: labeledTargetOptions(session, controllerSeatId, slot, source) };
  }
  if (trigger.effect.kind === "context_power_damage") {
    const entering = trigger.contextCardId ? findPermanentById(session, trigger.contextCardId) : undefined;
    const power = entering ? Math.max(0, effectivePower(entering)) : 0;
    if (!entering || power <= 0) return undefined;
    return { effect: { kind: "damage", amount: power, targetType: "any" }, options: labeledTargetOptions(session, controllerSeatId, "any_damage", entering) };
  }
  return undefined;
}

// Rule 603.3d: a triggered ability's target is chosen as it goes on the stack. An agent's targeted trigger used to pick it only as it resolved, so
// the stack panel showed nothing to respond to. Returns the encoded target (the same string a human's pick is stored as in effect.chosenOption:
// "p:seat" / "c:seat:card" for the damage kinds, a bare card id for the counter/pump/destroy kinds) for the kinds whose resolution already reads it,
// or undefined when the trigger needs no target or nothing is legal (resolution then keeps its own pick).
const agentTargetedTriggerKinds = new Set<string>([
  "targeted_effect", "damage_effect", "context_power_damage", "add_counter", "pump_target_creature", "double_power_counters", "target_creature_gains_keyword",
  "destroy_tapped_creature", "aura_reanimate", "exile_card_from_graveyard", "become_artifact_target", "gain_control_target_artifact"
]);

function agentTriggerTarget(session: GameSession, trigger: Extract<PendingAction, { type: "trigger" }>): string | undefined {
  const seatId = trigger.controllerSeatId;
  const mine = session.seats.find((seat) => seat.id === seatId);
  const source = findPermanentById(session, trigger.sourceCardId);
  const effect = trigger.effect;
  const bare = (pick: { seatId: string; card: VisibleCard } | undefined) => pick?.card.id;
  switch (effect.kind) {
    case "targeted_effect": {
      const picked = source ? pickTargetedEffectTarget(session, seatId, source, effect.effect) : undefined;
      return picked ? encodeChosenTarget(picked) : undefined;
    }
    // "Deals N damage to any target" (Scourge of Valkas, Dragon Tempest): the same deterministic damage chooser a spell uses.
    case "damage_effect": {
      if (!source || effect.effect.kind === "modal") return undefined;
      const picked = agentRemovalEffectTarget(session, seatId, source, effect.effect, undefined, false);
      return picked ? encodeChosenTarget(picked) : undefined;
    }
    // Warstorm Surge: the entering creature deals damage equal to its power.
    case "context_power_damage": {
      const entering = trigger.contextCardId ? findPermanentById(session, trigger.contextCardId) : undefined;
      const power = entering ? Math.max(0, effectivePower(entering)) : 0;
      if (!entering || power <= 0) return undefined;
      const aim = chooseDamageTarget(session, seatId, power, "any", entering);
      if (!aim) return undefined;
      return encodeChosenTarget(aim.kind === "player" ? { kind: "player", seatId: aim.seat.id } : { kind: "card", seatId: aim.seatId, cardId: aim.card.id });
    }
    case "add_counter": {
      if (effect.scope !== "target_creature" && effect.scope !== "target_creature_you_control") return undefined;
      return bare(chooseCounterTarget(targetableView(session, seatId, source ?? ({ id: trigger.sourceCardId, name: trigger.sourceCardName, typeLine: "", oracleText: "", colors: [], manaValue: 0, role: "effect", zone: "battlefield" } as VisibleCard)), seatId, effect.counterKind, effect.scope === "target_creature_you_control"));
    }
    case "pump_target_creature":
    case "double_power_counters":
      return bare(mine && strongestControlledCreature(mine) ? { seatId, card: strongestControlledCreature(mine)! } : undefined);
    case "target_creature_gains_keyword": {
      const keywords = effect.keywords;
      const best = (mine?.board.battlefield ?? [])
        .filter((card) => card.typeLine.includes("Creature") && !keywords.every((keyword) => hasKeyword(card, keyword)))
        .sort((a, b) => Number(Boolean(b.summoningSick)) - Number(Boolean(a.summoningSick)) || effectivePower(b) - effectivePower(a))[0];
      return best?.id;
    }
    // "You may destroy target creature if it's tapped": the opposing tapped creature worth the most.
    case "destroy_tapped_creature": {
      const worth = (card: VisibleCard) => card.manaValue * 2 + Math.max(0, effectivePower(card)) + (card.commander ? 5 : 0);
      const pool = session.seats
        .filter((seat) => seat.id !== seatId)
        .flatMap((seat) => seat.board.battlefield.filter((card) => card.tapped && card.typeLine.includes("Creature") && !hasShroud(card) && !hasHexproof(card) && !card.phasedOut));
      return [...pool].sort((a, b) => worth(b) - worth(a))[0]?.id;
    }
    // Animate Dead and friends: the best creature card in any graveyard.
    case "aura_reanimate":
      return chooseReanimationTarget(session, seatId, true, "creature")?.card.id;
    // Soul-Guide Lantern: an opponent's best graveyard card, else any.
    case "exile_card_from_graveyard": {
      const worth = (card: VisibleCard) => card.manaValue + (card.typeLine.includes("Creature") ? 2 : 0);
      const pool = session.seats.flatMap((seat) => (seat.board.graveyard ?? []).map((card) => ({ seatId: seat.id, card })));
      return [...pool].sort((a, b) => Number(b.seatId !== seatId) - Number(a.seatId !== seatId) || worth(b.card) - worth(a.card))[0]?.card.id;
    }
    // Memnarch: an agent turns one of its own nonartifact permanents into an artifact (a creature first, else its best other permanent).
    case "become_artifact_target": {
      const pool = (mine?.board.battlefield ?? []).filter((card) => !hasCardType(card, "Artifact") && !card.phasedOut && !hasShroud(card));
      return [...pool].sort((a, b) => Number(b.typeLine.includes("Creature")) - Number(a.typeLine.includes("Creature")) || b.manaValue - a.manaValue)[0]?.id;
    }
    case "gain_control_target_artifact": {
      const pool = session.seats
        .filter((seat) => seat.id !== seatId)
        .flatMap((seat) => seat.board.battlefield.filter((card) => hasCardType(card, "Artifact") && !hasShroud(card) && !hasHexproof(card) && !card.phasedOut));
      return [...pool].sort((a, b) => b.manaValue + Math.max(0, effectivePower(b)) - (a.manaValue + Math.max(0, effectivePower(a))))[0]?.id;
    }
    default:
      return undefined;
  }
}

function encodeChosenTarget(target: ChosenTarget): string {
  return target.kind === "player" ? "p:" + target.seatId : "c:" + target.seatId + ":" + target.cardId;
}

// The other permanents still available to sacrifice (God-Eternal Bontu), plus a final "done" entry.
function sacrificeOptions(seat: PlayerSeat, sourceCardId: string, alreadyPicked: string[]): Array<{ index: number; label: string }> {
  const remaining = seat.board.battlefield.filter((card) => card.id !== sourceCardId && !alreadyPicked.includes(card.id));
  return [...remaining.map((card, index) => ({ index, label: "Sacrifice " + card.name + (card.tapped ? " (tapped)" : "") })), { index: remaining.length, label: alreadyPicked.length === 0 ? "Sacrifice nothing" : "Done (sacrifice " + alreadyPicked.length + ", draw " + alreadyPicked.length + ")" }];
}

// The hand cards still available to discard, plus a final "done" entry (The Elder Dragon War's chapter II).
function discardOptions(seat: PlayerSeat, alreadyPicked: string[]): Array<{ index: number; label: string }> {
  const remaining = seat.board.hand.filter((card) => !alreadyPicked.includes(card.id));
  return [...remaining.map((card, index) => ({ index, label: "Discard " + card.name })), { index: remaining.length, label: alreadyPicked.length === 0 ? "Discard nothing" : "Done (discard " + alreadyPicked.length + ", draw " + alreadyPicked.length + ")" }];
}

// Dragonhawk's delayed trigger, at the beginning of its controller's end step: 2 damage to each opponent for each exiled card not played.
export function resolveEndStepExileDamage(session: GameSession, activeSeatId: string): GameSession {
  const active = session.seats.find((seat) => seat.id === activeSeatId);
  const marked = (active?.board.exile ?? []).filter((card) => card.exileEndStepDamage?.controllerSeatId === activeSeatId);
  if (!active || marked.length === 0) return session;
  const { sourceName, amount } = marked[0].exileEndStepDamage!;
  let next: GameSession = {
    ...session,
    seats: session.seats.map((seat) =>
      seat.id !== activeSeatId ? seat : { ...seat, board: { ...seat.board, exile: (seat.board.exile ?? []).map((card) => (card.exileEndStepDamage?.controllerSeatId === activeSeatId ? { ...card, exileEndStepDamage: undefined } : card)) } }
    )
  };
  const source = next.seats.flatMap((seat) => seat.board.battlefield).find((card) => card.name === sourceName);
  for (const opponent of session.seats) {
    if (opponent.id === activeSeatId || opponent.hasLost) continue;
    next = applyCombatDamageToTarget(next, sourceName, { seat: next.seats.find((item) => item.id === opponent.id)! }, amount * marked.length, source, activeSeatId, "noncombat");
  }
  return rulesEvent(next, activeSeatId, `${sourceName}: ${marked.length} exiled card${marked.length === 1 ? " was" : "s were"} not played, so each opponent takes ${amount * marked.length} damage.`);
}

// Rule 903.8: commander tax is +{2} for each time the commander was CAST from the command zone, whether the
// spell later resolves, is countered, fizzles, or is replaced. So the bump happens the moment the cast is
// announced (playCard), never on resolution — the commander card stays in the command zone while its spell is
// on the stack in this engine, so a countered cast leaves it there with the tax already counted. Casting from
// anywhere else (e.g. after it was put into hand) records nothing.
export function recordCommanderCast(session: GameSession, seatId: string, cardId: string): GameSession {
  return {
    ...session,
    seats: session.seats.map((seat) =>
      seat.id === seatId && seat.board.commander?.id === cardId
        ? { ...seat, board: { ...seat.board, commander: { ...seat.board.commander, commanderTax: (seat.board.commander.commanderTax ?? 0) + 2 } } }
        : seat
    )
  };
}

function isNonAuraEnchantment(card: VisibleCard): boolean {
  return card.typeLine.includes("Enchantment") && !isAura(card);
}

// What a resolving spell's own "prevent ..." text does: the Fog family ("prevent all combat damage that would be dealt this turn[ by non-X creatures]",
// Arachnogenesis), Batwing Brume's color-conditional halves (read off the mana actually spent), and targeted/self shields on an instant or sorcery
// ("prevent all combat damage that would be dealt to you this turn" + Inkshield's per-point tokens, "prevent the next N damage ... to target ...").
// A creature's own enters-trigger goes through commonTriggerEffect's prevent_damage; a pumped target's "it" through applyTargetedPumpEffect.
export function applySpellDamagePrevention(session: GameSession, seatId: string, sourceCard: VisibleCard, castTarget: ChosenTarget | undefined, manaSpentColors: string[]): GameSession {
  const text = etbEffectText(sourceCard.oracleText);
  const brumeFog = /\bprevent all combat damage that would be dealt this turn if \{w\} was spent to cast this spell/i.test(text);
  const fogMatch = brumeFog ? (manaSpentColors.includes("W") ? ["", undefined] : null) : text.match(/\bprevent all combat damage that would be dealt this turn(?! if\b)(?: by non-([a-z]+) creatures)?\b/i);
  const parsedSpec = /Instant|Sorcery/.test(sourceCard.typeLine) ? parseDamagePrevention(text) : undefined;
  let next = parsedSpec && parsedSpec.scope !== "it" ? addDamageShieldsFromSpec(session, seatId, sourceCard, parsedSpec, castTarget) : session;
  // Batwing Brume's {B} half: each player loses 1 life per attacking creature they control.
  if (manaSpentColors.includes("B") && /\beach player loses 1 life for each attacking creature they control if \{b\} was spent to cast this spell/i.test(text)) {
    for (const seat of next.seats) {
      const attackers = seat.board.battlefield.filter((card) => card.attacking).length;
      if (attackers > 0) next = rulesEvent({ ...next, seats: next.seats.map((item) => (item.id === seat.id ? { ...item, life: item.life - attackers } : item)) }, seat.id, `${sourceCard.name}: ${seat.name} loses ${attackers} life (one per attacking creature).`);
    }
  }
  if (!fogMatch) return next;
  return {
    ...next,
    combatDamagePrevented: { turn: next.turn, exceptType: fogMatch[1] ? capitalizeWord(fogMatch[1]) : undefined },
    events: [
      { id: crypto.randomUUID(), at: new Date().toISOString(), seatId, message: `${sourceCard.name}: all combat damage is prevented this turn${fogMatch[1] ? ` except from ${capitalizeWord(fogMatch[1])} creatures` : ""}.`, detail: "Rules action" },
      ...next.events
    ]
  };
}

// "Your opponents can't cast spells during your turn." (Dragonlord Dromoka): true when some OTHER seat with that static is the active player.
export function spellCastLockedOut(session: GameSession, castingSeatId: string, activeSeatId: string | undefined): boolean {
  if (!activeSeatId || activeSeatId === castingSeatId) return false;
  const active = session.seats.find((seat) => seat.id === activeSeatId);
  return Boolean(active?.board.battlefield.some((card) => !card.abilitiesStripped && /your opponents can'?t cast spells during your turn/i.test(card.oracleText)));
}

// "Add {R} for each tapped land your opponents control." (Mana Geyser) — the amount only. Mana pools
// live in the component's own React state, not in GameSession, so a pure session transformer can't
// add the mana itself; the live-game caller reads this and adds it to the caster's pool (see
// resolvePendingAction). Headless self-play has no pool at all, so this effect stays unmodeled there.
export function manaFromTappedOpponentLands(session: GameSession, casterSeatId: string): number {
  return session.seats
    .filter((seat) => seat.id !== casterSeatId && !seat.hasLost)
    .reduce((total, seat) => total + seat.board.battlefield.filter((card) => card.tapped && isLandCard(card)).length, 0);
}

// Applies one SpellExtraEffect (spellExtras.ts) for its caster. Same deterministic, no-target-prompt
// conventions as the rest of this file's removal/pump appliers: the "best" target is picked by
// heuristic for every seat kind (there's no selection UI for these shapes yet).
// The clickable list for one target slot. Opponent-side targets are filtered by hexproof/shroud/protection and player hexproof, like the
// automatic picks are.
// The modes a human may choose between for a cast modal spell, with the removal/generic parse that owns the card. Undefined when the card
// isn't modal, or fewer than two modes are usable (the automatic path then does the one thing that can be done).
export function spellModePrompt(
  session: GameSession,
  controllerSeatId: string,
  source: VisibleCard,
  chosenX?: number
): { chooseCount: number; labels: string[]; removalModes?: Array<Exclude<RemovalEffect, { kind: "modal" }>>; genericModes?: GenericModalMode[]; distinctPerTurn?: boolean } | undefined {
  if (!parseSpellModalHeader(source.oracleText)) return undefined;
  const removal = parseRemovalEffect(etbEffectText(source.oracleText));
  if (removal?.kind === "modal") {
    const modes = removal.modes.filter((mode) => removalEffectHasLegalTarget(session, controllerSeatId, source, mode));
    if (modes.length < 2) return undefined;
    return { chooseCount: Math.min(removal.chooseCount, modes.length), labels: modes.map((mode) => describeRemovalMode(mode)), removalModes: modes };
  }
  if (removal) return undefined;
  const generic = parseGenericModalEffect(source.oracleText, chosenX);
  if (!generic) return undefined;
  const modes = generic.modes.filter((mode) => genericModalModeHasLegalTarget(session, controllerSeatId, mode));
  if (modes.length < 2) return undefined;
  return { chooseCount: Math.min(generic.chooseCount, modes.length), labels: modes.map((mode, index) => mode.text ?? `Mode ${index + 1}`), genericModes: modes, distinctPerTurn: generic.distinctPerTurn };
}

export function labeledTargetOptions(
  session: GameSession,
  controllerSeatId: string,
  slot: "any_damage" | "player" | "own_creature" | "own_permanent" | "any_permanent" | "opponent_creature" | "opponent_creature_or_planeswalker" | "any_creature",
  source: VisibleCard
): LabeledSlot["options"] {
  const options: LabeledSlot["options"] = [];
  const cardLabel = (card: VisibleCard, seat: PlayerSeat) => {
    const stats = card.typeLine.includes("Creature") ? ` (${effectivePower(card)}/${effectiveToughness(card)})` : "";
    return `${card.name}${stats} — ${seat.id === controllerSeatId ? "yours" : seat.name}`;
  };
  const targetable = (card: VisibleCard, seat: PlayerSeat) => seat.id === controllerSeatId || (!hasShroud(card) && !hasHexproof(card) && !isProtectedFrom(card, source));
  for (const seat of session.seats) {
    if (seat.hasLost) continue;
    const own = seat.id === controllerSeatId;
    if (slot === "any_damage" || slot === "player") {
      if (slot === "player" || own || !playerHasHexproof(seat)) {
        if (!own || slot === "any_damage") options.push({ label: `${seat.name} (${seat.life} life)`, target: { kind: "player", seatId: seat.id } });
      }
    }
    for (const card of seat.board.battlefield) {
      const isCreature = card.typeLine.includes("Creature");
      const isPlaneswalker = card.typeLine.includes("Planeswalker");
      const wanted =
        slot === "any_damage" ? isCreature || isPlaneswalker :
        slot === "own_creature" ? own && isCreature :
        slot === "own_permanent" ? own :
        slot === "any_permanent" ? true :
        slot === "any_creature" ? isCreature :
        slot === "opponent_creature" ? !own && isCreature :
        slot === "opponent_creature_or_planeswalker" ? !own && (isCreature || isPlaneswalker) :
        false;
      if (wanted && targetable(card, seat)) options.push({ label: cardLabel(card, seat), target: { kind: "card", seatId: seat.id, cardId: card.id } });
    }
  }
  // Opponents' things first, then by name — the likely choices lead the list; capped so the modal stays usable.
  return options
    .sort((a, b) => Number(a.target.seatId === controllerSeatId) - Number(b.target.seatId === controllerSeatId))
    .slice(0, 16);
}

// ---- Cast-time targeting (rule 601.2c): modes and targets are chosen as the spell is cast, so opponents see them on the stack.

function optionsFromSpec(session: GameSession, seatId: string, spec: TargetSpec, source: VisibleCard): LabeledSlot["options"] {
  return legalTargets(session, seatId, spec, source)
    .map((target) => {
      if (target.kind === "player") {
        const seat = session.seats.find((item) => item.id === target.seatId);
        return { label: `${seat?.name ?? "Player"} (${seat?.life ?? 0} life)`, target: { kind: "player" as const, seatId: target.seatId } };
      }
      const owner = session.seats.find((item) => item.id === target.seatId);
      const stats = target.card.typeLine.includes("Creature") ? ` (${effectivePower(target.card)}/${effectiveToughness(target.card)})` : "";
      const where = spec.zone === "graveyard" ? `${owner?.id === seatId ? "your" : owner?.name + "'s"} graveyard` : owner?.id === seatId ? "yours" : owner?.name;
      return { label: `${target.card.name}${stats} — ${where}`, target: { kind: "card" as const, seatId: target.seatId, cardId: target.card.id } };
    })
    .slice(0, 24);
}

// The target slots one removal-shaped effect (or mode) asks for.
function removalSlots(session: GameSession, seatId: string, source: VisibleCard, effect: RemovalEffect): LabeledSlot[] {
  const named = (prompt: string, options: LabeledSlot["options"]): LabeledSlot[] => [{ prompt: `${source.name}: ${prompt}`, options }];
  switch (effect.kind) {
    case "destroy":
    case "exile":
    case "bounce": {
      const spec = removalEffectTargetSpec(effect, source.id);
      return spec ? named(spec.prompt.replace(/^./, (c) => c.toLowerCase()).replace(/^/, "choose a target — "), optionsFromSpec(session, seatId, spec, source)) : [];
    }
    case "damage": {
      if (effect.targetType === "creature") {
        const spec = removalEffectTargetSpec(effect, source.id);
        return spec ? named("choose a creature to damage.", optionsFromSpec(session, seatId, spec, source)) : [];
      }
      return named("choose a target for the damage.", labeledTargetOptions(session, seatId, effect.targetType === "player" ? "player" : "any_damage", source));
    }
    case "grant_keywords":
      return named("choose a creature you control to gain " + effect.keywords.join(" and ") + " until end of turn.", labeledTargetOptions(session, seatId, "own_creature", source));
    default:
      return [];
  }
}

function zoneSlots(session: GameSession, seatId: string, source: VisibleCard, effect: ZoneEffect): LabeledSlot[] {
  // Victimize: "Choose two target creature cards in your graveyard. Sacrifice a creature. If you do, return the chosen cards ..." —
  // one slot per graveyard target, then the creature to sacrifice (picked up front, since the cast prompt is where the player decides).
  if (effect.kind === "sacrifice_then_reanimate") {
    const owner = session.seats.find((item) => item.id === seatId);
    const graveyardOptions: LabeledSlot["options"] = (owner?.board.graveyard ?? [])
      .filter((card) => card.typeLine.includes("Creature"))
      .map((card) => ({ label: `${card.name} (mana value ${card.manaValue})`, target: { kind: "card" as const, seatId, cardId: card.id } }));
    const slots: LabeledSlot[] = Array.from({ length: effect.targetCount }, (_, index) => ({
      prompt: `${source.name}: choose creature card ${index + 1} of ${effect.targetCount} in your graveyard.`,
      options: graveyardOptions
    }));
    const sacrificeOptions = labeledTargetOptions(session, seatId, "own_creature", source);
    if (sacrificeOptions.length > 0) slots.push({ prompt: `${source.name}: choose the creature you sacrifice when it resolves.`, options: sacrificeOptions });
    return slots;
  }
  const spec = zoneEffectTargetSpec(effect);
  return spec ? [{ prompt: `${source.name}: ${spec.prompt}`, options: optionsFromSpec(session, seatId, spec, source) }] : [];
}

// The spellExtras shapes that name targets as the spell is cast (rule 601.2c): Bite Down's two creatures, Chandra's Ignition's creature, Chaos Warp's
// permanent, "target permanent you control gains ...", and the "target opponent" ones (Consumed by Greed, Secret Rendezvous).
const CAST_TARGETED_EXTRA_KINDS: string[] = ["creature_bites", "grant_keywords", "shuffle_permanent_reveal_top", "creature_damages_everything_else", "opponent_sacrifices_greatest_power", "you_and_opponent_draw"];

type CastStructure =
  | { kind: "removal"; effect: Exclude<RemovalEffect, { kind: "modal" }> }
  | { kind: "removal_modal"; modal: Extract<RemovalEffect, { kind: "modal" }> }
  | { kind: "generic_modal"; modal: GenericModalEffect }
  | { kind: "zone"; effect: ZoneEffect }
  | { kind: "extra"; effect: SpellExtraEffect }
  | { kind: "pump"; effect: PumpEffect }
  | { kind: "targeted"; effect: TargetedEffect }
  // An Aura spell targets as it is CAST (rule 303.4a / 601.2c): "Enchant creature [you control]".
  | { kind: "aura"; restriction: "creature" | "creature_you_control" };

// What a spell does that needs the caster's decisions — only for instants and sorceries (a permanent's enters effect is a trigger, whose
// targets are chosen when it triggers).
export function castStructure(card: VisibleCard, chosenX?: number): CastStructure | undefined {
  if (!card.typeLine.includes("Instant") && !card.typeLine.includes("Sorcery")) {
    if (isAura(card)) {
      const restriction = enchantRestriction(card.oracleText);
      if (restriction === "creature" || restriction === "creature_you_control") return { kind: "aura", restriction };
    }
    return undefined;
  }
  const text = etbEffectText(card.oracleText);
  if (parseModalHeader(card.oracleText)) {
    const removal = parseRemovalEffect(text);
    if (removal?.kind === "modal") return { kind: "removal_modal", modal: removal };
    if (removal) return undefined;
    const generic = parseGenericModalEffect(card.oracleText, chosenX);
    return generic ? { kind: "generic_modal", modal: generic } : undefined;
  }
  const removal = parseRemovalEffect(text);
  if (removal && removal.kind !== "modal") return { kind: "removal", effect: removal };
  const zone = parseZoneEffect(text);
  if (zone) return { kind: "zone", effect: zone };
  const extra = parseSpellExtraEffects(text).find((effect) => CAST_TARGETED_EXTRA_KINDS.includes(effect.kind));
  if (extra) return { kind: "extra", effect: extra };
  const pump = parseTargetedPump(chosenX !== undefined ? substituteX(text, chosenX) : text);
  if (pump) return { kind: "pump", effect: pump };
  const targetedSpell = parseTargetedEffect(text);
  if (targetedSpell) return { kind: "targeted", effect: targetedSpell };
  return undefined;
}

function extraSlots(session: GameSession, seatId: string, source: VisibleCard, effect: SpellExtraEffect): LabeledSlot[] {
  const text = etbEffectText(source.oracleText);
  if (effect.kind === "creature_bites") {
    return [
      { prompt: `${source.name}: choose the creature you control that deals the damage.`, options: labeledTargetOptions(session, seatId, "own_creature", source) },
      { prompt: `${source.name}: choose the creature that takes it.`, options: labeledTargetOptions(session, seatId, /creature or planeswalker you don'?t control/i.test(text) ? "opponent_creature_or_planeswalker" : "opponent_creature", source) }
    ];
  }
  if (effect.kind === "shuffle_permanent_reveal_top") {
    return [{ prompt: `${source.name}: choose the permanent its owner shuffles into their library.`, options: labeledTargetOptions(session, seatId, "any_permanent", source) }];
  }
  if (effect.kind === "grant_keywords") {
    return [{ prompt: `${source.name}: choose a permanent you control to gain ${effect.keywords.join(" and ")} until end of turn.`, options: labeledTargetOptions(session, seatId, "own_permanent", source) }];
  }
  if (effect.kind === "creature_damages_everything_else") {
    return [{ prompt: `${source.name}: choose the creature you control that deals the damage.`, options: labeledTargetOptions(session, seatId, "own_creature", source) }];
  }
  if (effect.kind === "opponent_sacrifices_greatest_power" || effect.kind === "you_and_opponent_draw") {
    return [{ prompt: `${source.name}: choose a target opponent.`, options: labeledTargetOptions(session, seatId, "player", source) }];
  }
  return [];
}

function genericModeSlots(session: GameSession, seatId: string, source: VisibleCard, mode: GenericModalMode): LabeledSlot[] {
  if (mode.kind === "zone") return zoneSlots(session, seatId, source, mode.effect);
  if (mode.kind === "removal") return removalSlots(session, seatId, source, mode.effect);
  if (mode.kind === "pump") return [{ prompt: `${source.name}: choose a creature.`, options: labeledTargetOptions(session, seatId, "any_creature", source) }];
  // One verb on a chosen target (Saheeli's Artistry's token copies): the legal targets of the shared target spec.
  if (mode.kind === "trigger" && mode.effect.kind === "targeted_effect") {
    const spec = targetedEffectSpec(mode.effect.effect, source.id, source.name);
    const options = legalTargets(session, seatId, spec, source).map((target) => {
      if (target.kind === "player") return { label: session.seats.find((seat) => seat.id === target.seatId)?.name ?? "Player", target: { kind: "player" as const, seatId: target.seatId } };
      const owner = session.seats.find((seat) => seat.id === target.seatId);
      return { label: `${target.card.name} — ${owner?.id === seatId ? "yours" : owner?.name ?? ""}`, target: { kind: "card" as const, seatId: target.seatId, cardId: target.card.id } };
    });
    return [{ prompt: `${source.name}: ${spec.prompt}`, options }];
  }
  return [];
}

// The next question to put to the caster, given what they have already answered; undefined when nothing is left to ask.
export function nextCastPrompt(
  session: GameSession,
  seatId: string,
  card: VisibleCard,
  chosenX: number | undefined,
  answers: CastChoices
): { kind: "modes"; prompt: string; options: Array<{ label: string; mode: number }> } | { kind: "target"; prompt: string; options: LabeledSlot["options"] } | undefined {
  const structure = castStructure(card, chosenX);
  if (!structure) return undefined;
  let slots: LabeledSlot[] = [];
  if (structure.kind === "removal_modal" || structure.kind === "generic_modal") {
    const all = structure.kind === "removal_modal" ? structure.modal.modes : structure.modal.modes;
    const viable = all
      .map((mode, index) => ({ mode, index }))
      .filter(({ mode }) => (structure.kind === "removal_modal" ? removalEffectHasLegalTarget(session, seatId, card, mode as Exclude<RemovalEffect, { kind: "modal" }>) : genericModalModeHasLegalTarget(session, seatId, mode as GenericModalMode)));
    const wanted = Math.min(structure.modal.chooseCount, viable.length);
    const picked = answers.modes ?? [];
    // "One or more / one or both": the player may stop early, so even a spell whose every mode is viable asks.
    const atMost = structure.kind === "generic_modal" && Boolean(structure.modal.atMost) && viable.length > 1;
    if (picked.length < wanted && !answers.modesDone) {
      const remaining = viable.filter(({ index }) => !picked.includes(index));
      // Nothing to decide when every viable mode has to be picked anyway.
      if (!atMost && remaining.length === wanted - picked.length) {
        answers.modes = [...picked, ...remaining.map(({ index }) => index)];
      } else {
        const options = remaining.map(({ mode, index }) => ({
          label: structure.kind === "removal_modal" ? describeRemovalMode(mode as Exclude<RemovalEffect, { kind: "modal" }>) : (mode as GenericModalMode).text ?? `Mode ${index + 1}`,
          mode: index
        }));
        if (atMost && picked.length >= 1) options.push({ label: "Done choosing", mode: -1 });
        return {
          kind: "modes",
          prompt: atMost ? `${card.name}: choose a mode (${picked.length} chosen).` : `${card.name}: choose mode ${picked.length + 1} of ${wanted}.`,
          options
        };
      }
    }
    const chosen = answers.modes ?? [];
    slots = chosen.flatMap((index) => (structure.kind === "removal_modal" ? removalSlots(session, seatId, card, structure.modal.modes[index]) : genericModeSlots(session, seatId, card, structure.modal.modes[index] as GenericModalMode)));
  } else if (structure.kind === "removal") {
    slots = removalSlots(session, seatId, card, structure.effect);
  } else if (structure.kind === "zone") {
    slots = zoneSlots(session, seatId, card, structure.effect);
  } else if (structure.kind === "extra") {
    slots = extraSlots(session, seatId, card, structure.effect);
  } else if (structure.kind === "targeted") {
    slots = [{ prompt: `${card.name}: choose a target.`, options: optionsFromSpec(session, seatId, targetedEffectSpec(structure.effect, card.id, card.name), card) }];
  } else if (structure.kind === "aura") {
    slots = [{ prompt: `${card.name}: choose the creature to enchant${structure.restriction === "creature_you_control" ? " (a creature you control)" : ""}.`, options: labeledTargetOptions(session, seatId, structure.restriction === "creature_you_control" ? "own_creature" : "any_creature", card) }];
  } else {
    slots = [{ prompt: `${card.name}: choose a creature.`, options: labeledTargetOptions(session, seatId, "any_creature", card) }];
  }
  const slot = slots[answers.targets.length];
  if (!slot || slot.options.length === 0) return undefined;
  // A card already picked for an earlier slot can't be picked again (Victimize's second graveyard creature).
  const alreadyPicked = new Set(answers.targets.flatMap((target) => (target.kind === "card" ? [target.cardId] : [])));
  const options = slot.options.filter((option) => option.target.kind !== "card" || !alreadyPicked.has(option.target.cardId));
  if (options.length === 0) return undefined;
  return { kind: "target", prompt: slot.prompt, options };
}

// A card by id in any visible zone of any seat (battlefield, hand, graveyard, exile, library) — lets the text-option pickers show real card art.
function findCardAnywhere(session: GameSession, cardId: string, seatId?: string): VisibleCard | undefined {
  for (const seat of seatId ? session.seats.filter((item) => item.id === seatId).concat(session.seats.filter((item) => item.id !== seatId)) : session.seats) {
    const found = [...seat.board.battlefield, ...seat.board.hand, ...(seat.board.graveyard ?? []), ...(seat.board.exile ?? []), ...(seat.library ?? [])].find((card) => card.id === cardId);
    if (found) return found;
  }
  return undefined;
}

// " targeting Grizzly Bears, Sable" for the event log when an agent casts a spell with recorded targets; a countered spell is named too.
// A modal spell also names its chosen modes: " (chooses: Destroy target creature.; Gain 3 life.) targeting ...".
export function stackTargetText(session: GameSession, targets: ChosenTarget[], counteredName?: string, modeLabels: string[] = []): string {
  const modeText = modeLabels.length > 0 ? ` (chooses: ${modeLabels.join("; ")})` : "";
  const names = targets.map((target) => {
    const seat = session.seats.find((item) => item.id === target.seatId);
    if (target.kind === "player") return seat?.name ?? "a player";
    const card = [...(seat?.board.battlefield ?? []), ...(seat?.board.graveyard ?? [])].find((item) => item.id === target.cardId);
    return card ? `${card.name} (${seat?.name ?? "?"}'s)` : "a card";
  });
  if (counteredName) names.push(counteredName);
  return `${modeText}${names.length > 0 ? ` targeting ${names.join(", ")}` : ""}`;
}

// The session as seen by the seat that is about to aim `source`: opposing permanents `source` could never legally target (shroud, hexproof,
// protection) are hidden, so the cast-time pickers below never choose something that would fizzle on resolution.
function targetableView(session: GameSession, controllerSeatId: string, source: VisibleCard): GameSession {
  return {
    ...session,
    seats: session.seats.map((seat) =>
      seat.id === controllerSeatId
        ? seat
        : { ...seat, board: { ...seat.board, battlefield: seat.board.battlefield.filter((card) => !hasShroud(card) && !hasHexproof(card) && !isProtectedFrom(card, source)) } }
    )
  };
}

function cardTarget(pick: { seatId: string; card: VisibleCard } | undefined): ChosenTarget | undefined {
  return pick ? { kind: "card", seatId: pick.seatId, cardId: pick.card.id } : undefined;
}

// The opponent a "target player" spell is aimed at: not eliminated, no player hexproof; `prefer` orders the candidates.
function agentOpponentTarget(session: GameSession, seatId: string, prefer: (a: PlayerSeat, b: PlayerSeat) => number): ChosenTarget | undefined {
  const opponents = session.seats.filter((seat) => seat.id !== seatId && !seat.hasLost && !playerHasHexproof(seat)).sort(prefer);
  return opponents[0] ? { kind: "player", seatId: opponents[0].id } : undefined;
}

// One removal-shaped effect (or one mode of a modal) -> the target the agent aims it at; undefined when it needs none or nothing is legal.
// `inModal`: a mode of a modal spell is only taken against opponents (see removalModeViable).
function agentRemovalEffectTarget(session: GameSession, seatId: string, card: VisibleCard, effect: Exclude<RemovalEffect, { kind: "modal" }>, chosenX: number | undefined, inModal: boolean): ChosenTarget | undefined {
  // Direct damage ("deals 3 damage to any target"): the same deterministic damage chooser resolution used, run as the spell is cast.
  if (effect.kind === "damage") {
    const amount = effect.amount === "X" ? (effect.xDefinition ? resolveDynamicAmount(session, seatId, effect.xDefinition) : chosenX ?? 0) : effect.amount;
    if (amount <= 0) return undefined;
    const aim = chooseDamageTarget(session, seatId, amount, effect.targetType, card);
    if (!aim) return undefined;
    return aim.kind === "player" ? { kind: "player", seatId: aim.seat.id } : { kind: "card", seatId: aim.seatId, cardId: aim.card.id };
  }
  if (effect.kind === "grant_keywords") return cardTarget(chooseCounterTarget(targetableView(session, seatId, card), seatId, "+1/+1", true));
  if (effect.kind === "destroy") {
    return cardTarget(chooseRemovalTarget(session, seatId, effect.targetType, card, effect.excludedColors, effect.artifactsExcluded, effect.basicsExcluded, true, effect.minToughness, inModal ? true : effect.opponentOnly));
  }
  if (effect.kind === "exile" || effect.kind === "bounce") {
    return cardTarget(inModal ? chooseRemovalTarget(session, seatId, effect.targetType, card, [], false, false, false, undefined, true) : chooseRemovalTarget(session, seatId, effect.targetType, card));
  }
  return undefined;
}

// A reanimate/regrow/gain-control/"target player's graveyard" spell: the graveyard card(s), permanent or player it names as it is cast
// (the same deterministic choosers applyZoneEffect used to run only on resolution).
function agentZoneEffectTargets(session: GameSession, seatId: string, card: VisibleCard, effect: ZoneEffect): ChosenTarget[] | undefined {
  const inGraveyard = (pick: { seatId: string; card: VisibleCard } | undefined): ChosenTarget[] | undefined => (pick ? [{ kind: "card", seatId: pick.seatId, cardId: pick.card.id }] : undefined);
  switch (effect.kind) {
    case "reanimate": {
      const maxManaValue =
        effect.manaValueCeiling === "graveyard_permanent_count"
          ? (session.seats.find((seat) => seat.id === seatId)?.board.graveyard ?? []).filter((item) => !item.typeLine.includes("Instant") && !item.typeLine.includes("Sorcery")).length
          : undefined;
      return inGraveyard(chooseReanimationTarget(session, seatId, effect.anyGraveyard, effect.targetType, maxManaValue));
    }
    case "regrow": {
      const pick = chooseRegrowTarget(session, seatId, effect.targetType, effect.subtype);
      return pick ? [{ kind: "card", seatId, cardId: pick.id }] : undefined;
    }
    case "gain_control": {
      const pick = cardTarget(chooseControlTarget(targetableView(session, seatId, card), seatId));
      return pick ? [pick] : undefined;
    }
    case "mill": {
      if (effect.scope !== "target_player") return undefined;
      const pick = agentOpponentTarget(session, seatId, () => 0);
      return pick ? [pick] : undefined;
    }
    case "graveyard_to_library": {
      if (effect.scope !== "target_player") return undefined;
      const pick = agentOpponentTarget(session, seatId, (a, b) => Number((b.board.graveyard ?? []).length > 0) - Number((a.board.graveyard ?? []).length > 0));
      return pick ? [pick] : undefined;
    }
    case "exile_graveyard": {
      if (effect.scope !== "target_player") return undefined;
      const seatPick = session.seats.find((seat) => seat.id === chooseGraveyardExileTarget(session, seatId));
      return seatPick && (seatPick.id === seatId || !playerHasHexproof(seatPick)) ? [{ kind: "player", seatId: seatPick.id }] : undefined;
    }
    // Victimize: the graveyard creatures it returns (the creature it sacrifices stays an as-it-resolves choice).
    case "sacrifice_then_reanimate": {
      const cards = chooseCreatureCardsFromOwnGraveyard(session, seatId, effect.targetCount);
      return cards ? cards.map((item) => ({ kind: "card" as const, seatId, cardId: item.id })) : undefined;
    }
    default:
      return undefined;
  }
}

// "Target creature gets +X/+X / -X/-X [and gains ...] until end of turn": a buff goes on the agent's own creature, a shrink on an opposing one
// that the spell could legally target.
function agentPumpTarget(session: GameSession, seatId: string, card: VisibleCard, effect: PumpEffect): ChosenTarget | undefined {
  const pick = choosePumpTarget(targetableView(session, seatId, card), seatId, effect, effect.another ? card.id : undefined);
  if (!pick) return undefined;
  const beneficial = effect.power + effect.toughness >= 0;
  if (beneficial !== (pick.seatId === seatId)) return undefined;
  return cardTarget(pick);
}

// The spellExtras shapes that name targets: Bite Down's dealer + victim, Chandra's Ignition's dealer, "target permanent you control gains ...",
// and the two "target opponent" spells.
function agentExtraEffectTargets(session: GameSession, seatId: string, card: VisibleCard, effect: SpellExtraEffect): ChosenTarget[] | undefined {
  const caster = session.seats.find((seat) => seat.id === seatId);
  const view = targetableView(session, seatId, card);
  switch (effect.kind) {
    case "shuffle_permanent_reveal_top": {
      const pick = chooseRemovalTarget(session, seatId, "nonland_permanent", card) ?? chooseRemovalTarget(session, seatId, "permanent", card);
      const target = cardTarget(pick);
      return target ? [target] : undefined;
    }
    case "creature_bites": {
      const dealer = strongestControlledCreature(caster);
      const power = dealer ? Math.max(0, effectivePower(dealer)) : 0;
      if (!dealer || power <= 0) return undefined;
      const aim = chooseDamageTarget(view, seatId, power, "creature", dealer);
      if (!aim || aim.kind !== "creature") return undefined;
      return [
        { kind: "card", seatId, cardId: dealer.id },
        { kind: "card", seatId: aim.seatId, cardId: aim.card.id }
      ];
    }
    case "creature_damages_everything_else": {
      const dealer = strongestControlledCreature(caster);
      return dealer && effectivePower(dealer) > 0 ? [{ kind: "card", seatId, cardId: dealer.id }] : undefined;
    }
    case "grant_keywords": {
      const target = cardTarget(chooseCounterTarget(view, seatId, "+1/+1", true));
      return target ? [target] : undefined;
    }
    case "opponent_sacrifices_greatest_power": {
      // The opponent whose best creature is the biggest (same threat bias the untargeted pick used).
      const best = (seat: PlayerSeat) => (strongestControlledCreature(seat) ? effectivePower(strongestControlledCreature(seat)!) : -1);
      const pick = agentOpponentTarget(session, seatId, (a, b) => best(b) - best(a));
      const chosen = pick && pick.kind === "player" ? session.seats.find((seat) => seat.id === pick.seatId) : undefined;
      return pick && chosen && best(chosen) >= 0 ? [pick] : undefined;
    }
    case "you_and_opponent_draw": {
      // The weakest (lowest life) opponent, so the symmetric draw doesn't feed the biggest threat.
      const pick = agentOpponentTarget(session, seatId, (a, b) => a.life - b.life);
      return pick ? [pick] : undefined;
    }
    default:
      return undefined;
  }
}

// An agent's modal spell: which modes it takes (the same viability and ordering resolution used) and each taken mode's target, in order.
function agentModalCastChoices(session: GameSession, seatId: string, card: VisibleCard, structure: Extract<CastStructure, { kind: "removal_modal" | "generic_modal" }>, chosenX?: number): CastChoices | undefined {
  const modes: number[] = [];
  const targets: ChosenTarget[] = [];
  if (structure.kind === "removal_modal") {
    const ranked = structure.modal.modes
      .map((mode, index) => ({ mode, index }))
      .filter(({ mode }) => removalModeViable(session, seatId, card, mode))
      .map((entry) => ({ ...entry, score: removalModeScore(session, seatId, entry.mode) }))
      .sort((a, b) => b.score - a.score)
      .slice(0, structure.modal.chooseCount);
    for (const { mode, index } of ranked) {
      if (removalSlots(session, seatId, card, mode).length > 0) {
        const target = agentRemovalEffectTarget(session, seatId, card, mode, chosenX, true);
        if (!target) continue;
        targets.push(target);
      }
      modes.push(index);
    }
  } else {
    const modal = structure.modal;
    const viable = modal.modes
      .map((mode, index) => ({ mode, index }))
      .filter(({ mode, index }) => genericModalModeHasLegalTarget(session, seatId, mode) && !(modal.distinctPerTurn && session.onceEachTurnEffectsUsed?.includes(`${session.turn}:${card.id}:mode:${index}`)))
      .slice(0, modal.chooseCount);
    for (const { mode, index } of viable) {
      if (genericModeSlots(session, seatId, card, mode).length > 0) {
        const target = agentGenericModeTarget(session, seatId, card, mode, chosenX);
        if (!target) continue;
        targets.push(target);
      }
      modes.push(index);
    }
  }
  return modes.length > 0 ? { modes, targets } : undefined;
}

function agentGenericModeTarget(session: GameSession, seatId: string, card: VisibleCard, mode: GenericModalMode, chosenX?: number): ChosenTarget | undefined {
  if (mode.kind === "zone") return agentZoneEffectTargets(session, seatId, card, mode.effect)?.[0];
  if (mode.kind === "removal" && mode.effect.kind !== "modal") return agentRemovalEffectTarget(session, seatId, card, mode.effect, chosenX, true);
  if (mode.kind === "pump") return agentPumpTarget(session, seatId, card, mode.effect);
  if (mode.kind === "trigger" && mode.effect.kind === "targeted_effect") return pickTargetedEffectTarget(session, seatId, card, mode.effect.effect);
  return undefined;
}

// Rule 601.2c: modes and targets are chosen as the spell is cast. An agent's spell used to pick them only as it resolved, so the stack showed
// nothing the human could respond to. Pick them as it is cast instead (the same deterministic choosers resolution used), record them in
// castChoices, and let resolution re-check them (castTargetLegal / applyCast*, rule 608.2b). `card` is the face actually being cast.
// Anything this does not recognise returns undefined and keeps its resolution-time pick.
export function agentCastTimeRemovalChoices(session: GameSession, seatId: string, card: VisibleCard, chosenX?: number): CastChoices | undefined {
  const structure = castStructure(card, chosenX);
  if (!structure) return card.typeLine.includes("Instant") || card.typeLine.includes("Sorcery") ? agentPlannedCastChoices(session, seatId, card) : undefined;
  // An agent's Aura names its creature as it is cast (the same deterministic choice resolution used to make).
  if (structure.kind === "aura") {
    const attach = chooseAuraAttachTarget(session, seatId, card.oracleText);
    return attach.kind === "attach" ? { targets: [{ kind: "card", seatId: attach.seatId, cardId: attach.cardId }] } : undefined;
  }
  // A single-verb targeted spell (tap/untap/counter/copy/gain-keyword effects on a chosen target).
  if (structure.kind === "targeted") {
    const picked = pickTargetedEffectTarget(session, seatId, card, structure.effect);
    return picked ? { targets: [picked] } : undefined;
  }
  if (structure.kind === "removal") {
    const target = agentRemovalEffectTarget(session, seatId, card, structure.effect, chosenX, false);
    return target ? { targets: [target] } : undefined;
  }
  if (structure.kind === "pump") {
    const target = agentPumpTarget(session, seatId, card, structure.effect);
    return target ? { targets: [target] } : undefined;
  }
  if (structure.kind === "zone") {
    const targets = agentZoneEffectTargets(session, seatId, card, structure.effect);
    return targets ? { targets } : undefined;
  }
  if (structure.kind === "extra") {
    const targets = agentExtraEffectTargets(session, seatId, card, structure.effect);
    return targets ? { targets } : undefined;
  }
  return agentModalCastChoices(session, seatId, card, structure, chosenX);
}

// The card as one face of it is cast: a Room door, an Adventure/Omen/split spell half or a modal-DFC's spell face reads as that face's name,
// type line and text (its combined oracle text would otherwise be parsed as a single spell).
function castFaceCard(card: VisibleCard, face: { name: string; typeLine: string; oracleText: string } | undefined): VisibleCard {
  return face ? { ...card, name: face.name, typeLine: face.typeLine, oracleText: face.oracleText } : card;
}

// "Mode 1; Mode 2" for the log and stack panel: the chosen modes of a modal spell, by the card's own mode text.
export function castModeLabels(card: VisibleCard, chosenX: number | undefined, choices: CastChoices | undefined): string[] {
  if (!choices?.modes?.length) return [];
  const structure = castStructure(card, chosenX);
  if (structure?.kind === "removal_modal") return choices.modes.map((index) => (structure.modal.modes[index] ? describeRemovalMode(structure.modal.modes[index]) : `Mode ${index + 1}`));
  if (structure?.kind === "generic_modal") return choices.modes.map((index) => structure.modal.modes[index]?.text ?? `Mode ${index + 1}`);
  return [];
}

// Applies a removal-shaped effect (or modal's chosen modes) using the targets chosen at cast time; modes/targets that became illegal fizzle.
export function applyCastRemoval(session: GameSession, casterSeatId: string, source: VisibleCard, effect: RemovalEffect, chosenX: number | undefined, choices: CastChoices): GameSession {
  const modes = effect.kind === "modal" ? (choices.modes ?? []).map((index) => effect.modes[index]).filter(Boolean) : [effect];
  let next = session;
  let used = 0;
  for (const mode of modes) {
    const needsTarget = removalSlots(session, casterSeatId, source, mode).length > 0;
    const target = needsTarget ? choices.targets[used++] : undefined;
    if (needsTarget && (!target || !castTargetLegal(next, casterSeatId, source, target))) {
      next = rulesEvent(next, casterSeatId, `${source.name}'s target is no longer legal; that part of the spell does nothing.`);
      continue;
    }
    next = applyRemovalEffect(next, casterSeatId, source.name, source, mode, chosenX, target);
  }
  return next;
}

// Same for a non-removal modal spell's chosen modes.
export function applyCastGenericModes(session: GameSession, casterSeatId: string, source: VisibleCard, modal: GenericModalEffect, choices: CastChoices): GameSession {
  // "Choose one that hasn't been chosen this turn": each mode taken is used up for the turn (applyGenericModalEffect does the same).
  let next: GameSession = modal.distinctPerTurn
    ? { ...session, onceEachTurnEffectsUsed: [...(session.onceEachTurnEffectsUsed ?? []), ...(choices.modes ?? []).map((index) => `${session.turn}:${source.id}:mode:${index}`)] }
    : session;
  let used = 0;
  for (const index of choices.modes ?? []) {
    const mode = modal.modes[index];
    if (!mode) continue;
    const needsTarget = genericModeSlots(session, casterSeatId, source, mode).length > 0;
    const target = needsTarget ? choices.targets[used++] : undefined;
    if (needsTarget && (!target || !castTargetLegal(next, casterSeatId, source, target))) {
      next = rulesEvent(next, casterSeatId, `${source.name}'s target is no longer legal; that mode does nothing.`);
      continue;
    }
    if (mode.kind === "zone") next = applyZoneEffect(next, casterSeatId, source.name, mode.effect, undefined, target);
    else if (mode.kind === "pump") next = applyTargetedPumpEffect(next, casterSeatId, source, mode.effect, target);
    else if (mode.kind === "removal") next = applyRemovalEffect(next, casterSeatId, source.name, source, mode.effect, undefined, target);
    else if (mode.kind === "trigger" && mode.effect.kind === "targeted_effect") next = applyTargetedEffect(next, casterSeatId, source, mode.effect.effect, target);
    else next = applyGenericModalEffect(next, casterSeatId, source, { chooseCount: 1, modes: [mode] });
  }
  return next;
}

// The target slots a human-cast spell needs (Ram Through's two creatures, Tamiyo's Safekeeping's permanent, "any target" damage), or
// undefined when the spell has nothing to choose between.
export function spellTargetSlots(session: GameSession, controllerSeatId: string, source: VisibleCard, chosenX?: number): { slots: LabeledSlot[]; continuation: LabeledContinuation } | undefined {
  const text = etbEffectText(source.oracleText);
  const extra = parseSpellExtraEffects(text).find((effect) => effect.kind === "creature_bites" || effect.kind === "grant_keywords" || effect.kind === "shuffle_permanent_reveal_top" || effect.kind === "creature_damages_everything_else" || effect.kind === "opponent_sacrifices_greatest_power" || effect.kind === "you_and_opponent_draw");
  // Chandra's Ignition: "Target creature you control deals damage equal to its power to each other creature and each opponent."
  if (extra?.kind === "creature_damages_everything_else") {
    const own = labeledTargetOptions(session, controllerSeatId, "own_creature", source);
    if (own.length < 2) return undefined;
    return { slots: [{ prompt: `${source.name}: choose the creature you control that deals the damage.`, options: own }], continuation: { kind: "extra", effect: extra } };
  }
  // Consumed by Greed / Secret Rendezvous: "target opponent".
  if (extra?.kind === "opponent_sacrifices_greatest_power" || extra?.kind === "you_and_opponent_draw") {
    const opponents = labeledTargetOptions(session, controllerSeatId, "player", source);
    if (opponents.length < 2) return undefined;
    return { slots: [{ prompt: `${source.name}: choose a target opponent.`, options: opponents }], continuation: { kind: "extra", effect: extra } };
  }
  if (extra?.kind === "creature_bites") {
    const mine = labeledTargetOptions(session, controllerSeatId, "own_creature", source);
    const theirs = labeledTargetOptions(session, controllerSeatId, /creature or planeswalker you don'?t control/i.test(text) ? "opponent_creature_or_planeswalker" : "opponent_creature", source);
    if (mine.length === 0 || theirs.length === 0 || mine.length + theirs.length < 3) return undefined;
    return {
      slots: [
        { prompt: `${source.name}: choose the creature you control that deals the damage.`, options: mine },
        { prompt: `${source.name}: choose the creature that takes it.`, options: theirs }
      ],
      continuation: { kind: "extra", effect: extra }
    };
  }
  if (extra?.kind === "shuffle_permanent_reveal_top") {
    const all = labeledTargetOptions(session, controllerSeatId, "any_permanent", source);
    if (all.length < 2) return undefined;
    return { slots: [{ prompt: `${source.name}: choose the permanent its owner shuffles into their library.`, options: all }], continuation: { kind: "extra", effect: extra } };
  }
  if (extra?.kind === "grant_keywords") {
    const own = labeledTargetOptions(session, controllerSeatId, "own_permanent", source);
    if (own.length < 2) return undefined;
    return {
      slots: [{ prompt: `${source.name}: choose a permanent you control to gain ${extra.keywords.join(" and ")} until end of turn.`, options: own }],
      continuation: { kind: "extra", effect: extra, lifeAmount: parseSimpleLifeChange(text)?.kind === "gain_life" ? parseSimpleLifeChange(text)!.amount : undefined }
    };
  }
  if (parseModalHeader(source.oracleText)) return undefined;
  const removal = parseRemovalEffect(text);
  if (removal?.kind === "damage" && removal.targetType !== "creature") {
    const options = labeledTargetOptions(session, controllerSeatId, removal.targetType === "player" ? "player" : "any_damage", source);
    if (options.length < 2) return undefined;
    return { slots: [{ prompt: `${source.name}: choose a target for the damage.`, options }], continuation: { kind: "damage", effect: removal, chosenX } };
  }
  return undefined;
}

// Runs a labeled target choice's continuation once the human has answered every slot. A pick that stopped being legal fizzles.
export function applyLabeledContinuation(session: GameSession, controllerSeatId: string, source: VisibleCard, continuation: LabeledContinuation, picks: ChosenTarget[]): GameSession {
  const stillThere = (target: ChosenTarget | undefined) =>
    target?.kind === "player" ? session.seats.some((seat) => seat.id === target.seatId && !seat.hasLost) : target?.kind === "card" ? Boolean(resolvePreChosenBattlefieldTarget(session, target)) : false;
  if (!picks.every(stillThere)) return noLegalTargetEvent(session, controllerSeatId, source.name);
  if (continuation.kind === "damage") return applyRemovalEffect(session, controllerSeatId, source.name, source, continuation.effect, continuation.chosenX, picks[0]);
  let next = applySpellExtraEffect(session, controllerSeatId, source, continuation.effect, undefined, picks);
  if (continuation.lifeAmount) {
    next = rulesEvent({ ...next, seats: next.seats.map((seat) => (seat.id === controllerSeatId ? { ...seat, life: seat.life + continuation.lifeAmount! } : seat)) }, controllerSeatId, `${source.name}: ${next.seats.find((seat) => seat.id === controllerSeatId)?.name ?? "Player"} gains ${continuation.lifeAmount} life.`);
  }
  return next;
}

// Steel Hellkite: the X values worth offering (each distinct mana value among the nonland permanents of players it damaged this turn that the seat can pay for).
export function steelHellkiteXOptions(session: GameSession, seat: PlayerSeat, card: VisibleCard): Array<{ x: number; theirs: number; mine: number; best?: boolean }> {
  const damaged = card.damagedPlayersThisTurn ?? [];
  if (damaged.length === 0 || session.onceEachTurnEffectsUsed?.includes(`${session.turn}:${card.id}:steel_hellkite_x`)) return [];
  const victims = session.seats.filter((other) => damaged.includes(other.id)).flatMap((other) => other.board.battlefield.filter((permanent) => !isLandCard(permanent) && !hasIndestructible(permanent)).map((permanent) => ({ ownerId: other.id, permanent })));
  const values = Array.from(new Set(victims.map((entry) => entry.permanent.manaValue))).sort((a, b) => a - b);
  const worth = (permanent: VisibleCard) => Math.max(1, permanent.manaValue) + Math.max(0, effectivePower(permanent)) / 2;
  const options = values
    .filter((x) => chooseManaSourcesForCost(seat, genericCostShim(x), x, undefined, session.seats).ok)
    .map((x) => {
      const hit = victims.filter((entry) => entry.permanent.manaValue === x);
      const theirs = hit.filter((entry) => entry.ownerId !== seat.id);
      const mine = hit.filter((entry) => entry.ownerId === seat.id);
      return { x, theirs: theirs.length, mine: mine.length, net: theirs.reduce((sum, entry) => sum + worth(entry.permanent), 0) - mine.reduce((sum, entry) => sum + worth(entry.permanent), 0) };
    });
  const top = [...options].sort((a, b) => b.net - a.net)[0];
  return options.map(({ x, theirs, mine, net }) => ({ x, theirs, mine, ...(top && top.net > 0 && net === top.net && x === top.x ? { best: true } : {}) }));
}

// Human-readable label for one mode button in the choose_modal_option modal — generated from the
// already-parsed structured effect rather than threading the card's original bullet text through
// ModalEffect (which only stores the parsed shape, not the source string), so it stays correct even
// though it can't reproduce the card's exact original wording verbatim.
function describeRemovalTargetType(targetType: RemovalTargetType): string {
  return targetType.replace(/_/g, " ");
}

function describeRemovalMode(mode: Exclude<RemovalEffect, { kind: "modal" }>): string {
  switch (mode.kind) {
    case "destroy":
      return `Destroy target ${describeRemovalTargetType(mode.targetType)}.`;
    case "destroy_up_to_x":
      return `Destroy up to X target ${describeRemovalTargetType(mode.targetType)}.`;
    case "destroy_all":
      return `Destroy all ${mode.excludeType ? `non-${mode.excludeType} ` : ""}${mode.targetType}s.`;
    case "destroy_all_conditional":
      return `Destroy all creatures with mana value ${mode.threshold} or ${mode.comparison === "or_less" ? "less" : "greater"}.`;
    case "exile":
      return `Exile target ${describeRemovalTargetType(mode.targetType)}.`;
    case "bounce":
      return `Return target ${describeRemovalTargetType(mode.targetType)} to its owner's hand.`;
    case "damage":
      return `Deal ${mode.amount} damage to ${mode.targetType === "any" ? "any target" : mode.targetType === "player" ? "target player" : "target creature"}.`;
    case "mass_damage":
      return `Deal ${mode.amount} damage to each ${mode.excludeType ? `non-${mode.excludeType} ` : ""}creature${mode.scope === "opponents" ? " you don't control" : ""}.`;
    case "proliferate":
      return "Proliferate.";
    case "grant_keywords":
      return `Target creature gains ${mode.keywords.join(" and ")} until end of turn.`;
  }
}

// Top-level dispatcher for the generic destroy/exile/damage primitives parsed by
// src/lib/removalSpells.ts. Deliberately narrow, matching that module's scope: multi-target-divided
// damage and non-destroy/exile/damage follow-up effects (Chaos Warp's shuffle-and-reveal, Swords to
// Plowshares' life gain, Beast Within's token) aren't modeled here — parseRemovalEffect already
// declines to match those shapes, so this only ever runs for the plain "destroy/exile/damage a
// target" pattern (or a "choose N" spell built from those patterns) it recognizes.
// Rule 601.2c: a spell that requires a target can't legally be cast at all if no legal target
// exists for it. Without this, legalMainPhaseActions/legalPriorityActions would offer "cast" for a
// removal spell with nothing to destroy/exile/bounce/damage on the board, the agent (or a human)
// would go ahead and cast it, and it would resolve into noLegalTargetEvent's silent whiff at
// resolution time — mirrors the exact same removalEffectHasLegalTarget check applyRemovalEffect
// itself uses below, just run one step earlier, before mana and the card are spent on something
// that can never do anything.
export function hasResolvableRemovalTarget(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  const effect = parseRemovalEffect(etbEffectText(card.oracleText));
  if (!effect) return true;
  return removalEffectHasLegalTarget(session, casterSeatId, card, effect);
}

// Same "no legal target = illegal to cast" check as hasResolvableRemovalTarget, for the
// reanimate/regrow/gain_control zone effects that also need one — mill, graveyard_to_library,
// impulse_draw, and steal_and_play are always "legal" to cast even when they'd do little (milling
// an empty library, exiling from an empty-ish deck), so only the genuinely target-dependent kinds
// are checked here.
function hasResolvableZoneEffectTarget(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  const effect = parseEtbZoneEffect(etbEffectText(card.oracleText));
  if (!effect) return true;
  return zoneEffectHasLegalTarget(session, casterSeatId, effect);
}

// Aura-based reanimation (Animate Dead, Necromancy, ...) is explicitly out of scope for
// parseZoneEffect (see zoneEffects.ts's file comment) — its ETB trigger text ("Return enchanted
// creature card to the battlefield...") doesn't match that parser's "target creature card"
// phrasing, since an Aura targets via its own "Enchant X" line rather than the spell itself. But an
// Aura's legality to cast still hinges on that Enchant line finding a legal object (rule 303.4c) —
// independent of whatever its ETB trigger does — so this checks that directly rather than needing
// the ETB effect itself to be understood.
function hasResolvableAuraEnchantTarget(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  if (!card.typeLine.includes("Aura")) return true;
  const enchantLine = oracleClauses(card.oracleText).find((clause) => /^enchant\b/i.test(clause));
  if (!enchantLine) return true;
  const graveyardEnchant = enchantLine.match(/^enchant creature card in (a|your) graveyard\b/i);
  if (!graveyardEnchant) return true;
  return chooseReanimationTarget(session, casterSeatId, graveyardEnchant[1].toLowerCase() === "a") !== undefined;
}

// Printed text of instants/sorceries the engine has NO deterministic resolution for (checked against every shipped deck). Kept in step with the
// "Human/agent parity gaps" section of docs/agents/system.md and guarded by AppFlow.humanAgentParity.test.ts.
export const AGENT_UNSUPPORTED_SPELL_TEXT: RegExp[] = [
  // Promise of Loyalty: needs a per-creature "can't attack you" restriction that lasts while the vow counter stays.
  /each player puts a vow counter on a creature they control and sacrifices the rest/i,
  // Agadeem's Awakening: any number of targets with pairwise-different mana values.
  /return from your graveyard to the battlefield any number of target creature cards that each have a different mana value/i
];

export function hasResolvableTarget(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  // "As an additional cost to cast this spell, sacrifice X creatures." (Immoral Bargain) has no X-choosing cost step here: refuse the cast rather than
  // let it be paid for and then do nothing.
  if (/as an additional cost to cast this spell, sacrifice x creatures/i.test(card.oracleText)) return false;
  // Human/agent parity (docs/agents/system.md, "Human/agent parity gaps"): spells whose resolution no deterministic handler owns. A human resolves them by
  // hand; an agent would pay for them and get nothing, so agents refuse to cast them.
  if (session.seats.find((seat) => seat.id === casterSeatId)?.kind !== "human" && AGENT_UNSUPPORTED_SPELL_TEXT.some((pattern) => pattern.test(card.oracleText))) return false;
  return (
    hasResolvableRemovalTarget(session, casterSeatId, card) &&
    hasResolvableZoneEffectTarget(session, casterSeatId, card) &&
    hasResolvableAuraEnchantTarget(session, casterSeatId, card) &&
    hasResolvableGenericCreatureTarget(session, casterSeatId, card) &&
    hasResolvableSpellExtraTarget(session, casterSeatId, card) &&
    hasPayableAdditionalSacrificeCost(session, casterSeatId, card) &&
    hasPayableAdditionalDiscardCost(session, casterSeatId, card)
  );
}

export interface MoveCheckContext {
  /** "agent": the action must also be a currently-offered option (`fresh`) and its mana must be payable. "human": rules checks only; payment is interactive. */
  mode: "agent" | "human";
  /** Has this seat already used its land drop(s) this turn? */
  hasPlayedLand: boolean;
  activeSeatId: string | undefined;
  /** True when nothing is on the stack (sorcery-speed plays need this; instant-speed responses need the opposite). */
  stackEmpty: boolean;
  /** Agent mode: the legal options regenerated from the LIVE state. The action must be one of them (catches stale ids, double-casts, a second land drop, ...). */
  fresh?: LegalAgentAction[];
}

// The central rules gate (see src/lib/moveLegality.ts): is this proposed move legal RIGHT NOW, and if not, why. Pure; never mutates the session. Humans and
// agents share it. It only refuses what the Magic rules forbid or what the engine cannot perform; a legal-but-pointless play (a wrath with no creatures, a
// draw spell with an empty library) is allowed here and left to the play guards (playGuards.ts).
export function checkMoveLegal(session: GameSession, seatId: string, action: LegalAgentAction, ctx: MoveCheckContext): LegalityResult {
  if (action.actionType === "pass_priority" || action.actionType === "end_turn" || action.actionType === "keep_hand" || action.actionType === "mulligan") return legalResult();
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat || seat.hasLost) return illegalResult("that player is not in the game");
  const ownMainWithEmptyStack = ctx.activeSeatId === seatId && isMainPhase(session.phase) && ctx.stackEmpty;
  const isResponse = action.id.startsWith("respond");
  const zone: "hand" | "command" | "exile" | "graveyard" | "library" =
    action.actionType === "cast_commander" ? "command" : action.sourceZone === "exile" ? "exile" : action.sourceZone === "graveyard" ? "graveyard" : action.sourceZone === "library" ? "library" : "hand";

  if (action.actionType === "play_land" || action.actionType === "cast_spell" || action.actionType === "cast_commander") {
    const card =
      zone === "command"
        ? seat.board.commander
        : zone === "exile"
          ? findExiledCardAnySeat(session, action.cardId ?? "")
          : zone === "graveyard"
            ? seat.board.graveyard?.find((item) => item.id === action.cardId)
            : zone === "library"
              ? (seat.library ?? [])[0]?.id === action.cardId ? (seat.library ?? [])[0] : undefined
              : seat.board.hand.find((item) => item.id === action.cardId);
    if (!card || (zone === "command" && card.id !== action.cardId)) {
      return illegalResult(`the card is not in ${zone === "hand" ? "the hand" : `the ${zone}`} any more`, "stale");
    }
    if (zone === "exile" && (card.exiledPlayableBySeatId !== seatId || (card.exiledPlayableUntilTurn !== undefined && session.turn > card.exiledPlayableUntilTurn))) {
      return illegalResult("there is no longer permission to play it from exile");
    }
    if (zone === "graveyard" && !graveyardCastPermission(card, { seatId, turn: session.turn, controllerBattlefield: seat.board.battlefield })) {
      return illegalResult("it has no flashback or other permission to be cast from the graveyard");
    }
    if (zone === "library" && !libraryTopCastPermission(card, seat.board.battlefield)) {
      return illegalResult("nothing lets it be cast from the top of the library");
    }
    const split = modalDoubleFacedLandSplit(card);
    const playingAsLand = action.actionType === "play_land" || (split !== undefined && action.faceIndex === split.landIndex);
    if (playingAsLand) {
      if (!ownMainWithEmptyStack) return illegalResult("a land can only be played in the player's own main phase with an empty stack", "illegal");
      if (ctx.hasPlayedLand) return illegalResult("the land drop for this turn is already used");
      return ctx.mode === "agent" && ctx.fresh ? membershipVerdict(action, ctx.fresh) : legalResult();
    }
    // The chosen half decides everything about the cast: its own type (timing), text (targets) and name — never the combined card's.
    const face = action.faceIndex !== undefined ? (split && action.faceIndex === split.spellIndex ? split.spellFace : independentlyCastableSpellFaces(card)?.[action.faceIndex]) : undefined;
    if (face && zone === "hand" && !spellFaceCastableFromHand(face)) return illegalResult(`${face.name} is an aftermath half and can only be cast from the graveyard`);
    const targetCard = face ? { ...card, name: face.name, typeLine: face.typeLine, oracleText: face.oracleText } : card;
    const instantSpeed = canCastAtInstantSpeed(targetCard, seatHasFlashGrant(seat, targetCard)) || (zone === "exile" && Boolean(card.exiledPlayableAnyTime));
    if (isResponse) {
      if (ctx.stackEmpty) return illegalResult("there is nothing on the stack to respond to");
      if (!instantSpeed) return illegalResult(`${targetCard.name} is not an instant and has no flash`);
    } else if (!ownMainWithEmptyStack && !instantSpeed) {
      return illegalResult(`${targetCard.name} can only be cast in the player's own main phase with an empty stack`);
    }
    // Rule 601.2c: "counter target spell" needs a spell on the stack to target when it is cast — with an empty stack there is no legal target.
    if (ctx.stackEmpty && isTargetedCounterspell(targetCard)) return illegalResult(`${targetCard.name} needs a spell on the stack to counter, and the stack is empty`);
    if (spellCastLockedOut(session, seatId, ctx.activeSeatId)) return illegalResult("an effect stops this player from casting spells right now");
    if (castRestrictedByTurnCount(session, card)) return illegalResult(`${card.name} cannot be cast during the first three turns of the game`);
    if (!hasResolvableTarget(session, seatId, targetCard)) {
      const unsupported = seat.kind !== "human" && AGENT_UNSUPPORTED_SPELL_TEXT.some((pattern) => pattern.test(targetCard.oracleText));
      const sacrificeCost = parseAdditionalSacrificeCost(targetCard.oracleText);
      if (sacrificeCost && additionalSacrificeCandidates(seat, sacrificeCost, card.id).length < sacrificeCost.count) {
        return illegalResult(`${card.name} has an additional cost that cannot be paid (no ${sacrificeCost.permanentType} to sacrifice)`);
      }
      return illegalResult(
        unsupported
          ? `${card.name} has an effect the engine cannot carry out for an automated player`
          : `${card.name} has no legal target or an additional cost that cannot be paid (nothing to sacrifice or discard)`
      );
    }
    return ctx.mode === "agent" && ctx.fresh ? membershipVerdict(action, ctx.fresh, "its mana cost cannot be paid or an extra condition is not met") : legalResult();
  }

  if (action.actionType === "activate_ability") {
    const onBattlefield = seat.board.battlefield.find((item) => item.id === action.cardId);
    const inHand = seat.board.hand.find((item) => item.id === action.cardId);
    if (!onBattlefield && !(action.abilityKind === "cycling" && inHand)) return illegalResult("the source is no longer where the ability can be activated", "stale");
    const sorcerySpeed = action.abilityKind === "loyalty_ability" || action.abilityKind === "equip" || action.abilityKind === "unlock_room_door";
    if (sorcerySpeed && !ownMainWithEmptyStack) return illegalResult("this ability can only be activated in the player's own main phase with an empty stack");
    return ctx.mode === "agent" && ctx.fresh
      ? membershipVerdict(action, ctx.fresh, "a cost cannot be paid (tapped, summoning sick, nothing to sacrifice or discard, not enough mana or life) or its condition is not met")
      : legalResult();
  }

  if (action.actionType === "attack") {
    const attacker = seat.board.battlefield.find((item) => item.id === action.cardId);
    if (!attacker) return illegalResult("the attacker is no longer on the battlefield", "stale");
    if (attacker.tapped) return illegalResult(`${attacker.name} is tapped`);
    if (!canAttack(attacker, seat.board.battlefield)) return illegalResult(`${attacker.name} cannot attack (summoning sick or restricted)`);
    return ctx.mode === "agent" && ctx.fresh ? membershipVerdict(action, ctx.fresh) : legalResult();
  }

  if (action.actionType === "block") {
    return ctx.mode === "agent" && ctx.fresh ? membershipVerdict(action, ctx.fresh, "that creature cannot legally block this attacker") : legalResult();
  }
  return legalResult();
}

function membershipVerdict(action: LegalAgentAction, fresh: LegalAgentAction[], reason = "it is not currently a legal option"): LegalityResult {
  const verdict = validateProposal(action.id, fresh);
  return verdict.legal ? legalResult() : illegalResult(reason, verdict.code);
}

// "Target creature you control deals damage ..." (Bite Down, Chandra's Ignition) and the other
// spellExtras shapes that need something on the board — casting them with nothing to point at just
// wastes the card (Bite Down fizzled six times in a 40-game self-play batch because the agent cast it
// with no creature of its own).
function hasResolvableSpellExtraTarget(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  const caster = session.seats.find((seat) => seat.id === casterSeatId);
  const effects = parseSpellExtraEffects(etbEffectText(card.oracleText));
  const hasOwnAttacker = greatestCreaturePower(caster) > 0;
  const opposingCreature = session.seats.some((seat) => seat.id !== casterSeatId && !seat.hasLost && seat.board.battlefield.some((item) => item.typeLine.includes("Creature")));
  return effects.every((effect) => {
    switch (effect.kind) {
      case "creature_bites": {
        const dealer = strongestControlledCreature(caster);
        return Boolean(dealer) && hasOwnAttacker && chooseDamageTarget(session, casterSeatId, Math.max(0, effectivePower(dealer!)), "creature", dealer!) !== undefined;
      }
      case "creature_damages_everything_else":
        return hasOwnAttacker;
      case "divided_damage_greatest_power":
        return hasOwnAttacker && opposingCreature;
      case "shuffle_permanent_reveal_top":
        return chooseRemovalTarget(session, casterSeatId, "permanent", card) !== undefined;
      case "each_other_player_sacrifices":
      case "opponent_sacrifices_greatest_power":
        return opposingCreature;
      // "Return up to two creature cards from your graveyard to your hand" (Find, Regrowth-style): legal with no target, but an agent would just throw the card
      // away. A human may still cast it (the rules allow zero targets for "up to").
      case "return_creatures_from_graveyard":
        return caster?.kind === "human" || (caster?.board.graveyard ?? []).some((item) => item.typeLine.includes("Creature"));
      default:
        return true;
    }
  });
}

// "As an additional cost to cast this spell, discard a card." — uncastable when the hand holds nothing
// else to discard (the spell itself doesn't count, it's leaving the hand to be cast).
function hasPayableAdditionalDiscardCost(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  const cost = parseAdditionalDiscardCost(card.oracleText);
  if (!cost) return true;
  const seat = session.seats.find((item) => item.id === casterSeatId);
  return Boolean(seat && seat.board.hand.filter((item) => item.id !== card.id).length >= cost.count);
}

// Pays the discard half of a spell's additional cost (Unexpected Windfall) at cast time, by the same
// heuristic every other automatic discard here uses. The spell itself is never the discard.
export function payAdditionalDiscardCost(session: GameSession, seatId: string, spell: VisibleCard): GameSession {
  const cost = parseAdditionalDiscardCost(spell.oracleText);
  const seat = session.seats.find((item) => item.id === seatId);
  if (!cost || !seat) return session;
  let next = session;
  for (let paid = 0; paid < cost.count; paid += 1) {
    const current = next.seats.find((item) => item.id === seatId);
    if (!current) break;
    const chosenDiscard = spell.chosenAdditionalDiscardIds?.[paid] ? current.board.hand.find((card) => card.id === spell.chosenAdditionalDiscardIds![paid] && card.id !== spell.id) : undefined;
    const discard = chosenDiscard ?? chooseWorstHandCardToDiscard({ ...current, board: { ...current.board, hand: current.board.hand.filter((card) => card.id !== spell.id) } });
    if (!discard) break;
    next = moveCardBetweenVisibleZones(next, seatId, discard.id, "graveyard");
    next = rulesEvent(next, seatId, `${seat.name} discards ${discard.name} as an additional cost to cast ${spell.name}.`);
  }
  return next;
}

// A mandatory additional cost (Village Rites' "sacrifice a creature", ...) makes a spell uncastable
// outright when it can't be paid (rule 601.2h/601.2b) — without this, every call site that reuses
// hasResolvableTarget as its "can this be cast right now" gate would offer/allow casting the spell
// with no creature anywhere on the battlefield to actually pay the cost with.
function hasPayableAdditionalSacrificeCost(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  const cost = parseAdditionalSacrificeCost(card.oracleText);
  if (!cost) return true;
  const seat = session.seats.find((item) => item.id === casterSeatId);
  return Boolean(seat && additionalSacrificeCandidates(seat, cost, card.id).length >= cost.count);
}

// Pays an additional sacrifice cost at cast time, routed through destroyCreatures so the sacrifice is scanned for death triggers like every other death path.
// The spell is already paying (or has paid) its mana, so this stays paid even if the spell is later countered: nothing here is undone on a counter.
export function sacrificeForAdditionalCost(session: GameSession, seatId: string, targets: VisibleCard[], spellName: string): GameSession {
  const seatName = session.seats.find((item) => item.id === seatId)?.name ?? "Player";
  return destroyCreatures(
    session,
    targets.map((target) => ({ seatId, cardId: target.id, message: `${seatName} sacrifices ${target.name} as an additional cost to cast ${spellName}.` })),
    "Rules action"
  );
}

function matchesAdditionalSacrificeType(card: VisibleCard, type: AdditionalSacrificeType): boolean {
  switch (type) {
    case "creature":
      return card.typeLine.includes("Creature");
    case "land":
      return card.typeLine.includes("Land");
    case "artifact":
      return card.typeLine.includes("Artifact");
    case "enchantment":
      return card.typeLine.includes("Enchantment");
    case "nonland permanent":
      return !card.typeLine.includes("Land");
    default:
      return true;
  }
}

// The permanents the caster may legally sacrifice to pay "As an additional cost to cast this spell, sacrifice a <type>" (rule 601.2b/601.2h): every
// matching permanent they control, tapped or not (a land already tapped for mana is a fine sacrifice, which is the usual Harrow trick). The spell itself is
// still in the hand while it is being cast, so it never appears here; `spellCardId` is only a guard for a spell cast from the battlefield-adjacent zones.
export function additionalSacrificeCandidates(seat: PlayerSeat, cost: { permanentType: AdditionalSacrificeType }, spellCardId?: string): VisibleCard[] {
  return seat.board.battlefield.filter((card) => card.id !== spellCardId && matchesAdditionalSacrificeType(card, cost.permanentType));
}

// The deterministic pick an agent (or a human who has only one legal choice) pays an additional sacrifice cost with: the least valuable legal permanent.
// Creatures use the shared sacrifice-fodder order (tokens, then lowest power+toughness). A land prefers one that is already tapped (this cast's own mana
// sources count as tapped, since they are spent before the sacrifice), then a basic over a utility land, then the one whose colours the rest of the
// manabase still covers, and never the sole source of a colour of the commander's identity unless nothing else is left. Anything else: tokens, then lowest
// mana value, the commander last. `paidWithSourceIds` are the permanents tapped to pay this very spell.
export function chooseAdditionalCostSacrifice(seat: PlayerSeat, cost: { count: number; permanentType: AdditionalSacrificeType }, paidWithSourceIds: string[] = [], spellCardId?: string): VisibleCard[] | undefined {
  const candidates = additionalSacrificeCandidates(seat, cost, spellCardId);
  if (candidates.length < cost.count) return undefined;
  if (cost.permanentType === "creature") return chooseSacrificeTargets(seat, undefined, cost.count, spellCardId);
  const identity = normalizeManaColors(seat.deck?.colors ?? seat.board.commander?.colorIdentity ?? []);
  const lands = seat.board.battlefield.filter((card) => card.typeLine.includes("Land"));
  const score = (card: VisibleCard): number => {
    if (card.commander) return 5000;
    let total = 0;
    if (card.typeLine.includes("Land")) {
      const colors = producibleColorsForLand(card);
      const others = lands.filter((land) => land.id !== card.id);
      const soleSource = colors.some((color) => (identity.length === 0 || identity.includes(color)) && color !== "C" && !others.some((land) => producibleColorsForLand(land).includes(color)));
      if (soleSource) total += 1000;
      if (!card.typeLine.includes("Basic")) total += 40;
      if (!card.tapped && !paidWithSourceIds.includes(card.id)) total += 25;
      // A land whose colours are produced by many other lands is the cheapest to lose.
      total -= Math.min(10, colors.reduce((sum, color) => sum + others.filter((land) => producibleColorsForLand(land).includes(color)).length, 0));
    } else {
      total += card.token ? 0 : 100 + card.manaValue * 10;
    }
    return total;
  };
  return [...candidates].sort((a, b) => score(a) - score(b)).slice(0, cost.count);
}

// Fallback for "target creature" spells that aren't a destroy/exile/damage effect (removalSpells.ts)
// or a graveyard-return effect (zoneEffects.ts) — pump spells, protection, Malakir Rebirth-style
// death-ward grants, and the like. Without this, a spell whose entire effect hinges on "target
// creature" with zero creatures anywhere in play (a real turn-1 scenario) still got offered as
// castable, since none of the other three checks recognize this shape and all default to "legal."
// Deliberately narrow: only the plain "target creature[, you control|an opponent controls]" phrasing
// is understood; anything else (planeswalkers, "target creature or player", multiple targets) is left
// alone rather than risk declining a spell that actually does have a legal target.
function hasResolvableGenericCreatureTarget(session: GameSession, casterSeatId: string, card: VisibleCard): boolean {
  if (parseRemovalEffect(etbEffectText(card.oracleText))) return true;
  if (parseEtbZoneEffect(etbEffectText(card.oracleText))) return true;
  if (card.typeLine.includes("Aura")) return true;
  // A modal spell might have a non-targeting mode that's still perfectly castable even when its
  // creature-targeting mode isn't — this checker has no mode-selection logic of its own (unlike
  // removalEffectHasLegalTarget's per-mode filtering), so declining here would risk hiding a
  // genuinely legal cast rather than just failing to catch an illegal one.
  if (parseModalHeader(card.oracleText)) return true;
  const clause = oracleClauses(card.oracleText).find(
    (item) => /\btarget creature\b/i.test(item) && !/\btarget creature (?:card|or )/i.test(item)
  );
  if (!clause) return true;
  const wantsOwn = /\btarget creature you control\b/i.test(clause);
  const wantsOpp = /\btarget creature (?:an opponent controls|you don't control)\b/i.test(clause);
  return session.seats.some((seat) => {
    if (wantsOwn && seat.id !== casterSeatId) return false;
    if (wantsOpp && seat.id === casterSeatId) return false;
    return seat.board.battlefield.some((permanent) => permanent.typeLine.includes("Creature"));
  });
}

// Same as parseZoneEffect, except "surveil N" is left out: a surveil is the rules advisor's look-at-top workflow (human prompt, agent
// agentSurveilDecision), never a silent auto-resolution in the ETB/land/spell resolution paths that used to claim it as a "zone effect".
export function parseEtbZoneEffect(text: string): ZoneEffect | undefined {
  const effect = parseZoneEffect(text);
  return effect?.kind === "surveil" ? undefined : effect;
}

// "Put a number of +1/+1 counters equal to that spell's mana value on up to one target creature."
// (Dusty Parlor) — the same "a dynamic amount spelled out in prose instead of abbreviated to X"
// shape substituteX already resolves, just for a specific manaValue-sized counter count rather than
// a general X. Only ever called with the just-cast spell's own manaValue (findCastTriggers is the
// only context that knows what was cast), so "that spell's"/"its own"/"its" all resolve to the same
// number here.
function substituteManaValueCount(text: string, manaValue: number): string {
  return text.replace(
    /\ba number of ([a-z0-9+/-]+ )?counters?\s+equal to (?:that spell'?s|its own|its) mana value\b/gi,
    (_, kind) => `${manaValue} ${kind ?? ""}counters`
  );
}

// "You gain N life."/"You lose N life." as an EXTRA clause on a spell whose main effect is
// something else entirely (Locthwain Scorn's "Target creature gets -3/-3 until end of turn. You
// gain 2 life." — a very common real-card template pairing removal/pump with a flat life change) —
// a plain substring search rather than an anchored match, since it only ever runs alongside
// removalEffect/pumpEffect/massPumpEffect above (each of which already owns matching its own single
// sentence) and just needs to notice this second, independent sentence anywhere in the same text.
export function parseSimpleLifeChange(text: string): { kind: "gain_life" | "lose_life"; amount: number } | undefined {
  const lower = text.toLowerCase();
  // "You gain 4 life for each creature you control with power 4 or greater." scales; the flat amount here would be wrong.
  if (/\byou gain\s+(?:\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s+life\s+for each\b/.test(lower)) return undefined;
  const gainMatch = lower.match(/\byou gain\s+(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s+life\b/);
  if (gainMatch) {
    const amount = numberWordToInt(gainMatch[1]);
    if (amount) return { kind: "gain_life", amount };
  }
  // "You draw two cards AND LOSE 2 life." (Night's Whisper, Ambition's Cost) — the lose half has no second
  // "you", which the plain "you lose N life" match never accepted, so the draw happened and the life
  // payment never did.
  const loseMatch = lower.match(/\b(?:you lose|and lose)\s+(\d+|one|two|three|four|five|six|seven|eight|nine|ten)\s+life\b/);
  if (loseMatch) {
    const amount = numberWordToInt(loseMatch[1]);
    if (amount) return { kind: "lose_life", amount };
  }
  return undefined;
}

// "Draw two cards." (Village Rites, and the same plain-draw shape on plenty of other instants/
// sorceries) — Village Rites' own sacrifice is an additional COST (paid at cast time, not part of
// this resolution effect at all), so this only ever needs to model the draw itself. Deliberately
// scoped to non-battlefield destinations only (see its call site) — a permanent's own ETB "draw a
// card" trigger is already fully owned by commonTriggerEffect's draw_cards case and the queued-
// trigger system (findCommonTriggersForPermanentEntered); applying this here too for a permanent
// would double the draw.
export function parseSimpleDrawEffect(text: string): { amount: number } | undefined {
  const lowered = text.toLowerCase();
  // Symmetric draws are owned by spellExtras (Secret Rendezvous, Cut a Deal) — a plain "draw three cards" here gave only
  // the caster the cards.
  if (/\bdraw a card for each\b/.test(lowered)) return undefined;
  // "Draw three cards. Then discard two cards unless you discard an artifact card." (Thirst for Knowledge) and "Draw X cards, then discard a card." (Pull from Tomorrow):
  // the discard half is owned by spellExtras; the bare draw here handed out the cards and never asked for the discard.
  if (/\bdraw (?:a|one|two|three|four|five|\d+|x) cards?(?:,|\.) (?:then )?discard\b/.test(lowered)) return undefined;
  if (/\byou and target opponent each draw\b|\beach opponent draws a card, then you draw/.test(lowered)) return undefined;
  // "Scry 2, then draw two cards." (Read the Bones): the scry workflow performs the draw after the scry.
  if (/^\s*scry \w+,? then draw\b/.test(lowered)) return undefined;
  // "If it's a Zombie card, draw a card." (Cemetery Recruitment) — a CONDITIONAL draw owned by the regrow
  // effect it follows; an unconditional draw here was giving the card for free.
  if (/\bif (?:it'?s|that card is|you do)\b[^.]*,\s*(?:you )?draw\b/.test(lowered)) return undefined;
  // "Draw three cards, then put two cards from your hand on top of your library in any order."
  // (Brainstorm, ...) — the bare draw regex below happily matches the "draw three cards" prefix on
  // its own, which set ownEtbAlreadyHandled and skipped the rules advisor entirely (see this
  // function's call site), silently dropping the "then put back" half. Same ordering fix already
  // applied to commonTriggerEffect's and the deterministic rules-advisor workflow's own
  // drawThenPutBack checks; declining here lets the advisor's draw_then_put_back workflow handle it
  // instead.
  if (
    /\bdraw\s+(a|one|two|three|four|five|\d+)\s+cards?,?\s*then put\s+(a|one|two|three|four|five|\d+)\s+cards?\s+from your hand on top of your library\b/.test(
      lowered
    )
  ) {
    return undefined;
  }
  // "Look at the top three cards of your library, then put them back in any order. You may
  // shuffle. Draw a card." (Ponder, and the same look/reorder-then-draw template on other cards) —
  // same ordering bug as the Brainstorm guard just above: the bare draw regex below happily
  // matches the trailing "Draw a card." on its own, which set ownEtbAlreadyHandled and skipped the
  // rules advisor entirely, silently dropping the whole look/reorder step. Declining here lets the
  // advisor's own reorder_top_cards workflow (rulesAdvisor.ts) handle it instead — see that
  // workflow's matching "put them back in any order" phrasing. Reported live as "Ponder just draws
  // a card, it skipped the whole look at the top 3... put them back" step.
  if (/\bput (?:them|those cards) back in any order\b/.test(lowered)) {
    return undefined;
  }
  const match = lowered.match(/\bdraw\s+(a|one|two|three|four|five|six|seven|eight|nine|ten|\d+)\s+cards?\b/);
  if (!match) return undefined;
  const amount = numberWordToInt(match[1]);
  return amount ? { amount } : undefined;
}

// Board-wide sibling of parseTargetedPump's single-target shape: "Each [non-Type] creature[s] [you
// control/an opponent controls] gets ±N/±N until end of turn." (Exude Toxin's -X/-X board wipe
// mode once substituteX has resolved X, "Each creature you control gets +1/+1 until end of turn"
// anthem-style tricks, ...) — previously entirely unmodeled, so a spell shaped like this (no single
// "target creature" to find) silently did nothing.
export function parseMassPump(text: string): MassPumpEffect | undefined {
  const match = text.match(/\beach (?:non-([a-z]+) )?creatures?(?: (you control)| (an? opponent controls))? gets? ([+-]\d+)\/([+-]\d+) until end of turn\b/i);
  if (!match) return undefined;
  return {
    power: Number.parseInt(match[4], 10),
    toughness: Number.parseInt(match[5], 10),
    excludeType: match[1]?.toLowerCase(),
    scope: match[2] ? "controlled" : match[3] ? "opponents" : "all"
  };
}

// "Return all creatures to their owners' hands." (Evacuation, and the same unqualified mass-bounce
// wording on a few other cards) — previously entirely unmodeled: no TriggerEffect/ZoneEffect kind
// covers "every creature on the battlefield goes to hand," so a spell shaped like this silently did
// nothing at all. Reported live as "Evacuation did not return all creatures to their owners hands."
// Deliberately narrow to this exact unqualified wording — a card that bounces only SOME creatures
// (Whelming Wave's power-4-or-greater restriction, Cyclonic Rift's "don't control," ...) needs its
// own scoped parser and isn't this shape.
// "Return all nonland permanents to their owners' hands." (Devastation Tide) — the same unmodeled
// mass-bounce shape as Evacuation above, just a wider target pool (every permanent, not only
// creatures). Reported live as Devastation Tide doing nothing at all: the old regex only matched
// the literal word "creatures", so this text never matched, and even if it had,
// applyMassBounceEffect's own battlefield filter was hardcoded to creatures only.
export function parseMassBounceEffect(text: string): "creatures" | "nonland_permanents" | undefined {
  if (/\breturn all creatures to their owners'? hands?\b/i.test(text)) return "creatures";
  if (/\breturn all nonland permanents to their owners'? hands?\b/i.test(text)) return "nonland_permanents";
  return undefined;
}

// Safe fallback for a target-type string that either wasn't supplied or fell outside
// RemovalTargetType's own vocabulary (e.g. the LLM-facing schema's bare "planeswalker", which
// RemovalTargetType only ever expresses combined with creature/artifact — see removalSpells.ts) —
// "creature" is the single most common real target of a removal-shaped effect, so it's the least
// surprising default rather than refusing the whole step outright.
function toRemovalTargetType(targetType?: string): RemovalTargetType {
  switch (targetType) {
    case "creature":
    case "artifact":
    case "enchantment":
    case "permanent":
    case "land":
    case "nonland_permanent":
      return targetType;
    case "planeswalker":
      return "creature_or_planeswalker";
    default:
      return "creature";
  }
}

function toRegrowTargetType(targetType?: string): RegrowTargetType {
  switch (targetType) {
    case "card":
    case "permanent":
    case "creature":
    case "land":
    case "enchantment":
    case "artifact":
      return targetType;
    default:
      return "creature";
  }
}

// Translates one flat, LLM-facing PrimitiveActionStep (src/lib/primitiveActionPlan.ts) into this
// file's own richer, nested PrimitiveAction — the one place that gap is bridged, so every other
// consumer of PrimitiveAction (applyPrimitiveAction itself, the deterministic parsers already
// wired into it) stays untouched. Returns undefined for a step whose required fields are missing
// (a small model omitting a field it was supposed to fill in) — declined rather than guessed at,
// same convention as every deterministic parser in this file.
function mapPrimitiveActionStep(step: PrimitiveActionStep): PrimitiveAction | undefined {
  switch (step.kind) {
    case "destroy_target":
      return { kind: "removal", effect: { kind: "destroy", targetType: toRemovalTargetType(step.targetType), excludedColors: [], artifactsExcluded: false, basicsExcluded: false } };
    case "destroy_all": {
      const targetType = step.targetType === "artifact" || step.targetType === "enchantment" ? step.targetType : "creature";
      return { kind: "removal", effect: { kind: "destroy_all", targetType, excludedColors: [] } };
    }
    case "exile_target":
      return { kind: "removal", effect: { kind: "exile", targetType: toRemovalTargetType(step.targetType), lifeGainToControllerEqualToPower: false } };
    case "bounce_target":
      return { kind: "removal", effect: { kind: "bounce", targetType: toRemovalTargetType(step.targetType) } };
    case "reanimate":
      return { kind: "zone", effect: { kind: "reanimate", anyGraveyard: step.anyGraveyard ?? false, targetType: toRegrowTargetType(step.regrowTargetType) } };
    case "mill":
      return step.amount ? { kind: "zone", effect: { kind: "mill", amount: step.amount, scope: step.millScope ?? "you" } } : undefined;
    case "draw_cards":
      return step.amount ? { kind: "draw_cards", amount: step.amount } : undefined;
    case "drain":
      return step.amount ? { kind: "drain", amount: step.amount, scope: step.drainScope ?? "target_player" } : undefined;
    case "damage_target":
      return step.amount ? { kind: "removal", effect: { kind: "damage", targetType: step.damageTargetType ?? "creature", amount: step.amount } } : undefined;
    case "discard":
      return step.amount ? { kind: "discard", amount: step.amount, scope: step.discardScope ?? "target_player" } : undefined;
    case "tap_target":
      return { kind: "tap_target", targetType: toRemovalTargetType(step.targetType) };
    case "untap_target":
      return { kind: "untap_target", targetType: toRemovalTargetType(step.targetType) };
    case "life_change":
      return step.lifeDelta
        ? { kind: "life_change", effect: step.lifeDelta > 0 ? { kind: "gain_life", amount: step.lifeDelta } : { kind: "lose_life", amount: -step.lifeDelta } }
        : undefined;
    case "pump_target":
      return step.power !== undefined && step.toughness !== undefined ? { kind: "pump_target", effect: { power: step.power, toughness: step.toughness } } : undefined;
    case "mass_pump":
      return step.power !== undefined && step.toughness !== undefined
        ? { kind: "mass_pump", effect: { power: step.power, toughness: step.toughness, scope: step.massPumpScope ?? "all" } }
        : undefined;
    case "mass_bounce":
      return { kind: "mass_bounce" };
    case "create_tokens":
      return step.tokenCount && step.tokenName
        ? {
            kind: "create_tokens",
            specs: [
              {
                count: step.tokenCount,
                name: step.tokenName,
                colors: step.tokenColors ?? [],
                typeLine: step.tokenTypeLine ?? "Creature",
                power: step.tokenPower !== undefined ? String(step.tokenPower) : undefined,
                toughness: step.tokenToughness !== undefined ? String(step.tokenToughness) : undefined,
                oracleText: "",
                role: "token"
              }
            ]
          }
        : undefined;
    case "put_counters_on_self":
      return step.counterKind && step.amount ? { kind: "put_counters_on_self", counterKind: step.counterKind, amount: step.amount } : undefined;
    case "sacrifice_permanent":
      return { kind: "sacrifice_permanent", scope: step.sacrificeScope ?? "self" };
    case "move_card_zone":
      return step.moveFrom && step.moveTo
        ? { kind: "move_card_zone", from: step.moveFrom, to: step.moveTo, filter: step.moveFilter ?? "worst", count: step.moveCount ?? 1 }
        : undefined;
  }
}

// Folds a whole LLM-produced plan over applyPrimitiveAction one step at a time — steps that fail to
// map (mapPrimitiveActionStep returning undefined) are simply skipped rather than aborting the rest
// of the plan, so a model getting one step wrong doesn't also cost the steps it got right.
// Does this planned step aim at a target (and which of the target pickers above can name one at cast time)?
function planActionNeedsTarget(action: PrimitiveAction): boolean {
  if (action.kind === "pump_target") return true;
  if (action.kind === "zone") return zoneEffectTargetSpec(action.effect) !== undefined;
  return action.kind === "removal" && ["damage", "destroy", "exile", "bounce", "grant_keywords"].includes(action.effect.kind);
}

// An agent's spell the deterministic parsers do not understand is resolved from a Rules Advisor (LLM) plan: text -> steps, which carry no target
// ids (the deterministic appliers pick those). The plan is fetched asynchronously, so only when this card text's plan is already cached (a
// repeat cast, or a card whose plan was fetched earlier this session) can its targets be named at cast time; they are recorded in castChoices
// and handed to the same steps on resolution (applyPrimitiveActionPlan's castTargets), which re-check them. First-ever cast: unchanged.
function agentPlannedCastChoices(session: GameSession, seatId: string, card: VisibleCard): CastChoices | undefined {
  if (!/\btargets?\b/i.test(card.oracleText)) return undefined;
  const cached = primitiveActionPlanCache.get(ruleWorkflowCacheKey("spell_resolved_to_graveyard", card.oracleText));
  if (!cached || cached.plan.declined || cached.plan.optional || cached.plan.condition) return undefined;
  const targets: ChosenTarget[] = [];
  for (const step of cached.plan.steps) {
    const action = mapPrimitiveActionStep(step);
    if (!action || !planActionNeedsTarget(action)) continue;
    const target =
      action.kind === "removal" ? (action.effect.kind === "modal" ? undefined : agentRemovalEffectTarget(session, seatId, card, action.effect, action.chosenX, false)) :
      action.kind === "zone" ? agentZoneEffectTargets(session, seatId, card, action.effect)?.[0] :
      action.kind === "pump_target" ? agentPumpTarget(session, seatId, card, action.effect) :
      undefined;
    // One unnamed target would shift the rest out of step with the steps that consume them: keep the resolution-time pick instead.
    if (!target) return undefined;
    targets.push(target);
  }
  return targets.length > 0 ? { targets } : undefined;
}

function applyPrimitiveActionPlan(session: GameSession, seatId: string, sourceCard: VisibleCard, steps: PrimitiveActionStep[], castTargets?: ChosenTarget[]): GameSession {
  // "drain" already moves the caster's own life for a Blood Artist-style effect — the prompt tells
  // the model never to also emit a life_change step for that same gain, but a small local model
  // doesn't reliably follow that (reproduced live: Blood Artist parsed as drain + a redundant
  // life_change lifeDelta=1, which would double the caster's gain if both ran). Dropping any
  // positive life_change step whenever a drain step is present is a deterministic backstop for
  // that specific double-count, not a prompt-only fix — cheaper and more certain than trying to
  // make the model perfectly reliable here.
  const hasDrainStep = steps.some((step) => step.kind === "drain");
  const dedupedSteps = hasDrainStep ? steps.filter((step) => !(step.kind === "life_change" && (step.lifeDelta ?? 0) > 0)) : steps;
  let usedTargets = 0;
  return dedupedSteps.reduce((current, step) => {
    const action = mapPrimitiveActionStep(step);
    if (!action) return current;
    // Targets named as the spell was cast go to the steps that aim at something, in order; one that is no longer legal does nothing (608.2b).
    if (castTargets && planActionNeedsTarget(action)) {
      const named = castTargets[usedTargets++];
      if (!named || !castTargetLegal(current, seatId, sourceCard, named)) {
        return rulesEvent(current, seatId, `${sourceCard.name}'s target is no longer legal; that part of the spell does nothing.`);
      }
      return applyPrimitiveAction(current, seatId, sourceCard, action, named);
    }
    return applyPrimitiveAction(current, seatId, sourceCard, action);
  }, session);
}

const MODAL_DONE_INDEX = 999;

// The "then discard a card" half of connive (Ledger Shredder, ...) — the draw already happened by
// the time this runs (see finishTriggerResolution's connive branch/startConniveIteration); this
// just moves the chosen card to the graveyard and, if it wasn't a land, puts a +1/+1 counter on the
// connived source. Mirrors resolveTriggerEffect's own connive case, which stays as the deterministic
// (chooseWorstHandCardToDiscard) fallback for pure-function callers that have no pendingRuleChoice
// to route an interactive pick through.
function applyConniveDiscard(session: GameSession, seatId: string, sourceCardId: string, sourceCardName: string, discardCardId: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  const discardCard = seat?.board.hand.find((card) => card.id === discardCardId);
  if (!seat || !discardCard) return session;
  const isNonland = !discardCard.typeLine.includes("Land");
  const seatName = seat.name;
  const discardedSession = moveCardBetweenVisibleZones(session, seatId, discardCardId, "graveyard");
  const countedSession = isNonland
    ? {
        ...discardedSession,
        seats: discardedSession.seats.map((item) =>
          item.id === seatId
            ? {
                ...item,
                board: {
                  ...item.board,
                  battlefield: item.board.battlefield.map((card) => (card.id === sourceCardId ? applyCounterDelta(card, "+1/+1", 1) : card))
                }
              }
            : item
        )
      }
    : discardedSession;
  return {
    ...countedSession,
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${sourceCardName} connives: ${seatName} discards ${discardCard.name}${isNonland ? `, putting a +1/+1 counter on ${sourceCardName}` : ""}.`
      },
      ...countedSession.events
    ]
  };
}

function dealsDamageInCombatStep(card: VisibleCard, step: "first" | "regular") {
  if (hasDoubleStrike(card)) return true;
  if (hasFirstStrike(card)) return step === "first";
  return step === "regular";
}

interface BlockedCombatOutcome {
  blockerDamageMarked: number;
  attackerDamageMarked: number;
  blockerDestroyed: boolean;
  attackerDestroyed: boolean;
  trampleOverflow: number;
  attackerLifegain: number;
  blockerLifegain: number;
  blockerMinusCounters: number;
  attackerMinusCounters: number;
}

interface MultiBlockedCombatOutcome {
  blockerResults: Array<{ blocker: VisibleCard; damageMarked: number; destroyed: boolean; lifegain: number; minusCounters: number }>;
  attackerDamageMarked: number;
  attackerDestroyed: boolean;
  trampleOverflow: number;
  attackerLifegain: number;
  attackerMinusCounters: number;
}

// Generalizes simulateBlockedCombat to two or more blockers on the same attacker (rule 509/510).
// The attacker's controller assigns damage among blockers in `blockers`' order — at least lethal
// (or, with deathtouch, 1) to one before any moves to the next; trample sends whatever's left after
// every blocker has lethal to the defending player/planeswalker, and without trample any leftover
// (the attacker has more power than total lethal needed) is simply dumped on the last blocker in
// order, since it has no other legal home and doesn't matter mechanically where it lands. Each
// blocker still deals its own full power to the attacker, same as a single block, just summed.
function simulateMultiBlockedCombat(attackingCard: VisibleCard, blockers: VisibleCard[]): MultiBlockedCombatOutcome {
  const attackerPower = Math.max(0, effectivePower(attackingCard));
  const attackerToughness = effectiveToughness(attackingCard) - (attackingCard.damage ?? 0);

  let attackerAlive = true;
  let attackerDamageMarked = 0;
  let trampleOverflow = 0;

  const states = blockers.map((card) => ({
    card,
    alive: true,
    damageMarked: 0,
    dealtToAttacker: 0,
    toughness: effectiveToughness(card) - (card.damage ?? 0),
    protectedFromAttacker: isProtectedFrom(card, attackingCard) || preventsCombatDamageToSelf(card)
  }));

  for (const step of ["first", "regular"] as const) {
    const attackerActs = attackerAlive && dealsDamageInCombatStep(attackingCard, step);

    if (attackerActs) {
      const targets = states.filter((state) => state.alive && !state.protectedFromAttacker);
      if (targets.length > 0) {
        let remaining = attackerPower;
        for (const state of targets) {
          if (remaining <= 0) break;
          const lethalNeeded = hasDeathtouch(attackingCard) ? 1 : Math.max(1, state.toughness - state.damageMarked);
          const assign = Math.min(remaining, lethalNeeded);
          state.damageMarked += assign;
          remaining -= assign;
        }
        if (hasTrample(attackingCard)) trampleOverflow += remaining;
        else if (remaining > 0) targets[targets.length - 1].damageMarked += remaining;
      } else if (hasTrample(attackingCard)) {
        trampleOverflow += attackerPower;
      }
    }

    const dealtDamageThisStep = new Set<string>();
    for (const state of states) {
      if (!state.alive || !dealsDamageInCombatStep(state.card, step)) continue;
      if (isProtectedFrom(attackingCard, state.card) || preventsCombatDamageToSelf(attackingCard)) continue;
      const dealt = Math.max(0, effectivePower(state.card));
      attackerDamageMarked += dealt;
      state.dealtToAttacker += dealt;
      dealtDamageThisStep.add(state.card.id);
    }

    for (const state of states) {
      if (
        state.alive &&
        !hasIndestructible(state.card) &&
        (state.damageMarked >= state.toughness || (hasDeathtouch(attackingCard) && attackerActs && !state.protectedFromAttacker && state.damageMarked > 0))
      ) {
        state.alive = false;
      }
    }
    if (attackerAlive && !hasIndestructible(attackingCard)) {
      const deathtouchHit = states.some((state) => hasDeathtouch(state.card) && dealtDamageThisStep.has(state.card.id));
      if (attackerDamageMarked >= attackerToughness || deathtouchHit) attackerAlive = false;
    }
  }

  const blockerResults = states.map((state) => ({
    blocker: state.card,
    damageMarked: state.damageMarked,
    destroyed: !state.alive,
    lifegain: hasLifelink(state.card) ? state.dealtToAttacker : 0,
    minusCounters: hasWither(attackingCard) || hasInfect(attackingCard) ? state.damageMarked : 0
  }));

  return {
    blockerResults,
    attackerDamageMarked,
    attackerDestroyed: !attackerAlive,
    trampleOverflow,
    attackerLifegain: hasLifelink(attackingCard) ? blockerResults.reduce((total, result) => total + result.damageMarked, 0) + trampleOverflow : 0,
    attackerMinusCounters: states.some((state) => hasWither(state.card) || hasInfect(state.card)) ? attackerDamageMarked : 0
  };
}

function simulateBlockedCombat(attackingCard: VisibleCard, blocker: VisibleCard): BlockedCombatOutcome {
  const attackerPower = Math.max(0, effectivePower(attackingCard));
  const blockerPower = Math.max(0, effectivePower(blocker));
  const attackerToughness = effectiveToughness(attackingCard);
  const blockerToughness = effectiveToughness(blocker);
  const blockerProtected = isProtectedFrom(blocker, attackingCard) || preventsCombatDamageToSelf(blocker);
  const attackerProtected = isProtectedFrom(attackingCard, blocker) || preventsCombatDamageToSelf(attackingCard);

  let attackerAlive = true;
  let blockerAlive = true;
  let attackerDamageMarked = 0;
  let blockerDamageMarked = 0;
  let trampleOverflow = 0;

  for (const step of ["first", "regular"] as const) {
    const attackerActs = attackerAlive && dealsDamageInCombatStep(attackingCard, step);
    const blockerActs = blockerAlive && dealsDamageInCombatStep(blocker, step);

    if (attackerActs && !blockerProtected) {
      const lethalNeeded = hasDeathtouch(attackingCard) ? 1 : Math.max(1, blockerToughness - blockerDamageMarked);
      const assignedToBlocker = hasTrample(attackingCard) ? Math.min(attackerPower, lethalNeeded) : attackerPower;
      trampleOverflow += hasTrample(attackingCard) ? Math.max(0, attackerPower - assignedToBlocker) : 0;
      blockerDamageMarked += assignedToBlocker;
    } else if (attackerActs && hasTrample(attackingCard)) {
      // Protection prevents damage to the blocker, but a trampling attacker's damage still goes
      // through to the defending player/planeswalker for the full amount.
      trampleOverflow += attackerPower;
    }
    if (blockerActs && !attackerProtected) {
      attackerDamageMarked += blockerPower;
    }
    if (blockerAlive && !hasIndestructible(blocker) && (blockerDamageMarked >= blockerToughness || (hasDeathtouch(attackingCard) && attackerActs && !blockerProtected && blockerDamageMarked > 0))) {
      blockerAlive = false;
    }
    if (attackerAlive && !hasIndestructible(attackingCard) && (attackerDamageMarked >= attackerToughness || (hasDeathtouch(blocker) && blockerActs && !attackerProtected && attackerDamageMarked > 0))) {
      attackerAlive = false;
    }
  }

  return {
    blockerDamageMarked,
    attackerDamageMarked,
    blockerDestroyed: !blockerAlive,
    attackerDestroyed: !attackerAlive,
    trampleOverflow,
    attackerLifegain: hasLifelink(attackingCard) ? blockerDamageMarked + trampleOverflow : 0,
    blockerLifegain: hasLifelink(blocker) ? attackerDamageMarked : 0,
    blockerMinusCounters: hasWither(attackingCard) || hasInfect(attackingCard) ? blockerDamageMarked : 0,
    attackerMinusCounters: hasWither(blocker) || hasInfect(blocker) ? attackerDamageMarked : 0
  };
}

// blockers must all belong to target.seat and be ordered the way the attacker's controller wants
// damage assigned (attackingCard.damageAssignmentOrder, falling back to however they're passed in
// for the single-blocker case where order is moot).
function resolveBlockedCombatDamage(
  inputSession: GameSession,
  attackerSeatId: string,
  attackingCard: VisibleCard,
  target: { seat: PlayerSeat; planeswalker?: VisibleCard },
  rawBlockers: VisibleCard[]
): GameSession {
  let session = inputSession;
  // A creature blocking two attackers deals its damage to the first one only.
  const blockers = rawBlockers.map((blocker) => (blocker.extraBlockingTargetId === attackingCard.id ? { ...blocker, temporaryPowerBonus: (blocker.temporaryPowerBonus ?? 0) - Math.max(0, effectivePower(blocker)) } : blocker));
  // Twinflame Tyrant: each side's combat damage to the other side's creatures is doubled when its controller has the doubler.
  const doubled = (card: VisibleCard, factor: number): VisibleCard => (factor > 1 ? { ...card, temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) + Math.max(0, effectivePower(card)) * (factor - 1) } : card);
  const attackerFactor = damageDoublingFactor(session, attackerSeatId, target.seat.id);
  const blockerFactor = damageDoublingFactor(session, target.seat.id, attackerSeatId);
  // "Prevent all damage target creature would deal this turn": that creature deals no damage in this combat.
  const silenced = (card: VisibleCard): VisibleCard =>
    (session.damageShields ?? []).some((shield) => shield.turn === session.turn && shield.protect.kind === "from_source" && shield.protect.cardId === card.id)
      ? { ...card, temporaryPowerBonus: (card.temporaryPowerBonus ?? 0) - Math.max(0, effectivePower(card)) }
      : card;
  const rawOutcome = simulateMultiBlockedCombat(silenced(doubled(attackingCard, attackerFactor)), blockers.map((blocker) => silenced(doubled(blocker, blockerFactor))));

  // Prevention shields (Enshrouding Mist, "prevent the next N damage", ...) apply to the damage each creature was assigned; the combat
  // outcome (deaths, lifelink, -1/-1 counters) is then re-derived from what actually got through. Seraph-style statics are already inside the simulation.
  const preventedInCombat = (seatId: string, card: VisibleCard, damage: number, source: VisibleCard) => {
    const result = applyDamagePrevention(session, { kind: "permanent", seatId, cardId: card.id, isCreature: true }, card.name, damage, true, source.name, source);
    session = result.session;
    return result.remaining;
  };
  for (const [seatId, card, source] of [[target.seat.id, blockers[0], attackingCard], [attackerSeatId, attackingCard, blockers[0]]] as Array<[string, VisibleCard, VisibleCard]>) {
    if (preventsCombatDamageToSelf(card) && effectivePower(source) > 0) session = rulesEvent(session, seatId, `${source.name}'s combat damage to ${card.name} is prevented by ${card.name}.`);
  }
  const outcome: MultiBlockedCombatOutcome = { ...rawOutcome, blockerResults: rawOutcome.blockerResults.map((entry) => ({ ...entry })) };
  if (session.damageShields?.length) {
    for (const entry of outcome.blockerResults) {
      if (entry.damageMarked <= 0) continue;
      const left = preventedInCombat(target.seat.id, entry.blocker, entry.damageMarked, attackingCard);
      if (left === entry.damageMarked) continue;
      entry.minusCounters = Math.min(entry.minusCounters, left);
      entry.destroyed = !hasIndestructible(entry.blocker) && ((entry.blocker.damage ?? 0) + left >= effectiveToughness(entry.blocker) || (hasDeathtouch(attackingCard) && left > 0));
      entry.damageMarked = left;
    }
    if (outcome.attackerDamageMarked > 0) {
      const left = preventedInCombat(attackerSeatId, attackingCard, outcome.attackerDamageMarked, blockers[0]);
      if (left !== outcome.attackerDamageMarked) {
        const scale = left / outcome.attackerDamageMarked;
        outcome.blockerResults.forEach((entry) => (entry.lifegain = Math.floor(entry.lifegain * scale)));
        outcome.attackerMinusCounters = Math.min(outcome.attackerMinusCounters, left);
        outcome.attackerDestroyed = !hasIndestructible(attackingCard) && ((attackingCard.damage ?? 0) + left >= effectiveToughness(attackingCard) || (left > 0 && blockers.some((blocker) => hasDeathtouch(blocker))));
        outcome.attackerDamageMarked = left;
      }
    }
    outcome.attackerLifegain = hasLifelink(attackingCard) ? outcome.blockerResults.reduce((total, entry) => total + entry.damageMarked, 0) + outcome.trampleOverflow : 0;
  }

  const destructions: Array<{ seatId: string; cardId: string; message: string }> = [];
  for (const result of outcome.blockerResults) {
    if (result.destroyed) {
      destructions.push({ seatId: target.seat.id, cardId: result.blocker.id, message: `${result.blocker.name} is destroyed by combat damage from ${attackingCard.name}.` });
    }
  }
  if (outcome.attackerDestroyed) {
    destructions.push({
      seatId: attackerSeatId,
      cardId: attackingCard.id,
      message: `${attackingCard.name} is destroyed by combat damage from ${blockers.map((blocker) => blocker.name).join(" and ")}.`
    });
  }

  const totalBlockerLifegain = outcome.blockerResults.reduce((total, result) => total + result.lifegain, 0);
  const tradeSummary = outcome.blockerResults.map((result) => `${result.damageMarked} to ${result.blocker.name}`).join(", ");

  let nextSession: GameSession = {
    ...session,
    seats: session.seats.map((seat) => {
      if (seat.id === attackerSeatId && outcome.attackerLifegain > 0) return { ...seat, life: seat.life + outcome.attackerLifegain };
      if (seat.id === target.seat.id && totalBlockerLifegain > 0) return { ...seat, life: seat.life + totalBlockerLifegain };
      return seat;
    }),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId: attackerSeatId,
        message: `${attackingCard.name} trades combat damage with ${blockers.map((blocker) => blocker.name).join(" and ")} (${tradeSummary}, ${outcome.attackerDamageMarked} to ${attackingCard.name}).`,
        detail: "Combat damage"
      },
      ...session.events
    ]
  };

  for (const result of outcome.blockerResults) {
    if (result.minusCounters <= 0) continue;
    nextSession = {
      ...nextSession,
      seats: nextSession.seats.map((seat) =>
        seat.id === target.seat.id
          ? {
              ...seat,
              board: {
                ...seat.board,
                battlefield: seat.board.battlefield.map((card) => (card.id === result.blocker.id ? applyCounterDelta(card, "-1/-1", result.minusCounters) : card))
              }
            }
          : seat
      )
    };
  }
  if (outcome.attackerMinusCounters > 0) {
    nextSession = {
      ...nextSession,
      seats: nextSession.seats.map((seat) =>
        seat.id === attackerSeatId
          ? { ...seat, board: { ...seat.board, battlefield: seat.board.battlefield.map((card) => (card.id === attackingCard.id ? applyCounterDelta(card, "-1/-1", outcome.attackerMinusCounters) : card)) } }
          : seat
      )
    };
  }

  // Survivors keep the damage they took (it can matter to a burn spell later this turn).
  for (const result of outcome.blockerResults) {
    if (!result.destroyed && result.minusCounters <= 0) nextSession = { ...nextSession, seats: markDamageOnCard(nextSession.seats, target.seat.id, result.blocker.id, result.damageMarked) };
  }
  if (!outcome.attackerDestroyed && outcome.attackerMinusCounters <= 0) nextSession = { ...nextSession, seats: markDamageOnCard(nextSession.seats, attackerSeatId, attackingCard.id, outcome.attackerDamageMarked) };

  if (outcome.trampleOverflow > 0) {
    nextSession = applyCombatDamageToTarget(nextSession, attackingCard.name, target, outcome.trampleOverflow, attackingCard, attackerSeatId);
  }
  // Damage-taken triggers ("whenever this creature is dealt damage"): every creature that was actually dealt combat damage.
  for (const result of outcome.blockerResults) nextSession = applyDealtDamageTriggers(nextSession, target.seat.id, result.blocker, result.damageMarked);
  nextSession = applyDealtDamageTriggers(nextSession, attackerSeatId, attackingCard, outcome.attackerDamageMarked);

  return destroyCreatures(nextSession, destructions);
}

function describeBlockTrade(attacker: VisibleCard | undefined, blocker: VisibleCard): string {
  if (!attacker) return "(trade outcome unclear from power/toughness alone).";
  const attackerPower = Number.parseInt(attacker.power ?? "", 10);
  const attackerToughness = Number.parseInt(attacker.toughness ?? "", 10);
  const blockerPower = Number.parseInt(blocker.power ?? "", 10);
  const blockerToughness = Number.parseInt(blocker.toughness ?? "", 10);
  if ([attackerPower, attackerToughness, blockerPower, blockerToughness].some((value) => Number.isNaN(value))) {
    return "(trade outcome unclear from power/toughness alone).";
  }

  const outcome = simulateBlockedCombat(attacker, blocker);
  const keywordNotes = Array.from(new Set([...describeKeywords(attacker), ...describeKeywords(blocker)]));
  const noteSuffix = keywordNotes.length > 0 ? ` [${keywordNotes.join(", ")}]` : "";
  const trampleNote = outcome.trampleOverflow > 0 ? `, ${outcome.trampleOverflow} tramples over` : "";

  if (outcome.blockerDestroyed && outcome.attackerDestroyed) return `(would trade: both creatures die${trampleNote}${noteSuffix}).`;
  if (outcome.blockerDestroyed && !outcome.attackerDestroyed) return `(blocker dies, attacker survives${trampleNote}${noteSuffix}).`;
  if (!outcome.blockerDestroyed && outcome.attackerDestroyed) return `(attacker dies, blocker survives${noteSuffix}).`;
  return `(neither creature dies${trampleNote}${noteSuffix}).`;
}

export function legalBlockActions(session: GameSession, choice: BlockChoiceState): LegalAgentAction[] {
  const defender = session.seats.find((seat) => seat.id === choice.defenderSeatId);
  const attacker = session.seats.find((seat) => seat.id === choice.attackerSeatId);
  const attackingCard = attacker?.board.battlefield.find((card) => card.id === choice.attackerCardId);
  const actions: LegalAgentAction[] =
    defender?.board.battlefield.filter((card) => canBlock(card, attackingCard, defender.board.battlefield)).map((card) => ({
      id: `block:${card.id}`,
      actionType: "block" as const,
      cardId: card.id,
      targetIds: [choice.attackerCardId],
      label: `block ${attackingCard?.name ?? "attacker"} with ${card.name}`,
      detail: `${effectivePower(card)}/${effectiveToughness(card)} ${card.oracleText} ${describeBlockTrade(attackingCard, card)}`.trim(),
      role: card.role
    })) ?? [];
  actions.push({ id: "no-blocks", actionType: "pass_priority", targetIds: [choice.attackerCardId], label: "declare no blockers" });
  return actions;
}

function fallbackLegalAction(actions: LegalAgentAction[]) {
  return (
    actions.find((action) => action.actionType === "cast_spell") ??
    actions.find((action) => action.actionType === "cast_commander") ??
    actions.find((action) => action.actionType === "play_land") ??
    actions.find((action) => action.actionType === "activate_ability") ??
    actions.find((action) => action.actionType === "attack") ??
    actions.find((action) => action.actionType === "block") ??
    actions.find((action) => action.actionType === "pass_priority") ??
    actions[0]
  );
}

// Without a session, this used to only send the card's NAME for anything on the stack — meaning
// an agent deciding whether to counter/answer something had to recognize the card from training
// data instead of reading what it actually does, the exact hallucination risk this codebase avoids
// everywhere else (e.g. the Rules Advisor's system prompt explicitly forbids it). Looking up the
// actual source card (still sitting in hand/command for an unresolved spell, or on the battlefield
// for a trigger source) lets the real oracle text ride along instead.
function pendingActionSourceCard(session: GameSession, action: PendingAction): VisibleCard | undefined {
  if (action.type === "spell") {
    const seat = session.seats.find((item) => item.id === action.actorSeatId);
    return action.sourceZone === "command"
      ? seat?.board.commander
      : action.sourceZone === "exile"
        ? seat?.board.exile?.find((card) => card.id === action.cardId)
        : action.sourceZone === "graveyard"
          ? seat?.board.graveyard?.find((card) => card.id === action.cardId)
          : action.sourceZone === "library"
            ? seat?.library?.find((card) => card.id === action.cardId)
            : seat?.board.hand.find((card) => card.id === action.cardId);
  }
  if (action.type === "trigger") {
    const seat = session.seats.find((item) => item.id === action.controllerSeatId);
    return seat?.board.battlefield.find((card) => card.id === action.sourceCardId);
  }
  return undefined;
}

// UI-only view of a PendingAction that also carries the live source card, so the stack HUD can
// render real card art (VisualCard) instead of just a name string. Never stored in state — derived
// fresh every render from pendingActionSourceCard so it can't go stale if the card's zone/counters
// change while it sits on the stack.
function withPendingActionSourceCard(session: GameSession, action: PendingAction, stack: PendingAction[] = []): PendingAction & { sourceCard?: VisibleCard; description?: StackItemDescription } {
  const sourceCard = pendingActionSourceCard(session, action);
  // Who controls it, what it does and what it targets (src/lib/stackDescription.ts), for the stack HUD's target lines and "targets you" badge.
  const faceCard = sourceCard && action.type === "spell" ? applyChosenFaceToCard(sourceCard, action.faceIndex) : sourceCard;
  const modeLabels = faceCard && action.type === "spell" ? castModeLabels(faceCard, action.chosenX, action.castChoices) : undefined;
  const description = action.type === "phase" ? undefined : describeStackItem(session, { ...action, sourceCard, modeLabels } as StackItemLike, stack as StackItemLike[]);
  return { ...action, sourceCard, description };
}

function pendingActionSummary(session: GameSession, action: PendingAction) {
  return {
    id: action.id,
    type: action.type,
    actorSeatId: action.actorSeatId,
    cardName: "cardName" in action ? action.cardName : "sourceCardName" in action ? action.sourceCardName : undefined,
    oracleText: pendingActionSourceCard(session, action)?.oracleText,
    message: action.message,
    // Targets chosen at cast time (a card on someone's battlefield, or a player), so agents can tell whether a spell is aimed at them.
    targetCardIds: action.type === "spell" ? (action.castChoices?.targets ?? []).flatMap((target) => (target.kind === "card" ? [target.cardId] : [])) : undefined,
    targetSeatIds: action.type === "spell" ? (action.castChoices?.targets ?? []).flatMap((target) => (target.kind === "player" ? [target.seatId] : [])) : undefined
  };
}

function buildAgentDecisionContext(
  session: GameSession,
  seat: PlayerSeat,
  extra: Record<string, unknown>
) {
  return {
    ...extra,
    // Damage-prevention shields live this turn (Fog effects, Inkshield, ...), so an agent doesn't attack into or waste burn on a shielded target.
    activeDamagePrevention: [...describeDamageShields(session), ...(session.combatDamagePrevented?.turn === session.turn ? [`All combat damage is prevented this turn${session.combatDamagePrevented.exceptType ? ` except from ${session.combatDamagePrevented.exceptType} creatures` : ""}.`] : [])],
    you: agentSeatSnapshot(seat, true),
    opponents: session.seats.filter((item) => item.id !== seat.id && !item.hasLost).map((item) => agentSeatSnapshot(item, false))
  };
}

function agentSeatSnapshot(seat: PlayerSeat, includeHand: boolean) {
  return {
    id: seat.id,
    name: seat.name,
    life: seat.life,
    commanderDamage: seat.commanderDamage,
    poison: seat.poison ?? 0,
    availableMana: summarizeAvailableMana(seat),
    commander: seat.board.commander ? agentCardSnapshot(seat.board.commander) : undefined,
    // For counterspell/protection awareness (lookAhead.estimateOpponentInterferenceRisk): the commander's colors, and counterspells /
    // protection tricks this seat has already shown in its graveyard or exile.
    colorIdentity: seat.board.commander?.colorIdentity ?? seat.board.commander?.colors,
    shownTells: (() => {
      const tells = [...(seat.board.graveyard ?? []), ...(seat.board.exile ?? [])].map((card) => classifyTell(card.oracleText, card.typeLine));
      return { counterspells: tells.filter((tell) => tell === "counter").length, protection: tells.filter((tell) => tell === "protection").length };
    })(),
    // Only for the deciding seat's own view ("you"), not an opponent's — this is the agent's own
    // deck's game plan (see bracketPolicy.ts' buildDeckGamePlan), not intelligence about others.
    gamePlan: includeHand ? seat.deck?.gamePlan : undefined,
    hand: includeHand ? seat.board.hand.map(agentCardSnapshot) : { count: seat.board.hand.length },
    battlefield: seat.board.battlefield.map(agentCardSnapshot),
    graveyard: (seat.board.graveyard ?? []).slice(-8).map(agentCardSnapshot),
    exile: (seat.board.exile ?? []).slice(-8).map(agentCardSnapshot),
    libraryCount: seat.library?.length ?? seat.zones.library
  };
}

function agentCardSnapshot(card: VisibleCard) {
  const ruledEffectSummaries = cachedRuleSummariesForCard(card.oracleText);
  return {
    id: card.id,
    name: card.name,
    typeLine: card.typeLine,
    role: card.role,
    manaCost: card.manaCost,
    manaValue: card.manaValue,
    power: card.power !== undefined ? String(effectivePower(card)) : card.power,
    toughness: card.toughness !== undefined ? String(effectiveToughness(card)) : card.toughness,
    loyalty: card.loyalty,
    tapped: card.tapped,
    summoningSick: card.summoningSick,
    enteredTurn: card.enteredTurn,
    phasedOut: card.phasedOut ? true : undefined,
    attacking: card.attacking,
    attackTargetId: card.attacking ? card.attackTargetId : undefined,
    blocking: card.blocking,
    counters: card.counters,
    oracleText: card.oracleText,
    goaded: card.goaded ? true : undefined,
    // What the card can actually do right now in combat terms (printed, granted, until end of turn) — read this rather than the text.
    keywords: describeKeywords(card),
    faces: card.faces?.map((face) => ({ name: face.name, typeLine: face.typeLine, manaCost: face.manaCost, oracleText: face.oracleText })),
    unlockedFaceIndices: card.unlockedFaceIndices,
    interpretedEffects: card.interpretedEffects,
    // Plain-English summaries the rules advisor already worked out for this exact card text — from
    // an earlier real consultation, this game or (via ruleWorkflowCache's localStorage persistence)
    // an earlier one — so the agent's own decision-making gets a digest of what an ability actually
    // does alongside the raw oracleText above, instead of having to re-derive it from scratch every
    // single time purely from the raw text. Empty for a card nobody's triggered/cast yet; the very
    // first real encounter of any given card still has to be read cold, same as before this existed.
    ruledEffects: ruledEffectSummaries.length > 0 ? ruledEffectSummaries : undefined,
    attachedToId: card.attachedToId,
    grantedKeywords: card.grantedKeywords,
    grantedProtectionColors: card.grantedProtectionColors,
    grantedTypes: card.grantedTypes,
    commander: card.commander,
    commanderTax: card.commanderTax,
    token: card.token
  };
}

function resolveHumanUnblockedDamage(session: GameSession, choice: BlockChoiceState): GameSession {
  const attacker = session.seats.find((seat) => seat.id === choice.attackerSeatId);
  const defender = session.seats.find((seat) => seat.id === choice.defenderSeatId);
  const attackingCard = attacker?.board.battlefield.find((card) => card.id === choice.attackerCardId && card.attacking);
  if (!attacker || !defender || !attackingCard) return session;
  const decidedSession = markAttackDecided(session, attacker.id, attackingCard.id);
  return {
    ...decidedSession,
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId: attacker.id,
        message: `${defender.name} declares no blockers for ${attackingCard.name}.`,
        detail: "Phase change"
      },
      ...decidedSession.events
    ]
  };
}

// "Whenever one or more other creatures you control enter, if they entered or were cast from a graveyard, create a token that's a copy of one of
// them. This ability triggers only once each turn." (Twilight Diviner). A batch watcher: ONE trigger per source for everything that entered together
// (`entries` is one simultaneous batch), judged on each entry's enteredFrom stamp (see VisibleCard.enteredFrom). The once-each-turn limit is checked
// here (no trigger when it already fired this turn) and again when the trigger resolves (resolveTriggerEffect's oncePerTurn key).
export function findEntersBatchWatcherTriggers(session: GameSession, entries: Array<{ seatId: string; card: VisibleCard }>): Array<Extract<PendingAction, { type: "trigger" }>> {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  if (entries.length === 0) return triggers;
  for (const seat of session.seats) {
    if (seat.hasLost) continue;
    for (const source of seat.board.battlefield) {
      if (source.abilitiesStripped || source.phasedOut) continue;
      const clause = oracleClauses(source.oracleText).find((line) => /^whenever one or more other creatures you control enter,\s*if they entered or were cast from a graveyard,\s*create a token that'?s a copy of one of them\b/i.test(line));
      if (!clause) continue;
      const once = /\bthis ability triggers only once each turn\b/i.test(clause);
      if (once && session.onceEachTurnEffectsUsed?.includes(`${session.turn}:${source.id}:once:copy_token`)) continue;
      const candidates = entries
        .filter((entry) => entry.seatId === seat.id && entry.card.id !== source.id && entry.card.enteredFrom === "graveyard")
        .map((entry) => findPermanentById(session, entry.card.id))
        .filter((card): card is VisibleCard => card !== undefined && hasCardType(card, "Creature"));
      if (candidates.length === 0) continue;
      const effect: TriggerEffect = { kind: "copy_token", scope: "one_of_candidates", candidateIds: candidates.map((card) => card.id), ...(once ? { oncePerTurn: true } : {}) };
      triggers.push(makeCommonTrigger(seat.id, seat.id, source, effect, `${source.name} triggers because ${candidates.map((card) => card.name).join(", ")} entered from a graveyard.`, candidates[0].id));
    }
  }
  return triggers;
}

// "Metalcraft — Whenever this creature attacks, if you control three or more artifacts, creatures
// your opponents control lose all abilities and have base power and toughness N/N until end of
// turn." (Vedalken Humiliator) — narrow to this exact wording, same single-card-scoped pattern as
// isArchaeomancersMapLandRaidTrigger below. Called from declareAttack, which already knows exactly
// which creature is attacking and who its controller's opponents are — see that call site's own
// comment for why the generic "declare attackers step" phase-trigger sweep can't express this.
function parseMetalcraftAttackDebuff(oracleText: string): { power: number; toughness: number } | undefined {
  const match = oracleText
    .toLowerCase()
    .match(
      /\bwhenever this creature attacks, if you control three or more artifacts, creatures your opponents control lose all abilities and have base power and toughness (\d+)\/(\d+) until end of turn\b/
    );
  return match ? { power: Number.parseInt(match[1], 10), toughness: Number.parseInt(match[2], 10) } : undefined;
}

// "Whenever a land an opponent controls enters, if that player controls more lands than you, you
// may put a land card from your hand onto the battlefield." (Archaeomancer's Map) — narrow to this
// exact wording rather than generalizing enteredTriggerApplies' own qualifier handling (which only
// understands "you control"/unqualified, not "an opponent controls") for what's currently a single
// motivating card. Scoped to the land-play entry point only (not every other way a land could
// enter, e.g. a search-to-battlefield effect) — the overwhelming majority of "a land enters" events
// in a real game are ordinary land drops. This previously required "you may pay {1}. If you do, put
// ... tapped" — text this card has never actually had — so the trigger never matched at all,
// reported live as it silently never firing even with more lands than the opponent.
export function isArchaeomancersMapLandRaidTrigger(oracleText: string): boolean {
  return /\bwhenever a land an opponent controls enters, if that player controls more lands than you, you may put a land card from your hand onto the battlefield\b/i.test(
    oracleText
  );
}

export function findLandRaidTriggers(session: GameSession, enteringSeatId: string, enteredCard: VisibleCard): Array<Extract<PendingAction, { type: "trigger" }>> {
  if (!enteredCard.typeLine.includes("Land")) return [];
  const enteringSeat = session.seats.find((seat) => seat.id === enteringSeatId);
  if (!enteringSeat) return [];
  const enteringLandCount = enteringSeat.board.battlefield.filter((card) => card.typeLine.includes("Land")).length;
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const seat of session.seats) {
    if (seat.id === enteringSeatId) continue;
    const landCount = seat.board.battlefield.filter((card) => card.typeLine.includes("Land")).length;
    if (enteringLandCount <= landCount) continue;
    for (const source of seat.board.battlefield) {
      if (!isArchaeomancersMapLandRaidTrigger(source.oracleText)) continue;
      triggers.push(
        makeCommonTrigger(enteringSeatId, seat.id, source, { kind: "put_land_from_hand" }, `${source.name} triggers because ${enteredCard.name} entered under ${possessive(enteringSeat)} control.`)
      );
    }
  }
  return triggers;
}

// "Untap all artifacts you control during each other player's untap step." (Unwinding Clock) /
// "Untap all permanents you control during each other player's untap step." (Seedborn Muse) — not
// a triggered ability at all (no "when"/"whenever"), so it doesn't belong in
// findCommonTriggersForPermanentEntered/died's trigger-scan machinery; it's a standing effect that
// extends WHO untaps during a given untap step, checked directly from untapForSeat below instead.
// Previously had no implementation anywhere in the engine for either wording, so a controller's
// artifacts/permanents only ever untapped on their own untap step like normal, never during anyone
// else's — reported live as both Unwinding Clock and, separately, Seedborn Muse "not working."
function extraUntapAbilityScope(card: { oracleText: string }): "artifacts" | "permanents" | undefined {
  if (/\buntap all artifacts you control during each other player's untap step\b/i.test(card.oracleText)) return "artifacts";
  if (/\buntap all permanents you control during each other player's untap step\b/i.test(card.oracleText)) return "permanents";
  return undefined;
}

// Called after a seat's own untap step already ran (untapForSeat) — untaps the artifacts/permanents
// of every OTHER seat that controls an Unwinding Clock or Seedborn Muse (or the same effect on any
// other permanent), since this step is "each other player's" untap step from each such controller's
// point of view. Each source's own controller is unaffected by their own copy (their stuff already
// untaps normally on their own untap step) — only every seat that ISN'T the one whose untap step
// this is can have a source granting them a bonus untap here. A seat with more than one qualifying
// source (unlikely, but not prevented) is scoped to the broadest one found ("permanents" beats
// "artifacts") rather than applying each separately, which would be indistinguishable in outcome
// anyway once "permanents" has already untapped everything.
function applyExtraUntapEffects(session: GameSession, activeUntapSeatId: string): GameSession {
  let next = session;
  for (const sourceSeat of session.seats) {
    if (sourceSeat.id === activeUntapSeatId) continue;
    const scopes = sourceSeat.board.battlefield.map(extraUntapAbilityScope).filter((scope): scope is "artifacts" | "permanents" => scope !== undefined);
    if (scopes.length === 0) continue;
    const scope = scopes.includes("permanents") ? "permanents" : "artifacts";
    const sourceName = scope === "permanents" ? "Seedborn Muse" : "Unwinding Clock";
    next = {
      ...next,
      seats: next.seats.map((item) =>
        item.id === sourceSeat.id
          ? {
              ...item,
              board: {
                ...item.board,
                commander: scope === "permanents" && item.board.commander?.tapped ? { ...item.board.commander, tapped: false } : item.board.commander,
                battlefield: item.board.battlefield.map((card) =>
                  card.tapped && (scope === "permanents" || card.typeLine.includes("Artifact")) ? { ...card, tapped: false } : card
                )
              }
            }
          : item
      ),
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId: sourceSeat.id,
          message: `${sourceName} untaps ${possessive(sourceSeat)} ${scope} during ${(() => {
            const untapSeat = session.seats.find((seat) => seat.id === activeUntapSeatId);
            return untapSeat ? possessive(untapSeat) : "another player's";
          })()} untap step.`,
          detail: "Phase change"
        },
        ...next.events
      ]
    };
  }
  return next;
}

// "When Atsushi dies, choose one — • ... • ..." — the modes sit on the bullet lines after the header clause.
function modalDeathTriggerEffect(source: VisibleCard): TriggerEffect | undefined {
  return modalClauseTriggerEffect(source, /^(?:when|whenever)\b[^,]*\bdies, choose (?:one|two)\b.*[—-]\s*$/i);
}

// "Whenever a player sacrifices another permanent, put a +1/+1 counter on each creature you control." (Mazirek,
// Kraul Death Priest) — fires once per sacrificed permanent (any player's, never Mazirek itself) for each such
// watcher on the battlefield. Deaths come from destroyCreatures' pendingDeaths, which marks sacrifices.
export function findSacrificeWatcherTriggers(
  session: GameSession,
  deaths: Array<{ seatId: string; card: VisibleCard; sacrificed?: boolean }>
): Array<Extract<PendingAction, { type: "trigger" }>> {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const death of deaths) {
    if (!death.sacrificed) continue;
    for (const seat of session.seats) {
      if (seat.hasLost) continue;
      for (const source of seat.board.battlefield) {
        if (source.id === death.card.id || source.abilitiesStripped) continue;
        const clause = oracleClauses(source.oracleText).find((line) => /^whenever a player sacrifices another permanent\b/i.test(line));
        if (!clause) continue;
        const effectText = clause.replace(/^whenever a player sacrifices another permanent,\s*/i, "");
        const effect = commonTriggerEffect(effectText, "clause", undefined, seat);
        if (!effect) continue;
        triggers.push(makeCommonTrigger(death.seatId, seat.id, source, effect, `${source.name} triggers because ${death.card.name} was sacrificed.`, death.card.id));
      }
    }
    // "Whenever you sacrifice a creature / a black creature / a green creature, ..." (Dina, Essence Brewer; Savra, Queen of the Golgari): only the
    // sacrificing player's own watchers, and the sacrificed card itself counts (a creature that watches its own sacrifice still sees it).
    const sacrificer = session.seats.find((item) => item.id === death.seatId);
    if (sacrificer && !sacrificer.hasLost) {
      for (const source of [...sacrificer.board.battlefield, ...(sacrificer.board.battlefield.some((card) => card.id === death.card.id) ? [] : [death.card])]) {
        if (source.abilitiesStripped) continue;
        for (const line of oracleClauses(source.oracleText)) {
          const match = line.match(/^whenever you sacrifice (?:an?|another) ([a-z]+ )?(creature|permanent|artifact|food|land)s?,\s*(.+)$/i);
          if (!match) continue;
          const adjective = match[1]?.trim().toLowerCase();
          const noun = match[2].toLowerCase();
          if (/\banother\b/i.test(line.slice(0, 40)) && source.id === death.card.id) continue;
          if (!deathMatchesSacrificeSubject(death.card, adjective, noun)) continue;
          const effectText = match[3];
          const effect = sacrificeWatcherEffect(effectText, sacrificer);
          if (!effect) continue;
          triggers.push(makeCommonTrigger(death.seatId, sacrificer.id, source, effect, `${source.name} triggers because ${death.card.name} was sacrificed.`, death.card.id));
        }
      }
    }
  }
  // "Whenever one or more other creatures die, ..." (Morbid Opportunist): one trigger per watcher for the whole batch of deaths.
  const dyingCreatures = deaths.filter((death) => hasCardType(death.card, "Creature"));
  if (dyingCreatures.length > 0) {
    for (const seat of session.seats) {
      if (seat.hasLost) continue;
      for (const source of [...seat.board.battlefield, ...dyingCreatures.filter((death) => death.seatId === seat.id).map((death) => death.card)]) {
        if (source.abilitiesStripped) continue;
        const clause = oracleClauses(source.oracleText).find((line) => /^whenever one or more other creatures die,/i.test(line));
        if (!clause) continue;
        if (!dyingCreatures.some((death) => death.card.id !== source.id)) continue;
        const once = /\bthis ability triggers only once each turn\b/i.test(clause);
        const effect = commonTriggerEffect(clause.replace(/^whenever one or more other creatures die,\s*/i, "").replace(/\s*this ability triggers only once each turn\.?$/i, ""), "clause", undefined, seat);
        if (!effect) continue;
        if (triggers.some((existing) => existing.sourceCardId === source.id && existing.effect.kind === effect.kind && existing.message.includes("one or more"))) continue;
        triggers.push(makeCommonTrigger(seat.id, seat.id, source, once ? { ...effect, oncePerTurn: true } : effect, `${source.name} triggers because one or more other creatures died.`, dyingCreatures[0].card.id));
      }
    }
  }
  return triggers;
}

// A creature's own name in its rules text ("put a +1/+1 counter on Gorma", "you gain life equal to its power") read as "this creature", which is
// what the trigger parsers know how to resolve.
function selfNameAsThisCreature(card: VisibleCard): string {
  const names = [card.name, card.name.split(",")[0], card.name.split(" of ")[0]].filter((name, index, all) => name.length >= 4 && all.indexOf(name) === index).sort((a, b) => b.length - a.length);
  let text = card.oracleText;
  for (const name of names) {
    const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    text = text.replace(new RegExp(`\\b${escaped}(?![a-z])`, "g"), "this creature");
  }
  return text;
}

// Whether a sacrificed card fits "a creature / a black creature / a green creature / a Food / another permanent" in a "whenever you sacrifice ..." watcher.
function deathMatchesSacrificeSubject(card: VisibleCard, adjective: string | undefined, noun: string): boolean {
  if (noun === "creature" && !hasCardType(card, "Creature")) return false;
  if (noun === "artifact" && !hasCardType(card, "Artifact")) return false;
  if (noun === "land" && !hasCardType(card, "Land")) return false;
  if (noun === "food" && !/\bfood\b/i.test(card.typeLine)) return false;
  if (!adjective) return true;
  const colorLetter: Record<string, string> = { white: "W", blue: "U", black: "B", red: "R", green: "G" };
  if (colorLetter[adjective]) return (card.colors ?? []).includes(colorLetter[adjective]);
  if (adjective === "nontoken") return !card.token;
  return true;
}

// The effect of a "whenever you sacrifice ..." watcher: the shapes the common parser doesn't know about (Savra's pay-2-life edict) first.
function sacrificeWatcherEffect(effectText: string, controller: PlayerSeat): TriggerEffect | undefined {
  const once = /\bthis ability triggers only once each turn\.?$/i.test(effectText);
  const text = effectText.replace(/\s*this ability triggers only once each turn\.?$/i, "").trim();
  // "you may pay 2 life. If you do, each other player sacrifices a creature of their choice." (Savra)
  const payEdict = text.match(/^you may pay (\d+) life\. if you do, each other player sacrifices an? creature of their choice\.?$/i);
  if (payEdict) return { kind: "lose_life", amount: Number.parseInt(payEdict[1], 10), optional: true, then: { kind: "each_opponent_sacrifices", filter: "creature" } };
  // "you may gain 2 life." (Savra's green half)
  const mayGain = text.match(/^you may gain (\d+) life\.?$/i);
  if (mayGain) return { kind: "gain_life", amount: Number.parseInt(mayGain[1], 10), optional: true };
  const effect = commonTriggerEffect(text, "clause", undefined, controller);
  if (!effect) return undefined;
  return once ? { ...effect, oncePerTurn: true } : effect;
}

// "Whenever a Food is put into a graveyard from the battlefield, put two +1/+1 counters on Ygra." (Ygra, Eater of All): a watcher on ANY permanent of the
// named type (a creature counts when it has been made that type, and so do real Food tokens), whoever controls it. Separate from the "dies" scan above, which
// only reads the word "dies" and only looks at creatures.
export function findPutIntoGraveyardTriggers(session: GameSession, deadSeatId: string, deadCard: VisibleCard): Array<Extract<PendingAction, { type: "trigger" }>> {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const seat of session.seats) {
    for (const source of seat.board.battlefield) {
      if (source.abilitiesStripped || source.id === deadCard.id) continue;
      for (const clause of oracleClauses(selfNameAsThisCreature(source))) {
        const match = clause.match(/^whenever an? ([a-z]+) is put into a graveyard from the battlefield, (.+)$/i);
        if (!match) continue;
        const type = match[1].charAt(0).toUpperCase() + match[1].slice(1).toLowerCase();
        if (!hasCardType(deadCard, type)) continue;
        const effect = commonTriggerEffect(match[2], "clause", undefined, seat);
        if (effect) triggers.push(makeCommonTrigger(deadSeatId, seat.id, source, effect, `${source.name} triggers because ${deadCard.name} was put into a graveyard.`));
      }
    }
  }
  return triggers;
}

export function findCommonTriggersForPermanentDied(
  session: GameSession,
  deadSeatId: string,
  deadCard: VisibleCard,
  attachedSourceIds?: string[],
  // Rule 603.10/603.6d ("look back in time"): every OTHER creature that died in the same
  // simultaneous event (a board wipe, most commonly) must still be visible to a triggered ability
  // that died in that same event — a Meren of Clan Nel Toth who dies alongside 4 other creatures
  // to Crux of Fate still triggers once per OTHER creature that died, even though she's gone too.
  // Defaults to just this one death (the pre-existing behavior) for the one other call site that
  // evaluates a single death in isolation, outside a batched destroyCreatures pass.
  simultaneousDeaths: Array<{ seatId: string; card: VisibleCard }> = [{ seatId: deadSeatId, card: deadCard }]
): Array<Extract<PendingAction, { type: "trigger" }>> {
  if (!hasCardType(deadCard, "Creature")) return [];
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];

  for (const seat of session.seats) {
    const simultaneousDeathsForSeat = simultaneousDeaths.filter((death) => death.seatId === seat.id).map((death) => death.card);
    // An Aura that fell off with the creature is already in the graveyard, but its own "when enchanted creature dies" still triggers.
    const fallenAttachments = (seat.board.graveyard ?? []).filter((card) => attachedSourceIds?.includes(card.id));
    const sources = [...seat.board.battlefield, ...simultaneousDeathsForSeat, ...fallenAttachments];
    for (const source of sources) {
      // Felisa, Fang of Silverquill: "create X ... tokens, where X is the number of counters it had on it" counts counters of EVERY kind.
      // The watcher (Felisa) is a different permanent from the creature that died, so this applies to any source with that wording.
      const dynamicCounterCount = /\bnumber of counters it had on it\b/i.test(source.oracleText) ? (deadCard.counters ?? []).reduce((sum, counter) => sum + counter.count, 0) : source.id === deadCard.id ? plusOneCounterCount(deadCard) : undefined;
      const effect = modalDeathTriggerEffect(source) ?? commonTriggerEffect(selfNameAsThisCreature(source), "died", dynamicCounterCount);
      if (!effect || !deathTriggerApplies(source, seat.id, deadCard, deadSeatId, attachedSourceIds)) continue;
      const resolvedEffect: TriggerEffect = effect.kind === "gain_life_equal_power" ? { kind: "gain_life", amount: Math.max(0, effectivePower(source)) } : effect;
      triggers.push(makeCommonTrigger(deadSeatId, seat.id, source, resolvedEffect, `${source.name} triggers because ${deadCard.name} died.`));
    }
  }

  // Imprint — Mimic Vat: any seat's Vat reacts to a NONTOKEN creature dying (the dead card must be in a graveyard to be exiled).
  if (!deadCard.token) {
    for (const seat of session.seats) {
      for (const vat of seat.board.battlefield) {
        if (vat.abilitiesStripped || !/imprint\s*[—-]\s*whenever a nontoken creature dies, you may exile that card/i.test(vat.oracleText)) continue;
        triggers.push(makeCommonTrigger(deadSeatId, seat.id, vat, { kind: "imprint_dying_creature" }, `${vat.name} triggers because ${deadCard.name} died.`, deadCard.id));
      }
    }
  }

  // Undying / persist (printed or granted, e.g. by Mikaeus, the Unhallowed): checked against the counters it died with.
  const hadCounter = (kind: string) => (deadCard.counters ?? []).some((counter) => counter.kind === kind && counter.count > 0);
  const returnKind = hasKeyword(deadCard, "undying") && !hadCounter("+1/+1") ? "+1/+1" : hasKeyword(deadCard, "persist") && !hadCounter("-1/-1") ? "-1/-1" : undefined;
  if (returnKind && !deadCard.token) {
    const ownerSeatId = deadCard.ownerSeatId ?? deadSeatId;
    triggers.push(makeCommonTrigger(deadSeatId, ownerSeatId, deadCard, { kind: "undying_return", counterKind: returnKind }, `${deadCard.name} triggers (${returnKind === "+1/+1" ? "undying" : "persist"}).`));
  }

  // Dying is one way to leave the battlefield; the others (bounce, exile) arrive through pendingLeaves.
  triggers.push(...findLeavesBattlefieldTriggers(session, deadSeatId, deadCard));

  return triggers;
}

// "• Dragons — Whenever a creature you control leaves the battlefield, this enchantment deals 1 damage to any target." (Outpost Siege)
export function findLeavesBattlefieldTriggers(session: GameSession, leavingSeatId: string, leavingCard: VisibleCard): Array<Extract<PendingAction, { type: "trigger" }>> {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  const hadCounters = (leavingCard.counters ?? []).some((counter) => counter.count > 0);
  if (!leavingCard.typeLine.includes("Creature") && !hadCounters) return triggers;
  // Athreos, Shroud-Veiled: any seat's watcher reacts to a marked creature of ANY controller dying or being exiled.
  for (const seat of session.seats) {
    for (const watcher of seat.board.battlefield) {
      if (watcher.abilitiesStripped || watcher.id === leavingCard.id) continue;
      for (const clause of oracleClauses(watcher.oracleText)) {
        const marked = clause.match(/^whenever a creature with an? ([a-z+/-]+) counter on it dies or is put into exile, return that card to the battlefield under your control\.?$/i);
        if (!marked || !(leavingCard.counters ?? []).some((counter) => counter.kind.toLowerCase() === marked[1].toLowerCase() && counter.count > 0)) continue;
        triggers.push(makeCommonTrigger(leavingSeatId, seat.id, watcher, { kind: "return_marked_to_battlefield" }, `${watcher.name} triggers because ${leavingCard.name} left the battlefield.`, leavingCard.id));
      }
    }
  }
  const watcherSeat = session.seats.find((seat) => seat.id === leavingSeatId);
  for (const watcher of watcherSeat?.board.battlefield ?? []) {
    if (watcher.abilitiesStripped || watcher.id === leavingCard.id) continue;
    for (const clause of oracleClauses(watcher.oracleText)) {
      // "Whenever another permanent you control leaves the battlefield, if it had counters on it, investigate." (Angelic Sleuth)
      const withCounters = hadCounters ? clause.match(/^whenever another permanent you control leaves the battlefield, if it had counters on it, (.+)$/i) : null;
      if (withCounters) {
        const countersEffect = commonTriggerEffect(withCounters[1], "clause");
        if (countersEffect) triggers.push(makeCommonTrigger(leavingSeatId, leavingSeatId, watcher, countersEffect, watcher.name + " triggers because " + leavingCard.name + " left the battlefield."));
        continue;
      }
      if (!leavingCard.typeLine.includes("Creature")) continue;
      const match = clause.match(/^(?:[•*]\s*)?(?:([A-Za-z]+)\s*[—-]\s*)?whenever a creature you control leaves the battlefield, (.+)$/i);
      if (!match) continue;
      if (match[1] && !watcher.chosenMode) continue;
      if (match[1] && watcher.chosenMode && watcher.chosenMode.toLowerCase() !== match[1].toLowerCase()) continue;
      const leaveEffect = commonTriggerEffect(match[2], "clause");
      if (leaveEffect) triggers.push(makeCommonTrigger(leavingSeatId, leavingSeatId, watcher, leaveEffect, watcher.name + " triggers because " + leavingCard.name + " left the battlefield."));
    }
  }
  return triggers;
}

// "Whenever a creature you control deals combat damage to a player, ..." (Toski, Bearer of
// Secrets, ...) — scoped to just dealingSeatId's own battlefield since every real instance of this
// template is self-relative ("a creature YOU control"), unlike findCommonTriggersForPermanentDied's
// all-seats scan. See pendingCombatDamageToPlayer's own comment on GameSession for why this can't
// just be a generic phase trigger.
// Every "Whenever <subject> attacks" trigger caused by ONE declared attacker, on any seat's battlefield
// (the watcher can be the attacker itself, another of its controller's permanents, or the defending
// player's — Marchesa's Decree). `unparsed` lists attacker-side sources whose clause no deterministic
// parser understands, which the caller sends to the rules advisor as the old phase sweep did.
// Gives one specific creature keywords until end of turn (the human's pick for a "target creature gains ..." effect).
export function grantKeywordsToCreature(session: GameSession, seatId: string, cardId: string, keywords: string[], sourceName: string): GameSession {
  const owner = session.seats.find((seat) => seat.id === seatId);
  const target = owner?.board.battlefield.find((card) => card.id === cardId);
  if (!owner || !target) return session;
  return rulesEvent(
    {
      ...session,
      seats: session.seats.map((seat) =>
        seat.id !== seatId
          ? seat
          : {
              ...seat,
              board: {
                ...seat.board,
                battlefield: seat.board.battlefield.map((card) =>
                  card.id === cardId ? { ...card, temporaryGrantedKeywords: [...(card.temporaryGrantedKeywords ?? []), ...keywords], grantedKeywords: [...new Set([...(card.grantedKeywords ?? []), ...keywords])] } : card
                )
              }
            }
      )
    },
    seatId,
    sourceName + " gives " + target.name + " " + keywords.join(" and ") + " until end of turn."
  );
}

// "Whenever you gain life, ..." (Archangel of Thune, Exemplar of Light, Ajani's Pridemate) and "Whenever you gain life for the
// first time each turn, ..." (Vanguard Seraph). Only the source's controller gaining life counts. `firstThisTurn` is supplied by
// the caller, which is the one place that sees every gain.
export function findLifeGainTriggers(
  session: GameSession,
  gain: { seatId: string; amount: number; firstThisTurn: boolean }
): Array<Extract<PendingAction, { type: "trigger" }>> {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  const sourceSeat = session.seats.find((seat) => seat.id === gain.seatId);
  if (!sourceSeat || sourceSeat.hasLost || gain.amount <= 0) return triggers;
  for (const source of sourceSeat.board.battlefield) {
    if (source.abilitiesStripped) continue;
    for (const clause of oracleClauses(source.oracleText)) {
      if (isActivatedAbilityClause(clause)) continue;
      const match = clause.match(/^(?:when|whenever) you gain life( for the first time each turn)?,/i);
      if (!match) continue;
      if (match[1] && !gain.firstThisTurn) continue;
      const effect = commonTriggerEffect(clause, "clause", undefined, sourceSeat);
      if (effect) triggers.push(makeCommonTrigger(gain.seatId, gain.seatId, source, effect, `${source.name} triggers because ${sourceSeat.name} gained life.`));
    }
  }
  return triggers;
}

// Angel of Vitality: "If you would gain life, you gain that much life plus 1 instead." One extra life per such permanent.
export function lifeGainReplacementBonus(seat: PlayerSeat): number {
  return seat.board.battlefield.filter((card) => !card.abilitiesStripped && /\bif you would gain life, you gain that much life plus 1 instead\b/i.test(card.oracleText)).length;
}

// "Whenever you attack with two or more creatures, ..." for the attacker's own permanents, and "Whenever another player attacks with
// two or more creatures, they draw a card if none of those creatures attacked you." for everyone else's. `keys` are the
// once-each-turn markers the caller records so a later declaration in the same combat doesn't fire them again.
export function findMultiAttackTriggers(session: GameSession, attackerSeatId: string): { triggers: Array<Extract<PendingAction, { type: "trigger" }>>; keys: string[] } {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  const keys: string[] = [];
  const attacker = session.seats.find((seat) => seat.id === attackerSeatId);
  const attackers = attacker?.board.battlefield.filter((card) => card.attacking) ?? [];
  // "Whenever one or more Dragons you control attack, draw that many cards, then you may put a permanent card from your hand onto the
  // battlefield." (The Ur-Dragon): once per declaration, for the attacking creatures of that subtype.
  if (attacker) {
    for (const source of attacker.board.battlefield) {
      if (source.abilitiesStripped) continue;
      const clause = oracleClauses(source.oracleText).find((line) => /^whenever one or more [a-z]+s you control attack, draw that many cards, then you may put a permanent card from your hand onto the battlefield/i.test(line));
      const subtype = clause?.match(/^whenever one or more ([a-z]+)s you control attack/i)?.[1];
      const key = `${session.turn}:${source.id}:subtype_attack`;
      if (!clause || !subtype || session.onceEachTurnEffectsUsed?.includes(key)) continue;
      const count = attackers.filter((card) => permanentMatchesQualifier(card, subtype)).length;
      if (count === 0) continue;
      keys.push(key);
      triggers.push(makeCommonTrigger(attackerSeatId, attackerSeatId, source, { kind: "draw_then_permanent", amount: count }, `${source.name} triggers because ${count} ${subtype}${count === 1 ? "" : "s"} attacked.`));
    }
  }
  if (!attacker || attackers.length < 2) return { triggers, keys };
  for (const sourceSeat of session.seats) {
    if (sourceSeat.hasLost) continue;
    for (const source of sourceSeat.board.battlefield) {
      if (source.abilitiesStripped) continue;
      const key = `${session.turn}:${source.id}:multi_attack:${attackerSeatId}`;
      if (session.onceEachTurnEffectsUsed?.includes(key)) continue;
      for (const clause of oracleClauses(source.oracleText)) {
        if (sourceSeat.id === attackerSeatId) {
          const own = clause.match(/^whenever you attack with two or more creatures, (.+)$/i);
          const effect = own ? commonTriggerEffect(own[1], "clause", undefined, sourceSeat) : undefined;
          if (effect) {
            triggers.push(makeCommonTrigger(attackerSeatId, sourceSeat.id, source, effect, `${source.name} triggers because ${attacker.name} attacked with two or more creatures.`));
            keys.push(key);
          }
        } else if (/^whenever another player attacks with two or more creatures, they draw a card if none of those creatures attacked you\b/i.test(clause)) {
          keys.push(key);
          if (attackers.some((card) => card.attackTargetId === sourceSeat.id)) continue;
          triggers.push(makeCommonTrigger(attackerSeatId, sourceSeat.id, source, { kind: "actor_draws_cards", amount: 1 }, `${source.name} triggers because ${attacker.name} attacked with two or more creatures, none at ${sourceSeat.name}.`));
        }
      }
    }
  }
  return { triggers, keys };
}

export function findAttackTriggers(
  session: GameSession,
  attack: { seatId: string; card: VisibleCard; defendingSeatId: string },
  event: "attacks" | "blocks" = "attacks"
): { triggers: Array<Extract<PendingAction, { type: "trigger" }>>; unparsed: Array<{ seatId: string; source: VisibleCard }> } {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  const unparsed: Array<{ seatId: string; source: VisibleCard }> = [];
  for (const sourceSeat of session.seats) {
    if (sourceSeat.hasLost) continue;
    for (const source of sourceSeat.board.battlefield) {
      if (source.abilitiesStripped) continue;
      // Dethrone (Scourge of the Throne): attacking the player with the most life (or tied) puts a +1/+1 counter on the attacker.
      if (event === "attacks" && source.id === attack.card.id && hasKeywordText(source.oracleText, "dethrone")) {
        const defending = session.seats.find((seat) => seat.id === attack.defendingSeatId);
        if (defending && session.seats.filter((seat) => !seat.hasLost).every((seat) => defending.life >= seat.life)) {
          triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, { kind: "add_counter", counterKind: "+1/+1", amount: 1, scope: "self" }, `${source.name} triggers (dethrone).`, attack.card.id));
        }
      }
      if (event === "attacks" && source.id === attack.card.id && hasKeywordText(source.oracleText, "battle cry")) {
        triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, { kind: "battle_cry" }, `${source.name} triggers (battle cry).`, attack.card.id));
      }
      if (event === "attacks" && source.id === attack.card.id && hasKeywordText(source.oracleText, "melee")) {
        triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, { kind: "melee" }, `${source.name} triggers (melee).`, attack.card.id));
      }
      // Myriad: a token copy of the attacker for every opponent other than the defending player.
      if (event === "attacks" && source.id === attack.card.id && hasKeywordText(source.oracleText, "myriad")) {
        triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, { kind: "myriad", defendingSeatId: attack.defendingSeatId, optional: true }, `${source.name} triggers (myriad).`, attack.card.id));
      }
      // Martial Impetus: an Aura on the attacker — "Whenever enchanted creature attacks, each other creature that's attacking one of your opponents gets +1/+1 until end of turn."
      if (event === "attacks" && source.attachedToId === attack.card.id && /whenever enchanted creature attacks, each other creature that'?s attacking one of your opponents gets \+1\/\+1 until end of turn/i.test(source.oracleText)) {
        triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, { kind: "pump_other_attackers", power: 1, toughness: 1 }, `${source.name} triggers because ${attack.card.name} attacked.`, attack.card.id));
      }
      const sourceClauses = oracleClauses(source.oracleText);
      const dragonPing = /^whenever a creature attacks you or a planeswalker you control, each dragon you control deals 1 damage to that creature\.?$/i;
      if (event === "attacks" && attack.defendingSeatId === sourceSeat.id && sourceClauses.some((clause) => dragonPing.test(clause.replace(/\([^)]*\)/g, "").trim()))) {
        triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, { kind: "dragons_ping_attacker" }, `${source.name} triggers because ${attack.card.name} attacked.`, attack.card.id));
      }
      for (const [clauseIndex, clause] of sourceClauses.entries()) {
        if (dragonPing.test(clause.replace(/\([^)]*\)/g, "").trim())) continue;
        const eventPattern = event === "attacks" ? /\b(?:when|whenever)\b[^,.]*\battacks\b/i : /\b(?:when|whenever)\b[^,.]*\bblocks\b/i;
        if (isActivatedAbilityClause(clause) || !eventPattern.test(clause)) continue;
        // Myriad's reminder text ("Myriad (Whenever this creature attacks, ...)") is handled above by the keyword itself.
        if (/^(?:myriad|battle cry|melee)\b/i.test(clause)) continue;
        // Owned by declareAttack's own inline handling.
        if (isAttackTriggerAddManaClause(clause) || parseMetalcraftAttackDebuff(clause)) continue;
        // "Lieutenant — As long as you control your commander, this creature gets +2/+2 and has \"Whenever this
        // creature attacks, it deals 7 damage to target creature defending player controls.\"" (Tyrant's Familiar):
        // the trigger is the QUOTED ability, and only exists while you control your commander.
        let triggerClause = clause;
        if (/^lieutenant\b/i.test(clause)) {
          if (!sourceSeat.board.battlefield.some((permanent) => permanent.commander)) continue;
          const quoted = clause.match(/"([^"]+)"/);
          if (!quoted) continue;
          triggerClause = quoted[1];
        }
        // "Whenever this creature attacks, put a +1/+1 counter on it." — "it" is the attacker itself.
        if (/^(?:when|whenever) (?:this creature|[a-z',-]+) (?:attacks|blocks)\b/i.test(triggerClause) && source.id === attack.card.id) {
          triggerClause = triggerClause.replace(/\bon it\b/i, "on this creature");
        }
        const applies = matchWatcherSubject(triggerClause, event, {
          sourceId: source.id,
          sourceName: source.name,
          subject: attack.card,
          subjectIsControlledBySourceController: attack.seatId === sourceSeat.id,
          defendingPlayerIsSourceController: attack.defendingSeatId === sourceSeat.id
        });
        if (applies === false) continue;
        if (applies === undefined) {
          if (sourceSeat.id === attack.seatId && source.id === attack.card.id) unparsed.push({ seatId: sourceSeat.id, source });
          continue;
        }
        let effect = commonTriggerEffect(triggerClause, "clause", undefined, sourceSeat);
        // "..., choose one —" with the modes on the following bullet lines.
        if (!effect && /[—-]\s*$/.test(triggerClause)) {
          const bullets: string[] = [];
          for (const next of sourceClauses.slice(clauseIndex + 1)) {
            if (!/^[•*]/.test(next)) break;
            bullets.push(next);
          }
          const modal = parseGenericModalEffect([triggerClause, ...bullets].join("\n"), undefined);
          if (modal) effect = { kind: "modal", modal };
        }
        // "...attacks for the first time each turn, if it's attacking the player with the most life or tied for most life, ..."
        // (Scourge of the Throne): once per turn per source, and only against a player at the top of the life totals.
        if (/\bfor the first time each turn\b/i.test(triggerClause) && session.onceEachTurnEffectsUsed?.includes(`${session.turn}:${source.id}:first_attack`)) continue;
        if (/\bif it'?s attacking the player with the most life or tied for most life\b/i.test(triggerClause)) {
          const defending = session.seats.find((seat) => seat.id === attack.defendingSeatId);
          if (!defending || !session.seats.filter((seat) => !seat.hasLost).every((seat) => defending.life >= seat.life)) continue;
        }
        // "...attacks while you don't control another Dinosaur, ..." (Pugnacious Hammerskull)
        const noOtherOfType = triggerClause.match(/\bwhile you don'?t control another ([a-z]+)\b/i);
        if (effect && noOtherOfType) effect = { ...effect, condition: { kind: "controls_no_other", subtype: noOtherOfType[1] } };
        if (effect) {
          triggers.push(makeCommonTrigger(attack.seatId, sourceSeat.id, source, effect, `${source.name} triggers because ${attack.card.name} ${event === "attacks" ? "attacked" : "blocked"}.`, attack.card.id));
        } else if (sourceSeat.id === attack.seatId) {
          unparsed.push({ seatId: sourceSeat.id, source });
        }
      }
    }
  }
  return { triggers, unparsed };
}

export function findCombatDamageToPlayerTriggers(
  session: GameSession,
  dealingSeatId: string,
  dealingCard: VisibleCard,
  damagedSeatId?: string
): Array<Extract<PendingAction, { type: "trigger" }>> {
  if (!hasCardType(dealingCard, "Creature")) return [];
  const seat = session.seats.find((item) => item.id === dealingSeatId);
  if (!seat) return [];
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const source of seat.board.battlefield) {
    // Renown N (the keyword itself, with its own once-only rule) replaces whatever the reminder text would otherwise parse as.
    const renownMatch = source.id === dealingCard.id && !source.abilitiesStripped ? source.oracleText.match(/^renown (\d+)/im) : null;
    if (renownMatch) {
      if (!source.renowned) triggers.push(makeCommonTrigger(dealingSeatId, seat.id, source, { kind: "renown", amount: Number.parseInt(renownMatch[1], 10) }, `${source.name} triggers (renown).`));
      continue;
    }
    // "Whenever THIS creature deals combat damage to a player" (Liliana's Reaver) only applies to the source's
    // own damage; "a creature you control" (Toski) applies to any. This used to fire for every creature.
    const damageClause = oracleClauses(source.oracleText).find((clause) => /\b(?:when|whenever)\b[^,.]*\bdeals? combat damage to a player\b/i.test(clause));
    const damageSubject = damageClause?.toLowerCase().match(/\b(?:when|whenever)\s+(.+?)\s+deals? combat damage to a player/)?.[1]?.trim();
    // "Whenever an artifact creature you control deals combat damage..." / "one or more artifact creatures you control deal...": the dealer must be that kind.
    const subjectQualifier = damageSubject?.match(/^(?:an?|one or more) ([a-z]+) creatures? you control$/)?.[1];
    if (subjectQualifier && subjectQualifier !== "other") {
      const word = subjectQualifier.startsWith("non") ? subjectQualifier.slice(3) : subjectQualifier;
      const has = word === "token" ? Boolean(dealingCard.token) : hasCardType(dealingCard, capitalizeWord(word)) || dealingCard.typeLine.toLowerCase().includes(word);
      if (subjectQualifier.startsWith("non") ? has : !has) continue;
    }
    const shortName = source.name.toLowerCase().split(" // ")[0].split(",")[0].trim();
    if (damageSubject && (/^this\b/.test(damageSubject) || damageSubject === source.name.toLowerCase() || damageSubject === shortName) && source.id !== dealingCard.id) continue;
    // Old Gnawbone: "...deals combat damage to a player, create that many Treasure tokens." — the damage dealt is the creature's power here.
    if (/\bcreate that many treasure tokens\b/i.test(source.oracleText) && /\bwhenever a creature you control deals combat damage to a player\b/i.test(source.oracleText)) {
      const amount = Math.max(0, effectivePower(dealingCard));
      if (amount > 0) {
        triggers.push(makeCommonTrigger(dealingSeatId, seat.id, source, { kind: "create_tokens", tokens: [{ ...predefinedTokenSpec("Treasure"), count: amount }] }, `${source.name} triggers because ${dealingCard.name} dealt ${amount} combat damage to a player.`));
      }
      continue;
    }
    const rawEffect = commonTriggerEffect(source.oracleText, "combat_damage_to_player");
    const effect = rawEffect && rawEffect.then?.kind === "seat_discards" && damagedSeatId ? { ...rawEffect, then: { ...rawEffect.then, seatId: damagedSeatId } } : rawEffect;
    if (!effect) {
      // "Whenever one or more Dragons you control deal combat damage to an opponent, choose one that hasn't been chosen this turn —"
      // (Parapet Thrasher). The damaged player rides along as the trigger's actor so "each other opponent" can exclude them.
      const sourceClauses = oracleClauses(source.oracleText);
      // "Whenever Rankle deals combat damage to a player, choose any number —": the creature's own trigger.
      if (source.id === dealingCard.id) {
        const ownModal = modalClauseTriggerEffect(source, /^whenever [^,]+ deals combat damage to a player, choose (?:one or more|one or both|any number|up to (?:two|three)|one|two|three)\b.*[—-]\s*$/i);
        if (ownModal) {
          triggers.push(makeCommonTrigger(dealingSeatId, seat.id, source, ownModal, `${source.name} triggers because it dealt combat damage to a player.`));
          continue;
        }
      }
      const groupIndex = sourceClauses.findIndex((clause) => /^whenever one or more [a-z]+s you control deal combat damage to an opponent, choose one\b.*[—-]\s*$/i.test(clause));
      const groupSubject = groupIndex >= 0 ? sourceClauses[groupIndex].match(/^whenever one or more ([a-z]+)s you control/i)?.[1] : undefined;
      if (groupIndex >= 0 && groupSubject && permanentMatchesQualifier(dealingCard, groupSubject)) {
        const bullets: string[] = [];
        for (const next of sourceClauses.slice(groupIndex + 1)) {
          if (!/^[•*]/.test(next)) break;
          bullets.push(next);
        }
        const modal = parseGenericModalEffect([sourceClauses[groupIndex], ...bullets].join("\n"), undefined);
        if (modal) {
          triggers.push(makeCommonTrigger(damagedSeatId ?? dealingSeatId, seat.id, source, { kind: "modal", modal }, `${source.name} triggers because ${dealingCard.name} dealt combat damage to an opponent.`));
        }
      }
      continue;
    }
    triggers.push(makeCommonTrigger(dealingSeatId, seat.id, source, effect, `${source.name} triggers because ${dealingCard.name} dealt combat damage to a player.`));
  }
  return triggers;
}

// "Whenever a creature deals combat damage to one of your opponents, its controller may pay 1
// life. If they do, they draw a card." (Gix, Yawgmoth Praetor) — a fully separate, narrow parser
// rather than reusing isCombatDamageToPlayerClause/combatDamageToPlayerEffectText above: that
// matcher requires the literal substring "deals combat damage to a player", which Gix's real text
// ("...to one of your opponents") never contains, so the two shapes can't accidentally double-fire
// off the same clause. Only the exact "pay N life, draw M cards" payoff is recognized; a card with
// this same trigger condition but a different payoff would need its own extension here.
export function parseAnyCreatureCombatDamageToOpponentTrigger(oracleText: string): { lifeCost: number; drawAmount: number } | undefined {
  const clause = oracleClauses(oracleText).find((item) => /^whenever a creature deals combat damage to (?:one of your opponents|an opponent)\b/i.test(item));
  if (!clause) return undefined;
  const match = clause.match(/its controller may pay (\d+) life\.\s*if they do,\s*(?:they draw|draw)\s+(a|one|two|three|four|five|\d+)\s+cards?\b/i);
  if (!match) return undefined;
  const drawAmount = numberWordToInt(match[2]);
  if (!drawAmount) return undefined;
  return { lifeCost: Number.parseInt(match[1], 10), drawAmount };
}

// Gix, Yawgmoth Praetor's trigger is symmetric and board-wide: it watches ANY creature (controlled
// by anyone) dealing combat damage, and only cares whether the DAMAGED player is an opponent of the
// WATCHING seat — completely independent of who controls the attacker. findCombatDamageToPlayerTriggers
// just above is structurally blind to this shape (it only ever scans the dealing creature's own
// controller's battlefield, matching every OTHER real card's self-relative "a creature YOU control"
// wording), so this is its own all-seats scan instead of a case inside that function. The effect
// applies to actorSeatId (the ATTACKING creature's controller — "its controller," not Gix's own),
// which is why this creates an "actor_may_pay_life_to_draw" trigger instead of any of the generic
// kinds above (see that kind's own doc comment for why). Reported live as Gix simply never firing.
export function findAnyCombatDamageToOpponentTriggers(
  session: GameSession,
  dealingSeatId: string,
  dealingCard: VisibleCard,
  damagedSeatId: string
): Array<Extract<PendingAction, { type: "trigger" }>> {
  if (!hasCardType(dealingCard, "Creature")) return [];
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const seat of session.seats) {
    // This app models free-for-all only (no teams) — any other seat is, by definition, an opponent
    // of the watcher, same "every other seat counts as an opponent" convention actionScoring.ts's
    // opponentBattlefields already uses. A watcher can't be triggered by damage dealt to its OWN
    // controller (not an opponent of themselves).
    if (seat.hasLost || seat.id === damagedSeatId) continue;
    for (const source of seat.board.battlefield) {
      const parsed = parseAnyCreatureCombatDamageToOpponentTrigger(source.oracleText);
      if (!parsed) continue;
      triggers.push(
        makeCommonTrigger(
          dealingSeatId,
          seat.id,
          source,
          { kind: "actor_may_pay_life_to_draw", lifeCost: parsed.lifeCost, drawAmount: parsed.drawAmount },
          `${source.name} triggers because ${dealingCard.name} dealt combat damage to an opponent.`
        )
      );
    }
  }
  return triggers;
}

// "Whenever a player attacks one of your opponents, if that opponent has more life than another of
// your opponents, that attacking player draws a card and you put two +1/+1 counters on a creature
// you control." (Breena, the Demagogue) — a fully separate parser from the "whenever you attack a
// player" self-relative shape declareAttack already handles inline: that one only ever scans the
// ATTACKING creature's own controller's battlefield, but Breena watches ANY player's attack against
// ANY of her own controller's opponents, independent of who's attacking. Only the exact "draws a
// card... put N +1/+1 counters on a creature you control" payoff is recognized.
export function parseBreenaAttackTrigger(oracleText: string): { drawAmount: number; counterAmount: number } | undefined {
  const clause = oracleClauses(oracleText).find((item) =>
    /^whenever a player attacks one of your opponents, if that opponent has more life than another of your opponents,/i.test(item)
  );
  if (!clause) return undefined;
  const match = clause.match(/that attacking player draws (a|one|two|three|four|five|\d+) cards?[\s\S]*?you put (a|one|two|three|four|five|\d+) \+1\/\+1 counters? on a creature you control\b/i);
  if (!match) return undefined;
  const drawAmount = numberWordToInt(match[1]);
  const counterAmount = numberWordToInt(match[2]);
  if (!drawAmount || !counterAmount) return undefined;
  return { drawAmount, counterAmount };
}

// Board-wide scan (a sibling to findAnyCombatDamageToOpponentTriggers's own board-wide shape, for
// the same "symmetric, third-party-beneficial trigger" reason) — called once per attack declared
// (from declareAttack, which already knows the attacking seat and the defending seat at the exact
// moment of declaration), checking every OTHER seat's battlefield for a Breena-shaped watcher.
// "if that opponent has more life than another of your opponents" is a genuine multi-seat life
// comparison relative to the WATCHING seat, not the attacker: it only holds when the defending seat
// has strictly more life than at least one OTHER opponent of the watcher (a seat that is neither the
// watcher nor the defender). A watcher with only one opponent total can never satisfy this — there's
// no "another" to compare against. Reported live as Breena never doing anything at all.
export function findBreenaAttackTriggers(session: GameSession, attackingSeatId: string, defendingSeatId: string): Array<Extract<PendingAction, { type: "trigger" }>> {
  const defendingSeat = session.seats.find((seat) => seat.id === defendingSeatId);
  if (!defendingSeat) return [];
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const seat of session.seats) {
    if (seat.hasLost || seat.id === defendingSeatId) continue;
    const hasLowerLifeOtherOpponent = session.seats.some(
      (other) => !other.hasLost && other.id !== seat.id && other.id !== defendingSeatId && other.life < defendingSeat.life
    );
    if (!hasLowerLifeOtherOpponent) continue;
    for (const source of seat.board.battlefield) {
      const parsed = parseBreenaAttackTrigger(source.oracleText);
      if (!parsed) continue;
      triggers.push(
        makeCommonTrigger(
          attackingSeatId,
          seat.id,
          source,
          {
            kind: "actor_draws_cards",
            amount: parsed.drawAmount,
            then: { kind: "add_counter", counterKind: "+1/+1", amount: parsed.counterAmount, scope: "target_creature_you_control" }
          },
          `${source.name} triggers because a player attacked ${defendingSeat.name}, who has more life than another of ${seat.name}'s opponents.`
        )
      );
    }
  }
  return triggers;
}

// "Whenever one or more cards leave your graveyard, ..." (Willow Geist, Insidious Roots) — scans
// only the GRAVEYARD OWNER'S OWN battlefield (the text says "your graveyard," so the watching
// permanent's controller must be the graveyard's own owner, not whoever caused the departure).
export function findCardsLeftGraveyardTriggers(session: GameSession, graveyardSeatId: string): Array<Extract<PendingAction, { type: "trigger" }>> {
  const seat = session.seats.find((item) => item.id === graveyardSeatId);
  if (!seat) return [];
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  for (const source of seat.board.battlefield) {
    const effect = commonTriggerEffect(source.oracleText, "cards_left_graveyard");
    if (!effect) continue;
    triggers.push(makeCommonTrigger(graveyardSeatId, seat.id, source, effect, `${source.name} triggers because one or more cards left ${seat.name}'s graveyard.`));
  }
  return triggers;
}

interface CastTriggerCondition {
  // Relative to the permanent's own controller — "you" only fires when its controller is the
  // caster, "opponent" only fires when the caster is a different seat, "any" (Ledger Shredder's
  // "whenever A PLAYER casts...") fires regardless of who cast it, mirroring how real oracle text is
  // always written relative to whoever controls the triggered ability, not any fixed seat.
  relativity: "you" | "opponent" | "any";
  // "their first spell"/"their second spell"/etc — undefined means no ordinal restriction at all
  // ("whenever you cast a spell,"). 1 for "first", 2 for "second", and so on.
  requiredOrdinal?: number;
  spellTypeFilter?: "noncreature" | "instant_or_sorcery" | "enchantment" | "artifact" | "creature" | "planeswalker" | "land" | "historic";
  // Any other descriptor word before "spell" — a creature subtype ("Zombie spell", Diregraf Colossus) or color,
  // matched with the shared qualifier matcher.
  spellDescriptor?: string;
  // "noncreature or Dragon spell" (Firespitter Whelp): also matches this descriptor (the type filter above is then "noncreature").
  alsoDescriptor?: string;
  effectClause: string;
}

const ORDINAL_WORDS: Record<string, number> = { first: 1, second: 2, third: 3, fourth: 4, fifth: 5 };

// "Whenever you cast a[n] [type] spell, ..." / "Whenever an opponent casts their first spell each
// turn, ..." / "Whenever an opponent casts their second spell each turn, ..." (Shark Typhoon,
// Murmuring Mystic, Mind's Dilation, Monologue Tax, ...) — a whole category of triggered abilities
// keyed to a spell being cast, distinct from the phase-triggered and ETB/death triggers this engine
// already models. "you"/"an opponent" is read relative to whichever seat controls the permanent
// bearing this text (checked by the caller against the actual caster), not hardcoded to any fixed
// player. The type-word list isn't exhaustive of every possible card type, just every one actually
// seen in this codebase's card pool so far (noncreature/instant-or-sorcery/enchantment/artifact/
// creature/planeswalker/land) — declined rather than guessed at for anything else, same as every
// other parser here.
const CAST_TRIGGER_PATTERN =
  /^whenever (you cast|an opponent casts|a player casts) (?:an?|(?:your|their) (first|second|third|fourth|fifth))\s*((?:instant or sorcery|noncreature or [a-z]+|[a-z]+)\s+)?spells?(?: each turn)?,\s*(.+)$/i;

function parseCastTriggerCondition(clause: string): CastTriggerCondition | undefined {
  const match = clause.match(CAST_TRIGGER_PATTERN);
  if (!match) return undefined;
  const relativity = /^you/i.test(match[1]) ? "you" : /^a player/i.test(match[1]) ? "any" : "opponent";
  const requiredOrdinal = match[2] ? ORDINAL_WORDS[match[2].toLowerCase()] : undefined;
  const typeWord = match[3]?.trim().toLowerCase();
  const orMatch = typeWord?.match(/^noncreature or ([a-z]+)$/);
  if (orMatch) return { relativity, requiredOrdinal, spellTypeFilter: "noncreature", alsoDescriptor: orMatch[1], effectClause: match[4].trim() };
  const spellTypeFilter =
    typeWord === "noncreature" ||
    typeWord === "enchantment" ||
    typeWord === "artifact" ||
    typeWord === "creature" ||
    typeWord === "planeswalker" ||
    typeWord === "land" ||
    typeWord === "historic"
      ? typeWord
      : typeWord === "instant or sorcery"
        ? "instant_or_sorcery"
        : undefined;
  const spellDescriptor = typeWord && !spellTypeFilter && typeWord !== "instant or sorcery" ? typeWord : undefined;
  return { relativity, requiredOrdinal, spellTypeFilter, spellDescriptor, effectClause: match[4].trim() };
}

function spellMatchesCastTriggerFilter(card: VisibleCard, filter: CastTriggerCondition["spellTypeFilter"]): boolean {
  if (filter === "noncreature") return !card.typeLine.includes("Creature");
  if (filter === "instant_or_sorcery") return card.typeLine.includes("Instant") || card.typeLine.includes("Sorcery");
  if (filter === "enchantment") return card.typeLine.includes("Enchantment");
  if (filter === "artifact") return card.typeLine.includes("Artifact");
  if (filter === "creature") return card.typeLine.includes("Creature");
  if (filter === "planeswalker") return card.typeLine.includes("Planeswalker");
  if (filter === "land") return card.typeLine.includes("Land");
  // Historic (Jhoira): artifacts, legendaries and Sagas.
  if (filter === "historic") return hasCardType(card, "Artifact") || card.typeLine.includes("Legendary") || card.typeLine.includes("Saga");
  return true;
}

// "Exile the top card of [that player]'s library. Until end of turn, you may cast that card
// without paying its mana cost if it's a nonland card." (an imperative-mood impulse-draw card) /
// "...that player exiles the top card of their library. If it's a nonland card, you may cast it
// without paying its mana cost." (Mind's Dilation's own third-person phrasing, since it's "that
// player" — the opponent whose spell triggered it — doing the exiling, not "you") — cross-seat and
// cost-waiving in a way no generic TriggerEffect models (see the "impulse_cast_free" kind's own
// comment), so it's detected as its own bespoke shape rather than folded into the generic parsers.
// "exiles?" tolerates both verb conjugations; matching only the imperative "exile" left Mind's
// Dilation's trigger never recognized at all, reported live as it "not triggering."
function isImpulseCastFreeEffectClause(clause: string): boolean {
  return /\bexiles? the top card of (their|your) library\b/i.test(clause) && /\bwithout paying its mana cost\b/i.test(clause) && /\bnonland\b/i.test(clause);
}

export function findCastTriggers(
  session: GameSession,
  casterSeatId: string,
  castCard: VisibleCard,
  castOrdinalThisTurnForCaster: number
): Array<Extract<PendingAction, { type: "trigger" }>> {
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];

  for (const seat of session.seats) {
    for (const source of seat.board.battlefield) {
      for (const clause of oracleClauses(source.oracleText)) {
        if (isActivatedAbilityClause(clause)) continue;
        const condition = parseCastTriggerCondition(clause);
        if (!condition) continue;
        if (condition.relativity === "you" && seat.id !== casterSeatId) continue;
        if (condition.relativity === "opponent" && seat.id === casterSeatId) continue;
        if (condition.requiredOrdinal !== undefined && condition.requiredOrdinal !== castOrdinalThisTurnForCaster) continue;
        const matchesFilter = spellMatchesCastTriggerFilter(castCard, condition.spellTypeFilter);
        const matchesAlso = condition.alsoDescriptor ? permanentMatchesQualifier(castCard, condition.alsoDescriptor) : false;
        if (!matchesFilter && !matchesAlso) continue;
        if (condition.spellDescriptor && !permanentMatchesQualifier(castCard, condition.spellDescriptor)) continue;
        // "... unless that player pays {N}." (Mystic Remora, Esper Sentinel, ...) is a tax-
        // conditional effect this generic scan has no way to model — the tax itself is dropped, same
        // simplification as everywhere else in this codebase that models a cost as "always paid" or
        // "never paid" rather than as a real choice (see e.g. Gix, Yawgmoth Praetor's own "may pay
        // life" resolution nearby). This USED TO be deferred entirely to a separate function
        // (findTriggeredAbilityForSpell) that ran at the triggering SPELL'S OWN RESOLUTION time
        // instead of at cast time — which meant the trigger only ever fired if the spell that caused
        // it actually resolved. A triggered ability is its own independent object on the stack the
        // instant it triggers (rule 603.3b): countering the spell that caused it doesn't cancel it.
        // Since a countered spell's own resolvePendingAction is never reached at all (it's removed
        // from the stack directly inside the COUNTERING spell's resolution instead), that deferred
        // check never ran, and the trigger silently never fired. Reported live as Esper Sentinel not
        // triggering off an opponent's Grave Pact once the human Countered it. Handled here instead,
        // at the correct (cast) time, so it goes through the exact same commonTriggerEffect fall-
        // through as every other cast trigger below — "draw a card" is still all commonTriggerEffect
        // ever extracts from this clause, so the amount is unaffected; only the TIMING changed.

        if (isImpulseCastFreeEffectClause(condition.effectClause)) {
          triggers.push(
            makeCommonTrigger(casterSeatId, seat.id, source, { kind: "impulse_cast_free", fromSeatId: casterSeatId }, `${source.name} triggers because ${castCard.name} was cast.`)
          );
          continue;
        }

        // "X" in the effect text (Shark Typhoon's "create an X/X ... token, where X is that
        // spell's mana value") means the just-cast spell's own mana value, resolved here since only
        // this scan actually knows which spell was cast — commonTriggerEffect's parsers have no
        // other way to learn it. "A number of ... counters equal to that spell's mana value" (Dusty
        // Parlor) is the same idea spelled out in full instead of abbreviated to a bare "X" — resolved
        // the same way, before the counter-count parser (which only understands a literal number
        // word/digit) ever sees it.
        const effect = commonTriggerEffect(
          substituteManaValueCount(substituteX(condition.effectClause, castCard.manaValue), castCard.manaValue),
          "clause"
        );
        if (!effect) continue;
        triggers.push(makeCommonTrigger(casterSeatId, seat.id, source, effect, `${source.name} triggers because ${castCard.name} was cast.`));
      }
    }
  }

  return triggers;
}

function deathTriggerApplies(source: VisibleCard, sourceSeatId: string, deadCard: VisibleCard, deadSeatId: string, attachedSourceIds?: string[]) {
  const text = source.oracleText.toLowerCase();
  if (!text.includes("dies")) return false;
  // See enteredTriggerApplies: structured subject first (Headless Rider, Midnight Reaper, Open the
  // Graves, Undead Augur, Vengeful Dead — "nontoken", "Zombie", "this creature or another ..."), old
  // heuristics only for clauses it declines.
  const parsedSubject = matchWatcherSubject(source.oracleText, "dies", {
    sourceId: source.id,
    sourceName: source.name,
    subject: deadCard,
    subjectIsControlledBySourceController: deadSeatId === sourceSeatId
  });
  if (parsedSubject !== undefined) return parsedSubject;
  const underYourControl = deadSeatId === sourceSeatId;
  const isAnother = source.id !== deadCard.id;

  // "Whenever this creature or another creature dies, ..." (Blood Artist, and the same
  // aristocrats-drain shape on several other cards) — self-OR-other in one clause, meaning it
  // always applies regardless of whose death it was. Checked before the self-only branch right
  // below (which starts with the same "this ... dies" prefix and would otherwise misread this as
  // self-only, since it has no way to see the "or another" that follows) and before the
  // "another creature dies" branch further down (which would otherwise misread it as other-only
  // and exclude the source's own death) — reported live as Blood Artist never triggering off
  // another creature's death, only its own.
  if (/\b(?:when|whenever)\s+this\b(?:\s+[a-z]+){0,3}\s+or another\b(?:\s+[a-z]+){0,3}\s+dies\b/.test(text)) {
    return text.includes("you control") ? underYourControl : true;
  }

  // Same self-referential-clause fix as enteredTriggerApplies, and for the same reason: "when this
  // creature dies, draw a card" must not also fire when a DIFFERENT creature dies just because the
  // text contains the substring "creature dies".
  if (/\b(when|whenever)\s+this\b.{0,30}\bdies\b/.test(text)) return source.id === deadCard.id;

  // "Whenever equipped/enchanted creature dies, ..." (Skullclamp, ...) refers to whichever specific
  // creature THIS Equipment/Aura was actually attached to — checked before the generic "creature ...
  // dies" fallback below, which would otherwise match the substring "creature dies" inside "equipped
  // creature dies" and fire for every death on the board regardless of whether that creature was ever
  // actually equipped/enchanted by this one. Uses the attachedSourceIds snapshot captured at the
  // moment of death (destroyCreatures), not the live attachedToId — by the time this runs, the same
  // state-based-action pass that recorded the death has already cleared attachedToId on any Equipment
  // whose target is no longer on the battlefield, so the live value is always already gone.
  if (/\b(?:when|whenever)\b(?:(?!\.).){0,30}\b(?:equipped|enchanted) creature dies\b/.test(text)) {
    return attachedSourceIds?.includes(source.id) ?? false;
  }

  // Same "when/whenever must actually precede the phrase" fix as enteredTriggerApplies, and for the
  // same reason: a plain `.includes("creature dies")` also matches non-trigger text that happens to
  // contain that substring anywhere on the card, not just inside an actual "whenever ... dies" clause.
  // "another" tolerates 0-2 qualifier words before "creature" (Grim Haruspex's real text is
  // "another NONTOKEN creature you control dies" — without this, the extra word broke the match
  // entirely, silently falling through to the unqualified "creature ... dies" branch below, which
  // has no self-exclusion at all and let Grim Haruspex's own death satisfy its own "another creature"
  // trigger — the exact bug this fixes).
  // Massacre Wurm: "Whenever a creature an opponent controls dies, ..." fires for every other seat's creatures, never the controller's own.
  if (/\b(?:when|whenever)\b(?:(?!\.).){0,40}\bcreatures? an opponent controls dies\b/.test(text)) return deadSeatId !== sourceSeatId;
  if (/\b(?:when|whenever)\b(?:(?!\.).){0,60}\banother(?:\s+[a-z]+){0,2}\s+creature(?: you control)? dies\b/.test(text)) {
    if (!isAnother) return false;
    return text.includes("you control") ? underYourControl : true;
  }
  if (/\b(?:when|whenever)\b(?:(?!\.).){0,60}\bcreature(?: you control)? dies\b/.test(text)) {
    return text.includes("you control") ? underYourControl : true;
  }
  return false;
}

// "Activate only as a sorcery." (Heliod, the Radiant Dawn's transform ability, and the general rule
// 602.3a templating for any activated ability restricted to sorcery speed) — same generic-limiter
// shape as hasOnceEachTurnLimiter above, checked against legalActivatedAbilityActions' existing
// sorcerySpeedAllowed parameter (already used for equip/loyalty) rather than adding a parallel gate.
function hasSorcerySpeedOnlyLimiter(clause: string): boolean {
  return /\bactivate only as a sorcery\b|\band only as a sorcery\b/i.test(clause);
}

// Pure half of cycling: pays with untapped mana sources, discards the card, draws one.
// Razorlash Transmogrant: pay the (possibly discounted) cost and return the card from the graveyard to the battlefield.
export function activateGraveyardReturnInSession(session: GameSession, seatId: string, cardId: string): { ok: true; session: GameSession } | { ok: false; message: string } {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = (seat?.board.graveyard ?? []).find((item) => item.id === cardId);
  if (!seat || !card) return { ok: false, message: "That card isn't in your graveyard." };
  const ability = parseGraveyardReturnAbility(card.oracleText);
  if (!ability) return { ok: false, message: `${card.name} has no ability that works from the graveyard.` };
  const nonbasic = (other: PlayerSeat) => other.board.battlefield.filter((permanent) => permanent.typeLine.includes("Land") && !permanent.typeLine.includes("Basic")).length;
  const discounted = ability.discount ? session.seats.some((other) => other.id !== seatId && !other.hasLost && nonbasic(other) >= ability.discount!.nonbasicLands) : false;
  const costText = discounted && ability.discount ? reduceGenericCost(ability.costManaText, ability.discount.amount) : ability.costManaText;
  const total = manaValueFromManaCost(costText);
  const payment = chooseManaSourcesForCost(seat, genericManaAbilityCostShim({ costManaText: costText }), total, undefined, session.seats);
  if (!payment.ok) return { ok: false, message: `${seat.name} can't pay ${costText || "{0}"} to return ${card.name}.` };
  const paid: GameSession = { ...session, seats: session.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  const moved = moveCardAcrossSeats(paid, seatId, cardId, seatId, "battlefield");
  if (!moved.movedCard) return { ok: false, message: `${card.name} couldn't be returned.` };
  const withCounter: GameSession = ability.withCounter
    ? {
        ...moved.session,
        seats: moved.session.seats.map((item) =>
          item.id !== seatId ? item : { ...item, board: { ...item.board, battlefield: item.board.battlefield.map((permanent) => (permanent.id === cardId ? applyCounterDelta(permanent, "+1/+1", 1) : permanent)) } }
        )
      }
    : moved.session;
  return { ok: true, session: rulesEvent(withCounter, seatId, `${seat.name} pays ${costText || "{0}"} and returns ${card.name} from the graveyard to the battlefield${ability.withCounter ? " with a +1/+1 counter" : ""}.`) };
}

export function cycleCardInSession(session: GameSession, seatId: string, cardId: string, options?: { skipSearch?: boolean }): { ok: true; session: GameSession } | { ok: false; message: string } {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.hand.find((item) => item.id === cardId);
  if (!seat || !card) return { ok: false, message: "That card isn't in your hand." };
  const cycling = parseCycling(card.oracleText);
  if (!cycling) return { ok: false, message: `${card.name} doesn't have cycling.` };
  // "Cycling {X}{1}{U}" (Shark Typhoon): X is the most the seat can afford beyond the fixed part.
  const fixedCostText = cycling.costManaText.replace(/\{X\}/gi, "");
  const hasX = /\{X\}/i.test(cycling.costManaText);
  const fixedTotal = manaValueFromManaCost(fixedCostText);
  let cycleX = 0;
  if (hasX) {
    for (let x = 12; x >= 0; x -= 1) {
      if (chooseManaSourcesForCost(seat, genericManaAbilityCostShim({ costManaText: fixedCostText }), fixedTotal + x, undefined, session.seats).ok) {
        cycleX = x;
        break;
      }
    }
  }
  const total = fixedTotal + cycleX;
  const payment = chooseManaSourcesForCost(seat, genericManaAbilityCostShim({ costManaText: fixedCostText }), total, undefined, session.seats);
  if (!payment.ok) return { ok: false, message: `${seat.name} can't pay ${cycling.costManaText} to cycle ${card.name}.` };
  const paid: GameSession = { ...session, seats: session.seats.map((item) => (item.id === seatId ? spendManaSources(item, payment.sourceIds) : item)) };
  const discarded = moveCardBetweenVisibleZones(paid, seatId, cardId, "graveyard");
  let withEvent = rulesEvent(discarded, seatId, `${seat.name} cycles ${card.name} (${cycling.costManaText}${hasX ? `, X=${cycleX}` : ""}).`);
  // "When you cycle this card, create an X/X blue Shark creature token with flying." (Shark Typhoon)
  const cycleToken = card.oracleText.match(/when you cycle this card, create an x\/x ([a-z ]+?) creature token with flying/i);
  if (cycleToken) {
    withEvent = createTokensForSeat(withEvent, seatId, card.id, [{ count: 1, name: "Shark Token", colors: ["U"], typeLine: "Token Creature - Shark", power: String(cycleX), toughness: String(cycleX), oracleText: "Flying", role: "creature" }]).session;
  }
  // A human picks the card to fetch themselves (the caller opens the library search): pay and discard only.
  if (cycling.searchType && options?.skipSearch) return { ok: true, session: withEvent };
  if (cycling.searchType) {
    // Plainscycling and friends: fetch the first matching card (basic only for "basic landcycling") and shuffle.
    const wanted = cycling.searchType;
    const found = (seat.library ?? []).find((candidate) => candidate.typeLine.includes(wanted) && (!cycling.basicOnly || candidate.typeLine.includes("Basic")));
    if (!found) {
      const shuffled = { ...withEvent, seats: withEvent.seats.map((item) => (item.id === seatId ? { ...item, library: shuffleCards(item.library ?? []) } : item)) };
      return { ok: true, session: rulesEvent(shuffled, seatId, `${seat.name} finds no ${wanted} card.`) };
    }
    const fetched = moveLibraryCardToDestination(withEvent, seatId, found.id, "hand", false);
    const shuffled = { ...fetched, seats: fetched.seats.map((item) => (item.id === seatId ? { ...item, library: shuffleCards(item.library ?? []) } : item)) };
    return { ok: true, session: rulesEvent(shuffled, seatId, `${seat.name} searches for ${found.name} with ${card.name}'s ${wanted.toLowerCase()}cycling and puts it into their hand.`) };
  }
  return { ok: true, session: drawForSeat(withEvent, seatId, `${seat.name} draws a card from cycling ${card.name}.`) };
}

// "Tap three untapped Zombies you control" — the weakest eligible creatures, so the best stay untapped. Undefined when there aren't enough.
// "Tap N untapped <things> you control" as a cost (Cryptbreaker's Zombies, Shimmer Dragon's and Whirler Rogue's artifacts, ...): artifacts/lands/enchantments need not be creatures,
// and being summoning sick never matters (it is not a {T} cost of the permanent itself).
function canTapForCost(card: VisibleCard, subtype: string): boolean {
  const nonCreatureKind = /^(?:artifacts?|enchantments?|lands?|permanents?|planeswalkers?)$/i.test(subtype.trim());
  return !card.tapped && !card.phasedOut && (nonCreatureKind || card.typeLine.includes("Creature")) && permanentMatchesQualifier(card, subtype);
}

function chooseCreaturesToTapForCost(seat: PlayerSeat, count: number, subtype: string): VisibleCard[] | undefined {
  const eligible = seat.board.battlefield
    .filter((card) => canTapForCost(card, subtype))
    .sort((a, b) => effectivePower(a) - effectivePower(b));
  return eligible.length >= count ? eligible.slice(0, count) : undefined;
}

// Sephara-style "pay {W} and tap four flyers": the cost and which creatures would be tapped, when that many untapped ones exist.
export function tapCreaturesAltCostFor(seat: PlayerSeat, card: VisibleCard): { costManaText: string; count: number; withKeyword?: string; creatureIds: string[] } | undefined {
  const alt = parseTapCreaturesAltCost(card.oracleText);
  if (!alt) return undefined;
  const creatures = seat.board.battlefield
    .filter((permanent) => permanent.typeLine.includes("Creature") && !permanent.tapped && !permanent.phasedOut && permanent.id !== card.id && (!alt.withKeyword || hasKeyword(permanent, alt.withKeyword)))
    .sort((a, b) => effectivePower(a) - effectivePower(b));
  return creatures.length >= alt.count ? { ...alt, creatureIds: creatures.map((permanent) => permanent.id) } : undefined;
}

// "...the number of colors in your commanders' color identity" (War Room).
function commanderColorCount(seat: PlayerSeat): number {
  const commanders = [...seat.board.battlefield.filter((card) => card.commander), ...(seat.board.commander ? [seat.board.commander] : [])];
  return new Set(commanders.flatMap((card) => card.colorIdentity ?? card.colors ?? [])).size;
}

// "You may look at an additional two cards each time you surveil." (Enhanced Surveillance) — a
// static bonus to every surveil the controller does, from any source, not just this card's own.
// Narrow to this exact wording, matching this file's other single-card parsers; scry is a distinct
// action this doesn't touch.
function surveilCountBonus(oracleText: string): number {
  const match = oracleText.match(/\byou may look at an additional (\d+|a|one|two|three|four|five) cards? each time you surveil\b/i);
  return match ? numberWordToInt(match[1]) ?? 0 : 0;
}

function surveilBonusForSeat(seat: PlayerSeat): number {
  return seat.board.battlefield.reduce((total, card) => total + surveilCountBonus(card.oracleText), 0);
}

// "an opponent was dealt 7 or more damage this turn" (Spinerock Knoll): any damage from any source to any one of the controller's opponents.
export function hideawayDamageConditionMet(session: GameSession, controllerSeatId: string, conditionText: string): boolean | undefined {
  // Shelldock Isle: "a library has twenty or fewer cards in it" (any player's). Howltooth Hollow: "each player has no cards in hand".
  const libraryMatch = conditionText.match(/^a library has (\d+|twenty) or fewer cards in it$/);
  if (libraryMatch) {
    const limit = libraryMatch[1] === "twenty" ? 20 : Number.parseInt(libraryMatch[1], 10);
    return session.seats.some((seat) => !seat.hasLost && (seat.library?.length ?? seat.zones.library) <= limit);
  }
  if (conditionText === "each player has no cards in hand") return session.seats.every((seat) => seat.hasLost || seat.board.hand.length === 0);
  const match = conditionText.match(/^an opponent was dealt (\d+) or more damage this turn$/);
  if (!match) return undefined;
  const needed = Number.parseInt(match[1], 10);
  if (session.damageThisTurn?.turn !== session.turn) return false;
  return Object.entries(session.damageThisTurn.bySeat).some(([seatId, dealt]) => seatId !== controllerSeatId && dealt >= needed);
}

export function applyDigPick(session: GameSession, seatId: string, sourceName: string, count: number, typeWord: string, pickedId?: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return session;
  const library = seat.library ?? [];
  const top = library.slice(0, count);
  const qualifies = (card: VisibleCard) => card.typeLine.toLowerCase().includes(typeWord);
  const found = pickedId === "none" ? undefined : pickedId ? top.find((card) => card.id === pickedId && qualifies(card)) : top.find(qualifies);
  const rest = top.filter((card) => card.id !== found?.id);
  const seats = session.seats.map((item) => {
    if (item.id !== seatId) return item;
    const remaining = [...library.slice(top.length), ...shuffleCards(rest)];
    return {
      ...item,
      library: remaining,
      board: { ...item.board, hand: found ? [...item.board.hand, { ...found, zone: "hand" as const }] : item.board.hand },
      zones: { ...item.zones, library: remaining.length, hand: item.zones.hand + (found ? 1 : 0) }
    };
  });
  return rulesEvent({ ...session, seats }, seatId, found ? `${seat.name} sacrifices ${sourceName} and puts ${found.name} into their hand.` : `${seat.name} sacrifices ${sourceName} and takes no ${typeWord}.`);
}


// The cards a human's library-search picker may offer: the search's own printed restriction ("Forest card",
// "basic land card", "creature card", a mana-value ceiling) is enforced, so the player can't pick an illegal
// card by mistake (rule 701.19: a search can only find cards that match; an empty list is a legal "fail to
// find"). A placeholder/unrecognized phrase (the rules advisor's generic "cards matching the source effect",
// "basic lands sharing a land type") leaves the whole library visible, as before.
export function searchableLibraryCards(
  library: VisibleCard[],
  choice: {
    allowedCardFilter?: string;
    manaValueRestriction?: { op: "lte" | "eq" | "gte"; value: number };
    // Protean Hulk: the budget still unspent (limit minus the picks' mana values so far).
    remainingTotalManaValue?: number;
  }
): VisibleCard[] {
  const rawFilter = (choice.allowedCardFilter ?? "").toLowerCase().trim();
  const filter = rawFilter.replace(/\s+cards?$/, "").trim();
  const usableFilter = filter && !/^cards?$/.test(filter) && !/matching the source effect|sharing a land type/.test(filter);
  const restriction = choice.manaValueRestriction;
  return library.filter((card) => {
    if (choice.remainingTotalManaValue !== undefined && card.manaValue > choice.remainingTotalManaValue) return false;
    if (usableFilter) {
      // "basic land" / "basic plains" (landcycling): the card must be a basic land, then match the remaining type word if there is one.
      const wantsBasic = /^basic\b/.test(filter);
      const typeWord = (wantsBasic ? filter.replace(/^basic\s*/, "") : filter).replace(/^lands?$/, "").trim();
      if (wantsBasic && !isBasicLandCard(card)) return false;
      if (typeWord && !cardMatchesTypeFilter(card.typeLine, typeWord)) return false;
    }
    if (restriction) {
      if (restriction.op === "lte" && card.manaValue > restriction.value) return false;
      if (restriction.op === "gte" && card.manaValue < restriction.value) return false;
      if (restriction.op === "eq" && card.manaValue !== restriction.value) return false;
    }
    return true;
  });
}

export function remainingLibraryTotalManaValue(
  choice: { totalManaValueLimit?: number; chosenCardIds?: string[] },
  library: VisibleCard[]
): number | undefined {
  if (choice.totalManaValueLimit === undefined) return undefined;
  const chosen = new Set(choice.chosenCardIds ?? []);
  const spent = library.filter((card) => chosen.has(card.id)).reduce((sum, card) => sum + card.manaValue, 0);
  return Math.max(0, choice.totalManaValueLimit - spent);
}

function ruleChoiceView(
  choice: PendingRuleChoice | undefined,
  humanSeat: PlayerSeat,
  manualSearch: ManualLibrarySearchState | undefined,
  session: GameSession
) {
  if (choice?.controllerSeatId === humanSeat.id) {
    if (choice.kind === "choose_card_from_library") {
      const chosenCardIds = new Set(choice.chosenCardIds ?? []);
      return {
        kind: "choose_card_from_library" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        cards: searchableLibraryCards((humanSeat.library ?? []).filter((card) => !chosenCardIds.has(card.id)), {
          ...choice,
          remainingTotalManaValue: remainingLibraryTotalManaValue(choice, humanSeat.library ?? [])
        }),
        // Kodama's Reach / Cultivate: after the first find's zone is picked, the second find just goes to the other zone.
        destination:
          choice.splitDestination && chosenCardIds.size > 0 && choice.destinationChoices
            ? choice.chosenDestinations?.[[...chosenCardIds][0]] === "battlefield"
              ? choice.splitDestination
              : "battlefield"
            : choice.destination,
        destinationChoices: choice.splitDestination && chosenCardIds.size > 0 ? undefined : choice.destinationChoices,
        allowedCardFilter: choice.allowedCardFilter,
        maxChoices: choice.maxChoices,
        chosenCount: chosenCardIds.size
      };
    }
    if (choice.kind === "choose_creature_from_graveyards") {
      return {
        kind: "choose_creature_from_graveyards" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: choice.manaValueCeiling !== undefined ? "Choose (Battlefield or Hand)" : "Return to Battlefield",
        cards: session.seats
          .filter((seat) => !choice.restrictToYourGraveyard || seat.id === choice.controllerSeatId)
          .flatMap((seat) =>
            (seat.board.graveyard ?? [])
              .filter((card) => hasCardType(card, "Creature"))
              .map((card) => ({ card, seatId: seat.id, seatName: seat.name }))
          )
      };
    }
    if (choice.kind === "choose_creature_to_sacrifice") {
      const filter = choice.typeFilter?.toLowerCase();
      return {
        kind: "choose_creature_to_sacrifice" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: choice.tapSubtype ? "Tap" : "Sacrifice",
        // Always the controller's own board — a sacrifice cost has no "sacrifice an opponent's
        // creature" shape, unlike choose_creature_on_battlefield's restrictToYourControl (which
        // varies per targeted effect) or choose_creature_from_graveyards' any-graveyard pool.
        // The source permanent itself is a legal choice ("a creature", not "another creature") —
        // deliberately not excluded, unlike choose_creature_on_battlefield's own sourceCardId filter.
        cards: humanSeat.board.battlefield
          .filter((card) =>
            !choice.pickedIds?.includes(card.id) &&
            (choice.eligibleIds
              ? choice.eligibleIds.includes(card.id) && !card.tapped
              : choice.tapSubtype
              ? canTapForCost(card, choice.tapSubtype)
              : choice.anyPermanent
                ? card.id !== choice.excludeCardId && matchesPermanentSacrificeFilter(card, choice.typeFilter)
                : hasCardType(card, "Creature") && card.id !== choice.excludeCardId && matchesSacrificeFilter(card, filter))
          )
          .map((card) => ({ card, seatId: humanSeat.id, seatName: humanSeat.name }))
      };
    }
    if (choice.kind === "choose_each_player_sacrifice") {
      return {
        kind: "choose_each_player_sacrifice" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: "Sacrifice",
        cards: humanSeat.board.battlefield
          .filter((card) => matchesEachPlayerSacrificeFilter(card, choice.typeFilter) && !(choice.excludeTokensFromSourceId && card.token && card.tokenSourceCardId === choice.excludeTokensFromSourceId))
          .map((card) => ({ card, seatId: humanSeat.id, seatName: humanSeat.name }))
      };
    }
    if (choice.kind === "choose_creature_to_sacrifice_for_cast") {
      return {
        kind: "choose_creature_to_sacrifice_for_cast" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: "Sacrifice",
        cards: humanSeat.board.battlefield
          .filter((card) => matchesAdditionalSacrificeType(card, choice.sacrificeType ?? "creature"))
          .map((card) => ({ card, seatId: humanSeat.id, seatName: humanSeat.name }))
      };
    }
    if (choice.kind === "choose_cast_x") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: choice.options.map((option, index) => ({ index, label: option.label })) };
    }
    if (choice.kind === "choose_cast_copy") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: choice.options.map((option, index) => ({ index, label: option.label, card: findCardAnywhere(session, option.cardId, choice.controllerSeatId) })) };
    }
    if (choice.kind === "choose_cast_face") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: choice.options.map((option, index) => ({ index, label: option.label })) };
    }
    if (choice.kind === "choose_cast_alt") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: [{ index: 0, label: choice.altLabel }, { index: 1, label: "Pay the normal mana cost" }] };
    }
    // A card target (a graveyard creature, a permanent) is shown with its art and text, not just its name.
    const cardForTarget = (target: ChosenTarget | undefined): VisibleCard | undefined => (target?.kind === "card" ? findCardAnywhere(session, target.cardId, target.seatId) : undefined);
    if (choice.kind === "choose_cast_targets") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: choice.options.map((option, index) => ({ index, label: option.label, card: cardForTarget(option.target) })) };
    }
    if (choice.kind === "choose_spell_modes") {
      return {
        kind: "choose_modal_option" as const,
        sourceCardName: choice.sourceCardName,
        prompt: `${choice.sourceCardName}: choose mode ${choice.picked.length + 1} of ${choice.chooseCount}.`,
        options: choice.labels.map((label, index) => ({ index, label })).filter((option) => !choice.picked.includes(option.index))
      };
    }
    if (choice.kind === "choose_dig_card") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: choice.options.map((option) => ({ index: option.index, label: option.label, card: findCardAnywhere(session, option.cardId, choice.controllerSeatId) })) };
    }
    if (choice.kind === "choose_labeled_target") {
      const slot = choice.slots[choice.slotIndex];
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: slot.prompt, options: slot.options.map((option, index) => ({ index, label: option.label, card: cardForTarget(option.target) })) };
    }
    if (choice.kind === "choose_creature_for_grant") {
      const owner = session.seats.find((seat) => seat.id === choice.controllerSeatId);
      return {
        kind: "choose_creature_on_battlefield" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: "Give " + choice.keywords.join(" and "),
        cards: (owner?.board.battlefield ?? []).filter((card) => card.typeLine.includes("Creature")).map((card) => ({ card, seatId: owner!.id, seatName: owner!.name }))
      };
    }
    if (choice.kind === "choose_trigger_card") {
      const cards = choice.cards.flatMap((entry) => {
        const owner = session.seats.find((seat) => seat.id === entry.seatId);
        const card = choice.zone === "graveyard" ? owner?.board.graveyard?.find((item) => item.id === entry.cardId) : owner?.board.battlefield.find((item) => item.id === entry.cardId);
        return owner && card ? [{ card, seatId: owner.id, seatName: owner.name }] : [];
      });
      return choice.zone === "graveyard"
        ? { kind: "choose_creature_from_graveyards" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, actionLabel: "Choose", cards }
        : { kind: "choose_creature_on_battlefield" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, actionLabel: "Choose", cards };
    }
    if (choice.kind === "choose_trigger_option") {
      return { kind: "choose_modal_option" as const, sourceCardName: choice.sourceCardName, prompt: choice.prompt, options: choice.options.map((option) => ({ ...option, card: option.cardId ? findCardAnywhere(session, option.cardId, choice.controllerSeatId) : undefined })) };
    }
    if (choice.kind === "choose_ability_card_target") {
      return {
        kind: "choose_creature_from_graveyards" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: /exile/i.test(choice.prompt) ? "Exile" : "Choose",
        cards: choice.cards.flatMap((entry) => {
          const owner = session.seats.find((seat) => seat.id === entry.seatId);
          const card = owner?.board.graveyard?.find((item) => item.id === entry.cardId);
          return owner && card ? [{ card, seatId: owner.id, seatName: owner.name }] : [];
        })
      };
    }
    if (choice.kind === "choose_modal_option") {
      return {
        kind: "choose_modal_option" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        options: choice.options
      };
    }
    if (choice.kind === "choose_effect_target") {
      // legalTargets (src/lib/targeting.ts) is the single source of truth for this pool — the same
      // function maybeRequestTarget used to decide whether to even open this choice, and the same
      // one targetsStillLegal re-checks against at resolution time, so the two can never disagree.
      const pool = legalTargets(session, choice.controllerSeatId, choice.spec, choice.sourceCard);
      if (choice.spec.zone === "player") {
        return {
          kind: "choose_effect_target" as const,
          sourceCardName: choice.sourceCardName,
          prompt: choice.prompt,
          optional: choice.optional,
          zone: "player" as const,
          cards: [],
          players: pool
            .filter((target): target is Extract<typeof pool[number], { kind: "player" }> => target.kind === "player")
            .map((target) => ({ seatId: target.seatId, seatName: session.seats.find((seat) => seat.id === target.seatId)?.name ?? "" }))
        };
      }
      return {
        kind: "choose_effect_target" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        optional: choice.optional,
        zone: choice.spec.zone === "graveyard" ? ("graveyard" as const) : ("battlefield" as const),
        cards: pool
          .filter((target): target is Extract<typeof pool[number], { kind: "card" }> => target.kind === "card")
          .map((target) => ({ card: target.card, seatId: target.seatId, seatName: session.seats.find((seat) => seat.id === target.seatId)?.name ?? "" })),
        players: []
      };
    }
    if (choice.kind === "choose_proliferate_targets") {
      return {
        kind: "choose_proliferate_targets" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        cards: session.seats.flatMap((seat) =>
          seat.board.battlefield
            .filter((card) => card.counters && card.counters.length > 0)
            .map((card) => ({ card, seatId: seat.id, seatName: seat.name }))
        ),
        players: session.seats
          .filter((seat) => (seat.poison ?? 0) > 0 || (seat.experienceCounters ?? 0) > 0)
          .map((seat) => ({
            seatId: seat.id,
            seatName: seat.name,
            countersLabel: [seat.poison ? `${seat.poison} poison` : undefined, seat.experienceCounters ? `${seat.experienceCounters} experience` : undefined]
              .filter(Boolean)
              .join(", ")
          }))
      };
    }
    if (choice.kind === "choose_creature_on_battlefield") {
      return {
        kind: "choose_creature_on_battlefield" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: `Put a ${choice.counterKind} counter here`,
        cards: session.seats
          .filter((seat) => !choice.restrictToYourControl || seat.id === choice.controllerSeatId)
          .flatMap((seat) =>
            seat.board.battlefield
              .filter((card) => hasCardType(card, "Creature") && card.id !== choice.sourceCardId)
              .map((card) => ({ card, seatId: seat.id, seatName: seat.name }))
          )
      };
    }
    if (choice.kind === "choose_aura_attach_target") {
      return {
        kind: "choose_aura_attach_target" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: `Enchant with ${choice.sourceCardName}`,
        // Same targetOwn scoping as chooseAuraAttachTarget's own candidate search: a beneficial
        // aura's pool is the controller's own creatures, a removal-style aura's is opponents' only.
        cards: session.seats
          .filter((seat) => (choice.restrictToYourControl ? seat.id === choice.controllerSeatId : seat.id !== choice.controllerSeatId))
          .flatMap((seat) => seat.board.battlefield.filter((card) => hasCardType(card, "Creature")).map((card) => ({ card, seatId: seat.id, seatName: seat.name })))
      };
    }
    if (choice.kind === "choose_equip_target") {
      const controllerSeat = session.seats.find((seat) => seat.id === choice.controllerSeatId);
      return {
        kind: "choose_equip_target" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        actionLabel: `Equip ${choice.sourceCardName}`,
        // Equip's own reminder text is always "target creature YOU control" — no opponent pool,
        // unlike an Aura's beneficial-vs-removal split.
        cards: (controllerSeat?.board.battlefield ?? [])
          .filter((card) => hasCardType(card, "Creature"))
          .map((card) => ({ card, seatId: choice.controllerSeatId, seatName: controllerSeat?.name ?? "" }))
      };
    }
    if (choice.kind === "order_triggers") {
      return {
        kind: "order_triggers" as const,
        prompt: choice.prompt,
        triggers: choice.triggers,
        orderedTriggers: choice.orderedTriggers
      };
    }
    if (choice.kind === "miracle_offer") {
      // A Room card offered a miracle-like cast (Aminatou, Veil Piercer's granted miracle, ...)
      // still needs a door choice like any other cast of it — without this, acceptMiracleOffer had
      // no way to know a face was even in play and always cast face 0 (whichever door happens to
      // print first) regardless of which one the player actually wanted, reported live as Secret
      // Arcade // Dusty Parlor always choosing Secret Arcade for itself.
      const sourceSeat = session.seats.find((seat) => seat.id === choice.controllerSeatId);
      const sourceCard = sourceSeat?.board.hand.find((card) => card.id === choice.sourceCardId);
      const doors = sourceCard ? roomDoorFaces(sourceCard) : undefined;
      return {
        kind: "miracle_offer" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        miracleCost: choice.miracleCost,
        doorFaces: doors ? ([doors[0].name, doors[1].name] as [string, string]) : undefined
      };
    }
    if (choice.kind === "optional_trigger" || choice.kind === "optional_primitive_plan") {
      // Both project to the same "optional_trigger" view kind — ThreeGameTable.tsx's
      // OptionalTriggerModal only ever reads sourceCardName/prompt, and AppFlow.tsx's
      // acceptOptionalTrigger/declineOptionalTrigger (bound to that modal's onAccept/onDecline)
      // already branch internally on the real pendingRuleChoice.kind, so reusing the exact same
      // modal needs no new UI component.
      return {
        kind: "optional_trigger" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt
      };
    }
    if (choice.kind === "commander_zone_choice") {
      return {
        kind: "commander_zone_choice" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt
      };
    }
    if (choice.kind === "discard_to_hand_size") {
      return {
        kind: "discard_to_hand_size" as const,
        prompt: choice.prompt,
        hand: discardableHandCards(humanSeat, choice.activation?.discardType),
        requiredDiscards: choice.requiredDiscards,
        sourceCardName: choice.sourceCardName
      };
    }
    if (choice.kind === "put_cards_on_library") {
      return {
        kind: "put_cards_on_library" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        hand: humanSeat.board.hand,
        requiredCount: choice.requiredCount
      };
    }
    if (choice.kind === "connive_discard") {
      return {
        kind: "connive_discard" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        hand: humanSeat.board.hand
      };
    }
    if (choice.kind === "return_land_to_hand") {
      return {
        kind: "return_land_to_hand" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        lands: humanSeat.board.battlefield.filter((card) => card.typeLine.includes("Land"))
      };
    }
    if (choice.kind === "choose_permanent_to_blink") {
      return {
        kind: "choose_permanent_to_blink" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        permanents: humanSeat.board.battlefield.filter((card) => card.id !== choice.sourceCardId)
      };
    }
    if (choice.kind === "choose_creature_type") {
      return {
        kind: "choose_creature_type" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        currentChoice: humanSeat.board.battlefield.find((card) => card.id === choice.sourceCardId)?.chosenCreatureType
      };
    }
    if (choice.kind === "choose_color") {
      return {
        kind: "choose_color" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        excludedColor: choice.excludedColor,
        currentChoice: humanSeat.board.battlefield.find((card) => card.id === choice.sourceCardId)?.chosenColor
      };
    }
    if (choice.kind === "distribute_attack_trigger_mana") {
      return {
        kind: "distribute_attack_trigger_mana" as const,
        sourceCardName: choice.sourceCardName,
        prompt: choice.prompt,
        amount: choice.amount
      };
    }
    const source = humanSeat.board.battlefield.find((card) => card.id === choice.sourceCardId);
    return {
      kind: "manual_review" as const,
      sourceCardId: choice.sourceCardId,
      sourceCardName: choice.sourceCardName,
      prompt: choice.prompt,
      isCumulativeUpkeep: source ? isCumulativeUpkeepCard(source) : false,
      cumulativeUpkeepCost: source && isCumulativeUpkeepCard(source) ? cumulativeUpkeepCost(source) : undefined
    };
  }

  if (manualSearch?.seatId === humanSeat.id) {
    return {
      kind: "choose_card_from_library" as const,
      sourceCardName: "Manual Search",
      prompt: "Choose a card from your library.",
      cards: humanSeat.library ?? [],
      destination: manualSearch.destination,
      maxChoices: 1,
      chosenCount: 0
    };
  }

  return undefined;
}

function withEffectiveStats(card: VisibleCard): VisibleCard {
  // The live numbers become the printed ones, so every modifier is dropped from the copy: the block prompt applies effectivePower() again,
  // which used to count +1/+1 counters and pumps twice (a 10/10 Managorger Hydra was shown as 19/19).
  return {
    ...card,
    power: card.power !== undefined ? String(effectivePower(card)) : card.power,
    toughness: card.toughness !== undefined ? String(effectiveToughness(card)) : card.toughness,
    setPowerOverride: undefined,
    setToughnessOverride: undefined,
    cdaPower: undefined,
    cdaToughness: undefined,
    temporaryPowerBonus: undefined,
    temporaryToughnessBonus: undefined,
    attachmentPowerBonus: undefined,
    attachmentToughnessBonus: undefined,
    counters: card.counters?.filter((counter) => counter.kind !== "+1/+1" && counter.kind !== "-1/-1")
  };
}

function blockChoiceView(session: GameSession, choice: BlockChoiceState | undefined) {
  if (!choice) return undefined;
  const attacker = session.seats.find((seat) => seat.id === choice.attackerSeatId);
  const defender = session.seats.find((seat) => seat.id === choice.defenderSeatId);
  const attackingCard = attacker?.board.battlefield.find((card) => card.id === choice.attackerCardId && card.attacking);
  if (!attacker || !defender || !attackingCard) return undefined;
  return {
    attackerName: attacker.name,
    defenderName: defender.name,
    attackingCard: withEffectiveStats(attackingCard),
    blockers: defender.board.battlefield.filter((card) => canBlock(card, attackingCard, defender.board.battlefield)).map(withEffectiveStats)
  };
}

function ruleChoiceLabel(choice: PendingRuleChoice) {
  if (choice.kind === "order_triggers") return "phase triggers";
  if (choice.kind === "discard_to_hand_size") return "discarding to hand size";
  return choice.sourceCardName;
}

export function shouldConsultRulesAdvisor(event: string, card: VisibleCard) {
  if (event === "activated_ability") return true;
  // Sagas (rule 714) gate each numbered chapter's text behind a lore-counter count that only
  // advances over several of the controller's own turns — the advisor has no concept of that
  // gating and reads the card's whole oracle text as one blob, so consulting it on ETB (event
  // "land_played"/spell cast) would immediately run every later chapter's effect the same turn the
  // Saga entered, instead of waiting for its lore counters to actually reach that chapter. Every
  // Saga instead gets its own chapter-scoped consultation from triggerSagaChapter/
  // applySagaLoreCounter/advanceSagaLoreCounters, fired at the right lore-counter threshold — this
  // exclusion just stops the normal ETB/cast consultation path from misfiring on the whole card.
  // event "saga_chapter" is exempted: by the time triggerSagaChapter calls consultRulesAdvisor with
  // it, oracleText has already been narrowed to just that one chapter's own clause (not the whole
  // card), so there's no whole-card-blob risk left to guard against — and without this exemption,
  // deterministicRuleWorkflow's search_library_to_battlefield workflow (and its manaValueRestriction,
  // added for exactly this case) never actually runs for a search-shaped chapter like Urza's Saga's
  // own chapter III, which fell through to the weaker LLM-only primitive-action planner instead.
  if (event !== "saga_chapter" && card.typeLine.includes("Saga")) return false;
  // A land's ETB is now checked against parseZoneEffect deterministically before this ever runs
  // (see playCard's playingAsLand branch) — Bojuka Bog's "exile target player's graveyard" and the
  // rest of that shape (mill/reanimate/regrow/graveyard_to_library/gain_control/...) are already
  // resolved by the time this is reached, so consulting the advisor too would either redundantly
  // re-ask about the same clause or, worse, offer a confusing second manual_review prompt for an
  // effect that already happened.
  if (event === "land_played" && parseEtbZoneEffect(etbEffectText(card.oracleText))) return false;
  // Scope the pattern match to the card's own standing/triggered text, not text describing what an
  // OPTIONAL activated ability's cost or effect does — e.g. Phyrexian Tower's "{T}, Sacrifice a
  // creature: Add {B}{B}." contains "sacrifice", but that's a cost the controller chooses to pay,
  // not something that happens on its own. Without this, playing the land at all (event
  // "land_played") would consult the advisor purely because that word appears somewhere on the
  // card, with nothing relevant for the advisor to actually resolve — and an LLM asked "what should
  // happen" about a card whose only matching text is a sacrifice cost can hallucinate an actual
  // sacrifice.
  // "~ enters the battlefield tapped[, unless/because ...]." (Myriad Landscape, Karplusan Forest,
  // Bojuka Bog, and the huge share of nonbasic lands templated this way) is a static replacement
  // clause, not a "when ~ enters" triggered ability — it's already fully handled by the tapped flag
  // set at the moment the land is played. But it's plain prose that happens to contain the word
  // "enters," so without this it matched the "enters" keyword below on nearly every tapped land
  // played, wastefully consulting the advisor (and often landing on a pointless manual_review
  // prompt) for a card with nothing left for it to actually resolve.
  //
  // For an ETB or death event specifically, scope to etbEffectText/deathEffectText — the exact same
  // scoping requestRuleWorkflow's own deterministicRuleWorkflow applies via eventRelevantOracleText
  // — rather than this function's own looser "just drop activated-ability clauses" filter. Without
  // this, a clause genuinely irrelevant to THIS event (Skullclamp's "Whenever equipped creature
  // dies, draw two cards." — a real trigger, just not an ETB one) still leaked its "whenever"/"dies"/
  // "draw cards" keywords into the pre-check for a "spell_resolved_to_battlefield" consultation,
  // triggering one anyway. The deterministic classifier then correctly found nothing (its own
  // properly-scoped text was just "Equipped creature gets +1/-1.", matching no known shape) and fell
  // through to Ollama — which, asked to classify a bare static-bonus line as some kind of workflow,
  // hallucinated an unrelated explanation about death triggers and counters. Reproduced live.
  const isEtbEvent = event === "land_played" || event === "spell_resolved_to_battlefield";
  const isDeathEvent = event === "card_moved_to_graveyard";
  // The "~ enters tapped" replacement clause has to be dropped from the ORIGINAL, still-per-line
  // oracle text, before etbEffectText ever joins lines together — dropping it afterward (on the
  // already-space-joined blob) let the prefix match consume an entire merged clause, silently
  // swallowing a genuine second ETB trigger that happened to share a line with it once joined.
  // Reproduced live: Temple of Deceit's "This land enters tapped.\nWhen this land enters, scry 1...."
  // joins into one string, whose START still literally reads "this land enters tapped" — so the old
  // post-join filter matched that as a prefix and threw away the whole clause, scry trigger
  // included, and the land never actually scried. Filtering per original line first still correctly
  // drops a land whose ENTIRE separate line is just the (possibly conditional, e.g. "...unless you
  // control two or more basic lands") tapped clause, with nothing else on it.
  const tappedConditionFilteredOracleText = isEtbEvent
    ? oracleClauses(card.oracleText)
        .filter((clause) => !/^[a-z][a-z',. -]* enters (?:the battlefield )?tapped\b/i.test(clause))
        .join("\n")
    : card.oracleText;
  const scopedOracleText = isEtbEvent
    ? etbEffectText(tappedConditionFilteredOracleText)
    : isDeathEvent
      ? deathEffectText(card.oracleText)
      : card.oracleText;
  const text = oracleClauses(scopedOracleText)
    .filter((clause) => !isActivatedAbilityClause(clause))
    .join(" ")
    .toLowerCase();
  if (!text.trim()) return false;
  // "draw a card"/"draw cards" as fixed substrings miss any numbered draw ("draw three cards," a
  // number word or digit sitting between "draw" and "card(s)") — which is exactly Brainstorm's
  // "Draw three cards, then put two cards from your hand on top of your library in any order.": no
  // entry below matched it, so shouldConsultRulesAdvisor returned false and consultRulesAdvisor was
  // never even called, silently dropping both the draw and the put-back (parseSimpleDrawEffect
  // deliberately declines this exact "draw N, then put M back" shape so the rules advisor's
  // draw_then_put_back workflow can own it — see that function's own comment — but nothing reaches
  // that workflow if this gate blocks the call first). Reported live as "Brainstorm still does not
  // work." A bare regex test for the word "draw" covers every numbered/unnumbered phrasing at once.
  if (/\bdraw\b/.test(text)) return true;
  // A bare substring check for "sacrifice " (with a trailing space) never matches "sacrifices" or
  // "sacrificing" — a real card's own wording almost always inflects the verb (Torment of Hailfire's
  // "...unless that player sacrifices a nonland permanent...") rather than using the bare infinitive,
  // so this gate silently rejected nearly every sacrifice-shaped card it was meant to catch. "sacrific"
  // (no trailing space) covers every inflection at once, the same way the \bdraw\b check just above
  // already covers every numbered draw.
  if (/\bsacrific/.test(text)) return true;
  return [
    "when ",
    "whenever ",
    "at the beginning",
    "enters",
    "dies",
    "search your library",
    "create ",
    "return ",
    "exile ",
    "surveil",
    "scry"
  ].some((pattern) => text.includes(pattern));
}

// Rule 111.2/111.7-111.9: "You get an emblem with ..." — one emblem per grant (an emblem that prints several abilities, Saheeli's
// "...+1/+1" and "...cost {1} less", is still ONE emblem; its clauses are kept as separate lines of oracleText, which every parser here already
// reads line by line). Emblems stay in seat.emblems for the rest of the game and are public information.
export function addEmblemToSeat(session: GameSession, seatId: string, sourceName: string, clauses: string[]): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  const text = clauses.map((clause) => clause.trim()).filter(Boolean);
  if (!seat || text.length === 0) return session;
  const emblem: EmblemState = { id: crypto.randomUUID(), sourceName, oracleText: text.join("\n") };
  return {
    ...session,
    seats: session.seats.map((item) => (item.id === seatId ? { ...item, emblems: [...(item.emblems ?? []), emblem] } : item)),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${seat.name} gets an emblem from ${sourceName}: ${text.map((clause) => `"${clause}"`).join(" and ")}`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

// "Search your library for a permanent card, put it onto the battlefield, then shuffle." (the clause of a phase trigger) -> the searched type word.
export function parseSearchLibraryPutEffect(clauseText: string): { filter: string; tapped: boolean; optional: boolean } | undefined {
  const match = clauseText
    .replace(/\([^)]*\)/g, "")
    .match(/(?:^|,\s*)(you may )?search your library for an? ([a-z][a-z' -]*?) card, (?:reveal it, )?put it onto the battlefield( tapped)?, then shuffle\.?\s*$/i);
  if (!match) return undefined;
  return { filter: match[2].trim().toLowerCase(), tapped: Boolean(match[3]), optional: Boolean(match[1]) };
}

// Emblem "whenever" watchers that return cards: "Whenever an artifact is put into your graveyard from the battlefield, return that card to the
// battlefield at the beginning of the next end step." (Daretti, Scrap Savant -10) and "Whenever a creature dies, return it to the battlefield
// under your control at the beginning of the next end step." (Liliana, Heretical Healer -8).
export interface EmblemReturnWatcher {
  typeWord: string;
  // Whose graveyard counts: "you" = the emblem controller's own ("your graveyard"), "any" = every player's ("a creature dies").
  graveyardOf: "you" | "any";
  // Who controls the card when it returns: its owner, or the emblem's controller.
  returnsUnder: "owner" | "you";
}
export function parseEmblemReturnWatchers(oracleText: string): EmblemReturnWatcher[] {
  const out: EmblemReturnWatcher[] = [];
  for (const clause of oracleClauses(oracleText)) {
    const text = clause.replace(/\([^)]*\)/g, "").trim();
    const put = text.match(/^whenever an? ([a-z]+) is put into your graveyard from the battlefield, return that card to the battlefield(?: under your control)? at the beginning of the next end step\.?$/i);
    if (put) out.push({ typeWord: put[1].toLowerCase(), graveyardOf: "you", returnsUnder: /under your control/i.test(text) ? "you" : "owner" });
    const dies = text.match(/^whenever an? ([a-z]+) dies, return it to the battlefield under your control at the beginning of the next end step\.?$/i);
    if (dies) out.push({ typeWord: dies[1].toLowerCase(), graveyardOf: "any", returnsUnder: "you" });
  }
  return out;
}

// Compares two consecutive session snapshots (path-independent: combat damage, destroy spells, sacrifice, state-based actions all end the same way)
// and returns the delayed "return it at the next end step" triggers earned by cards that went battlefield -> graveyard in between. Tokens cease to
// exist in the graveyard (rule 111.7) so they never come back; a card that is not in the graveyard any more when the step arrives is skipped then.
export function findEmblemGraveyardReturns(before: GameSession, after: GameSession): Array<Omit<DelayedPhaseTrigger, "id" | "createdTurn" | "createdPhase">> {
  const found: Array<Omit<DelayedPhaseTrigger, "id" | "createdTurn" | "createdPhase">> = [];
  if (!after.seats.some((seat) => (seat.emblems?.length ?? 0) > 0)) return found;
  const wasOnBattlefield = new Map<string, VisibleCard>();
  for (const seat of before.seats) for (const card of seat.board.battlefield) wasOnBattlefield.set(card.id, card);
  const alreadyGraveyard = new Set(before.seats.flatMap((seat) => (seat.board.graveyard ?? []).map((card) => card.id)));
  for (const emblemSeat of after.seats) {
    for (const emblem of emblemSeat.emblems ?? []) {
      for (const watcher of parseEmblemReturnWatchers(emblem.oracleText)) {
        for (const graveSeat of after.seats) {
          if (watcher.graveyardOf === "you" && graveSeat.id !== emblemSeat.id) continue;
          for (const card of graveSeat.board.graveyard ?? []) {
            if (alreadyGraveyard.has(card.id) || card.token) continue;
            const prior = wasOnBattlefield.get(card.id);
            if (!prior || prior.token) continue;
            if (!hasCardType(prior, capitalizeWord(watcher.typeWord))) continue;
            const ownerSeatId = card.ownerSeatId ?? graveSeat.id;
            found.push({
              controllerSeatId: emblemSeat.id,
              sourceCardId: emblem.id,
              sourceCardName: emblemDisplayName(emblem.sourceName),
              phase: "end step",
              scope: "any",
              effectText: `Return ${card.name} to the battlefield.`,
              returnCard: { cardId: card.id, cardName: card.name, ownerSeatId, controlSeatId: watcher.returnsUnder === "you" ? emblemSeat.id : ownerSeatId }
            });
          }
        }
      }
    }
  }
  return found;
}

function phaseTriggeredCards(seat: PlayerSeat, phase: TurnPhase) {
  const permanents = seat.board.battlefield.filter((card) => hasPhaseTrigger(card, phase));
  const emblems = (seat.emblems ?? []).map(emblemAsShimCard).filter((card) => hasPhaseTrigger(card, phase));
  return [...permanents, ...emblems];
}

// Shadow of the Second Sun-style "enchant player" Auras live on their CASTER's battlefield, not
// the enchanted player's — scans every seat's battlefield rather than just the enchanted seat's own.
function hasExtraBeginningPhaseAura(session: GameSession, enchantedSeatId: string): boolean {
  return session.seats.some((seat) =>
    seat.board.battlefield.some((card) => isAura(card) && card.attachedToSeatId === enchantedSeatId && attachmentGrantsExtraBeginningPhase(card.oracleText))
  );
}

export function hasPhaseTrigger(card: VisibleCard, phase: TurnPhase) {
  // A creature that's lost all abilities (abilitiesStripped) can't fire its own phase-triggered
  // ability either — same suppression hasKeyword already applies to its keywords.
  if (card.abilitiesStripped) return false;
  return mergeModalBulletClauses(oracleClauses(card.oracleText)).some(
    (clause) => !isActivatedAbilityClause(clause) && phaseTriggerTextMatches(clause.toLowerCase(), phase)
  );
}

// "At the beginning of your upkeep, if you have four or more creature cards in your graveyard, you may return target creature card from your
// graveyard to your hand." (Oversold Cemetery, Reya Dawnbringer, ...): what a human is asked at the phase, or "skip" when its "if" isn't met.
export function humanPhaseGraveyardChoice(session: GameSession, seatId: string, sourceCard: VisibleCard, phase: TurnPhase): "skip" | { effect: ZoneEffect; optional: boolean } | undefined {
  const clauseText = phaseEffectText(sourceCard.oracleText, phase);
  if (!clauseText.trim()) return undefined;
  const effect = parseZoneEffect(clauseText);
  if (!effect || (effect.kind !== "regrow" && !(effect.kind === "reanimate" && !effect.anyGraveyard))) return undefined;
  const condition = clauseText.replace(/^.*?\bat the beginning of[^,]*,\s*/i, "").match(/^if\s+(.+?),/i);
  if (condition) {
    if (!isRecognizedBoardCondition(condition[1])) return undefined;
    const seat = session.seats.find((item) => item.id === seatId);
    if (!seat || !isBoardConditionMet(condition[1], seat, session.seats)) return "skip";
  }
  return { effect, optional: /\byou may\b/i.test(clauseText) };
}

// Creatures that must attack ("attacks each combat if able", or goaded) and the opponents each may legally attack. A goaded creature can't attack
// the player who goaded it unless that player is the only one it can attack.
export function forcedAttackers(session: GameSession, seat: PlayerSeat): Array<{ cardId: string; targetIds: string[] }> {
  const opponents = session.seats.filter((other) => other.id !== seat.id && !other.hasLost);
  const byCard = new Map<string, string[]>();
  for (const action of legalAttackActions(seat, opponents)) {
    if (action.actionType !== "attack" || !action.cardId) continue;
    const card = seat.board.battlefield.find((entry) => entry.id === action.cardId);
    if (!card || !mustAttackEachCombat(card)) continue;
    byCard.set(card.id, [...(byCard.get(card.id) ?? []), action.targetIds[0]]);
  }
  return [...byCard.entries()].map(([cardId, targetIds]) => {
    const goader = seat.board.battlefield.find((entry) => entry.id === cardId)?.goaded?.bySeatId;
    const others = goader ? targetIds.filter((id) => id !== goader) : targetIds;
    return { cardId, targetIds: others.length > 0 ? others : targetIds };
  });
}

export function applyEndStepEffects(session: GameSession, seatId: string): GameSession {
  let next = session;
  // Treasure Nabber's steals end at the stealer's end step on a LATER turn than the tap.
  for (const holder of next.seats) {
    for (const card of holder.board.battlefield.filter((permanent) => permanent.nabbedUntil && permanent.nabbedUntil.seatId === seatId && next.turn > permanent.nabbedUntil.afterTurn && permanent.nabbedFromSeatId)) {
      const back = card.nabbedFromSeatId!;
      next = changeControlWithinBattlefield(next, card.id, holder.id, back);
      next = { ...next, seats: next.seats.map((seat) => (seat.id !== back ? seat : { ...seat, board: { ...seat.board, battlefield: seat.board.battlefield.map((permanent) => (permanent.id === card.id ? { ...permanent, nabbedFromSeatId: undefined, nabbedUntil: undefined, summoningSick: false } : permanent)) } })) };
    }
  }
  const monarch = next.seats.find((seat) => seat.id === seatId);
  if (next.monarchSeatId === seatId && next.monarchDrawTurn !== next.turn && monarch && !monarch.hasLost) {
    next = drawForSeat({ ...next, monarchDrawTurn: next.turn }, seatId, `${monarch.name} draws a card as the monarch.`);
  }
  // "Exile it at the beginning of the next end step": tokens just cease to exist, a real card goes to exile.
  const doomed = next.seats.flatMap((item) => item.board.battlefield.filter((card) => card.exileAtEndStep).map((card) => ({ seatId: item.id, card })));
  for (const entry of doomed) {
    next = entry.card.token
      ? { ...next, seats: next.seats.map((item) => (item.id === entry.seatId ? { ...item, board: { ...item.board, battlefield: item.board.battlefield.filter((card) => card.id !== entry.card.id) }, zones: { ...item.zones, battlefield: Math.max(0, item.zones.battlefield - 1) } } : item)) }
      : moveCardAcrossSeats(next, entry.seatId, entry.card.id, entry.card.ownerSeatId ?? entry.seatId, "exile").session;
  }
  return resolveEndStepExileDamage(next, seatId);
}

// Cards in an opening hand that may begin the game on the battlefield (Leyline of Abundance, ...).
export function openingHandBattlefieldCards(seat: PlayerSeat): VisibleCard[] {
  return seat.board.hand.filter((card) => /if this card is in your opening hand, you may begin the game with it on the battlefield/i.test(card.oracleText));
}

export function putOpeningHandCardOnBattlefield(session: GameSession, seatId: string, cardId: string): GameSession {
  const card = session.seats.find((item) => item.id === seatId)?.board.hand.find((entry) => entry.id === cardId);
  if (!card) return session;
  const moved = moveCardAcrossSeats(session, seatId, cardId, seatId, "battlefield");
  return rulesEvent(moved.session, seatId, `${card.name} begins the game on the battlefield.`);
}

function phaseEventName(phase: TurnPhase) {
  return `${phase.replace(/ /g, "_")}_trigger`;
}

// Whether this phase's clause on sourceCard is a reanimate effect sourced from ANY graveyard (not
// just the controller's own) — Virtue of Persistence's shape. Checked at the phase-trigger dispatch
// site (before applyDeterministicPhaseTrigger ever runs) so a human controller can be asked to pick
// the actual target instead of it going straight to chooseReanimationTarget's heuristic.
function isReanimateFromAnyGraveyardPhaseTrigger(sourceCard: VisibleCard, phase: TurnPhase): boolean {
  const effect = parseZoneEffect(phaseEffectText(sourceCard.oracleText, phase));
  return effect?.kind === "reanimate" && effect.anyGraveyard;
}

// Whether this phase's clause on sourceCard puts a counter on a battlefield creature the
// controller doesn't get to auto-resolve for free — Athreos, Shroud-Veiled's "put a coin counter
// on another target creature" shape. Checked at the phase-trigger dispatch site, same reasoning as
// isReanimateFromAnyGraveyardPhaseTrigger just above.
function targetCreatureCounterPhaseTrigger(
  sourceCard: VisibleCard,
  phase: TurnPhase
): Extract<TriggerEffect, { kind: "add_counter" }> | undefined {
  const effect = commonTriggerEffect(phaseEffectText(sourceCard.oracleText, phase), "clause");
  if (effect?.kind !== "add_counter") return undefined;
  return effect.scope === "target_creature" || effect.scope === "target_creature_you_control" ? effect : undefined;
}

// --- phase triggers on the stack ---------------------------------------------------------------------------------------------------------------
// A step's "at the beginning of ..." abilities used to be applied directly by the phase sweep (no stack, no response window, no recorded target).
// src/lib/phaseTriggers.ts now derives the standing watchers of every seat's permanents; the sweep turns them into real trigger stack items here.
function phaseStepLabel(phase: TurnPhase): string {
  return phase === "end of combat step" ? "end of combat" : phase === "beginning of combat step" ? "combat" : phase.replace(/ step$/, " step");
}

function hasInterveningIf(clauseText: string): boolean {
  return /^.*?\bat the beginning of[^,]*,\s*if\s/i.test(clauseText);
}

function stubSourceCard(id: string, name: string): VisibleCard {
  return { id, name, typeLine: "", oracleText: "", colors: [], manaValue: 0, role: "effect", zone: "battlefield" } as VisibleCard;
}

// The stack item for one of the ACTIVE player's own phase triggers that resolves without a human decision (after the sweep's human prompts have
// been offered). "blocked": its intervening "if" is false right now (rule 603.4: it does not trigger at all). undefined: no deterministic handler,
// so the rules-advisor fallback owns it. An agent's aimed trigger records its target as it goes on the stack (rule 603.3d).
export function makePhaseStackTrigger(session: GameSession, seatId: string, sourceCard: VisibleCard, phase: TurnPhase): Extract<PendingAction, { type: "trigger" }> | "blocked" | undefined {
  const clause = phaseEffectText(sourceCard.oracleText, phase);
  if (!clause.trim()) return undefined;
  if (phaseConditionBlocks(session, seatId, clause)) return "blocked";
  const seat = session.seats.find((item) => item.id === seatId);
  // "At the beginning of your end step, search your library for a permanent card, put it onto the battlefield, then shuffle." (Tezzeret's and Garruk's
  // emblems): a real stack item whose resolution opens the library picker for a human / makes the deterministic pick for an agent.
  const searchPut = parseSearchLibraryPutEffect(clause);
  if (searchPut) {
    return makeCommonTrigger(seatId, seatId, sourceCard, { kind: "search_library_put", filter: searchPut.filter, tapped: searchPut.tapped, optional: searchPut.optional, fromPhaseStep: true, ...(hasInterveningIf(clause) ? { recheckClause: clause } : {}) }, `${sourceCard.name} triggers at the beginning of ${seat?.name ?? "the"} ${phaseStepLabel(phase)}.`);
  }
  if (applyDeterministicPhaseTrigger(session, seatId, sourceCard, phase) === undefined) return undefined;
  let effect: Extract<TriggerEffect, { kind: "phase_trigger" }> = { kind: "phase_trigger", phase, sourceSnapshot: sourceCard, fromPhaseStep: true, ...(hasInterveningIf(clause) ? { recheckClause: clause } : {}) };
  if (seat?.kind === "agent") {
    const common = commonTriggerEffect(clause, "clause", undefined, seat);
    if (common && agentTargetedTriggerKinds.has(common.kind)) {
      const aimed = agentTriggerTarget(session, makeCommonTrigger(seatId, seatId, sourceCard, common, ""));
      if (aimed) effect = { ...effect, viaEffect: common, chosenOption: aimed };
    }
  }
  return makeCommonTrigger(seatId, seatId, sourceCard, effect, `${sourceCard.name} triggers at the beginning of ${seat?.name ?? "the"} ${phaseStepLabel(phase)}.`);
}

// Phase triggers that are NOT the active player's own legacy-swept permanents: every other seat's permanents ("each upkeep", "each opponent's
// upkeep", "at the beginning of each combat", Sheoldred's edict, ...) and due one-shot delayed triggers. Returned in resolution order (APNAP: the
// non-active players' triggers resolve before the active player's), already shaped as stack items. consumedDelayedIds are removed from the session
// once queued (they fire once).
export function planOffTurnPhaseTriggers(session: GameSession, phase: TurnPhase, activeSeatId: string): { triggers: Array<Extract<PendingAction, { type: "trigger" }>>; consumedDelayedIds: string[] } {
  const groups = collectPhaseTriggers(session.seats, phase, activeSeatId, { delayed: session.delayedPhaseTriggers, turn: session.turn });
  const active = session.seats.find((item) => item.id === activeSeatId);
  const triggers: Array<Extract<PendingAction, { type: "trigger" }>> = [];
  const consumedDelayedIds: string[] = [];
  for (const entry of stackResolutionOrder(groups)) {
    const { watcher, delayed } = entry;
    const controller = session.seats.find((item) => item.id === watcher.controllerSeatId);
    if (!controller) continue;
    const spec = watcher.spec;
    const card = controller.board.battlefield.find((item) => item.id === watcher.sourceCardId);
    const emblem = watcher.emblem ? (controller.emblems ?? []).find((item) => item.id === watcher.sourceCardId) : undefined;
    const sourceCard = card ?? (emblem ? emblemAsShimCard(emblem) : stubSourceCard(watcher.sourceCardId, watcher.sourceCardName));
    if (delayed) {
      consumedDelayedIds.push(delayed.id);
      triggers.push(makeCommonTrigger(activeSeatId, controller.id, sourceCard, { kind: "phase_trigger", phase, delayedEffectText: delayed.effectText, sourceSnapshot: sourceCard, fromPhaseStep: true, ...(delayed.returnCard ? { delayedReturn: delayed.returnCard } : {}) }, `${watcher.sourceCardName}'s delayed trigger happens at the beginning of ${active?.name ?? "the"} ${phaseStepLabel(phase)}.`));
      continue;
    }
    // The active player's own permanents are owned by the sweep's per-card flow (human prompts included) whenever its legacy matcher claims them.
    if (watcher.controllerSeatId === activeSeatId && sourceCard && hasPhaseTrigger(sourceCard, phase)) continue;
    if (spec.keyword) continue;
    if (spec.condition && phaseConditionBlocks(session, controller.id, spec.clause)) continue;
    let effect: TriggerEffect | undefined;
    if (spec.scope === "opponents" && /^that player sacrifices an? (?:nontoken )?creature of their choice/i.test(spec.effectText)) {
      effect = { kind: "each_opponent_sacrifices", filter: "creature", onlySeatId: activeSeatId };
    } else if (/\b(?:that player|each player|the active player|enchanted player|defending player|target player)\b/i.test(spec.effectText)) {
      // The effect is about whoever's turn it is, which the generic parsers read as the controller: not resolved rather than resolved wrongly.
      continue;
    } else {
      effect = commonTriggerEffect(spec.clause, "clause", undefined, controller);
    }
    if (!effect) continue;
    effect = { ...effect, fromPhaseStep: true, ...(spec.condition ? { recheckClause: spec.clause } : {}) };
    triggers.push(makeCommonTrigger(activeSeatId, controller.id, sourceCard, effect, `${sourceCard.name} triggers at the beginning of ${active?.name ?? "the"} ${phaseStepLabel(phase)}.`));
  }
  return { triggers, consumedDelayedIds };
}

// Schedules a one-shot delayed "at the beginning of the next <step>" trigger (rule 603.7) created by a resolved effect.
export function scheduleDelayedPhaseTrigger(session: GameSession, trigger: Omit<DelayedPhaseTrigger, "id" | "createdTurn" | "createdPhase">): GameSession {
  const createdPhase = (TURN_PHASES as readonly string[]).includes(session.phase) ? (session.phase as TurnPhase) : "precombat main phase";
  return { ...session, delayedPhaseTriggers: [...(session.delayedPhaseTriggers ?? []), { ...trigger, id: crypto.randomUUID(), createdTurn: session.turn, createdPhase }] };
}

// Path of Ancestry: "When that mana is spent to cast a creature spell that shares a creature type with your commander, scry 1."
export function pathOfAncestryScries(session: GameSession, seatId: string, spell: VisibleCard, manaSourceIds: string[]): boolean {
  if (!spell.typeLine.includes("Creature")) return false;
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return false;
  const usedPath = seat.board.battlefield.some((card) => manaSourceIds.includes(card.id) && /when that mana is spent to cast a creature spell that shares a creature type with your commander, scry 1/i.test(card.oracleText));
  if (!usedPath) return false;
  const commander = seat.board.commander ?? seat.board.battlefield.find((card) => card.commander);
  const typesOf = (typeLine: string) => (typeLine.includes("—") ? typeLine.slice(typeLine.indexOf("—") + 1).trim().split(/\s+/).filter(Boolean) : []);
  if (!commander) return false;
  const commanderTypes = typesOf(commander.typeLine);
  return typesOf(spell.typeLine).some((type) => commanderTypes.includes(type));
}

// An agent's pick for a free cast: the most expensive permanent that fits, else the most expensive spell.
export function chooseFreeCastCard(cards: VisibleCard[]): VisibleCard | undefined {
  const isSpellOnly = (card: VisibleCard) => card.typeLine.includes("Instant") || card.typeLine.includes("Sorcery");
  const byValue = (a: VisibleCard, b: VisibleCard) => b.manaValue - a.manaValue;
  return [...cards].filter((card) => !isSpellOnly(card)).sort(byValue)[0] ?? [...cards].sort(byValue)[0];
}

// Moves a hand card to exile with a free-cast permission for this turn, so the normal cast flow (targets, ETBs, triggers) can cast it for {0}.
export function markHandCardFreeCastable(session: GameSession, seatId: string, cardId: string): GameSession {
  const moved = moveCardAcrossSeats(session, seatId, cardId, seatId, "exile").session;
  return {
    ...moved,
    seats: moved.seats.map((seat) =>
      seat.id !== seatId
        ? seat
        : { ...seat, board: { ...seat.board, exile: (seat.board.exile ?? []).map((card) => (card.id === cardId ? { ...card, exiledPlayableBySeatId: seatId, exiledPlayableUntilTurn: session.turn, exiledPlayableFree: true } : card)) } }
    )
  };
}

// "Each player sacrifices a creature or planeswalker of their choice. If a player can't, they
// discard a card instead." (Plaguecrafter, and the same "everyone independently, not just you or a
// single chosen opponent" edict shape on similar cards) — no existing effect kind models "every
// player does this to themselves" (TriggerEffect's kinds all either affect only the controller, a
// single chosen target, or every OTHER player, never every player symmetrically including the
// controller), so this is detected and applied as its own bespoke ETB shape rather than forced into
// that union. The discardFallback regex previously looked for "if a player can't, they discard a
// card instead" — a phrasing that doesn't match Plaguecrafter's real printed text ("Each player who
// can't discards a card.") at all, so discardFallback was always false for the actual card and this
// whole branch was silently dead code, verified against the real Scryfall-sourced oracle text (this
// codebase's own local card database), not a guess. Reported live as "Plaguecrafter does not let you
// choose what card to discard if you got no creatures" — with the wrong regex, nothing happened for
// that player at all.
export function parseEachPlayerSacrificeEffect(text: string): { typeFilter: string; discardFallback: boolean } | undefined {
  const match = text.toLowerCase().match(/\beach player sacrifices an? ([a-z ]+?) of their choice\b/);
  if (!match) return undefined;
  return { typeFilter: match[1].trim(), discardFallback: /\beach player who can'?t discards? a card\b/i.test(text) };
}

export function applyEachPlayerSacrificeEffect(
  session: GameSession,
  sourceCardName: string,
  effect: { typeFilter: string; discardFallback: boolean }
): { session: GameSession; humanDiscardNeededSeatId?: string; humanSacrificeNeededSeatId?: string } {
  const destructions: Array<{ seatId: string; cardId: string; message: string }> = [];
  const discarders: string[] = [];
  let humanDiscardNeededSeatId: string | undefined;
  let humanSacrificeNeededSeatId: string | undefined;
  for (const seat of session.seats) {
    if (seat.hasLost) continue;
    // A human with a genuine choice (more than one legal creature/planeswalker to sacrifice) picks
    // their own — see the choose_each_player_sacrifice PendingRuleChoice this defers to, opened by
    // the resolvePendingAction call site that reads humanSacrificeNeededSeatId back. A human with 0
    // or 1 candidate has no real decision to make (0 falls through to the discard-fallback branch
    // below exactly as before, 1 has only one possible pick), so both stay on the same deterministic
    // path an agent seat always uses — there's nothing to choose between either way.
    if (seat.kind === "human" && seat.board.battlefield.filter((card) => matchesEachPlayerSacrificeFilter(card, effect.typeFilter)).length > 1) {
      humanSacrificeNeededSeatId = seat.id;
      continue;
    }
    const target = choosePlaguecrafterSacrifice(seat, effect.typeFilter);
    if (target) {
      destructions.push({ seatId: seat.id, cardId: target.id, message: `${seat.name} sacrifices ${target.name} to ${sourceCardName}.` });
    } else if (effect.discardFallback) {
      // A human player chooses which card to discard themselves — see the interactive
      // choose-a-card-to-discard prompt resolvePendingAction opens for humanDiscardNeededSeatId,
      // reusing discard_to_hand_size's picker UI. Only an agent seat gets auto-resolved here.
      if (seat.kind === "human") humanDiscardNeededSeatId = seat.id;
      else discarders.push(seat.id);
    }
  }
  // Sacrifices resolve through the same destroyCreatures pipeline every other death path uses
  // (combat, removal, state-based) so death triggers fire correctly for each of them — Blood
  // Artist's controller draining life off a Plaguecrafter-forced sacrifice needs exactly this, not
  // a direct graveyard move that would silently skip the death-trigger scan entirely.
  let next = destroyCreatures(session, destructions, "Rules action");
  for (const seatId of discarders) {
    const seat = next.seats.find((item) => item.id === seatId);
    const discard = seat ? chooseWorstHandCardToDiscard(seat) : undefined;
    if (!seat || !discard) continue;
    next = moveCardBetweenVisibleZones(next, seatId, discard.id, "graveyard");
    next = {
      ...next,
      events: [
        {
          id: crypto.randomUUID(),
          at: new Date().toISOString(),
          seatId,
          message: `${seat.name} can't sacrifice a ${effect.typeFilter} and discards ${discard.name} instead.`,
          detail: "Rules action"
        },
        ...next.events
      ]
    };
  }
  return { session: next, humanDiscardNeededSeatId, humanSacrificeNeededSeatId };
}

// Applies the human controller's OWN pick from a choose_each_player_sacrifice choice — every other
// seat's sacrifice/discard has already resolved by the time this runs (see
// applyEachPlayerSacrificeEffect's humanSacrificeNeededSeatId deferral), so this only ever handles
// the one remaining seat. Routed through destroyCreatures, same reasoning as
// applyEachPlayerSacrificeEffect's own sacrifices, so death triggers (Meren, Blood Artist, ...) fire
// correctly for the human's pick too, not just the auto-resolved ones.
export function applyChosenEachPlayerSacrifice(session: GameSession, seatId: string, cardId: string, sourceCardName: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  const card = seat?.board.battlefield.find((item) => item.id === cardId);
  if (!seat || !card) return session;
  return destroyCreatures(session, [{ seatId, cardId, message: `${seat.name} sacrifices ${card.name} to ${sourceCardName}.` }], "Rules action");
}

// Braids, Arisen Nightmare: "At the beginning of your end step, you may sacrifice an artifact, creature, enchantment, land, or planeswalker.
// If you do, each opponent may sacrifice a permanent of their choice that shares a card type with it. For each opponent who doesn't, that
// player loses 2 life and you draw a card." A human answers each "may" through a picker (closing it declines); agents decide by heuristic.
export function isBraidsEndStepText(oracleText: string): boolean {
  return /\bat the beginning of your end step, you may sacrifice an artifact, creature, enchantment, land, or planeswalker\b.*\beach opponent may sacrifice\b/is.test(oracleText);
}

// "Repeat the following process X times. Each opponent loses N life unless that player sacrifices a
// nonland permanent or discards a card." (Torment of Hailfire, and the same "punisher" template on
// similarly-worded cards) — X is the spell's own chosenX (the same X-cost convention
// entersWithXCounters/multikicker already use elsewhere), not parsed out of the text itself.
export function parsePunisherChoiceEffect(text: string): { lifeAmount: number } | undefined {
  const match = text
    .toLowerCase()
    .match(/\brepeat the following process \w+ times\.\s*each opponent loses (\d+) life unless that player sacrifices an? nonland permanent(?: of their choice)? or discards a card\b/);
  if (!match) return undefined;
  return { lifeAmount: Number(match[1]) };
}

// No interactive choice exists for a non-controller seat anywhere in this engine yet (the interactive-
// targeting plan tracks per-controller choices as future work; a choice belonging to someone OTHER
// than the spell's own controller isn't even scoped there) — so, same as applyEachPlayerSacrificeEffect
// just below auto-deciding everyone's sacrifice for them, every affected opponent's outcome here is
// auto-decided by a heuristic regardless of seat kind: keep the life loss while it's not dangerous
// (a small, bounded per-iteration amount against Commander's 40 starting life rarely is), otherwise
// give up whatever's cheapest to lose first — a token permanent, then a spare hand card, then a real
// nonland permanent — before finally accepting the life loss as a last resort with nothing left to
// spend. Previously fell entirely to the LLM fallback with no deterministic path at all, and reported
// live as no choice ever being offered to the affected opponent for what the effect actually did.
export function applyPunisherChoiceEffect(session: GameSession, casterSeatId: string, sourceCardName: string, effect: { lifeAmount: number }, times: number): GameSession {
  let next = session;
  // A human victim chooses (lose the life, sacrifice, or discard) each time; their repetitions are queued for the picker.
  const humanVictims = session.seats.filter((seat) => seat.id !== casterSeatId && !seat.hasLost && seat.kind === "human");
  if (humanVictims.length > 0 && times > 0) {
    next = { ...next, pendingPunisherChoices: [...(next.pendingPunisherChoices ?? []), ...humanVictims.map((seat) => ({ seatId: seat.id, sourceName: sourceCardName, lifeAmount: effect.lifeAmount, times }))] };
  }
  for (let iteration = 0; iteration < times; iteration++) {
    for (const seat of next.seats) {
      if (seat.id === casterSeatId || seat.hasLost || seat.kind === "human") continue;
      const current = next.seats.find((item) => item.id === seat.id);
      if (!current) continue;
      const survivesComfortably = current.life - effect.lifeAmount > 10;
      const sacrificeCandidate = survivesComfortably ? undefined : chooseNonlandPermanentToSacrifice(current);
      const tokenToSacrifice = sacrificeCandidate?.token ? sacrificeCandidate : undefined;
      const discardTarget = !survivesComfortably && !tokenToSacrifice ? chooseWorstHandCardToDiscard(current) : undefined;
      const permanentToSacrifice = !discardTarget && !tokenToSacrifice ? sacrificeCandidate : undefined;
      if (tokenToSacrifice) {
        next = destroyCreatures(
          next,
          [{ seatId: seat.id, cardId: tokenToSacrifice.id, message: `${current.name} sacrifices ${tokenToSacrifice.name} to avoid losing ${effect.lifeAmount} life to ${sourceCardName}.` }],
          "Rules action"
        );
      } else if (discardTarget) {
        next = moveCardBetweenVisibleZones(next, seat.id, discardTarget.id, "graveyard");
        next = {
          ...next,
          events: [
            {
              id: crypto.randomUUID(),
              at: new Date().toISOString(),
              seatId: seat.id,
              message: `${current.name} discards ${discardTarget.name} to avoid losing ${effect.lifeAmount} life to ${sourceCardName}.`,
              detail: "Rules action"
            },
            ...next.events
          ]
        };
      } else if (permanentToSacrifice) {
        next = destroyCreatures(
          next,
          [{ seatId: seat.id, cardId: permanentToSacrifice.id, message: `${current.name} sacrifices ${permanentToSacrifice.name} to avoid losing ${effect.lifeAmount} life to ${sourceCardName}.` }],
          "Rules action"
        );
      } else {
        next = {
          ...next,
          seats: next.seats.map((item) => (item.id === seat.id ? { ...item, life: Math.max(0, item.life - effect.lifeAmount) } : item)),
          events: [
            {
              id: crypto.randomUUID(),
              at: new Date().toISOString(),
              seatId: seat.id,
              message: `${current.name} loses ${effect.lifeAmount} life to ${sourceCardName}.`,
              detail: "Rules action"
            },
            ...next.events
          ]
        };
      }
    }
  }
  return next;
}

// "Each player exiles all creature cards from their graveyard, then sacrifices all creatures they
// control, then puts all cards they exiled this way onto the battlefield." (Living Death) — no
// existing effect kind models this "snapshot state, act on everyone, then reanimate exactly what
// was snapshotted" three-step combo (closest is applyEachPlayerSacrificeEffect's "everyone does
// this to themselves" shape just above, but that's a single step with no ordering dependency),
// so it's its own bespoke shape, applied unconditionally to every seat, like that one. Previously
// unhandled by any deterministic parser, reported live as "Living Death did not work."
export function isLivingDeathEffect(text: string): boolean {
  return /\beach player exiles all creature cards from their graveyard,\s*then sacrifices all creatures they control,\s*then puts all cards they exiled this way onto the battlefield\b/i.test(
    text
  );
}

export function applyLivingDeathEffect(session: GameSession, sourceCardName: string): GameSession {
  // Step 1: snapshot and exile each player's own graveyard creatures FIRST, before anything else
  // moves — the creatures that die in step 2 must land in the graveyard as normal (this same spell
  // doesn't bring those back too), only what was already in the graveyard when Living Death resolved.
  let next = session;
  const exiledIdsBySeat = new Map<string, string[]>();
  for (const seat of session.seats) {
    const creatureCardIds = (seat.board.graveyard ?? []).filter((card) => card.typeLine.includes("Creature")).map((card) => card.id);
    if (creatureCardIds.length === 0) continue;
    exiledIdsBySeat.set(seat.id, creatureCardIds);
    for (const cardId of creatureCardIds) {
      next = moveCardBetweenVisibleZones(next, seat.id, cardId, "exile");
    }
  }

  // Step 2: each player sacrifices every creature they control.
  const destructions: Array<{ seatId: string; cardId: string; message: string }> = [];
  for (const seat of next.seats) {
    for (const card of seat.board.battlefield) {
      if (card.typeLine.includes("Creature")) destructions.push({ seatId: seat.id, cardId: card.id, message: `${seat.name} sacrifices ${card.name} to ${sourceCardName}.` });
    }
  }
  next = destroyCreatures(next, destructions, "Rules action");

  // Step 3: each player puts all the cards THEY exiled this way (step 1's snapshot, not anything
  // else that might separately reach exile in between) onto the battlefield under their own control.
  for (const [seatId, cardIds] of exiledIdsBySeat) {
    for (const cardId of cardIds) {
      next = moveCardAcrossSeats(next, seatId, cardId, seatId, "battlefield").session;
    }
  }
  return next;
}

export function spellResolutionDestination(session: GameSession, action: Extract<PendingAction, { type: "spell" }>): "battlefield" | "graveyard" | "exile" | "library" {
  const actor = session.seats.find((seat) => seat.id === action.actorSeatId);
  const card =
    action.sourceZone === "command"
      ? actor?.board.commander
      : action.sourceZone === "exile"
        ? actor?.board.exile?.find((item) => item.id === action.cardId)
        : action.sourceZone === "graveyard"
          ? actor?.board.graveyard?.find((item) => item.id === action.cardId)
          : action.sourceZone === "library"
            ? actor?.library?.find((item) => item.id === action.cardId)
            : actor?.board.hand.find((item) => item.id === action.cardId);
  if (!card) return "graveyard";
  // A two-faced card's own typeLine is the combined "Creature — Dragon // Sorcery — Omen" string,
  // which contains "Sorcery" regardless of which face was actually cast — checking it directly here
  // meant casting the CREATURE face of a card like Scavenger Regent still (accidentally, only
  // "correctly" for the other face) sent it to the graveyard instead of the battlefield. Applying
  // the chosen face first (same as findSpellSourceCard's own sourceCard derivation) makes this read
  // whichever face was actually paid for.
  const effectiveCard = applyChosenFaceToCard(card, action.faceIndex);
  // Adventure (rule 715): casting the smaller spell half doesn't send the card to the graveyard —
  // the rest of the card (its permanent half) is exiled instead, castable later for as long as it
  // remains there (see playCardFromZone's "exile" branch, which stamps exiledPlayableBySeatId).
  if (effectiveCard.typeLine.includes("Adventure")) return "exile";
  // Omen (Tarkir: Dragonstorm): same "smaller spell half, rest of the card goes elsewhere" shape as
  // Adventure, but shuffled into the owner's library instead of exiled — nothing carries over to
  // let it be cast again later the way Adventure's exile does.
  if (effectiveCard.typeLine.includes("Omen")) return "library";
  // "Exile Finale of Revelation." as the spell's own last sentence: it is exiled as it finishes resolving instead of going to the graveyard.
  if ((effectiveCard.typeLine.includes("Instant") || effectiveCard.typeLine.includes("Sorcery")) && effectiveCard.oracleText.split("\n").some((line) => { const lower = line.trim().toLowerCase(); const own = `exile ${effectiveCard.name.toLowerCase()}.`; return lower === own || lower.endsWith(` ${own}`); })) return "exile";
  // Flashback (rule 702.34a): an instant or sorcery cast with flashback is exiled instead of going anywhere
  // else when it would leave the stack. A flashback PERMANENT just enters the battlefield as normal.
  if (action.flashback && (effectiveCard.typeLine.includes("Instant") || effectiveCard.typeLine.includes("Sorcery"))) return "exile";
  return effectiveCard.typeLine.includes("Instant") || effectiveCard.typeLine.includes("Sorcery") ? "graveyard" : "battlefield";
}

// Rule 205.2j: an object is historic if it's an artifact, a Saga (or other subtype with the same
// carve-out), or has the legendary supertype — legendary creatures/enchantments/planeswalkers all
// qualify via "Legendary" appearing in the type line, not just legendary artifacts.

function twoSidedFaces(card: VisibleCard): [CardFaceRecord, CardFaceRecord] | undefined {
  if (!card.faces || card.faces.length !== 2) return undefined;
  return [card.faces[0], card.faces[1]];
}

// Scryfall's own convention for a transform back face: it always opens with this exact
// parenthetical reminder ("(Transforms from Storm the Vault.)", "(Transforms from Azor's
// Gateway.)", ...), never present on a genuine modal DFC's own back face (Zendikar Rising's
// "land // spell" cycle, the Pathway/battle lands, ...), which just states its own rules text
// directly. This is the only reliable signal available at runtime: this app's card data never
// stores Scryfall's own `layout` field (transform vs modal_dfc), only face shapes.
function isTransformBackFace(face: CardFaceRecord): boolean {
  return /^\(transforms from /i.test(face.oracleText.trim());
}

export function modalDoubleFacedLandSplit(card: VisibleCard): { spellFace: CardFaceRecord; spellIndex: number; landFace: CardFaceRecord; landIndex: number } | undefined {
  const faces = twoSidedFaces(card);
  if (!faces) return undefined;
  const [first, second] = faces;
  // A transform card's back face (Westvale Abbey -> Ormendahl, Profane Prince; Storm the Vault ->
  // Vault of Catlacan; any other permanent that flips into something else via an in-play ability)
  // is never castable from hand — Scryfall represents that by leaving its manaCost empty, unlike a
  // genuine modal DFC land (Zendikar Rising-style "land // spell") whose spell face always carries
  // a real printed cost. That alone only distinguishes a transform card whose back face is the
  // NON-land side (Westvale Abbey): a transform card whose back face IS a land (Storm the Vault,
  // Azor's Gateway, Arguel's Blood Fast, ...) has the exact same shape as a real modal DFC land
  // from this manaCost check's perspective (front has a real cost, back — being a land — never
  // does either way), so isTransformBackFace's reminder-text check is what actually tells them
  // apart. Without it, "cast the land side" was offered for a transform permanent whose back face
  // can only ever be reached by transforming, never played from hand at all. Reported live for
  // Storm the Vault // Vault of Catlacan.
  if (!first.typeLine.includes("Land") && second.typeLine.includes("Land") && first.manaCost && !isTransformBackFace(second)) {
    return { spellFace: first, spellIndex: 0, landFace: second, landIndex: 1 };
  }
  if (first.typeLine.includes("Land") && !second.typeLine.includes("Land") && second.manaCost && !isTransformBackFace(first)) {
    return { spellFace: second, spellIndex: 1, landFace: first, landIndex: 0 };
  }
  return undefined;
}

export function roomDoorFaces(card: VisibleCard): [CardFaceRecord, CardFaceRecord] | undefined {
  const faces = twoSidedFaces(card);
  if (!faces) return undefined;
  return faces.every((face) => face.typeLine.includes("Room")) ? faces : undefined;
}

// Two faces that are each independently castable as their own spell — Adventure (Bonecrusher
// Giant // Stomp) and Omen (Scavenger Regent // Exude Toxin) cards, where the "front" permanent
// face and a smaller instant/sorcery back face both have their own real printed mana cost, unlike
// modalDoubleFacedLandSplit's land+spell shape (where only one face is ever cast) or a transform
// permanent's back face (empty manaCost, per modalDoubleFacedLandSplit's own comment — never
// castable from hand at all). Without this, a Creature//Sorcery card like Scavenger Regent had no
// way to be cast as its sorcery face specifically: it always resolved as the single fused,
// combined-oracleText pseudo-card built from both faces mashed together, so the sorcery's own
// effect text was never what actually ran.
export function independentlyCastableSpellFaces(card: VisibleCard): [CardFaceRecord, CardFaceRecord] | undefined {
  const faces = twoSidedFaces(card);
  if (!faces) return undefined;
  const [first, second] = faces;
  if (first.typeLine.includes("Land") || second.typeLine.includes("Land")) return undefined;
  if (first.typeLine.includes("Room") || second.typeLine.includes("Room")) return undefined;
  if (!first.manaCost || !second.manaCost) return undefined;
  return faces;
}

// A SPLIT card (Find // Finality, Fire // Ice, Turn // Burn, Appeal // Authority): two spell halves side by side. Rule 708.4: in every zone but the
// stack it has the combined characteristics of both halves (so its card-level manaValue is the SUM, 8 for Find // Finality); only on the stack does it
// have just the one half that was cast. An Adventure / Omen card (Bonecrusher Giant // Stomp) is also two castable faces, but is not a split card.
export function isSplitSpellCard(card: VisibleCard): boolean {
  const faces = independentlyCastableSpellFaces(card);
  return Boolean(faces && !faces.some((face) => /Adventure|Omen/.test(face.typeLine)));
}

// "Aftermath (Cast this spell only from your graveyard.)" - that half is never castable from the hand.
export function spellFaceCastableFromHand(face: CardFaceRecord): boolean {
  return !/^\s*aftermath\b/im.test(face.oracleText);
}

// The card as it is while ONE half is being cast: that half's own name, type, text, cost and mana value (rule 708.4 / 715.3), so cost reducers,
// timing, targets and affordability all read the half and never the combined card.
export function spellFaceCostCard(card: VisibleCard, face: CardFaceRecord): VisibleCard {
  return { ...card, name: face.name, typeLine: face.typeLine, oracleText: face.oracleText, manaCost: face.manaCost, manaValue: manaValueFromManaCost(face.manaCost) };
}

export interface CastFaceOption {
  faceIndex: number;
  faceName: string;
  label: string;
  /** Timing, aftermath and target rules allow casting this half right now. */
  castable: boolean;
  /** The half's OWN cost (after reductions, not counting X) can be paid. */
  payable: boolean;
}

// One entry per castable half of a split / Adventure card, each priced from its OWN cost. A human pays from the floating pool; an agent from untapped sources.
// `session` (optional) adds the timing and legal-target checks per half; without it only the aftermath rule is applied.
export function castFaceOptions(
  seat: PlayerSeat,
  card: VisibleCard,
  activeSeatId: string | undefined,
  pool: ManaPool | undefined,
  allSeats: PlayerSeat[],
  session?: GameSession,
  response = false
): CastFaceOption[] | undefined {
  const faces = independentlyCastableSpellFaces(card);
  if (!faces) return undefined;
  return faces.map((face, index) => {
    const costCard = spellFaceCostCard(card, face);
    const fixedCost = adjustedCastingCost(seat, costCard, costCard.manaValue, "hand", activeSeatId, allSeats);
    // Only the non-X portion has to be payable to offer the half at all (X = 0 is always legal).
    const payable = pool ? payCostFromPool(pool, costCard, fixedCost).ok : chooseManaSourcesForCost(seat, costCard, fixedCost, undefined, allSeats).ok;
    let castable = spellFaceCastableFromHand(face);
    if (castable && session) {
      const instant = canCastAtInstantSpeed(costCard, seatHasFlashGrant(seat, costCard));
      const sorcerySpeedOk = !response && activeSeatId === seat.id && isMainPhase(session.phase);
      castable = (instant || sorcerySpeedOk) && hasResolvableTarget(session, seat.id, costCard);
    }
    return { faceIndex: index, faceName: face.name, label: `Cast ${face.name} (${face.manaCost ?? "no cost"})`, castable, payable };
  });
}

export type CastFaceDecision =
  | { kind: "none" }
  | { kind: "unpayable"; options: CastFaceOption[] }
  | { kind: "single"; faceIndex: number; options: CastFaceOption[] }
  | { kind: "choose"; options: CastFaceOption[] };

// What casting a multi-half card from the hand should do when the caller did not say which half: nothing to decide (an ordinary card), no half is
// castable right now, exactly one is (just cast that one), or several are (the human must be asked which one).
export function castFaceDecision(session: GameSession, seat: PlayerSeat, card: VisibleCard, activeSeatId: string | undefined, pool?: ManaPool, response = false): CastFaceDecision {
  const options = castFaceOptions(seat, card, activeSeatId, pool, session.seats, session, response);
  if (!options) return { kind: "none" };
  const usable = options.filter((option) => option.castable && option.payable);
  if (usable.length === 0) return { kind: "unpayable", options };
  if (usable.length === 1) return { kind: "single", faceIndex: usable[0].faceIndex, options };
  return { kind: "choose", options };
}

// A fake card carrying a GenericManaAbility's raw cost text as its manaCost, so
// chooseManaSourcesForCost/manaRequirementForCost can pull the correct colored requirement out of
// it the same way they already do for a real card's casting cost — genericCostShim's plain numeric
// amount has no color information, which silently treated a colored activation cost (Greed's
// "{B}, Pay 2 life: Draw a card.") as free, since its digit-only mana-symbol sum found no digits.
// The cost of an ability with an {X} (Fiend Artisan) once X is chosen: {X} becomes that many generic mana (or nothing at 0).
function abilityCostWithX(ability: SacrificeAbility, x: number): SacrificeAbility {
  return { ...ability, costManaText: ability.costManaText.replace(/{X}/gi, x > 0 ? `{${x}}` : "") };
}

// The X an {X} ability is activated with: the cheapest X that reaches the best creature card in the library the controller can afford, so
// no mana is paid for a card that cannot be fetched. Undefined when nothing can be fetched (no creature card at or below what is affordable).
function chooseAbilityX(session: GameSession, seat: PlayerSeat, card: VisibleCard, ability: SacrificeAbility): number | undefined {
  if (!ability.costX) return 0;
  const creatureValues = (seat.library ?? []).filter((candidate) => candidate.typeLine.includes("Creature")).map((candidate) => candidate.manaValue);
  if (creatureValues.length === 0) return undefined;
  let maxX = -1;
  for (let x = 0; x <= 15; x += 1) {
    const paying = abilityCostWithX(ability, x);
    const total = manaValueFromManaCost(paying.costManaText);
    if (total > 0 && !chooseManaSourcesForCost(seat, genericManaAbilityCostShim(paying), total, card.id, session.seats).ok) break;
    maxX = x;
  }
  if (maxX < 0) return undefined;
  const reachable = creatureValues.filter((value) => value <= maxX);
  return reachable.length > 0 ? Math.max(...reachable) : undefined;
}

// Rule 118.4: a life-payment cost can't be paid if it would take the payer below 0 life.
// Agent policy for "Pay N life: Untap all lands you control." (Beledros Witherbloom). The ability is legal for anyone with the life, but
// paying 10 life is only right when it buys something real: a spell worth casting (mana value 4+) that the lands still untapped cannot
// pay for NOW but the full set of lands can, and only while the payment leaves a safe life total (20+) so it never walks into lethal.
export const UNTAP_LANDS_SAFE_LIFE = 20;
export function untapAllLandsIsWorthIt(seat: PlayerSeat, costLife: number, allSeats?: PlayerSeat[]): boolean {
  if (seat.life - costLife < UNTAP_LANDS_SAFE_LIFE) return false;
  const untappedSeat: PlayerSeat = {
    ...seat,
    board: { ...seat.board, battlefield: seat.board.battlefield.map((card) => (card.tapped && card.typeLine.includes("Land") ? { ...card, tapped: false } : card)) }
  };
  return seat.board.hand.some(
    (card) =>
      !card.typeLine.includes("Land") &&
      card.manaValue >= 4 &&
      !chooseManaSourcesForCost(seat, card, card.manaValue, undefined, allSeats).ok &&
      chooseManaSourcesForCost(untappedSeat, card, card.manaValue, undefined, allSeats).ok
  );
}

// "Exile this enchantment: Shuffle your graveyard into your library." (Enhanced Surveillance). The shuffle is only worth the card when it
// protects or recovers something: (a) an opponent's spell/ability on the stack is about to exile or otherwise gut the graveyard, or (b) the
// library is nearly empty and the graveyard holds cards that would keep the seat from decking, or (c) a big graveyard that is not a
// resource (no recursion in play) while the library is thinning. A reanimator's graveyard is its engine, so it is never shuffled away
// without a graveyard-hate response. Empty graveyard: never (nothing to protect or recover).
const GRAVEYARD_HATE_TEXT = /\bexile\b[^.]{0,80}\bgraveyards?\b|\bexile target card from a graveyard\b|\bexile (?:all )?cards? from (?:a|target|each|all)\b[^.]{0,40}graveyards?|\binto a graveyard from anywhere, exile it instead\b|\bgraveyards? (?:is|are) exiled\b/i;
export function graveyardHateOnStack(session: GameSession, seat: PlayerSeat, stack: PendingAction[]): boolean {
  return stack.some((item) => {
    if (item.actorSeatId === seat.id) return false;
    if (item.type === "trigger" && item.controllerSeatId === seat.id) return false;
    const text = (pendingActionSourceCard(session, item)?.oracleText ?? "").replace(/\([^)]*\)/g, "");
    return GRAVEYARD_HATE_TEXT.test(text);
  });
}
function graveyardIsResource(seat: PlayerSeat): boolean {
  const cards = [...seat.board.battlefield, ...seat.board.hand, ...(seat.board.commander ? [seat.board.commander] : [])];
  return cards.some((card) => !card.abilitiesStripped && /\b(?:from|in) (?:your|a) graveyard\b/i.test(card.oracleText));
}
export function graveyardShuffleIsWorthIt(session: GameSession, seat: PlayerSeat, stack: PendingAction[] = []): boolean {
  const graveyardSize = seat.board.graveyard?.length ?? 0;
  if (graveyardSize === 0) return false;
  if (graveyardHateOnStack(session, seat, stack)) return true;
  const librarySize = seat.library?.length ?? 0;
  if (librarySize <= 5 && graveyardSize >= 3) return true;
  if (graveyardSize >= 10 && librarySize <= 20 && !graveyardIsResource(seat)) return true;
  return false;
}

function genericManaAbilityAffordable(seat: PlayerSeat, ability: GenericManaAbility, allSeats?: PlayerSeat[]): boolean {
  if (seat.life < ability.costLife) return false;
  const totalCost = manaValueFromManaCost(ability.costManaText);
  return totalCost === 0 || chooseManaSourcesForCost(seat, genericManaAbilityCostShim(ability), totalCost, undefined, allSeats).ok;
}

function attackTaxEffectsFor(defender: PlayerSeat, targetIsPlaneswalker: boolean): InterpretedEffect[] {
  return defender.board.battlefield
    .flatMap((card) => card.interpretedEffects ?? [])
    .filter((effect) => {
      if (effect.kind !== "attack_tax") return false;
      return targetIsPlaneswalker ? effect.appliesTo !== "controller" : effect.appliesTo !== "planeswalkers";
    });
}

// Sum of all attack-tax effects the defending seat has in play, evaluated against their current
// board state (e.g. Sphere of Safety's per-enchantment amount can change turn to turn).
export function totalAttackTax(defender: PlayerSeat, targetIsPlaneswalker: boolean): number {
  const enchantmentCount = defender.board.battlefield.filter((card) => card.typeLine.includes("Enchantment")).length;
  // "As long as this creature is untapped, creatures can't attack you or planeswalkers you control unless their controller
  // pays {1} for each of those creatures." (Archangel of Tithes) — read straight from the text, for cards the interpreter
  // hasn't already turned into an attack_tax effect.
  const textTax = defender.board.battlefield
    .filter((card) => !card.abilitiesStripped && !(card.interpretedEffects ?? []).some((effect) => effect.kind === "attack_tax"))
    .reduce((total, card) => {
      const match = card.oracleText.match(/creatures can'?t attack you or planeswalkers you control unless their controller pays \{(\d+)\} for each of those creatures/i);
      if (!match) return total;
      if (/as long as this creature is untapped/i.test(card.oracleText) && card.tapped) return total;
      return total + Number.parseInt(match[1], 10);
    }, 0);
  return (
    textTax +
    attackTaxEffectsFor(defender, targetIsPlaneswalker).reduce((total, effect) => total + effectiveAttackTaxAmount(effect, enchantmentCount), 0)
  );
}

function applyChosenFaceToCard(card: VisibleCard, faceIndex: number | undefined): VisibleCard {
  const face = faceIndex !== undefined ? card.faces?.[faceIndex] : undefined;
  if (!face) return card;
  return {
    ...card,
    name: face.name,
    typeLine: face.typeLine,
    oracleText: face.oracleText,
    manaCost: face.manaCost,
    power: face.power,
    toughness: face.toughness,
    loyalty: face.loyalty,
    imageUris: face.imageUris ?? card.imageUris,
    unlockedFaceIndices: [faceIndex as number]
  };
}

function unlockSecondRoomDoor(card: VisibleCard, newFaceIndex: number): VisibleCard {
  const doors = roomDoorFaces(card);
  if (!doors) return card;
  const [firstDoor, secondDoor] = doors;
  const alreadyUnlocked = card.unlockedFaceIndices ?? [];
  const nextUnlocked = Array.from(new Set([...alreadyUnlocked, newFaceIndex])).sort();
  return {
    ...card,
    name: `${firstDoor.name} // ${secondDoor.name}`,
    typeLine: "Enchantment — Room",
    oracleText: `${firstDoor.name}: ${firstDoor.oracleText}\n\n${secondDoor.name}: ${secondDoor.oracleText}`,
    unlockedFaceIndices: nextUnlocked
  };
}

export interface HandCardFaceOption {
  faceIndex: number;
  actionKind: "play_land" | "cast_spell";
  label: string;
  payable: boolean;
}

export function handCardFaceOptions(
  seat: PlayerSeat,
  card: VisibleCard,
  hasPlayedLand: boolean,
  activeSeatId: string | undefined,
  manaPool: ManaPool,
  allSeats: PlayerSeat[],
  session?: GameSession
): HandCardFaceOption[] | undefined {
  const split = modalDoubleFacedLandSplit(card);
  if (split) {
    const spellCost = adjustedCastingCost(seat, card, card.manaValue, "hand", activeSeatId, allSeats);
    const spellPayment = payCostFromPool(manaPool, card, spellCost);
    return [
      {
        faceIndex: split.landIndex,
        actionKind: "play_land",
        label: `Play ${split.landFace.name} (land)`,
        payable: !hasPlayedLand
      },
      {
        faceIndex: split.spellIndex,
        actionKind: "cast_spell",
        label: `Cast ${split.spellFace.name} (${split.spellFace.manaCost ?? "no cost"})`,
        payable: spellPayment.ok
      }
    ];
  }

  const doors = roomDoorFaces(card);
  if (doors) {
    return doors.map((door, index) => {
      const shim = cardWithFaceManaCost(card, door.manaCost);
      const totalCost = adjustedCastingCost(seat, shim, manaValueFromManaCost(door.manaCost), "hand", activeSeatId, allSeats);
      const payment = payCostFromPool(manaPool, shim, totalCost);
      return {
        faceIndex: index,
        actionKind: "cast_spell" as const,
        label: `Cast ${door.name} (${door.manaCost ?? "no cost"})`,
        payable: payment.ok
      };
    });
  }

  // Split / Adventure / Omen cards: one button per half, each priced from its OWN cost and greyed out unless that half is castable now (affordable,
  // right timing, a legal target, not an aftermath half).
  const faceOptions = castFaceOptions(seat, card, activeSeatId, manaPool, allSeats, session);
  if (faceOptions) {
    return faceOptions.map((option) => ({
      faceIndex: option.faceIndex,
      actionKind: "cast_spell" as const,
      label: option.label,
      payable: option.payable && option.castable
    }));
  }

  return undefined;
}

// flashGranted covers a battlefield static effect like Vedalken Orrery/Leyline of Anticipation
// ("you may cast spells as though they had flash") — see seatHasFlashGrant below, whose scan this
// card-level check can't do on its own (a card only knows its own type line/oracle text, never
// what's sitting elsewhere on its controller's battlefield). Defaults to false so every existing
// call site keeps its current behavior until it's updated to pass the seat's actual grant status.
function canCastAtInstantSpeed(card: VisibleCard, flashGranted = false) {
  // "You may cast this spell as though it had flash if it targets a commander." (Timely Ward) is a conditional permission, not the Flash keyword.
  const printedFlash = /\bflash\b/i.test(card.oracleText.replace(/as though it had flash/gi, ""));
  return card.typeLine.includes("Instant") || printedFlash || flashGranted;
}

// Scoped narrowly to what a priority-response decision needs: battlefield-only, no "spells of the
// chosen type" variants, no layer-system involvement. A card's own printed Flash is still handled
// entirely by canCastAtInstantSpeed itself; this only covers a SEPARATE permanent granting it.
// "You may cast spells as though they had flash." (Leyline of Anticipation, Vedalken Orrery) grants every spell; "You may cast green creature
// spells as though they had flash." (Yeva, Nature's Herald) only the ones it describes (pass the card to check). Reminder text is ignored:
// a creature that merely HAS flash ("(You may cast this spell any time you could cast an instant.)") grants nothing to anything else.
// "Creatures and enchantments you control have 'Spells your opponents cast that target this permanent cost {1} more to cast.'" (Callaphe,
// Beloved of the Sea, and the same tax printed directly on a permanent, as with Sphere of Safety-style cards): {1} more for each chosen
// target that carries it and belongs to an opponent of the caster.
export function targetingTax(session: GameSession, casterSeatId: string, targets: ChosenTarget[]): number {
  let tax = 0;
  for (const target of targets) {
    if (target.kind !== "card" || target.seatId === casterSeatId) continue;
    const owner = session.seats.find((seat) => seat.id === target.seatId);
    const targeted = owner?.board.battlefield.find((card) => card.id === target.cardId);
    if (!owner || !targeted) continue;
    const grants = owner.board.battlefield.some(
      (source) =>
        !source.abilitiesStripped &&
        /creatures and enchantments you control have "spells your opponents cast that target this permanent cost \{1\} more to cast\."/i.test(source.oracleText) &&
        (targeted.typeLine.includes("Creature") || targeted.typeLine.includes("Enchantment"))
    );
    if (grants || /\bspells your opponents cast that target this (?:permanent|creature) cost \{1\} more to cast\b/i.test(targeted.oracleText)) tax += 1;
  }
  return tax;
}

export function seatHasFlashGrant(seat: PlayerSeat, card?: VisibleCard): boolean {
  // Timely Ward: flash only if it can target a commander (this checks the caster's own commander on the battlefield).
  if (card && /cast this spell as though it had flash if it targets a commander/i.test(card.oracleText) && seat.board.battlefield.some((permanent) => permanent.commander)) return true;
  return seat.board.battlefield.some((source) => {
    if (source.abilitiesStripped) return false;
    const text = source.oracleText.replace(/\([^)]*\)/g, "");
    if (/\byou may cast spells as though they had flash\b/i.test(text)) return true;
    const scoped = text.match(/\byou may cast ([a-z ]+?) spells as though they had flash\b/i);
    return Boolean(scoped && card && permanentMatchesQualifier(card, scoped[1]) && !card.typeLine.includes("Land"));
  });
}

// Is any seat's attacking creature currently declared against this seat — as the defending player
// directly, or as the controller of an attacked planeswalker (resolveAttackTarget covers both). Used
// by the priority-stop policy's "I'm being attacked" condition; combat-state-only (attacking/
// attackTargetId are cleared at cleanupCombat), so this is naturally false outside combat.
function seatIsBeingAttacked(session: GameSession, seatId: string): boolean {
  return session.seats.some((attackerSeat) =>
    attackerSeat.board.battlefield.some((card) => card.attacking && resolveAttackTarget(session, card.attackTargetId)?.seat.id === seatId)
  );
}

function canPayForCard(seat: PlayerSeat, card: VisibleCard) {
  return chooseManaSourcesForCost(seat, card, card.manaValue).ok;
}

function chooseAgentMainPhaseCard(seat: PlayerSeat, hasPlayedLand: boolean) {
  const unplayedLand = seat.board.hand.find((card) => isLandCard(card));
  if (unplayedLand && !hasPlayedLand) return unplayedLand;

  const playableSpells = seat.board.hand
    .filter((card) => !isLandCard(card))
    .filter((card) => chooseManaSourcesForCost(seat, card, adjustedCastingCost(seat, card, card.manaValue, "hand", seat.id)).ok)
    .sort((left, right) => right.manaValue - left.manaValue);
  return playableSpells[0];
}

function inferColors(commander: string) {
  const lower = commander.toLowerCase();
  const matched = Object.entries(COMMANDER_COLOR_HINTS).find(([hint]) => lower.includes(hint));
  return matched?.[1] ?? ["G", "W"];
}

function fallbackCommander(name: string) {
  if (name.includes("Malik")) return "Saheeli, the Gifted";
  if (name.includes("Sable")) return "Meren of Clan Nel Toth";
  if (name.includes("Veyra")) return "The Ur-Dragon";
  return "Atraxa, Praetors' Voice";
}

export function resolveAgentMulligans(seats: PlayerSeat[]) {
  const mulligans: Record<string, number> = {};
  const keptHands: Record<string, boolean> = {};
  const events: GameEvent[] = [];

  const resolvedSeats = seats.map((seat) => {
    if (seat.kind !== "agent") return seat;
    let nextSeat = seat;
    let count = 0;
    while (!agentKeepsHand(nextSeat, count) && count < MULLIGAN_HARD_CAP) {
      if (count >= MULLIGAN_SOFT_CAP && nextSeat.board.hand.some(isLandCard)) break;
      count += 1;
      nextSeat = withOpeningHand(nextSeat, 7, count);
    }
    mulligans[seat.id] = count;
    keptHands[seat.id] = true;
    nextSeat = keepOpeningHandSize(nextSeat, openingHandKeepSize(count));
    events.push({
      id: crypto.randomUUID(),
      at: new Date().toISOString(),
      seatId: seat.id,
      message: describeMulliganOutcome(seat.name, count)
    });
    return nextSeat;
  });

  return { seats: resolvedSeats, mulligans, keptHands, events };
}

function agentKeepsHand(seat: PlayerSeat, mulligansTaken = 0) {
  return evaluateOpeningHand(seat, mulligansTaken).keep;
}

// The user's own stated preference: a 4-card hand (mulligan count 4, see openingHandKeepSize below)
// is as far down as it's worth going for a normal bad hand — beyond that the card disadvantage
// outweighs any improvement in quality. MULLIGAN_HARD_CAP is the one exception: a hand that still
// has no land at all past the soft cap is unplayable regardless, so it's worth pushing further,
// up to this absolute safety valve so a persistently landless shuffle can't loop forever.
const MULLIGAN_SOFT_CAP = 4;
const MULLIGAN_HARD_CAP = 6;

// This table's house rule: the first mulligan is a free "friendly mulligan" (fresh 7, no cards
// bottomed), and the standard London mulligan (rule 103.5, bottom one card per mulligan) only kicks
// in from the second mulligan onward — so 0 or 1 mulligans both keep 7, 2 keeps 6, 3 keeps 5, etc.
// (Not the plain Comprehensive Rules London mulligan, which would bottom a card on the very first
// mulligan too — deliberately different here, confirmed by the user after a wrong "fix" attempt.)
function openingHandKeepSize(mulliganCount: number) {
  if (mulliganCount <= 1) return 7;
  return Math.max(1, 8 - mulliganCount);
}

// Spells out the mulligan count explicitly rather than collapsing every non-mulligan outcome into
// a single "kept 7" — the free mulligan (count 1) also keeps 7, so without this the action log gave
// no way to tell "kept the original hand" apart from "mulliganed once, then kept the fresh 7."
// Reported live: a user unable to tell from the log whether an agent had taken its free mulligan.
function describeMulliganOutcome(seatName: string, count: number): string {
  if (count === 0) return `${seatName} kept the original 7.`;
  if (count === 1) return `${seatName} took the free mulligan and kept a fresh 7.`;
  return `${seatName} mulliganed ${count} times and kept ${openingHandKeepSize(count)}.`;
}

function keepOpeningHandSize(seat: PlayerSeat, keepSize: number, returnCardIds: string[] = [], shuffleReturned = false): PlayerSeat {
  const returnSet = new Set(returnCardIds);
  const chosenReturns = returnCardIds.length > 0 ? seat.board.hand.filter((card) => returnSet.has(card.id)) : seat.board.hand.slice(keepSize);
  const hand = returnCardIds.length > 0 ? seat.board.hand.filter((card) => !returnSet.has(card.id)) : seat.board.hand.slice(0, keepSize);
  const returnedLibraryCards = chosenReturns.map((card) => ({ ...card, zone: "library" as const }));
  const library = [...(seat.library ?? []), ...returnedLibraryCards];
  return {
    ...seat,
    library: shuffleReturned ? shuffleCards(library) : library,
    board: {
      ...seat.board,
      hand
    },
    zones: {
      ...seat.zones,
      hand: hand.length,
      library: (seat.library?.length ?? seat.zones.library) + returnedLibraryCards.length
    }
  };
}

export function withOpeningHand(seat: PlayerSeat, size: number, mulliganCount: number): PlayerSeat {
  const library = makeShuffledLibrary(seat, mulliganCount);
  const hand = library.slice(0, size).map((card) => ({ ...card, zone: "hand" as const }));
  const remainingLibrary = library.slice(size);
  return {
    ...seat,
    library: remainingLibrary,
    board: {
      ...seat.board,
      hand
    },
    zones: {
      ...seat.zones,
      hand: hand.length,
      library: remainingLibrary.length
    }
  };
}

export function makeShuffledLibrary(seat: PlayerSeat, shuffleCount: number) {
  const deckCards = expandDeckCards(seat);
  if (deckCards.length === 0) {
    return Array.from({ length: 99 }, (_, index) =>
      createVisibleFromDeckCard({ name: "Wastes", role: "land" }, [], `${seat.id}-fallback-library-${shuffleCount}-${index}`, "library")
    );
  }
  return shuffleCards(
    deckCards.map((card, index) => createVisibleFromDeckCard(card, seat.deck?.colors ?? [], `${seat.id}-library-${shuffleCount}-${index}-${crypto.randomUUID()}`, "library"))
  );
}

export function expandDeckCards(seat: PlayerSeat) {
  const cards = seat.deck?.cards.filter((card) => card.role !== "commander") ?? [];
  return cards.flatMap((card) => Array.from({ length: card.count }, () => card));
}

// How much an agent wants a looked-at card for Lim-Dûl's Vault (deterministic; higher = keep nearer the top). Lands are
// worth a lot until the seat has ~4 lands, a fair amount until ~7, and little after; spells are worth more the higher their
// mana value, except that something far beyond the seat's current mana is discounted (it can't be cast for a long time).
function limDulCardValue(card: VisibleCard, landCount: number): number {
  if (isLandCard(card)) return landCount < 4 ? 10 : landCount < 7 ? 6 : 2;
  const overBudget = card.manaValue > landCount + 3;
  return 4 + Math.min(card.manaValue, 6) * 0.5 - (overBudget ? 3 : 0);
}

const LIM_DUL_GOOD_CARD_VALUE = 6;
const LIM_DUL_MAX_PAYMENTS = 3;
const LIM_DUL_LIFE_FLOOR = 12; // an agent never pays life that would leave it at or below this
const LIM_DUL_MIN_LIBRARY = 10; // never churn a nearly-empty library

// An AGENT's resolution of Lim-Dûl's Vault (the human gets an interactive flow instead). Deterministic chooser:
//  - Pay 1 life and look again only while fewer than 2 of the 5 looked-at cards are "good" (value >= 6), at most 3 times, only
//    if life stays above 12 and the library has at least 10 cards. The loop is therefore always bounded.
//  - The cards put on the bottom keep the order they were looked at in (unobservable, as with Growing Rites of Itlimoc).
//  - Finally shuffle the rest of the library and put the five last-looked-at cards on top, best card first (it is drawn next).
// The log states only public facts (how much life was paid, that the top cards were arranged), never card names.
export function resolveAgentLimDulVault(session: GameSession, seatId: string, sourceCardName: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return session;
  const library = seat.library ?? [];
  if (library.length === 0) return addLibraryLookEvent(session, seatId, `${seat.name} resolves ${sourceCardName}, but the library is empty.`);
  const landCount = seat.board.battlefield.filter((card) => isLandCard(card)).length + seat.board.hand.filter((card) => isLandCard(card)).length;
  let current = library;
  let life = seat.life;
  let payments = 0;
  let looked = current.slice(0, 5);
  while (
    payments < LIM_DUL_MAX_PAYMENTS &&
    life - 1 > LIM_DUL_LIFE_FLOOR &&
    current.length >= LIM_DUL_MIN_LIBRARY &&
    looked.filter((card) => limDulCardValue(card, landCount) >= LIM_DUL_GOOD_CARD_VALUE).length < 2
  ) {
    life -= 1;
    payments += 1;
    current = [...current.slice(looked.length), ...looked];
    looked = current.slice(0, 5);
  }
  const lookedIds = new Set(looked.map((card) => card.id));
  const ordered = [...looked].sort((a, b) => limDulCardValue(b, landCount) - limDulCardValue(a, landCount));
  const rest = shuffleCards(current.filter((card) => !lookedIds.has(card.id)));
  const nextLibrary = [...ordered.map((card) => ({ ...card, zone: "library" as const })), ...rest];
  return {
    ...session,
    seats: session.seats.map((item) => (item.id === seatId ? { ...item, life, library: nextLibrary } : item)),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message:
          payments > 0
            ? `${seat.name} resolves ${sourceCardName}: pays ${payments} life to look again ${payments === 1 ? "once" : `${payments} times`}, shuffles, and puts the last ${looked.length} cards looked at on top of their library in an order of their choosing.`
            : `${seat.name} resolves ${sourceCardName}: looks at the top ${looked.length} cards, pays no life, shuffles, and puts those cards back on top in an order of their choosing.`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

function isLimDulsVault(name: string | undefined): boolean {
  return Boolean(name) && name!.normalize("NFD").replace(/[̀-ͯ]/g, "").toLowerCase() === "lim-dul's vault";
}

function addLibraryLookEvent(session: GameSession, seatId: string, message: string): GameSession {
  return {
    ...session,
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message
      },
      ...session.events
    ]
  };
}

export function playCardFromZone(
  session: GameSession,
  seatId: string,
  cardId: string,
  message?: string,
  position?: { x: number; z: number },
  destination: "battlefield" | "graveyard" | "exile" | "library" = "battlefield",
  manaSourceIds: string[] = [],
  sourceZone: "hand" | "command" | "exile" | "graveyard" | "library" = "hand",
  faceIndex?: number
): GameSession {
  let playedName = "";
  let enteredTapped = false;
  let shockLifePaid = 0;
  let shockPrompt: { cardId: string; cardName: string; life: number; revealTypes?: string[] } | undefined;
  let revealedForLand: string | undefined;
  // Set only when an "enter as a copy" replacement effect (parseEnterAsCopyEffect) actually found a
  // target — surfaced in the event log below so the copy is visible even if imageUris didn't come
  // through for some reason (e.g. the copied card itself has none).
  let copiedFromName: string | undefined;

  // A card exiled by an effect like Mind's Dilation's physically sits in its OWNER's exile zone,
  // not necessarily the seat granted permission to cast it (see the impulse_cast_free trigger
  // resolution) — so when the acting seat's own exile doesn't have this card, search every other
  // seat's exile for it before giving up. Every OTHER exile-cast shape already in this engine
  // (Adventure cards, Bribery-style steal-and-play) keeps the card in the acting seat's own exile,
  // so this fallback only ever fires for that new cross-seat case; ownExileCard being set is what
  // keeps this whole function's existing same-seat behavior completely unchanged otherwise.
  // Reported live as Mind's Dilation "not working at all" — the exiled card silently could never be
  // found (and so never cast) once it stopped living in the caster's own exile array.
  const actingSeat = session.seats.find((seat) => seat.id === seatId);
  const ownExileCard = sourceZone === "exile" ? actingSeat?.board.exile?.find((item) => item.id === cardId) : undefined;
  const exileOwnerSeatId =
    sourceZone === "exile" && !ownExileCard
      ? session.seats.find((seat) => seat.id !== seatId && seat.board.exile?.some((item) => item.id === cardId))?.id
      : undefined;

  const seats = session.seats.map((seat) => {
    if (exileOwnerSeatId && seat.id === exileOwnerSeatId) {
      // Only removes the card from its owner's exile — the cast's actual resolution (added to the
      // destination zone) is applied to the ACTING seat (seatId) below, same as every other cast.
      return {
        ...seat,
        board: { ...seat.board, exile: (seat.board.exile ?? []).filter((item) => item.id !== cardId) },
        zones: { ...seat.zones, exile: Math.max(0, seat.zones.exile - 1) }
      };
    }
    if (seat.id !== seatId) return seat;
    const sourceCard =
      sourceZone === "command"
        ? seat.board.commander
        : sourceZone === "exile"
          ? (ownExileCard ?? session.seats.find((s) => s.id === exileOwnerSeatId)?.board.exile?.find((item) => item.id === cardId))
          : sourceZone === "graveyard"
            ? (seat.board.graveyard ?? []).find((item) => item.id === cardId)
            : sourceZone === "library"
              ? (seat.library ?? []).find((item) => item.id === cardId)
              : seat.board.hand.find((item) => item.id === cardId);
    if (!sourceCard) return seat;
    const card = applyChosenFaceToCard(sourceCard, faceIndex);
    playedName = card.name;
    // A human is asked whether to pay the life (pendingShockChoices): the land enters tapped first, untapped if they pay.
    const humanShockCost = seat.kind === "human" && destination === "battlefield" ? shocklandPayLifeAmount(card.oracleText) : undefined;
    if (humanShockCost !== undefined) shockPrompt = { cardId: card.id, cardName: card.name, life: humanShockCost };
    // Checkland-style reveal (Snarls): a human with something revealable is asked (pendingShockChoices); an agent just reveals it.
    const revealables = destination === "battlefield" && !revealLandControlExempt(card, seat) ? revealableLandCards(card, seat.board.hand) : [];
    if (revealables.length > 0 && seat.kind === "human") shockPrompt = { cardId: card.id, cardName: card.name, life: 0, revealTypes: revealLandTypes(card.oracleText) };
    if (revealables.length > 0 && seat.kind !== "human") revealedForLand = revealables[0].name;
    const entersTapped = destination === "battlefield" && (humanShockCost !== undefined || (revealables.length > 0 && seat.kind === "human") || entersBattlefieldTapped(card, seat, session.seats));
    enteredTapped = entersTapped;
    // Shockland-style "pay life for untapped" replacement — entersBattlefieldTapped already decided
    // whether that life was worth paying; this is just the other half of that same choice, actually
    // charging it when the land enters untapped as a result.
    const shockCost = destination === "battlefield" ? shocklandPayLifeAmount(card.oracleText) : undefined;
    const lifePaidForUntapped = shockCost !== undefined && !entersTapped ? shockCost : 0;
    shockLifePaid = lifePaidForUntapped;
    // An Adventure card landing in exile, or an Omen card shuffled into the library, is still
    // identified by whichever spell face was just cast (card.name/typeLine/etc. above reflect that
    // face, via applyChosenFaceToCard) — but the card should read as the permanent it actually is
    // (faces[0], by Scryfall's convention for Adventure/Omen cards) once it's off the stack: that's
    // the only thing left castable from exile, and a card back in the library needs to show as
    // itself (not as the spell that already resolved) the next time it's drawn. card.faces itself
    // is untouched by applyChosenFaceToCard (only the top-level display fields are overwritten), so
    // the front face is still there to read.
    const revertsToFrontFace = destination === "exile" || destination === "library";
    const frontFace = revertsToFrontFace ? card.faces?.[0] : undefined;
    const enteredCard: VisibleCard = {
      ...card,
      ...(frontFace
        ? {
            name: frontFace.name,
            typeLine: frontFace.typeLine,
            oracleText: frontFace.oracleText,
            manaCost: frontFace.manaCost,
            // Recomputed alongside manaCost above — every cost-check that reads a plain card
            // object (respondWithCard's instant-speed path, most notably) uses card.manaValue
            // directly rather than recomputing it from manaCost, so leaving the old combined-card
            // manaValue in place here would silently misprice the exiled permanent face.
            manaValue: manaValueFromManaCost(frontFace.manaCost),
            power: frontFace.power,
            toughness: frontFace.toughness,
            loyalty: frontFace.loyalty,
            imageUris: frontFace.imageUris ?? card.imageUris,
            unlockedFaceIndices: [0]
          }
        : {}),
      // Rule 708.4: a split card is only ever one half while it is on the stack; once it lands in the graveyard it is the whole card again
      // (name "Find // Finality", both halves' text, combined mana value), not just the half that was cast.
      ...(destination === "graveyard" && faceIndex !== undefined && isSplitSpellCard(sourceCard)
        ? {
            name: sourceCard.name,
            typeLine: sourceCard.typeLine,
            oracleText: sourceCard.oracleText,
            manaCost: sourceCard.manaCost,
            manaValue: sourceCard.manaValue,
            imageUris: sourceCard.imageUris,
            unlockedFaceIndices: sourceCard.unlockedFaceIndices
          }
        : {}),
      zone: destination,
      // Origin zone of a battlefield entry ("entered or were cast from a graveyard": Twilight Diviner). A spell cast from a graveyard
      // (flashback-style grant) counts as coming from there even though sourceZone says where it physically was.
      enteredFrom: destination === "battlefield" ? (card.graveyardCastGrant ? "graveyard" : sourceZone) : undefined,
      // Rule 903.8: the tax was already raised when the cast was announced (recordCommanderCast), so resolving adds nothing.
      commanderTax: card.commanderTax,
      tapped: entersTapped ? true : card.tapped,
      battlefieldPosition: destination === "battlefield" ? position : undefined,
      summoningSick: destination === "battlefield" && card.typeLine.includes("Creature") ? true : card.summoningSick,
      counters: destination === "battlefield" && isPlaneswalkerCard(card) ? withInitialLoyaltyCounters(card) : card.counters,
      // Adventure (destination "exile"): the OTHER face is now exiled, castable indefinitely —
      // exiledPlayableUntilTurn left undefined, same "for as long as it remains exiled" shape
      // applyStealAndPlay already uses for Bribery-style effects (never swept by
      // clearTemporaryBuffs, which only expires a turn-limited exiledPlayableUntilTurn).
      // A flashback spell exiled after resolving (from the graveyard) is NOT castable again from exile.
      exiledPlayableBySeatId: destination === "exile" && sourceZone !== "graveyard" ? seatId : undefined,
      exiledPlayableUntilTurn: undefined,
      graveyardCastGrant: undefined
    };
    // Rule 707.2: "enters as a copy" is a replacement effect on the copiable values only (name,
    // type line, oracle text, mana cost/value, colors, P/T, image) — everything else about
    // enteredCard (id, zone, tapped state, ...) is untouched. session.seats here is still the PRE-
    // this-card board (this permanent hasn't been added to any battlefield yet), so it can't
    // accidentally copy itself. "You may" is auto-accepted (this engine's standard "always take the
    // beneficial choice" policy for unmodeled optional decisions) since entering with no copy target
    // just leaves it a blank enchantment with no text, strictly worse in every real case.
    const copyEffect = destination === "battlefield" ? parseEnterAsCopyEffect(enteredCard.oracleText) : undefined;
    const copyTarget = copyEffect ? findEnterAsCopyTarget(session, seatId, copyEffect, enteredCard.chosenCopyTargetId) : undefined;
    if (copyTarget) copiedFromName = copyTarget.name;
    const played: VisibleCard = copyTarget
      ? {
          ...enteredCard,
          name: copyTarget.name,
          typeLine: copyTarget.typeLine,
          oracleText: copyEffect?.extraAbilityText ? `${copyTarget.oracleText}\n${copyEffect.extraAbilityText}` : copyTarget.oracleText,
          manaCost: copyTarget.manaCost,
          manaValue: copyTarget.manaValue,
          colors: copyTarget.colors,
          colorIdentity: copyTarget.colorIdentity,
          power: copyTarget.power,
          toughness: copyTarget.toughness,
          // Not one of rule 707.2's own copiable values (paper Magic just relies on the physical
          // copied card being face-up on the battlefield) — but this engine has only one card object
          // per permanent, and the point of copying is to actually look like what it copied rather
          // than sit there under its original art with a different name in small text. Reported
          // live: even Estrid's Invocation's existing (narrower) copy support left the permanent
          // showing its own card image no matter what it copied.
          imageUris: copyTarget.imageUris ?? enteredCard.imageUris,
          // Cursed Mirror: only until end of turn, with an extra keyword; remember what it really is so it can change back.
          ...(copyEffect?.temporary
            ? {
                temporaryCopyOriginal: {
                  name: enteredCard.name,
                  typeLine: enteredCard.typeLine,
                  oracleText: enteredCard.oracleText,
                  manaCost: enteredCard.manaCost,
                  manaValue: enteredCard.manaValue,
                  colors: enteredCard.colors,
                  colorIdentity: enteredCard.colorIdentity,
                  power: enteredCard.power,
                  toughness: enteredCard.toughness,
                  imageUris: enteredCard.imageUris
                },
                ...(copyEffect.extraKeyword ? { temporaryGrantedKeywords: [copyEffect.extraKeyword], grantedKeywords: [copyEffect.extraKeyword] } : {})
              }
            : {})
        }
      : enteredCard;
    const spentSeat = spendManaSources(seat, manaSourceIds);
    // Casting from the graveyard takes the card out of it first (it re-enters only if it resolves back there).
    const graveyard = sourceZone === "graveyard" ? (spentSeat.board.graveyard ?? []).filter((item) => item.id !== cardId) : (spentSeat.board.graveyard ?? []);
    // Casting from the top of the library takes the card out of it (Thundermane Dragon); the cast creature gains haste until end of turn.
    const library = sourceZone === "library" ? (spentSeat.library ?? []).filter((item) => item.id !== cardId) : (spentSeat.library ?? []);
    const libraryHaste = sourceZone === "library" && destination === "battlefield" && Boolean(libraryTopCastPermission(card, seat.board.battlefield)?.grantsHaste);
    const playedOnBattlefield: VisibleCard = libraryHaste ? { ...played, temporaryGrantedKeywords: [...(played.temporaryGrantedKeywords ?? []), "haste"], grantedKeywords: [...(played.grantedKeywords ?? []), "haste"] } : played;
    const exile = spentSeat.board.exile ?? [];
    const commanderLeavesCommand = sourceZone === "command" && seat.board.commander?.id === cardId;
    // Only relevant when a card is cast FROM exile and resolves somewhere other than back into
    // exile (Adventure's spell half is always cast from hand, so this is really only exercised by
    // an impulse-drawn/stolen card being cast normally) — kept distinct from the "entering exile"
    // case below since both can't be true for the same resolution. Gated on ownExileCard: a
    // Mind's-Dilation-style cross-seat cast never had this card in the ACTING seat's own exile in
    // the first place (it was removed from its owner's exile in the seats.map branch above
    // instead), so there is nothing to remove — or decrement zones.exile for — here.
    const leavesExileZone = sourceZone === "exile" && destination !== "exile" && Boolean(ownExileCard);
    return {
      ...spentSeat,
      life: lifePaidForUntapped > 0 ? Math.max(0, spentSeat.life - lifePaidForUntapped) : spentSeat.life,
      library: destination === "library" ? [played, ...library] : sourceZone === "library" ? library : spentSeat.library,
      board: {
        ...spentSeat.board,
        commander: commanderLeavesCommand ? undefined : spentSeat.board.commander,
        hand: sourceZone === "hand" ? spentSeat.board.hand.filter((item) => item.id !== cardId) : spentSeat.board.hand,
        exile: destination === "exile" ? [...exile.filter((item) => item.id !== cardId), played] : leavesExileZone ? exile.filter((item) => item.id !== cardId) : spentSeat.board.exile,
        battlefield: destination === "battlefield" ? [...spentSeat.board.battlefield, playedOnBattlefield] : spentSeat.board.battlefield,
        graveyard: destination === "graveyard" && !played.spellCopy ? [...graveyard, played] : graveyard
      },
      zones: {
        ...spentSeat.zones,
        battlefield: spentSeat.zones.battlefield + (destination === "battlefield" ? 1 : 0),
        command: Math.max(0, spentSeat.zones.command - (commanderLeavesCommand ? 1 : 0)),
        graveyard: Math.max(0, spentSeat.zones.graveyard + (destination === "graveyard" && !played.spellCopy ? 1 : 0) - (sourceZone === "graveyard" ? 1 : 0)),
        hand: sourceZone === "hand" ? Math.max(0, spentSeat.zones.hand - 1) : spentSeat.zones.hand,
        exile: Math.max(0, spentSeat.zones.exile + (destination === "exile" && sourceZone !== "exile" ? 1 : 0) - (leavesExileZone ? 1 : 0)),
        library: Math.max(0, spentSeat.zones.library + (destination === "library" ? 1 : 0) - (sourceZone === "library" ? 1 : 0))
      }
    };
  });

  if (!playedName) return session;

  return {
    ...session,
    seats,
    ...(shockPrompt ? { pendingShockChoices: [...(session.pendingShockChoices ?? []), { seatId, ...shockPrompt }] } : {}),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${message ?? `${session.seats.find((seat) => seat.id === seatId)?.name ?? "Player"} plays ${playedName}.`}${copiedFromName ? ` It enters as a copy of ${copiedFromName}.` : ""}${enteredTapped ? " It enters tapped." : revealedForLand ? ` Reveals ${revealedForLand} from hand, so it enters untapped.` : shockLifePaid > 0 ? ` Pays ${shockLifePaid} life for it to enter untapped.` : ""}${destination === "exile" ? (sourceZone === "graveyard" ? " It's exiled (flashback)." : " It's exiled — you may cast the other half later.") : destination === "library" ? " It's shuffled into its owner's library." : ""}`,
        detail: destination === "graveyard" || destination === "exile" || destination === "library" ? "Response" : undefined
      },
      ...session.events
    ]
  };
}

// Free-for-all Commander games continue while 2+ players remain — eliminated seats stay in the
// array (for history/log purposes) but are skipped when finding whose turn/priority is next.
function nextInRotation(seats: PlayerSeat[], fromIndex: number): PlayerSeat {
  for (let offset = 1; offset <= seats.length; offset += 1) {
    const candidate = seats[(fromIndex + offset) % seats.length];
    if (!candidate.hasLost) return candidate;
  }
  return seats[fromIndex];
}

// Rule 500.7: an extra turn is inserted immediately after the current one, without disturbing the
// base rotation — once it (and any other still-queued extra turns) concludes, play resumes exactly
// where normal rotation would have left off. Achieved for free here: activeIndex stays pinned to
// whoever is CURRENTLY active (the extra-turn taker included), so once the queue drains,
// nextInRotation(seats, activeIndex) naturally computes the same next player it would have if the
// extra turn(s) had never been inserted. Eliminated players' queued extra turns are skipped, same
// as nextInRotation already skips them for normal rotation.
function nextSeatForTurn(seats: PlayerSeat[], activeIndex: number, extraTurnsQueue: string[] | undefined): { seat: PlayerSeat; queue: string[] } {
  const queue = extraTurnsQueue ?? [];
  for (let i = 0; i < queue.length; i += 1) {
    const queuedSeat = seats.find((seat) => seat.id === queue[i] && !seat.hasLost);
    if (queuedSeat) return { seat: queuedSeat, queue: queue.slice(i + 1) };
  }
  return { seat: nextInRotation(seats, activeIndex), queue: [] };
}

function nextSeatId(seats: PlayerSeat[], seatId: string) {
  const index = Math.max(0, seats.findIndex((seat) => seat.id === seatId));
  return nextInRotation(seats, index).id;
}

function rollD20() {
  return 1 + Math.floor(Math.random() * 20);
}

// Rule 103.2: before the game, each player rolls a die (traditionally a d20); the highest roll
// chooses who plays first. Ties are broken by having only the tied players re-roll against each
// other, not by falling back to seat/array order.
export function rollForStartingSeat(seats: PlayerSeat[]): { winnerId: string; rolls: Record<string, number> } {
  const allRolls: Record<string, number> = {};
  let contenders = seats;
  let guard = 0;
  while (guard < 20) {
    guard += 1;
    const roundRolls: Record<string, number> = {};
    for (const seat of contenders) roundRolls[seat.id] = rollD20();
    Object.assign(allRolls, roundRolls);
    const highest = Math.max(...contenders.map((seat) => roundRolls[seat.id]));
    const tiedForHighest = contenders.filter((seat) => roundRolls[seat.id] === highest);
    if (tiedForHighest.length === 1) return { winnerId: tiedForHighest[0].id, rolls: allRolls };
    contenders = tiedForHighest;
  }
  return { winnerId: contenders[0]?.id ?? seats[0].id, rolls: allRolls };
}

// Rule 117.3b policy lives in src/engine/priority.ts; these wrappers inject the AppFlow-side "can this seat get a priority window" predicate.
export function pendingActionRequiredPasses(
  seats: PlayerSeat[],
  action: PendingAction,
  activeSeatId: string | undefined,
  session: GameSession,
  manaPools: Record<string, ManaPool>,
  stops: PriorityStopSettings,
  holdPriorityOnceSeatId: string | undefined
) {
  return requiredPassesPolicy(seats, action, (seat, pending) =>
    canReceivePriorityForPendingAction(seat, pending, activeSeatId, session, manaPools, stops, holdPriorityOnceSeatId)
  );
}

function nextPrioritySeatId(
  seats: PlayerSeat[],
  actorSeatId: string,
  passes: string[],
  action: PendingAction,
  activeSeatId: string | undefined,
  session: GameSession,
  manaPools: Record<string, ManaPool>,
  stops: PriorityStopSettings,
  holdPriorityOnceSeatId: string | undefined
) {
  return nextPrioritySeatIdPolicy(seats, actorSeatId, passes, action, (seat, pending) =>
    canReceivePriorityForPendingAction(seat, pending, activeSeatId, session, manaPools, stops, holdPriorityOnceSeatId)
  );
}

export function canReceivePriorityForPendingAction(
  seat: PlayerSeat,
  action: PendingAction,
  activeSeatId: string | undefined,
  session: GameSession,
  manaPools: Record<string, ManaPool>,
  stops: PriorityStopSettings,
  holdPriorityOnceSeatId: string | undefined
) {
  if (seat.hasLost) return false;
  if (seat.kind === "agent") {
    // Used to unconditionally return true here, meaning every agent seat — even ones holding zero
    // instant-speed cards or usable abilities — had to individually "confirm" passing on every
    // single phase transition, each needing its own decision-timer delay and (with a real model
    // configured) LLM round trip. That's what makes turns crawl in real play: three idle agents
    // each getting asked whether they want to do something during untap/upkeep/draw/combat
    // damage/cleanup, phases where a response was never actually possible for them. Mirrors the
    // human check below: only require a pass when there's a genuine response available. Agents have
    // no stops UI of their own — the priorityStops policy (phase grid, full control, hold-once) is
    // human-only, so this branch is untouched by it.
    return legalPriorityActions(seat, action, activeSeatId, session).some((item) => item.actionType !== "pass_priority");
  }
  const pool = manaPools[seat.id] ?? emptyManaPool();
  const pendingSpellTarget = action.type === "spell" ? findSpellSourceCard(session, action) : undefined;
  const flashGranted = seatHasFlashGrant(seat);
  // A human whose only legal instant-speed response is an activated ability on a battlefield
  // permanent (not a card in hand) previously never had a priority window opened for them at all —
  // this loop only ever checked seat.board.hand, so e.g. a usable instant-speed sacrifice ability
  // was silently unreachable via priority even though the agent side of this same function already
  // covered it (legalPriorityActions, which the agent branch above delegates to, already includes
  // legalActivatedAbilityActions). sorcerySpeedAllowed=false/EMPTY_LOYALTY_KEYS matches exactly how
  // legalPriorityActions calls it for the instant-speed-only case.
  // Cards the human could actually cast as a response: instants/flash in hand, plus exiled cards they currently have
  // permission to cast (impulse draw, steal-and-play) — the same two sources respondWithCard and the agent path accept.
  // Previously only the hand was scanned, so a castable exiled instant never opened a window.
  const respondableCards: Array<{ card: VisibleCard; zone: "hand" | "exile" }> = [
    ...seat.board.hand.map((card) => ({ card, zone: "hand" as const })),
    ...session.seats
      .flatMap((s) => s.board.exile ?? [])
      .filter((card) => card.exiledPlayableBySeatId === seat.id && (card.exiledPlayableUntilTurn === undefined || session.turn <= card.exiledPlayableUntilTurn))
      .map((card) => ({ card, zone: "exile" as const }))
  ];
  const castingLockedOut = spellCastLockedOut(session, seat.id, activeSeatId);
  const hasLegalResponse =
    legalActivatedAbilityActions(seat, false, session.turn, EMPTY_LOYALTY_KEYS, session).length > 0 ||
    (!castingLockedOut && respondableCards.some(({ card, zone }) => {
    if (!canCastAtInstantSpeed(card, flashGranted || seatHasFlashGrant(seat, card)) && !(zone === "exile" && card.exiledPlayableAnyTime)) return false;
    // A spell with no legal target (a "destroy target creature" instant on an empty board) isn't a response either —
    // the agent path already filters on this; without it the human was asked to pass for a card they could never cast.
    if (!hasResolvableTarget(session, seat.id, card)) return false;
    // A type-restricted counterspell ("counter target creature/noncreature/commander spell") isn't
    // a real response option if it can't legally target what's actually on the stack — without this,
    // a human whose only instant-speed card was e.g. Negate got offered a priority window (and the
    // "Respond"/"Pass Priority" choice) against a creature spell it can never legally counter, when
    // the window should never have opened at all — same gap already closed in respondWithCard and
    // selectedCardCanRespond, just missing from the check that decides whether to open the window
    // in the first place. This also covers action.type !== "spell" (a plain phase-pass or a trigger
    // window, i.e. nothing on the stack at all): "counter target spell" is a mandatory target, so a
    // pure counterspell can't legally be cast when there's no spell to target, and a priority window
    // shouldn't open on its account either. A modal card is skipped here (matches
    // hasResolvableGenericCreatureTarget's same carve-out) since it may have a non-counter mode that's
    // perfectly castable with no spell on the stack; this check has no per-mode logic of its own, so
    // excluding it would risk hiding a genuinely legal response rather than just an illegal one.
    const counterAbility = parseCounterSpellAbility(card.oracleText);
    if (counterAbility && !parseModalHeader(card.oracleText)) {
      const legalCounterTarget =
        action.type === "spell" &&
        pendingSpellTarget &&
        !spellIsImmuneToCounters(session, pendingSpellTarget, action.actorSeatId) &&
        counterSpellCanTarget(counterAbility, pendingSpellTarget.typeLine, action.sourceZone === "command");
      if (!legalCounterTarget) return false;
    }
    const fixedCost = adjustedCastingCost(seat, card, card.manaValue, zone, activeSeatId, session.seats);
    const chosenX = maxAffordableX(seat, card, fixedCost);
    const totalCost = totalCastingCost(seat, card, card.manaValue, chosenX, session.seats);
    // A human hasn't necessarily tapped anything into their mana pool yet at this point — that
    // normally happens once they actually get priority and choose to respond. Checking only
    // payCostFromPool's already-tapped pool here meant a human with untapped lands and a castable
    // instant was never even offered a priority window: they needed priority to tap mana, but only
    // got priority if mana was already tapped. chooseManaSourcesForCost simulates tapping directly
    // from the battlefield (same color-aware logic already used for agents), so check that too.
    return payCostFromPool(pool, card, totalCost).ok || chooseManaSourcesForCost(seat, card, totalCost, undefined, session.seats).ok;
  }));
  const turnOwnerSeatIndex = Math.max(0, session.seats.findIndex((item) => item.id === activeSeatId));
  return (
    shouldStopForPriority({
      settings: stops,
      phase: session.phase,
      turnOwnerSeatIndex,
      actionType: action.type,
      actionIsMine: action.actorSeatId === seat.id,
      hasLegalResponse,
      isDefendingPlayer: seatIsBeingAttacked(session, seat.id),
      // isPendingActionLikelyIrrelevantToSeat was written to judge a SPELL/TRIGGER's oracle text —
      // a bare "phase" action has none, so it early-returns false ("not irrelevant") for every single
      // one, which inverted to actionAffectsMe: true would make "stop when I/my permanents are
      // targeted" fire on literally every phase transition on every seat's turn, not just real
      // targeted effects. Reported live: a human with only stopOnTargeted (+ stack response/attacked/
      // a ticked End Step) configured was asked to pass priority at every single phase of every
      // agent's turn. A phase-pass can never target anyone — there's no effect to be affected by.
      actionAffectsMe: action.type !== "phase" && !isPendingActionLikelyIrrelevantToSeat(seat, action, session),
      holdOnce: holdPriorityOnceSeatId === seat.id,
      willPromptMe: pendingActionWillPromptSeat(seat, action, session)
    }) !== undefined
  );
}

function resolveMyriadLandscapeSearch(session: GameSession, seatId: string, cardId: string, chosenCardIds: string[]): GameSession {
  let sourceName = "";
  let foundNames: string[] = [];
  // For the landfall watchers (Avenger of Zendikar, ...) and Mazirek-style sacrifice watchers: the lands that entered and the sacrificed source.
  let enteredLands: VisibleCard[] = [];
  let sacrificedSource: VisibleCard | undefined;

  const seats = session.seats.map((seat) => {
    if (seat.id !== seatId) return seat;
    const source = seat.board.battlefield.find((card) => card.id === cardId);
    if (!source || source.name !== "Myriad Landscape") return seat;

    sourceName = source.name;
    const library = seat.library ?? [];
    const chosenIdSet = new Set(chosenCardIds.slice(0, 2));
    const chosen = library.filter((card) => chosenIdSet.has(card.id) && isBasicLandCard(card));
    const sharedTypes = sharedBasicLandTypes(chosen);
    const found = chosen.length > 0 && sharedTypes.length > 0 ? chosen.slice(0, 2) : [];
    foundNames = found.map((card) => card.name);
    const foundIds = new Set(found.map((card) => card.id));
    const graveyard = seat.board.graveyard ?? [];
    enteredLands = found.map((card) => ({ ...card, zone: "battlefield" as const, tapped: true, battlefieldPosition: undefined, enteredFrom: "library" as const }));
    sacrificedSource = source;

    return {
      ...seat,
      // "... then shuffle."
      library: shuffleCards(library.filter((card) => !foundIds.has(card.id))),
      board: {
        ...seat.board,
        battlefield: [
          ...seat.board.battlefield.filter((card) => card.id !== cardId),
          ...found.map((card) => ({
            ...card,
            zone: "battlefield" as const,
            tapped: true,
            battlefieldPosition: undefined,
            enteredFrom: "library" as const
          }))
        ],
        graveyard: [
          ...graveyard,
          {
            ...source,
            zone: "graveyard" as const,
            tapped: false,
            battlefieldPosition: undefined
          }
        ]
      },
      zones: {
        ...seat.zones,
        battlefield: seat.zones.battlefield - 1 + found.length,
        graveyard: seat.zones.graveyard + 1,
        library: Math.max(0, seat.zones.library - found.length)
      }
    };
  });

  if (!sourceName) return session;

  const seatName = session.seats.find((seat) => seat.id === seatId)?.name ?? "Player";
  const detail = foundNames.length > 0 ? ` Finds ${foundNames.join(", ")}. They enter tapped.` : " No basic lands were found.";
  return {
    ...session,
    seats,
    pendingEntries: enteredLands.length > 0 ? [...(session.pendingEntries ?? []), ...enteredLands.map((card) => ({ seatId, card }))] : session.pendingEntries,
    pendingDeaths: sacrificedSource ? [...(session.pendingDeaths ?? []), { seatId, card: sacrificedSource, sacrificed: true }] : session.pendingDeaths,
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${seatName} sacrifices ${sourceName} and searches for up to two basic lands.${detail}`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

// Urza's Saga's chapter III ("Search your library for an artifact card with mana cost {0} or {1},
// put it onto the battlefield, then shuffle.") now flows through the generic search pipeline
// (deterministicRuleWorkflow's search_library_to_battlefield + manaValueRestriction, via
// triggerSagaChapter/consultRulesAdvisor) instead of this bespoke function — deleted along with it.

// "You may behold an Elf. If you do, untap that land." (Elven Passage) — the type word, or undefined for any other fetch.
export function basicLandFetchBeholdType(oracleText: string): string | undefined {
  const match = oracleText.match(/you may behold an? ([A-Za-z]+)\.\s*if you do, untap that land/i);
  return match ? capitalizeWord(match[1].toLowerCase()) : undefined;
}

// The cards in `hand` carrying one of the given types (creature types, land types, ...), never `excludeId`.
function handCardsOfTypes(hand: VisibleCard[], types: string[], excludeId?: string): VisibleCard[] {
  return hand.filter((candidate) => candidate.id !== excludeId && types.some((type) => candidate.typeLine.includes(type)));
}

export function resolveBasicLandFetchSearch(session: GameSession, seatId: string, cardId: string, chosenCardId?: string): GameSession {
  let sourceName = "";
  let foundName = "";
  let lifePaid = 0;
  let beholdNote = "";
  let beholdPrompt: { cardId: string; cardName: string; revealTypes: string[] } | undefined;

  const seats = session.seats.map((seat) => {
    if (seat.id !== seatId) return seat;
    const source = seat.board.battlefield.find((card) => card.id === cardId);
    if (!source || !isBasicLandFetchAbility(source)) return seat;
    const requiresTap = basicLandFetchCostRequiresTap(source);
    if (requiresTap && source.tapped) return seat;
    if (requiresTap && source.typeLine.includes("Creature") && source.summoningSick && !hasHaste(source)) return seat;

    sourceName = source.name;
    // "{T}, Pay 1 life, Sacrifice this land: ..." (Elven Passage): the life is part of the cost.
    const lifeCost = Number(source.oracleText.split("\n").find((line) => /search your library for a basic land card/i.test(line))?.split(":")[0].match(/pay (\d+) life/i)?.[1] ?? 0);
    lifePaid = lifeCost;
    const library = seat.library ?? [];
    const chosen =
      (chosenCardId ? library.find((card) => card.id === chosenCardId && isBasicLandCard(card)) : undefined) ??
      chooseBestBasicLandForFetch(seat);
    // Behold: choosing a permanent you control of that type costs nothing; otherwise reveal one from hand (agents just do it, humans are asked).
    const beholdType = basicLandFetchBeholdType(source.oracleText);
    const controlsType = beholdType ? seat.board.battlefield.some((card) => card.id !== cardId && card.typeLine.includes(beholdType)) : false;
    const handBehold = beholdType ? handCardsOfTypes(seat.board.hand, [beholdType]) : [];
    const beholdNow = Boolean(chosen && beholdType && (controlsType || (handBehold.length > 0 && seat.kind !== "human")));
    if (chosen && beholdType && beholdNow) beholdNote = controlsType ? ` Beholds a ${beholdType} it controls, so the land is untapped.` : ` Reveals ${handBehold[0].name} from hand to behold a ${beholdType}, so the land is untapped.`;
    if (chosen && beholdType && !beholdNow && handBehold.length > 0 && seat.kind === "human") beholdPrompt = { cardId: chosen.id, cardName: chosen.name, revealTypes: [beholdType] };
    const graveyard = seat.board.graveyard ?? [];
    const sacrificedSource = {
      ...source,
      zone: "graveyard" as const,
      tapped: false,
      battlefieldPosition: undefined
    };

    if (!chosen) {
      return {
        ...seat,
        life: Math.max(0, seat.life - lifeCost),
        board: {
          ...seat.board,
          battlefield: seat.board.battlefield.filter((card) => card.id !== cardId),
          graveyard: [...graveyard, sacrificedSource]
        },
        zones: {
          ...seat.zones,
          battlefield: Math.max(0, seat.zones.battlefield - 1),
          graveyard: seat.zones.graveyard + 1
        }
      };
    }

    foundName = chosen.name;
    return {
      ...seat,
      life: Math.max(0, seat.life - lifeCost),
      library: shuffleCards(library.filter((card) => card.id !== chosen.id)),
      board: {
        ...seat.board,
        battlefield: [
          ...seat.board.battlefield.filter((card) => card.id !== cardId),
          {
            ...chosen,
            zone: "battlefield" as const,
            tapped: !beholdNow,
            battlefieldPosition: undefined,
            enteredFrom: "library" as const
          }
        ],
        graveyard: [...graveyard, sacrificedSource]
      },
      zones: {
        ...seat.zones,
        battlefield: seat.zones.battlefield,
        graveyard: seat.zones.graveyard + 1,
        library: Math.max(0, seat.zones.library - 1)
      }
    };
  });

  if (!sourceName) return session;

  const seatName = session.seats.find((seat) => seat.id === seatId)?.name ?? "Player";
  const detail = (foundName ? ` Finds ${foundName}, puts it onto the battlefield tapped, then shuffles.` : " No basic land was found.") + (lifePaid > 0 ? ` Pays ${lifePaid} life.` : "") + beholdNote;
  return {
    ...session,
    seats,
    ...(beholdPrompt ? { pendingShockChoices: [...(session.pendingShockChoices ?? []), { seatId, life: 0, ...beholdPrompt }] } : {}),
    events: [
      {
        id: crypto.randomUUID(),
        at: new Date().toISOString(),
        seatId,
        message: `${seatName} sacrifices ${sourceName} and searches for a basic land.${detail}`,
        detail: "Rules action"
      },
      ...session.events
    ]
  };
}

function sharedBasicLandTypes(cards: VisibleCard[]) {
  if (cards.length === 0) return [];
  return basicLandTypes(cards[0]).filter((type) => cards.every((card) => basicLandTypes(card).includes(type)));
}

function getMyriadLandscapeOptions(library: VisibleCard[]) {
  return library.filter((card) => isBasicLandCard(card) && basicLandTypes(card).length > 0);
}

function getBasicLandFetchOptions(library: VisibleCard[]) {
  return library.filter(isBasicLandCard);
}

export function chooseBestBasicLandPairForMyriad(seat: PlayerSeat): VisibleCard[] {
  const options = getMyriadLandscapeOptions(seat.library ?? []);
  // Myriad Landscape's own "share a land type" restriction means only a type with at least two
  // copies actually sitting in the library can be fetched as a pair at all — narrowed to those
  // before the color-gap preference below runs, so it never picks a first land whose type has no
  // possible partner (which would make the pair search fail entirely for no reason).
  const seenOnce = new Set<string>();
  const pairableTypes = new Set<string>();
  for (const card of options) {
    for (const type of basicLandTypes(card)) {
      if (seenOnce.has(type)) pairableTypes.add(type);
      else seenOnce.add(type);
    }
  }
  const pairableOptions = options.filter((card) => basicLandTypes(card).some((type) => pairableTypes.has(type)));
  const first = chooseColorGapBasicLand(seat, pairableOptions);
  if (!first) return [];
  const firstTypes = basicLandTypes(first).filter((type) => pairableTypes.has(type));
  const second = pairableOptions.find((card) => card.id !== first.id && basicLandTypes(card).some((type) => firstTypes.includes(type)));
  return second ? [first, second] : [];
}

function chooseBestBasicLandForFetch(seat: PlayerSeat) {
  const basics = getBasicLandFetchOptions(seat.library ?? []);
  if (basics.length === 0) return undefined;
  const preferredNames = (seat.deck?.colors ?? seat.board.commander?.colorIdentity ?? [])
    .map((color) => basicLandForColor(color))
    .filter((name): name is string => Boolean(name));
  return basics.find((card) => preferredNames.includes(card.name)) ?? basics[0];
}

// Generalized from isUrzaSagaCard (card.name === "Urza's Saga") — see parseSagaChapters/
// advanceSagaLoreCounters, which now work for any real Saga instead of just that one.
function isSagaCard(card: VisibleCard) {
  return card.typeLine.includes("Saga");
}

function loreCounterCount(card: VisibleCard): number {
  return card.counters?.find((counter) => counter.kind === "lore")?.count ?? 0;
}

// Headless Saga support for the self-play simulator. The live game's version (applySagaEntryLoreCounter /
// advanceSagaLoreCounters / triggerSagaChapter, nested in the component) defers each chapter through window.setTimeout into
// React-bound queues; here a chapter resolves synchronously through the same pure pieces (grant text, transform, or
// commonTriggerEffect + resolveTriggerEffect). A chapter no deterministic parser owns does nothing (the live game would hand it
// to the rules advisor). Read ahead takes the last chapter, the live agent heuristic's default (chooseReadAheadChapter).
function sagaChapterHeadless(session: GameSession, seatId: string, saga: VisibleCard, chapterText: string): GameSession {
  const grantedAbility = parseGainsAbilityGrant(chapterText);
  if (grantedAbility) {
    return { ...session, seats: session.seats.map((seat) => (seat.id === seatId ? { ...seat, board: { ...seat.board, battlefield: seat.board.battlefield.map((card) => (card.id === saga.id ? { ...card, oracleText: `${card.oracleText}\n${grantedAbility}` } : card)) } } : seat)) };
  }
  if (isSagaTransformChapter(chapterText)) return transformPermanent(session, seatId, saga.id, saga.name, false);
  const effect = commonTriggerEffect(chapterText, "clause");
  if (!effect) return session;
  return resolveTriggerEffect(session, { id: crypto.randomUUID(), type: "trigger", actorSeatId: seatId, controllerSeatId: seatId, sourceCardId: saga.id, sourceCardName: saga.name, triggerKind: "common", effect, message: `${saga.name}'s chapter triggers.` });
}

function sagaLoreStepHeadless(session: GameSession, seatId: string, saga: VisibleCard, chapters: SagaChapters, newCount: number, counterSteps: number): GameSession {
  let next = session;
  for (let index = 0; index < counterSteps; index += 1) next = applyLoreCounterEtb(next, seatId, saga.id);
  const chapterText = chapters.effectByChapter.get(newCount);
  if (chapterText) next = sagaChapterHeadless(next, seatId, saga, chapterText);
  if (newCount >= chapters.chapterCount && chapters.sacrificesOnFinalChapter) next = moveCardBetweenVisibleZones(next, seatId, saga.id, "graveyard");
  return next;
}

// Chapter I as the Saga enters (only if it has no lore counter yet).
export function applySagaEntryLoreCounterHeadless(session: GameSession, seatId: string, cardId: string): GameSession {
  const saga = session.seats.find((seat) => seat.id === seatId)?.board.battlefield.find((card) => card.id === cardId);
  const chapters = saga && isSagaCard(saga) && loreCounterCount(saga) === 0 ? parseSagaChapters(saga.oracleText) : undefined;
  if (!saga || !chapters) return session;
  if (/^read ahead\b/im.test(saga.oracleText)) return sagaLoreStepHeadless(session, seatId, saga, chapters, chapters.chapterCount, chapters.chapterCount);
  return sagaLoreStepHeadless(session, seatId, saga, chapters, 1, 1);
}

// Each Saga the seat controls that is still short of its last chapter gains a counter (after the draw step).
export function advanceSagaLoreCountersHeadless(session: GameSession, seatId: string): GameSession {
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return session;
  let next = session;
  for (const saga of seat.board.battlefield.filter(isSagaCard)) {
    const chapters = parseSagaChapters(saga.oracleText);
    const count = loreCounterCount(saga);
    if (chapters && count < chapters.chapterCount) next = sagaLoreStepHeadless(next, seatId, saga, chapters, count + 1, 1);
  }
  return next;
}

function basicLandForColor(color: string): string | undefined {
  if (color === "W") return "Plains";
  if (color === "U") return "Island";
  if (color === "B") return "Swamp";
  if (color === "R") return "Mountain";
  if (color === "G") return "Forest";
  return undefined;
}

function createVisibleFromDeckCard(deckCard: { name: string; role?: string; card?: CommanderDeck["cards"][number]["card"] }, colors: string[], id: string, zone: VisibleCard["zone"]): VisibleCard {
  const name = deckCard.card?.name ?? deckCard.name;
  const role = deckCard.role ?? "spell";
  const isLand = role === "land" || ["Plains", "Island", "Swamp", "Mountain", "Forest", "Wastes"].includes(name);
  // A multi-faced card's CardRecord.typeLine/oracleText is Scryfall's *combined* string across
  // both faces (e.g. "Land // Legendary Creature — Demon" for Westvale Abbey // Ormendahl), never
  // meant for gameplay checks. A permanent always starts as its front face (faces[0]), matching
  // what transformPermanent later flips away from and what unlockedFaceIndices defaults to.
  const frontFace = deckCard.card?.faces?.[0];
  const typeLine = frontFace?.typeLine ?? deckCard.card?.typeLine;
  const fallbackTypeLine = fallbackTypeLineForCard(name, role, isLand);
  const isCreature = typeLine?.includes("Creature") ?? fallbackTypeLine.includes("Creature");
  return {
    id,
    name: frontFace?.name ?? name,
    typeLine: typeLine ?? fallbackTypeLine,
    oracleText: frontFace?.oracleText ?? deckCard.card?.oracleText ?? (isLand ? "Tap: Add mana." : `Mock ${role} card. Full rules text will come from card data lookup.`),
    manaCost: frontFace?.manaCost ?? deckCard.card?.manaCost,
    manaValue: deckCard.card?.manaValue ?? fallbackManaValueForCard(name, role, isLand),
    colors: frontFace?.colors ?? deckCard.card?.colors ?? (isLand ? [] : colors.slice(0, 1)),
    colorIdentity: deckCard.card?.colorIdentity ?? colors,
    producedMana: deckCard.card?.producedMana,
    imageUris: frontFace?.imageUris ?? deckCard.card?.imageUris,
    faces: deckCard.card?.faces,
    unlockedFaceIndices: deckCard.card?.faces ? [0] : undefined,
    role,
    zone,
    power: frontFace?.power ?? deckCard.card?.power ?? (isCreature ? "2" : undefined),
    toughness: frontFace?.toughness ?? deckCard.card?.toughness ?? (isCreature ? "2" : undefined),
    loyalty: frontFace?.loyalty ?? deckCard.card?.loyalty
  };
}

function fallbackTypeLineForCard(name: string, role: string, isLand: boolean) {
  if (isLand) return "Land";
  if (isKnownManaArtifact(name)) return "Artifact";
  if (role === "removal" || role === "protection") return "Instant";
  if (["creature", "synergy", "wincon", "draw"].includes(role)) return "Creature - Spell";
  return "Spell";
}

function fallbackManaValueForCard(name: string, role: string, isLand: boolean) {
  if (isLand) return 0;
  if (name === "Sol Ring" || name === "Wayfarer's Bauble") return 1;
  if (isKnownManaArtifact(name)) return 2;
  if (role === "removal") return 2;
  if (role === "ramp") return 2;
  return 4;
}

function isKnownManaArtifact(name: string) {
  const lower = name.toLowerCase();
  return lower === "sol ring" || lower.includes("signet") || lower.includes("talisman") || lower === "wayfarer's bauble";
}

// "When you cast this spell, reveal cards from the top of your library until you reveal X creature cards. Put all creature cards revealed this way
// into your graveyard, then put the rest on the bottom of your library in a random order." (Old Stickfingers) — X is the {X} paid in the spell's
// cost; it only decides HOW MANY creature cards get revealed (it does NOT set power/toughness, which is a graveyard-count CDA). Revealing X = 0
// creature cards reveals nothing. Resolved deterministically at cast time (it has no choices) for humans and agents alike.
export function applyCastRevealUntilCreatures(session: GameSession, seatId: string, card: VisibleCard, chosenX: number | undefined): GameSession {
  const match = card.oracleText
    .toLowerCase()
    .match(/when you cast this spell, reveal cards from the top of your library until you reveal (x|\d+) ([a-z]+) cards?\. put all \2 cards revealed this way into your graveyard, then put the rest on the bottom of your library in a random order/);
  if (!match) return session;
  const wanted = match[1] === "x" ? Math.max(0, chosenX ?? 0) : Number.parseInt(match[1], 10);
  const seat = session.seats.find((item) => item.id === seatId);
  if (!seat) return session;
  const typeName = match[2].charAt(0).toUpperCase() + match[2].slice(1);
  const library = seat.library ?? [];
  const revealed: VisibleCard[] = [];
  let found = 0;
  let index = 0;
  while (found < wanted && index < library.length) {
    revealed.push(library[index]);
    if (library[index].typeLine.includes(typeName)) found += 1;
    index += 1;
  }
  const toGraveyard = revealed.filter((item) => item.typeLine.includes(typeName)).map((item) => ({ ...item, zone: "graveyard" as const }));
  const toBottom = shuffleCards(revealed.filter((item) => !item.typeLine.includes(typeName)));
  return {
    ...session,
    seats: session.seats.map((item) =>
      item.id !== seatId ? item : { ...item, library: [...library.slice(index), ...toBottom], board: { ...item.board, graveyard: [...(item.board.graveyard ?? []), ...toGraveyard] } }
    ),
    events: [
      { id: crypto.randomUUID(), at: new Date().toISOString(), seatId, message: `${card.name}: ${seat.name} reveals ${revealed.length} card${revealed.length === 1 ? "" : "s"} and puts ${toGraveyard.length} ${match[2]} card${toGraveyard.length === 1 ? "" : "s"} into their graveyard.`, detail: "Cast trigger" },
      ...session.events
    ]
  };
}

